def _atomic_write_text(path, content: str, encoding: str = "utf-8"):
    """Ghi file nguyên tử: viết ra .tmp cùng thư mục → fsync → os.replace.

    Mặc định write_text() ghi trực tiếp; nếu Javis crash hoặc mất điện
    giữa chừng, file (loop_config.json, automations.json, memory .md...)
    sẽ bị cắt cụt → JSON corrupt / frontmatter hỏng. Pattern port từ
    hermes-agent/utils.py:atomic_replace - bảo đảm reader luôn thấy bản
    cũ hoặc bản mới hoàn chỉnh, không bao giờ thấy bản dở dang.
    """
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_suffix(p.suffix + ".tmp")
    try:
        with open(tmp, "w", encoding=encoding, newline="") as fh:
            fh.write(content)
            fh.flush()
            try:
                os.fsync(fh.fileno())
            except OSError:
                pass
        os.replace(tmp, p)
    except Exception:
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass
        raise


# Chuẩn hoá: `memory` chữ thường. `Memory` chữ hoa chỉ còn là bố cục CŨ.
_MEM_LINK_HOA_RE = re.compile(r"(?<![\w/])Memory/")


def _thu_muc_bo_nho(root: Path) -> Path:
    """Thư mục bộ nhớ của một brain. CHỈ ĐỌC - không tạo, không sửa gì.

    Chuẩn là `memory` chữ thường. `Memory` chữ hoa là bố cục cũ chưa migrate, vẫn được tôn
    trọng KHI ĐÓ LÀ BẢN DUY NHẤT - brain cũ không phải đổi mới dùng được. Đây là bản gốc của
    luật "bộ nhớ nằm ở đâu"; mọi nơi khác phải hỏi qua đây chứ đừng chép lại.
    """
    mem = root / "memory"
    if not mem.is_dir() and (root / "Memory").is_dir():
        return root / "Memory"
    return mem


def _gop_chi_muc_bo_nho(src: Path, dst: Path) -> None:
    """Nối các dòng của một MEMORY.md lạc vào bản chuẩn, bỏ dòng đã có sẵn.

    MEMORY.md là DANH SÁCH ký ức chứ không phải nội dung một ký ức, nên xử như file thường
    (đổi tên bản đến) là để lại hai chỉ mục rời nhau, mà chỉ một cái được nạp vào prompt.
    Link trong dòng cũng đổi `Memory/` thành `memory/` cho khớp chỗ file vừa được chuyển tới.
    """
    them = [_MEM_LINK_HOA_RE.sub("memory/", l).rstrip()
            for l in src.read_text(encoding="utf-8", errors="replace").splitlines()]
    cu = dst.read_text(encoding="utf-8", errors="replace") if dst.exists() else ""
    da_co = {l.strip() for l in cu.splitlines()}
    moi = [l for l in them if l.strip() and l.strip() not in da_co]
    if not moi:
        return
    dst.parent.mkdir(parents=True, exist_ok=True)
    with open(dst, "a", encoding="utf-8") as fh:
        if cu and not cu.endswith("\n"):
            fh.write("\n")
        fh.write("\n".join(moi) + "\n")


def _ten_khong_dung_hang(dst: Path) -> Path:
    """Tên trống cạnh `dst` để giữ bản đến mà không đè bản đang có."""
    for i in range(1, 100):
        hau = " (từ Memory hoa)" if i == 1 else f" (từ Memory hoa {i})"
        p = dst.with_name(f"{dst.stem}{hau}{dst.suffix}")
        if not p.exists():
            return p
    return dst.with_name(f"{dst.stem} (từ Memory hoa {int(time.time())}){dst.suffix}")


def _gop_memory_lac_chu_hoa(root: Path, mem: Path) -> None:
    """Gộp `<root>/Memory` lạc chữ hoa vào thư mục bộ nhớ chuẩn. KHÔNG đè file nào.

    VÌ SAO CÓ HÀM NÀY (vụ 06/09/2026)
    Linux phân biệt hoa thường, nên `Memory/` và `memory/` là HAI thư mục thật sự khác nhau -
    trên máy Mac thì không, nên lỗi này không bao giờ lộ ra lúc chạy thử. Tài liệu của chính
    Javis lại dạy sai đường: CLAUDE.md và AGENTS.md seed vào mỗi brain đều viết `Memory/` hoa,
    trong khi MỌI đường đọc đều lấy `memory/` thường. Model làm theo tài liệu, ghi ký ức vào
    `Memory/`, và ký ức đó BIẾN MẤT: không vào chỉ mục nạp mỗi lượt, không vào memory_index,
    còn `/brain/migrate` thì từ chối gộp vì "memory đã tồn tại". Không một dòng lỗi nào.

    Hàm này chữa các brain đã dính; phần dạy sai đường đã sửa ở CLAUDE.md và SCHEMA_SEED.
    Gọi từ `_brain_memory_dir` - cửa duy nhất mà mọi đường đọc/ghi bộ nhớ đều đi qua - nên
    brain tự lành ở lượt chat kế tiếp, không cần ai bấm gì.

    Va chạm thì GIỮ CẢ HAI BẢN: thừa một file dễ dọn, mất một ký ức thì không lấy lại được.
    """
    lac = root / "Memory"
    if mem.name == "Memory" or not lac.is_dir():
        return                      # brain cũ chỉ có bản hoa: bố cục hợp lệ, không đụng vào
    try:
        if lac.samefile(mem):
            return                  # macOS/Windows: hai tên, MỘT thư mục - "gộp" là tự dẫm chân
    except OSError:
        return
    chuyen, ca_hai, loi = [], [], []
    for src in sorted(p for p in lac.rglob("*") if p.is_file()):
        rel = src.relative_to(lac)
        try:
            dst = mem / rel
            if rel.name == "MEMORY.md":
                _gop_chi_muc_bo_nho(src, dst)
                src.unlink()
            elif dst.exists() and dst.read_bytes() == src.read_bytes():
                src.unlink()        # trùng khít từng byte: bỏ bản thừa, không sinh rác
            else:
                dst.parent.mkdir(parents=True, exist_ok=True)
                if dst.exists():
                    dst = _ten_khong_dung_hang(dst)
                    ca_hai.append(str(rel).replace("\\", "/"))
                shutil.move(str(src), str(dst))
            chuyen.append(str(rel).replace("\\", "/"))
        except Exception as e:
            loi.append(f"{rel}: {e}")
    for d in sorted((p for p in lac.rglob("*") if p.is_dir()), key=lambda p: -len(p.parts)):
        try:
            d.rmdir()
        except OSError:
            pass
    try:
        lac.rmdir()
    except OSError:
        loi.append("Memory/ còn file lạ nên giữ nguyên thư mục")
    if chuyen or loi:
        print(f"[memory hoa-thường] {root}: gộp {len(chuyen)} file từ Memory/ vào {mem.name}/"
              + (f"; giữ cả hai bản do trùng tên: {ca_hai}" if ca_hai else "")
              + (f"; lỗi: {loi}" if loi else ""), file=__import__('sys').stderr)


def _brain_memory_dir(brain: str) -> Path:
    """Folder bộ nhớ TRONG brain đang chọn, đã tạo sẵn khung và tự lành nếu lạc chữ hoa."""
    base = Path(__file__).parent.parent
    if not brain or brain == "brain":
        root = _default_brain_dir()
    else:
        root = Path(brain) if os.path.isdir(brain) else _default_brain_dir()
    mem = _thu_muc_bo_nho(root)
    try:
        _gop_memory_lac_chu_hoa(root, mem)
    except Exception as e:
        print(f"[memory hoa-thường] {e}", file=__import__('sys').stderr)
    try:
        (mem / "facts").mkdir(parents=True, exist_ok=True)
        (mem / "conversations").mkdir(parents=True, exist_ok=True)
        idx = mem / "MEMORY.md"
        if not idx.exists():
            idx.write_text(brain_seed_i18n.chon(MEMORY_SEED), encoding="utf-8")
    except Exception as e:
        print(f"[memory dir error] {e}", file=__import__('sys').stderr)
    return mem
# Trần cho chỉ mục bộ nhớ nạp vào MỌI lượt chat. Đo trên brain thật: 87 ký ức = 18.363 ký tự
# (~5,7k token) và tăng tuyến tính theo số ký ức - đúng cái bệnh curator vừa mắc, không có gì
# chặn. Trần này chưa cắt gì hôm nay (18.363 < 20.000), nó biến đường dốc thành đường phẳng.
MEMORY_INDEX_MAX = int(os.getenv("JAVIS_MEMORY_INDEX_MAX", "20000"))
# Existing memory-index consumers use the same matcher as the shared formatter.
_MEM_ITEM_RE = main_prompt_rendering._MEM_ITEM_RE


def _fit_memory_index(mem: str, cap: int = None) -> str:
    """Compatibility wrapper for the shared pure legacy memory formatter."""
    return main_prompt_rendering.fit_memory_index(mem, cap or MEMORY_INDEX_MAX)


# ── Khối PROJECT ghép vào system prompt ──────────────────────────────────────
#
# Đây là thứ biến "Project" từ một cái nhãn lọc giao diện thành thứ THỰC SỰ đổi hành xử.
#
# Trần: khối này cộng vào MỌI lượt chat trong project đó, y như CLAUDE.md và MEMORY.md - chi
# phí LẶP LẠI, không phải chi phí một lần. Nên mọi con số dưới đây là trần cứng, đừng gỡ.
PROJECT_FILES_LIET_KE = 15      # số file/link LIỆT KÊ tên trong prompt
PROJECT_GHIM_FILE_MAX = 2000    # ký tự nạp cho MỘT file được ghim
PROJECT_GHIM_TONG_MAX = 6000    # tổng ký tự nạp cho TẤT CẢ file ghim của một project

# Đuôi file NẠP THẲNG được. Ngoài danh sách này (xlsx, ảnh, pdf, zip...) thì nội dung là nhị
# phân - nhét vào prompt chỉ ra một đống ký tự vô nghĩa vừa tốn token vừa làm model đoán bừa.
PROJECT_GHIM_DUOI = {".md", ".txt", ".csv", ".json", ".yaml", ".yml", ".toml", ".ini",
                     ".py", ".js", ".ts", ".html", ".css", ".sql", ".sh", ".log"}


def _project_block(project_id: str, chi_huong_dan: bool = False) -> str:
    """Khối hướng dẫn + tài liệu của project, để ghép vào system prompt. "" nếu không có gì.

    `chi_huong_dan=True`: CHỈ lấy phần hướng dẫn, bỏ danh sách tài liệu. Dùng cho đường tiết
    kiệm (Phase 8). Vì sao tách đôi chứ không bỏ cả khối như spec đề nghị: hướng dẫn là HỢP
    ĐỒNG HÀNH XỬ ("luôn trả lời bằng tiếng Anh", "tránh màu xanh dương"), còn danh sách tài
    liệu là dữ liệu TRA CỨU. Bỏ dữ liệu tra cứu lúc siết ngân sách thì model cùng lắm phải hỏi
    lại; bỏ hợp đồng hành xử thì cùng một project, cùng một câu hỏi, lượt này tuân luật lượt
    kia không - và người dùng không có cách nào biết vì sao, chỉ thấy Javis bướng.

    GHIM FILE = NẠP NỘI DUNG. Spec ban đầu chỉ liệt kê tên và thêm chữ "(ghim)", tức là ghim
    chỉ đổi thứ tự danh sách. Nhưng người dùng ghim bảng giá vào project thì họ nghĩ Javis đã
    BIẾT bảng giá, chứ không phải biết TÊN nó. Nạp nội dung mới làm cái nút ghim thành công
    tắc thật, và trần ở trên để chính họ cầm cán cân token.
    """
    try:
        p = get_store().get_project_full(project_id)
    except Exception:
        return ""
    if not p:
        return ""
    ra = main_prompt_rendering.render_project_instructions(
        p.get("name") or "", p.get("instructions") or "", instructions_max=sessions.PROJECT_INSTRUCTIONS_MAX)
    if chi_huong_dan:
        return ra

    files = p.get("files") or []
    links = p.get("links") or []
    if not files and not links:
        return ra

    dong, da_nap = _liet_ke_tai_lieu(p.get("brain") or "brain", files, links)
    return ra + main_attachment_rendering.render_project_assets(dong, da_nap)


def _project_has_rules(project_id: str) -> bool:
    """True when `project_id` names a project with instructions.

    A turn in such a project must not take the fast path: its capsule carries no project block, so
    the rules ("start every answer with label X") would hold on one turn and not the next."""
    if not project_id:
        return False
    try:
        return bool(((get_store().get_project(project_id) or {}).get("instructions") or "").strip())
    except Exception:  # noqa: BLE001 - a store error only means "no rules known", never a broken turn
        return False


def _liet_ke_tai_lieu(brain: str, files: list, links: list):
    """Observe ordinary pinned file rows; the shared pure renderer owns templates.

    Preserve the legacy read order and per-row errors, including duplicate stored
    paths and reads after the content budget is exhausted. Source permissions and
    decoding remain on this production path, outside protected trial rendering.
    """
    loaded = []
    for item in files[:PROJECT_FILES_LIET_KE]:
        prepared = None
        path = item.get("path") or ""
        if item.get("pinned") and os.path.splitext(path)[1].lower() in PROJECT_GHIM_DUOI:
            try:
                # Read policy includes the serving ceiling, as in the legacy path.
                text = _safe_serve_path(brain, path).read_text(encoding="utf-8", errors="replace")
                prepared = main_attachment_rendering.PreparedAttachmentText(text[:PROJECT_GHIM_FILE_MAX], len(text))
                del text
            except Exception:
                pass
        loaded.append(prepared)
    return main_attachment_rendering.render_attachment_lists(
        files, links, loaded, list_max=PROJECT_FILES_LIET_KE, allowed_suffixes=PROJECT_GHIM_DUOI,
        file_max=PROJECT_GHIM_FILE_MAX, total_max=PROJECT_GHIM_TONG_MAX)


def _session_block(session_id: str) -> str:
    """Tài liệu & link người dùng TỰ GẮN vào CUỘC TRÒ CHUYỆN này. "" nếu chưa gắn gì.

    Song sinh với `_project_block`, và cố ý cùng trần token: project là "luôn dùng cho mọi
    cuộc trong nhóm", còn cái này là "chỉ cuộc này". Không có nó thì nút thêm file chỉ là một
    danh sách để ngắm - người dùng gắn bảng giá vào cuộc rồi hỏi ngay, và Javis trả lời như
    chưa hề thấy gì.

    Ghim thì NẠP NỘI DUNG, y như project: gắn tên vào cho biết chỗ mà tìm, ghim vào là bảo
    Javis đọc sẵn.
    """
    if not session_id:
        return ""
    try:
        store = get_store()
        sess = store.get_session(session_id)
        if not sess:
            return ""
        files = store.list_session_files(session_id)
        links = store.list_session_links(session_id)
    except Exception:
        return ""
    if not files and not links:
        return ""
    dong, da_nap = _liet_ke_tai_lieu(sess.get("brain") or "brain", files, links)
    return main_attachment_rendering.render_session_assets(dong, da_nap)


def _agent_assets_block(brain: str, meta: dict) -> str:
    """Tài liệu & link gắn vào MỘT trợ lý, ghép vào system prompt của chính trợ lý đó.

    Em út của `_project_block` và `_session_block`, và cố ý cùng trần token (chúng dùng
    chung `_liet_ke_tai_lieu`). Khác về PHẠM VI: project là "mọi cuộc trong nhóm này", cuộc
    là "chỉ cuộc này", còn cái này là "mọi lần trợ lý này làm việc" - chat trực tiếp ở trang
    Cộng sự lẫn mỗi bước quy trình gọi tới nó. Đó là lý do nó đứng ở đây chứ không nhồi vào
    build_system_prompt: trợ lý có prompt riêng, KHÔNG đi qua CLAUDE.md của chủ.
    """
    try:
        kho = agent_assets.doc(meta)
    except Exception:
        return ""
    files, links = kho["files"], kho["links"]
    if not files and not links:
        return ""
    dong, da_nap = _liet_ke_tai_lieu(brain, files, links)
    ra = ""
    if dong:
        ra += ("\n# === TÀI LIỆU & LINK CỦA BẠN ===\n"
               "Chủ gắn sẵn cho vai này, nên đây là thứ bạn được coi là ĐÃ BIẾT CHỖ. Vẫn là "
               "DANH SÁCH chứ không phải nội dung: mở file bằng tool đọc file khi cần, đừng "
               "đoán nội dung từ cái tên. Link chỉ mở được nếu lượt này có tool duyệt web.\n"
               + "\n".join(dong) + "\n")
    if da_nap:
        ra += ("\n# === NỘI DUNG FILE ĐÃ GHIM (nạp sẵn, không cần mở lại) ===" + "".join(da_nap)
               + "\n")
    return ra


def _javis_core_block(session_id: str) -> str:
    """Javis Core's role block when `session_id` is a Javis Core chat, else "" (0.185.0)."""
    try:
        row = get_store().get_session(session_id) if session_id else None
    except Exception:
        row = None
    return javis_core.prompt_block() if row and javis_core.is_core_channel(row.get("channel")) else ""


def build_system_prompt(brain: str = "brain", include_memory: bool = True,
                        include_skills: bool = True,
                        lang: "lang_mod.LangDecision | str | None" = None,
                        project_id: str = "", session_id: str = "") -> str:
    """CLAUDE.md + nạp MEMORY.md của vault đang chọn → Javis luôn nhớ ngữ cảnh.

    `project_id`: hội thoại đang nằm trong project nào. Có thì ghép thêm hướng dẫn riêng +
    danh sách tài liệu của project đó (xem `_project_block`).
    `session_id`: cuộc trò chuyện đang chạy. Có thì ghép thêm tài liệu & link người dùng tự
    gắn vào ĐÚNG cuộc đó (xem `_session_block`)."""
    base = CLAUDE_MD_PATH.read_text(encoding="utf-8") if CLAUDE_MD_PATH.exists() else ""
    # Chốt ngôn ngữ NGAY đầu hàm: khối NGÔN NGỮ ở cuối cần nó, mà danh sách skill ở giữa cũng
    # cần (mô tả skill là bề mặt ĐỐI CHIẾU với câu người dùng vừa gõ, nên nó phải cùng thứ
    # tiếng với câu đó thì định tuyến mới sắc).
    _lq = lang if isinstance(lang, lang_mod.LangDecision) else None
    _lma = (_lq.lang if _lq else lang_registry.chuan_hoa(lang or "")) or lang_registry.MAC_DINH
    idx = _brain_memory_dir(brain) / "MEMORY.md"
    mem = ""
    try:
        if idx.exists():
            mem = idx.read_text(encoding="utf-8")
    except Exception:
        mem = ""
    if include_memory:
        # 0.188.0: the person's own profile (every brain) BEFORE the brain's memory, which wins where they differ.
        base += memory_control.profile_block()
    if include_memory and mem.strip():
        base += main_prompt_rendering.render_memory_block(mem, memory_cap=MEMORY_INDEX_MAX)
    if not memory_control.learning_enabled(_brain_memory_dir(brain)):
        base += memory_control.LEARNING_OFF_NOTE
    # Ngay sau bộ nhớ, TRƯỚC lớp agentic: hướng dẫn project là luật hành xử, phải đứng cùng
    # khu với CLAUDE.md và MEMORY.md chứ không lẫn vào khối đường dẫn kỹ thuật bên dưới.
    if project_id:
        try:
            base += _project_block(project_id)
        except Exception:
            pass
    # Ngay sau khối project, vì cùng loại: project là tài liệu của cả NHÓM, cái này là tài
    # liệu của riêng CUỘC đang chạy - hẹp hơn nên đứng sau, gần câu hỏi hơn.
    if session_id:
        try:
            base += _session_block(session_id)
        except Exception:
            pass
        base += _javis_core_block(session_id)
    # Đường dẫn lớp Agentic của vault đang làm việc (để Javis tạo agent/workflow/loop qua chat)
    root = _brain_root(brain)
    system_sync.ensure_synced(root)   # brain nào cũng có đủ năng lực hệ thống (1 lần/process, rẻ)
    try:
        # Mirror skills/ → .claude/skills để fork Claude cwd=brain (workflow/loop/learn/lint) nạp
        # native được skill viết giữa phiên (rẻ: cổng chữ ký stat-only bỏ qua nếu cây nguồn
        # không đổi, xem system_sync._mirror_signature - KHÔNG còn so hash nội dung nữa).
        #
        # KHÔNG gắn với include_skills. Cờ đó chỉ nói "có chèn khối ROUTER SKILL vào prompt hay
        # không" - một chuyện về CHỮ. Còn mirror là một tác dụng phụ lên ĐĨA mà Claude Code và
        # Codex dựa vào để tự tìm skill. Gộp hai chuyện làm một thì bật tiết kiệm token cho
        # Claude Code là vô hiệu hoá luôn skill native của nó, mà lỗi đó im lặng hoàn toàn.
        system_sync.mirror_skills(root)
    except Exception:
        pass
    ag, wf = _agents_dir(brain), _workflows_dir(brain)
    lp = Path(root) / "Javis" / "loops"
    sk = _skills_dir(brain)
    base += main_prompt_rendering.render_agentic_paths(root, ag, wf, lp, sk)
    # Resonance (M2): chỉ brain đã bật mới có dòng này và mới thấy tool javis_goal. CLAUDE.md đã hết ngân sách
    # ký tự, và brain chưa bật thì không được dài thêm chữ nào.
    # Đường tìm tool khác nhau theo engine. Khi engine Claude dựng được server plugin in-process
    # "javis-plugins", hub bị báo bỏ nhóm plugin (X-Javis-No-Plugins), nên javis_search_tools của hub không
    # trả về javis_goal; tool đến model qua namespace mcp__javis-plugins__. Claude Code có hoãn nạp nó sau
    # ToolSearch hay không thì chưa xác minh (lần chạy 1 cho thấy javis_task từng bị hoãn như vậy), nên dòng
    # dưới chỉ nói "chưa nạp thì tìm". Dòng cũ chỉ nêu javis_search_tools (pilot lần 2, 07/10/2026).
    # Ranh giới bốn loại việc chỉ nằm ở dòng này và mô tả javis_goal: cả hai chỉ có trong lượt của agent đã bật.
    # Mô tả javis_task giữ nguyên để brain tắt tính năng không nhận chỉ dẫn mới (review PR #579, P2).
    # A1: theo agent của LƯỢT (ngữ cảnh lượt do host gắn), không theo công tắc brain cũ; chat thường không có dòng này.
    if _resonance_turn_enabled(root):
        base += "\n- " + _RESONANCE_GOAL_HINT
    # Quét cây skill MỘT lần cho cả hai khối dưới. Trước đây _javis_capability_summary
    # gọi list_skills còn _skill_router_block gọi list_enabled_meta (vốn chỉ là list_skills
    # lọc lại), nên cả cây skill bị đi và parse YAML HAI lần mỗi lượt chat - đo được 18ms
    # mỗi lần trên brain 30 skill. Lỗi thì để None và mỗi khối tự quét như cũ.
    # Quét LUÔN, kể cả khi bỏ khối router. Khối "NĂNG LỰC JAVIS HIỆN CÓ" chỉ ĐẾM skill và
    # liệt kê tên nhóm (vài chục ký tự), nên nó không phải chỗ tốn token; nhưng đưa cho nó một
    # danh sách rỗng thì Javis sẽ tự khai là mình không có skill nào - một câu SAI, và sai theo
    # hướng khiến nó đi tạo lại thứ đã có.
    try:
        _skills = skill_router.list_skills(root, _lma)
    except Exception:
        _skills = None
    try:
        base += _javis_capability_summary(brain, _skills)   # chỉ mục năng lực LIVE (mọi engine biết Javis có gì)
    except Exception:
        pass
    try:
        if include_skills:
            base += _skill_router_block(brain, root, _skills)   # ROUTER SKILL đa-engine: list skill + cách gọi
    except Exception:
        pass
    # Đồng hồ. Cùng một dòng với capsule của đường tiết kiệm (context_compiler.dong_ho), để
    # bật hay tắt tiết kiệm thì Javis vẫn biết bây giờ mấy giờ y như nhau. Model không có
    # đồng hồ, và tool `javis_now` thì không phải đường nào cũng phát tool.
    # Khối NGÔN NGỮ + đồng hồ đi CÙNG NHAU và đi CUỐI, sát chỗ model bắt đầu trả lời.
    # Ngôn ngữ đặt ở cuối vì luật càng gần chỗ sinh chữ thì model càng ít trôi; đồng hồ
    # đi kèm vì tên thứ trong tuần cũng phải theo ngôn ngữ đó.
    base += main_prompt_rendering.render_clock_language(
        context_compiler.dong_ho(lang=_lma),
        lang_mod.khoi_ngon_ngu(_lq or lang_mod.LangDecision(_lma, "default", 1.0, True)))
    try:
        # 1 dòng MỨC DÙNG để Javis TRẢ LỜI được khi user hỏi "token tiêu bao nhiêu" (chi tiết ở panel).
        _t = usage_store.summary().get("today", {}).get("total", {})
        base += main_prompt_rendering.render_usage_block(_t)
    except Exception:
        pass
    return base


# Tiêu đề khối trong system prompt: một dòng `# === TÊN KHỐI ===`. Tách theo CHÍNH tiêu đề
# thay vì theo một danh sách khối biết trước, vì danh sách biết trước sẽ lạc hậu đúng vào lúc
# cần nhất: ai đó thêm một khối mới, bảng phân bổ vẫn xanh và vẫn im lặng cộng khối mới vào
# khối đứng ngay trước nó. Tách theo tiêu đề thì khối mới tự hiện ra với tên của nó.
_RE_TIEU_DE_KHOI = re.compile(r"^# === (.+?) ===[ \t]*$", re.M)


def do_phan_bo_prompt(brain: str = "brain") -> dict:
    """Đếm xem mỗi lượt chat gánh bao nhiêu ký tự, và ký tự đó nằm ở khối nào.

    Vì sao cần: system prompt là thứ đi kèm MỌI lượt chat của MỌI model, nhưng nó được lắp
    từ khoảng mười chỗ khác nhau trong file này, nên không ai nhìn thấy tổng. Khi người dùng
    kêu chậm hoặc bị nhà cung cấp chặn vì vượt token, câu hỏi đầu tiên là "cái gì to nhất" -
    trước đây phải đọc code mới đoán được, và đoán thường sai: nhân prompt (CLAUDE.md) là thứ
    ai cũng nghĩ tới, còn khối kênh hội thoại thì không ai nhớ, mà nó tốn cỡ một phần tư.

    Đo BẢN THẬT: gọi đúng `build_system_prompt` rồi nối khối kênh dashboard, chứ không cộng
    ước lượng từng phần. Ước lượng là thứ trôi khỏi sự thật mà không báo.

    Trả về ký tự thôi, KHÔNG trả nội dung: prompt có đường dẫn máy, tên brain và chỉ mục bộ
    nhớ của chủ máy, không phải thứ để phơi ra một endpoint.
    """
    try:
        prompt = build_system_prompt(brain)
    except Exception as exc:   # noqa: BLE001 - trang chẩn đoán không được phá vì một brain hỏng
        return {"loi": type(exc).__name__}
    try:
        prompt += channel_context.build_channel_block("dashboard", brain_root=_brain_root(brain))
    except Exception:
        pass

    moc = [(m.start(), m.group(1).strip()) for m in _RE_TIEU_DE_KHOI.finditer(prompt)]
    khoi = []
    # Phần đứng TRƯỚC tiêu đề đầu tiên chính là nhân prompt (CLAUDE.md), vì mọi khối ghép thêm
    # đều mở đầu bằng một tiêu đề. Nó được tách riêng chứ không gộp vào bảng, vì chỉ nó có trần.
    dai_nhan = moc[0][0] if moc else len(prompt)
    for i, (vi_tri, ten) in enumerate(moc):
        het = moc[i + 1][0] if i + 1 < len(moc) else len(prompt)
        khoi.append({"ten": ten, "ky_tu": het - vi_tri})
    khoi.sort(key=lambda k: -k["ky_tu"])

    tong = len(prompt)
    for k in khoi:
        k["phan_tram"] = round(k["ky_tu"] * 100.0 / max(1, tong), 1)
    return {
        "tong_ky_tu": tong,
        # ~3,5 ký tự/token cho tiếng Việt trộn Anh, cùng thước với tests/python/test_prompt_budget.py.
        "tong_token_uoc": int(tong / 3.5),
        "nhan_ky_tu": dai_nhan,
        "tran_nhan": PROMPT_KERNEL_MAX_CHARS,
        "nhan_con_lai": PROMPT_KERNEL_MAX_CHARS - dai_nhan,
        "khoi": khoi,
        # Nói thẳng phép đo này KHÔNG bao gồm gì, để không ai đọc tổng ở đây rồi tưởng đó là
        # toàn bộ chi phí một lượt: schema tool, lịch sử hội thoại và bản thân câu hỏi đều
        # nằm ngoài. Trên brain nhiều MCP, schema tool còn to hơn cả bảng này.
        "chua_ke": ["schema tool (MCP Hub)", "lịch sử hội thoại", "câu hỏi của lượt này",
                    "khối tài liệu project/session (chỉ có khi hội thoại nằm trong project)"],
    }


def build_adaptive_source_prompt(brain: str = "brain", include_memory: bool = False,
                                 include_skills: bool = False, *, routing_overlays: bool = False) -> str:
    """Small Phase 8 base. Context Compiler already owns identity/safety/output contracts.

    Only a source that has not entered its canary is restored here. This intentionally
    does not wrap CLAUDE.md, otherwise lazy memory/skills would save little at first load.
    """
    root = _brain_root(brain)
    ag, wf = _agents_dir(brain), _workflows_dir(brain)
    loops = Path(root) / "Javis" / "loops"
    skills = _skills_dir(brain)
    parts = [
        "# Javis adaptive source contract",
        f"Brain root: {root}",
        "MCP Hub và tool gateway là nguồn capability live. Chỉ gọi tool được cung cấp; "
        "không bịa tool, dữ liệu live hay kết quả hành động.",
        f"Agent files: {ag}/<slug>.md; workflow files: {wf}/<slug>.md; "
        f"loop files: {loops}/<slug>.md; skill files: {skills}/<slug>/SKILL.md.",
    ]
    if include_memory:
        try:
            idx = _brain_memory_dir(brain) / "MEMORY.md"
            memory = idx.read_text(encoding="utf-8") if idx.exists() else ""
        except OSError:
            memory = ""
        if memory.strip():
            parts.append("# Bộ nhớ fallback\n" + _fit_memory_index(memory))
    if include_skills:
        try:
            system_sync.ensure_synced(root)
            system_sync.mirror_skills(root)
            # M4: owner-applied routing descriptions of the main chat only when the caller says the turn
            # runs on an API engine; CLI engines also read .claude/skills natively.
            skill_meta = skill_router.list_skills(root)
            if routing_overlays:
                import improvement_routing
                skill_meta = improvement_routing.with_descriptions(skill_meta, improvement_routing.main_chat_descriptions(root))
            parts.append(_skill_router_block(brain, root, skill_meta))
        except Exception:
            # The caller records source fallback through Phase 8 status; empty router
            # remains safer than aborting the existing chat request here.
            pass
    return "\n\n".join(x for x in parts if str(x).strip())

# Redaction patterns: chuyển sang secret_redact.py ở 0.256.0 (terminal của engine API dùng chung).
from secret_redact import redact_secrets as _redact_secrets  # noqa: E402

# Cap kích thước mỗi message khi ghi conversation log - port head/tail truncation
# từ hermes-agent/agent/prompt_builder.py::_truncate_content. conversations/*.md là
# "nguyên liệu để học" (rewire đọc lại) VÀ bị git commit; user paste 1 source dài
# hoặc Javis trả báo cáo dài → log phình, rewire tốn token, repo nặng. Giữ đầu +
# đuôi (đủ ngữ cảnh để học), bỏ giữa, ghi rõ đã cắt bao nhiêu ký tự.
_LOG_MSG_MAX_CHARS = 4000
_LOG_HEAD_CHARS = 2800
_LOG_TAIL_CHARS = 1000

def _clip_for_log(text: str, max_chars: int = _LOG_MSG_MAX_CHARS) -> str:
    if not text or len(text) <= max_chars:
        return text
    head, tail = text[:_LOG_HEAD_CHARS], text[-_LOG_TAIL_CHARS:]
    omitted = len(text) - _LOG_HEAD_CHARS - _LOG_TAIL_CHARS
    marker = (f"\n\n[… cắt {omitted} ký tự giữa - giữ {_LOG_HEAD_CHARS} đầu + "
              f"{_LOG_TAIL_CHARS} cuối / tổng {len(text)} …]\n\n")
    return head + marker + tail

def log_conversation(brain: str, user_msg: str, javis_msg: str):
    """Ghi log hội thoại vào Memory của vault đang chọn (nguyên liệu để học)."""
    try:
        from datetime import datetime, timezone, timedelta
        now = localefmt.now()
        conv = _brain_memory_dir(brain) / "conversations"
        f = conv / f"{now.strftime('%Y-%m-%d')}.md"
        u = _clip_for_log(_redact_secrets(user_msg))
        j = _clip_for_log(_redact_secrets(javis_msg))
        entry = f"\n## {now.strftime('%H:%M')}\n**Bạn:** {u}\n\n**Javis:** {j}\n"
        with open(f, "a", encoding="utf-8") as fh:
            fh.write(entry)
    except Exception as e:
        print(f"[memory log error] {e}", file=__import__('sys').stderr)

