# ---- Đường HTTP của plugin (0.64.26) ----
#
# Lõi chỉ CHUYỂN request; luật nằm ở plugins_host (ai được mở đường, đường nào công khai, đường
# nào không cookie). Sinh ra để "Javis trong ChatGPT" rời lõi thành một gói trong kho, nhưng cố
# ý làm chung: webhook của dịch vụ ngoài là cùng một nhu cầu.
_EXT_METHODS = ["GET", "POST", "PUT", "PATCH", "DELETE"]


async def _goi_plugin_http(request: Request, lp, handler, bo_cookie: bool):
    if bo_cookie:
        # Gỡ cookie ở đây chứ không tin plugin tự lờ đi: đây là đường đã được miễn CSRF, nên
        # nếu còn cookie thì một trang lạ gọi vào sẽ mang theo phiên của chủ.
        scope = dict(request.scope)
        scope["headers"] = [(k, v) for k, v in request.scope.get("headers", [])
                            if k.lower() != b"cookie"]
        request = Request(scope, request.receive)
    try:
        if asyncio.iscoroutinefunction(handler):
            kq = await handler(request, lp.ctx)
        else:
            kq = await asyncio.to_thread(handler, request, lp.ctx)
    except Exception as e:
        print(f"[plugin-http] {lp.slug}: {type(e).__name__}: {e}", file=__import__('sys').stderr)
        return JSONResponse({"error": localefmt.chu(f"plugin {lp.slug} lỗi: {type(e).__name__}", f"plugin {lp.slug} failed: {type(e).__name__}")}, status_code=500)
    if isinstance(kq, Response):
        return kq
    if isinstance(kq, (dict, list)):
        return JSONResponse(kq)
    if isinstance(kq, str):
        return HTMLResponse(kq)
    return Response(status_code=204)


@app.api_route("/ext/{slug}", methods=_EXT_METHODS, include_in_schema=False)
@app.api_route("/ext/{slug}/{rest:path}", methods=_EXT_METHODS, include_in_schema=False)
async def plugin_http(request: Request, slug: str, rest: str = ""):
    tr = plugins_host.tim_http(slug, rest, request.method)
    if not tr:
        return JSONResponse({"error": "not_found"}, status_code=404)
    lp, r = tr
    # Đường không công khai: đòi PHIÊN TRÌNH DUYỆT thật. Hàng rào phía trước đã cho token API
    # qua, nhưng một token rò ra không được mở trang cài đặt của plugin.
    if (not r["public"] and cfgmod.gate_active()
            and not cfgmod.valid_session(request.cookies.get("javis_session", ""))):
        return JSONResponse({"error": localefmt.chu("Trang này phải đăng nhập bằng trình duyệt.", "This page requires signing in from a browser.")}, status_code=401)
    return await _goi_plugin_http(request, lp, r["handler"], r["no_cookie"])


@app.get("/.well-known/{rest:path}", include_in_schema=False)
async def plugin_well_known(request: Request, rest: str):
    tr = plugins_host.tim_well_known(rest.split("/", 1)[0])
    if not tr:
        return JSONResponse({"error": "not_found"}, status_code=404)
    lp, handler = tr
    return await _goi_plugin_http(request, lp, handler, True)

@app.post("/connect/core-toggle")
async def connect_core_toggle(request: Request):
    """Gỡ hoặc cài lại một connector CÓ SẴN của Javis.

    "Gỡ" ở đây KHÔNG xoá file trong `system/`: cây code là read-only trên Docker và bị ghi đè
    bởi `git pull` trên bản native, nên lựa chọn phải sống ở STATE_DIR mới qua được một lần cập
    nhật. Chi tiết trong `server/core_off.py`.

    Gỡ khuôn KHÔNG xoá kết nối đã đấu theo nó - kết nối là dữ liệu của người dùng. Chúng thành
    mồ côi, `mcp_store.resolved` từ chối dựng dial spec cho chúng, và trả về đây để giao diện
    hỏi lại một câu trước khi gỡ."""
    data = await request.json()
    cid = (data.get("id") or "").strip()
    off = bool(data.get("off"))
    if cid not in mcp_catalog.tat_ca():
        return JSONResponse({"ok": False, "error": localefmt.chu("Không có connector này trong kho", "This connector is not in the catalog")},
                            status_code=400)
    anh_huong = [{"id": c["id"], "label": c.get("label") or c["id"]}
                 for c in mcp_store.list_connections() if c.get("connector_id") == cid]
    # XEM TRƯỚC, không đụng gì. Giao diện hỏi lại người dùng TRƯỚC khi gỡ, nên nó cần biết cái
    # gì sắp dừng - mà đường duy nhất để biết trước đây là gọi thẳng rồi đọc lỗi 409, tức là
    # với connector KHÔNG có kết nối nào thì lần gọi đó đã gỡ xong trước khi kịp hỏi ai.
    if data.get("plan"):
        return {"ok": True, "plan": True, "connections": anh_huong,
                "off": core_off.la_da_go("connectors", cid)}
    if off and anh_huong and not data.get("confirm"):
        return JSONResponse({"ok": False, "need_confirm": True, "connections": anh_huong},
                            status_code=409)
    try:
        core_off.dat("connectors", cid, off)
    except (OSError, ValueError) as e:
        return JSONResponse({"ok": False, "error": str(e)}, status_code=500)
    mcp_hub.invalidate_cache()
    _write_codex_profile()
    return {"ok": True, "off": off, "orphans": mcp_store.orphans()}


@app.post("/connect/add")
async def connect_add(request: Request):
    """Thêm tài khoản cho 1 connector trong kho: lưu tạm → VALIDATE ngay (gọi tool xác minh,
    tự lấy tên shop làm label) → key sai thì xoá, không lưu rác."""
    data = await request.json()
    con_id = (data.get("connector_id") or "").strip()
    # Connector cần trình duyệt TRÊN MÁY CHẠY JAVIS (workspace-mcp: OAuth callback cứng
    # localhost:8000) mà user đang mở dashboard qua domain public → luồng đăng nhập Google
    # chắc chắn đứt ở ERR_CONNECTION_REFUSED (issue #112). Chặn kèm lời giải thích + đường
    # thay thế; can_force để ca đặc biệt (đấu sẵn từ xa, sang máy bấm đồng ý sau) vẫn đi được.
    if (mcp_catalog.get(con_id) or {}).get("needs_local_browser") and not data.get("force"):
        host_thay = web_security.external_base(
            request.url.scheme, request.url.netloc,
            request.headers.get("x-forwarded-proto", ""),
            request.headers.get("x-forwarded-host", ""))
        if not web_security.host_kieu_local(host_thay):
            return {"ok": False, "can_force": True, "error": localefmt.chu(
                    "Kết nối này chạy OAuth trên CHÍNH MÁY cài Javis (Google sẽ chuyển về "
                    "localhost:8000), mà bạn đang mở Javis qua domain public - đăng nhập Google "
                    "sẽ đứt giữa chừng với lỗi không kết nối được. Trên VPS hãy dùng thẻ Lịch "
                    "và Gmail riêng (hai thẻ đó đăng nhập ngay trong dashboard). Nếu máy chạy "
                    "Javis có màn hình và bạn sẽ bấm đồng ý trên đó, bấm Kết nối lần nữa.",
                    "This connection runs OAuth on the SAME MACHINE Javis is installed on (Google "
                    "redirects back to localhost:8000), but you are opening Javis through a public "
                    "domain, so the Google sign-in will break halfway with a connection error. On a "
                    "VPS, use the separate Calendar and Gmail cards (those two sign in right inside "
                    "the dashboard). If the machine running Javis has a screen and you will click "
                    "Allow there, click Connect again.")}
        if _deploy_mode() == "docker":
            # Issue #855: Javis in Docker on the same computer. Google sends the browser back to localhost:8000 on that
            # computer, which reaches the sign-in listener only when the container publishes port 8000
            # (docker-compose.google.yml). Javis cannot see the host's port mapping from inside, so it says it once.
            return {"ok": False, "can_force": True, "error": localefmt.chu(
                    "Javis đang chạy trong Docker. Sau khi bấm đồng ý, Google chuyển trình duyệt về "
                    "localhost:8000 trên máy bạn, nên container phải mở cổng 8000 (chỉ cho chính máy này). "
                    "Làm một lần trong thư mục Javis: docker compose -f docker-compose.yml -f "
                    "docker-compose.google.yml up -d. Đã làm rồi thì bấm Kết nối lần nữa.",
                    "Javis is running in Docker. After you click Allow, Google sends the browser back to "
                    "localhost:8000 on your computer, so the container must publish port 8000 (to this "
                    "computer only). Do it once in the Javis folder: docker compose -f docker-compose.yml -f "
                    "docker-compose.google.yml up -d. If you already did, click Connect again.")}
    # Dùng lại key OAuth client của connection khác (vd Gmail dùng lại key đã tạo cho
    # Calendar) - copy server-side, secrets không bao giờ về browser.
    fields_in = mcp_store.reuse_client_fields(
        mcp_catalog.get(con_id), data.get("fields") or {}, (data.get("reuse_from") or "").strip())
    # Bước ĐỔI CREDENTIAL (nếu connector khai auth.exchange): vd Google Keep đổi App Password
    # thành master token ngay tại đây, để người dùng khỏi phải mở terminal. Hàm này LUÔN xoá các
    # field khai trong `drop` (như app_password) nên thứ đó không bao giờ xuống tới mcp_store.
    # Apify/Google verification performs network I/O; keep the event loop responsive.
    fields, ex_err = await asyncio.to_thread(
        cred_exchange.run, mcp_catalog.get(con_id), fields_in)
    if ex_err:
        return {"ok": False, "error": ex_err}
    cid, err = mcp_store.add_connection(con_id, {
        "label": (data.get("label") or "").strip(), "fields": fields})
    if err:
        return {"ok": False, "error": err}
    val = await mcp_hub.validate_connection(cid)
    if not val.get("ok"):
        mcp_store.delete_connection(cid)
        return {"ok": False, "error": val.get("error") or localefmt.chu("Không kết nối được", "Could not connect")}
    if val.get("label") and not (data.get("label") or "").strip():
        mcp_store.update_connection(cid, {"label": val["label"]})
    mcp_hub.invalidate_cache()
    _write_codex_profile()
    c = mcp_store.get_connection(cid) or {}
    return {"ok": True, "id": cid, "label": c.get("label"), "tools": val.get("tools", 0)}


