@app.post("/connect/delete")
async def connect_delete(request: Request):
    """Xoá kết nối VÀ mọi dấu vết nó để lại. Toàn bộ việc dọn nằm ở `server/purge.py`.

    Trước 0.55.19 chỗ này gọi bốn hàm dọn rồi coi như xong, và bỏ sót ba thứ: tiến trình con
    stdio sống thêm 15 phút (xoá hàng trước nên `invalidate_cache` không còn tìm ra phiên để
    đóng), thư mục `connector-home` chứa phiên đăng nhập không ai xoá, và sổ năng lực chỉ xoá
    mềm. Đừng thêm bước dọn mới vào đây - thêm vào `purge.py`, để chỉ có MỘT chỗ biết một kết
    nối có thể để lại những gì."""
    data = await request.json()
    cid = (data.get("id") or "").strip()
    bao_cao = await purge.purge_connection(
        cid,
        mode=("hard" if data.get("hard") else "trash"),
        purge_audit=bool(data.get("purge_audit")),
    )
    if bao_cao.get("ok"):
        _write_codex_profile()
    return bao_cao


@app.post("/connect/relogin")
async def connect_relogin(request: Request):
    """Vứt token mà connector tự cache ngoài Javis (workspace-mcp) mà GIỮ nguyên kết nối.

    Vì sao cần một nút riêng: với connector loại này, nút Kết nối lại chỉ lưu lại Client ID/Secret
    chứ không đụng được token - server con đã có credential trên đĩa nên không bao giờ mở lại màn
    đăng nhập Google. Token cấp thiếu quyền thì thiếu mãi. Dọn kho token xong, lần gọi tool kế
    tiếp server tự mở trình duyệt xin lại quyền theo đúng bộ hiện hành."""
    data = await request.json()
    cid = (data.get("id") or "").strip()
    if not cid:
        return JSONResponse({"ok": False, "error": localefmt.chu("Thiếu id kết nối", "Missing connection id")}, status_code=400)
    done = mcp_store.forget_cred_dir_by_id(cid)
    mcp_client.pool.invalidate(cid)   # giết tiến trình con đang giữ token cũ trong RAM
    mcp_hub.invalidate_cache()
    connect_health.forget(cid)
    return {"ok": True, "cleared": done,
            "message": (localefmt.chu(
                "Đã xoá đăng nhập Google cũ. Nhờ Javis làm một việc bất kỳ với nguồn này, "
                "trình duyệt trên máy chạy Javis sẽ mở để bạn cấp lại quyền.",
                "The old Google sign-in was removed. Ask Javis to do anything with this source and "
                "the browser on the machine running Javis will open so you can grant access again.")
                        if done else
                        localefmt.chu("Kết nối này không tự giữ token riêng, hoặc chưa từng đăng nhập.",
                                      "This connection keeps no token of its own, or was never signed in."))}


