# ---- OAuth chuẩn MCP: Javis tự giữ token, không cần terminal ----
@app.post("/connect/oauth/start")
async def connect_oauth_start(request: Request):
    data = await request.json()
    conn_id = data.get("id")
    # fields: client_id/secret user tự khai (BYO) cho provider không DCR (vd Google). Rỗng với Meta.
    fields = {k: v for k, v in (data.get("fields") or {}).items() if v}
    # Dùng lại key client từ connection Google khác (copy server-side, xem reuse_client_fields)
    fields = mcp_store.reuse_client_fields(
        mcp_catalog.get((data.get("connector_id") or "").strip()), fields,
        (data.get("reuse_from") or "").strip())
    if not conn_id and data.get("connector_id"):
        # Tái dùng connection oauth dở dang (chưa có token) của connector này -
        # tránh mỗi lần bấm nút lại đẻ 1 connection mồ côi.
        pend = next((c for c in mcp_store.list_connections()
                     if c.get("connector_id") == data["connector_id"] and c.get("auth") == "oauth"
                     and not oauth_mcp.status(c["id"]).get("connected")), None)
        if pend:
            conn_id = pend["id"]
            if fields:   # cập nhật lại client_id/secret nếu user nhập mới ở lần bấm này
                mcp_store.update_connection(conn_id, {"fields": fields})
        else:
            conn_id, err = mcp_store.add_connection(data["connector_id"],
                {"label": (data.get("label") or "").strip(), "auth": "oauth", "fields": fields})
            if err:
                return {"ok": False, "error": err}
    elif conn_id and fields:
        mcp_store.update_connection(conn_id, {"fields": fields})
    # Địa chỉ quay về NHƯ NGƯỜI DÙNG THẤY: sau reverse proxy (VPS https) phải theo
    # X-Forwarded-Proto/Host, không thì dựng ra http://... và Meta/Google từ chối.
    redirect = web_security.external_base(
        request.url.scheme, request.url.netloc,
        request.headers.get("x-forwarded-proto", ""),
        request.headers.get("x-forwarded-host", "")) + "/connect/oauth/callback"
    res = await oauth_mcp.start_auth(conn_id, redirect)
    # start_auth FAIL (vd Meta MCP beta allowlist từ chối DCR) mà connection chưa từng có
    # token → XOÁ ngay, đừng để "xác chưa đăng nhập" nằm lại trên trang Kết nối như tài
    # khoản thật (vụ Meta Ads xoá rồi cứ mọc lại mỗi lần bấm thử nút Kết nối).
    if not res.get("ok") and conn_id and not oauth_mcp.status(conn_id).get("connected"):
        # Kết nối TỰ THÊM (form URL) do người dùng gõ tay: xoá là mất luôn thứ họ vừa nhập.
        # Trả về auth=header để nút "Kết nối lại" lại mở form Sửa như cũ.
        if (mcp_store.get_connection(conn_id) or {}).get("connector_id") == "custom":
            mcp_store.update_connection(conn_id, {"auth": "header"})
            mcp_hub.invalidate_cache()
            return {"ok": False, "id": conn_id, "auth": "header",
                    "error": res.get("error") or localefmt.chu("Không mở được trang đăng nhập.", "Could not open the sign-in page.")}
        oauth_mcp.forget(conn_id)
        connect_health.forget(conn_id)
        mcp_store.delete_connection(conn_id)
        mcp_hub.invalidate_cache()
        return {"ok": False, "error": res.get("error") or localefmt.chu("Không mở được trang đăng nhập.", "Could not open the sign-in page.")}
    res["id"] = conn_id
    if not res.get("ok") and conn_id:
        res["auth"] = (mcp_store.get_connection(conn_id) or {}).get("auth")
    return res


@app.get("/connect/oauth/callback")
async def connect_oauth_callback(state: str = Query(""), code: str = Query(""), error: str = Query(""),
                                 error_description: str = Query("")):
    # 0.175.1: nhà cung cấp báo lỗi ở bước xin quyền (vd invalid_scope của Higgsfield/Clerk) thì không có code; đọc lỗi thật.
    # invalid_scope có cách gỡ: oauth_mcp bỏ phạm vi bị từ chối và trả trang đăng nhập mới, chuyển thẳng sang đó.
    res = await oauth_mcp.handle_callback(state, code, error, error_description)
    mcp_hub.invalidate_cache()
    if res.get("retry_url"):
        return RedirectResponse(url=res["retry_url"], status_code=302)
    if res.get("ok"):
        _write_codex_profile()
        # Vừa có token: kiểm lại đèn ngay, không thì chip vẫn báo "Kết nối lại" tới vòng quét
        # nền kế tiếp (600s) dù kết nối đã chạy được.
        try:
            await connect_health.check_by_id(res.get("conn_id"))
        except Exception as e:
            print(f"[oauth health] {type(e).__name__}: {e}", file=sys.stderr)
        # Tự đặt tên tài khoản như flow dán key (vd lấy tên tài khoản ads từ Meta) -
        # chỉ ở lần đăng nhập ĐẦU và khi label còn là tên mặc định (đăng nhập lại giữ tên user
        # đã đặt, kể cả khi trùng tên connector); lỗi thì bỏ qua, không phá trang báo thành công.
        try:
            cid = res.get("conn_id")
            c = mcp_store.get_connection(cid) or {}
            con = mcp_catalog.get(c.get("connector_id")) or {}
            if (cid and res.get("first_auth", True)
                    and c.get("label") in ("", None, con.get("name"), c.get("connector_id"))):
                label = res.get("email") or ""   # email từ id_token (Google) chắc chắn hơn validate
                if not label:
                    val = await mcp_hub.validate_connection(cid)
                    label = val.get("label") or ""
                if label:
                    mcp_store.update_connection(cid, {"label": label})
        except Exception as e:
            print(f"[oauth label] {e}")
        html = ("<html><body style='font-family:sans-serif;background:#111;color:#eee;text-align:center;padding-top:80px'>"
                + localefmt.chu("<h2>✓ Đã kết nối thành công</h2><p>Đóng tab này và quay lại Javis, bấm Làm mới ở trang Kết nối.</p>",
                                "<h2>✓ Connected successfully</h2><p>Close this tab, go back to Javis and click Refresh on the Connections page.</p>")
                + "</body></html>")
    else:
        html = (f"<html><body style='font-family:sans-serif;background:#111;color:#eee;text-align:center;padding-top:80px'>"
                + localefmt.chu("<h2>⚠ Kết nối thất bại</h2>", "<h2>⚠ Connection failed</h2>")
                # Lời báo có thể mang error_description do nhà cung cấp (qua URL) gửi về: escape, không chèn HTML thô.
                + f"<p>{html_mod.escape(str(res.get('error', '')))}</p></body></html>")
    return HTMLResponse(html)


@app.get("/settings")  # def thường, xem ghi chú ở list_agents
def settings_get():
    cfg = cfgmod.read_settings()
    safe = json.loads(json.dumps(cfg))
    safe["auth"] = {"username": cfg["auth"].get("username", ""), "has_password": bool(cfg["auth"].get("password_hash"))}
    # Danh sách ngôn ngữ đi kèm cài đặt luôn, thay vì bắt dashboard gọi thêm một endpoint.
    # Nguồn duy nhất là sổ đăng ký phía server: dashboard KHÔNG khai lại danh sách, nếu không
    # thì thêm ngôn ngữ mới phải nhớ sửa hai chỗ và chỗ bị quên hỏng trong im lặng.
    safe["lang_list"] = lang_registry.cho_giao_dien()
    # Interface pickers also offer dashboard-only dictionaries (a community xx.json, 0.99.0); `lang_list` stays the
    # languages the server itself speaks, which is what reply language and voice may choose from.
    safe["ui_lang_list"] = safe["lang_list"] + lang_registry.dashboard_only_languages(DASHBOARD_PATH / "i18n")
    # Gói locale (múi giờ, tiền tệ, locale định dạng số). Dashboard KHÔNG tự suy nó từ ngôn
    # ngữ: hai thứ đó tách rời, người dùng đọc tiếng Anh mà vẫn ngồi ở UTC+7 là bình thường.
    safe["locale_fmt"] = localefmt.cho_giao_dien()
    # Che MỌI key_field của PROVIDER_DEFS, không liệt kê tay: danh sách tay cũ sót ollama_key
    # nên key Ollama Cloud đi nguyên văn ra trình duyệt.
    for kf in _PROVIDER_KEY_FIELDS:
        k = cfg["model"].get(kf, "")
        safe["model"][kf] = ("••••" + k[-4:]) if k else ""
        safe["model"][kf + "_set"] = bool(k)
    # 0.350.0: account keys never leave the server. The Models page gets each card's accounts with the last 4 characters.
    safe["model"].pop("account_keys", None)
    safe["model"]["accounts"] = {
        pid: [{"id": a["id"], "label": a["label"], "enabled": a["enabled"],
               "key": ("••••" + a["key"][-4:]) if a["key"] else "",
               "resting_until": model_routing.resting_until(pid, a["id"])}
              for a in model_routing.accounts(cfg["model"], pid, kf)]
        for pid, kf in _routing_key_fields().items() if model_routing.accounts(cfg["model"], pid, kf)}
    for pid in plan_accounts.KIND:   # plan cards: account 1 plus any extra account (0.353.0)
        try:
            safe["model"]["accounts"][pid] = plan_accounts.view(cfg["model"], pid)
        except Exception as e:  # noqa: BLE001 - one unreadable folder must not take the settings page down
            print(f"[plan accounts] view {pid}: {type(e).__name__}: {e}", file=sys.stderr)
    o = cfg["model"].get("openai_oauth") or {}
    safe["model"]["openai_oauth"] = {   # che token, chỉ lộ trạng thái
        "connected": bool(o.get("access_token") or o.get("refresh_token")),
        "account_id": o.get("account_id", ""), "plan": o.get("plan", ""),
    }
    tok = cfg["telegram"].get("token", "")
    safe["telegram"]["token"] = ("••••" + tok[-4:]) if tok else ""
    safe["telegram"]["token_set"] = bool(tok)
    for _oc in owner_channels.ALL:
        _sec, _keys = _oc.key, _oc.secret_fields
        safe.setdefault(_sec, {})
        for _k in _keys:
            _v = str((cfg.get(_sec, {}) or {}).get(_k, "") or "")
            safe[_sec][_k] = ("••••" + _v[-4:]) if _v else ""
            safe[_sec][_k + "_set"] = bool(_v)
    vk = (cfg.get("voice", {}) or {}).get("elevenlabs_key", "")
    safe.setdefault("voice", {})
    safe["voice"]["elevenlabs_key"] = ("••••" + vk[-4:]) if vk else ""
    safe["voice"]["elevenlabs_key_set"] = bool(vk)
    # The tunnel token never leaves the server; Settings reads /remote-access/status instead.
    safe.pop("remote_tunnel", None)
    bt = (cfg.get("backup", {}) or {}).get("token", "")
    safe.setdefault("backup", {})
    safe["backup"]["token"] = ("••••" + bt[-4:]) if bt else ""
    safe["backup"]["token_set"] = bool(bt)
    safe["model"]["providers"] = _providers_view(cfg)   # danh sách provider + trạng thái + model
    safe["model"]["main"] = _effective_main(cfg)         # model chính hiệu lực (suy từ legacy nếu cần)
    safe["model"]["routing"] = _routing_view(cfg["model"], safe["model"]["providers"])
    return safe


def _default_model_name(mcfg, prov: str) -> str:
    """The model a card runs when its model is left on "default" (0.355.0, owner 27/10: "default" alone tells nothing).
    "" when only the CLI itself knows (it picks by plan and we cannot read it): the page then says "default" alone."""
    try:
        if prov == "openrouter" and (mcfg.get("openrouter_model") or "").strip():
            return mcfg["openrouter_model"].strip()
        if prov in engine.DEFAULT_MODELS:
            return engine.DEFAULT_MODELS[prov]
        if prov == "openai-oauth":
            m = _codex_safe_model("")
            if m:
                return m
            cfg = grok_cli._doc_toml(plan_accounts.default_home(prov) / "config.toml")
            return str(cfg.get("model") or "").strip()
        if prov == "anthropic-cli":
            m = (mcfg.get("claude_model") or "").strip()
            if m:
                return m
            f = plan_accounts.default_home(prov) / "settings.json"
            return str((json.loads(f.read_text(encoding="utf-8")) or {}).get("model") or "").strip() if f.is_file() else ""
        if prov == "grok-cli":
            cfg = grok_cli._doc_toml(plan_accounts.default_home(prov) / "config.toml")
            return str(((cfg.get("models") or {}) or {}).get("default") or "").strip()
    except Exception:  # noqa: BLE001 - an unreadable config only means the plain "default" label
        pass
    return ""


def _routing_view(mcfg, providers) -> dict:
    """What the Models page draws (spec 2.1-2.4): the usage order of signed-in cards, each card's model and effort,
    the background model, and which card chat and background work run on right now. Built from the provider list
    already computed for this response, so the page costs no second round of CLI checks."""
    conn = [p["id"] for p in providers if p.get("configured") and p.get("cli_found") is not False]
    o = model_routing.order(mcfg, conn)
    chat = next((p for p in o if _route_ready(mcfg, p)), "")
    bg = None
    try:
        for st in model_routing.background_chain(mcfg, conn, once=_ROUTING_PLAN_PROVIDERS):
            if st["provider"] in conn and _route_ready(mcfg, st["provider"]):
                bg = {"provider": st["provider"], "model": st["model"], "step": st["step"]}
                break
    except Exception as e:  # noqa: BLE001 - a broken view must not take the whole settings page down
        print(f"[routing] view: {type(e).__name__}: {e}", file=sys.stderr)
    return {"order": o, "profiles": {p: model_routing.profile(mcfg, p) for p in o},
            "background": model_routing.background_spec(mcfg), "chat_in_use": chat, "bg_in_use": bg,
            "multi_key": list(_routing_key_fields()), "multi_plan": list(plan_accounts.KIND),
            "defaults": {p["id"]: d for p in providers if (d := _default_model_name(mcfg, p["id"]))}}


@app.post("/settings")
async def settings_set(section: str = Form(...), data: str = Form("{}")):
    cfg = cfgmod.read_settings()
    try:
        patch = json.loads(data)
    except json.JSONDecodeError:
        return JSONResponse({"ok": False, "error": localefmt.chu("data không phải JSON", "data is not JSON")}, status_code=400)

    if section == "locale":
        # Nhánh RIÊNG chứ không nhét vào "general": endpoint này dùng allowlist TỪNG KEY chứ
        # không merge, nên key nào không có tên trong một nhánh sẽ bị bỏ trong khi vẫn trả
        # {"ok": true} và nút vẫn hiện "Đã lưu". Một cụm cài đặt mới mà quên nhánh của nó thì
        # người dùng bấm lưu, thấy báo thành công, F5 xong mất sạch - không lỗi, không log.
        lc = cfg.setdefault("locale", {})
        if "reply_lang" in patch:
            v = str(patch["reply_lang"] or "").strip().lower()
            # "auto" là giá trị HỢP LỆ, không phải chuỗi rỗng: nó nghĩa là "bám theo người
            # dùng", khác hẳn với "chưa chọn".
            lc["reply_lang"] = "auto" if v in ("", "auto") else (lang_registry.chuan_hoa(v) or "auto")
        if "ui_lang" in patch:
            lc["ui_lang"] = lang_registry.chuan_hoa(patch["ui_lang"]) or lang_registry.MAC_DINH
            # Nguồn của giá trị: "tu_dong" = dashboard tự ghi theo trình duyệt của thiết bị ghé
            # đầu tiên, "chon" = người dùng chọn. Chỉ giá trị người CHỌN mới được áp lên thiết bị
            # khác (console.js); không thì người ghé đầu tiên quyết định ngôn ngữ của mọi người.
            lc["ui_lang_nguon"] = "tu_dong" if patch.get("tu_dong") else "chon"
            _doi_ngon_ngu_hat_giong(lc["ui_lang"])
        if "tz" in patch:
            lc["tz"] = str(patch["tz"] or "").strip() or "Asia/Ho_Chi_Minh"
        if "currency" in patch:
            lc["currency"] = str(patch["currency"] or "").strip().upper() or "VND"
    elif section == "general":
        if "workspace_name" in patch:
            cfg["workspace_name"] = patch["workspace_name"] or "Javis OS"
        if "setup_done" in patch:
            cfg["setup_done"] = bool(patch["setup_done"])
    elif section == "model":
        m = cfg["model"]
        # Đặt model chính theo provider (UI mới)
        if patch.get("main"):
            prov = patch["main"].get("provider"); mod = patch["main"].get("model")
            if _provider_def(prov) and mod:
                _set_main_model(cfg, prov, mod)
        # Nhập credential provider (chỉ ghi khi có giá trị mới - tránh xoá bằng giá trị che ••••)
        # Lấy từ PROVIDER_DEFS: danh sách tay cũ sót ollama_key, dán key Ollama Cloud rồi bấm
        # Kết nối là báo đã lưu mà không lưu gì.
        for kf in _PROVIDER_KEY_FIELDS:
            if patch.get(kf) and not str(patch[kf]).startswith("••••"):
                m[kf] = str(patch[kf]).strip()
                _routing_key_saved(m, kf)
        if "openai_compat_base" in patch:
            new_base = str(patch["openai_compat_base"] or "").strip().rstrip("/")
            if new_base != (m.get("openai_compat_base") or "") and not (
                    patch.get("openai_compat_key") and
                    not str(patch["openai_compat_key"]).startswith("••••")):
                # A saved key belongs to its old endpoint. Never carry it to a new URL.
                m["openai_compat_key"] = ""
            m["openai_compat_base"] = new_base
            _PROV_MODELS_CACHE.pop("openai-compat", None)
        if "anthropic_compat_base" in patch:
            new_base = engine.normalize_anthropic_compat_base(str(patch["anthropic_compat_base"] or ""))
            if new_base != (m.get("anthropic_compat_base") or "") and not (
                    patch.get("anthropic_compat_key") and
                    not str(patch["anthropic_compat_key"]).startswith("••••")):
                m["anthropic_compat_key"] = ""   # a saved key belongs to its old gateway
            m["anthropic_compat_base"] = new_base
            _PROV_MODELS_CACHE.pop("anthropic-compat", None)
        # Ngắt kết nối 1 provider (xoá key). Nếu nó đang là MAIN → quay về Claude Code CLI để chat không gãy.
        if patch.get("clear_key"):
            d = _provider_def(patch["clear_key"])
            if d and d.get("key_field"):
                m[d["key_field"]] = ""
                # 0.350.0: every key of the card goes, and the card leaves the usage order (the next card becomes MAIN).
                if d["id"] not in _ROUTING_SINGLE_KEY:
                    model_routing.save_accounts(m, d["id"], [], d["key_field"])
                model_routing.drop_from_order(m, d["id"])
                if patch["clear_key"] == "openai-compat":
                    m["openai_compat_base"] = ""
                    _PROV_MODELS_CACHE.pop("openai-compat", None)
                if patch["clear_key"] == "anthropic-compat":
                    m["anthropic_compat_base"] = ""
                    m["anthropic_compat_models"] = []
                    _PROV_MODELS_CACHE.pop("anthropic-compat", None)
                if _effective_main(cfg).get("provider") == patch["clear_key"]:
                    _set_main_model(cfg, "anthropic-cli", m.get("claude_model") or "opus")
        # Gói Claude Code xác thực bằng gì: phiên subscription sẵn có, hay API key riêng.
        # Giá trị lạ về "subscription" thay vì báo lỗi - đây là ô hai lựa chọn, gõ sai thì lui
        # về cái không tốn tiền của người dùng chứ không làm chết đường chat.
        if "claude_auth" in patch:
            m["claude_auth"] = (claude_auth.API_KEY
                                if str(patch["claude_auth"] or "").strip().lower() == claude_auth.API_KEY
                                else claude_auth.SUBSCRIPTION)
        if "auxiliary" in patch:   # model phụ cho việc nền (provider + model)
            aux_patch = patch["auxiliary"] or {}
            aux = m.setdefault("auxiliary", {})
            if "model" in aux_patch or "provider" in aux_patch:
                aux["model"] = aux_patch.get("model", "")
                # Thiếu provider (client cũ) = Claude, đúng hành vi trước khi mở nhiều provider.
                prov = aux_patch.get("provider") or aux_engine.CLAUDE
                aux["provider"] = prov if _provider_def(prov) else aux_engine.CLAUDE
            if "reasoning" in aux_patch:   # 0.350.0: the background model keeps its own effort
                r = aux_patch["reasoning"]
                aux["reasoning"] = r if r in engine.REASONING_LEVELS else "off"
        if "telegram" in patch:   # model riêng cho kênh Telegram; provider rỗng = theo model chính
            tg_patch = patch["telegram"] or {}
            tg = m.setdefault("telegram", {})
            prov = (tg_patch.get("provider") or "").strip()
            tg["provider"] = prov if (prov and _provider_def(prov)) else ""
            tg["model"] = (tg_patch.get("model") or "").strip() if tg["provider"] else ""
        # Độ sâu suy nghĩ. Danh sách nấc lấy từ engine.REASONING_LEVELS - đường LƯU này và
        # đường ĐỌC (_reasoning_level) phải soi CÙNG một nguồn, nếu không thêm nấc mới là
        # giao diện cho chọn mà server lặng lẽ hạ về "off".
        if "reasoning" in patch:
            r = patch["reasoning"]
            m["reasoning"] = r if r in engine.REASONING_LEVELS else "off"
            # 0.350.0: the composer's effort chip is MAIN's card effort.
            model_routing.set_profile(m, model_routing.main_provider(m), reasoning=m["reasoning"])
        # 0.350.0 Models page: usage order, one card's model/effort, one card's accounts or keys.
        if isinstance(patch.get("order"), list):
            ids = [p for p in patch["order"] if _provider_def(str(p or ""))]
            if ids:
                model_routing.set_order(m, ids)
                _sync_legacy_engine(m)
        if isinstance(patch.get("profile"), dict):
            pp = patch["profile"]
            pid = str(pp.get("provider") or "")
            if _provider_def(pid):
                r = pp.get("reasoning")
                model_routing.set_profile(m, pid, model=pp.get("model") if "model" in pp else None,
                                          reasoning=(r if r in engine.REASONING_LEVELS else "off") if "reasoning" in pp else None)
                if model_routing.main_provider(m) == pid:
                    _sync_legacy_engine(m)
        if isinstance(patch.get("accounts"), dict):
            pa = patch["accounts"]
            pid = str(pa.get("provider") or "")
            kf = _routing_key_fields().get(pid)
            if plan_accounts.supported(pid) and isinstance(pa.get("items"), list):
                # A plan card's accounts carry no key: order, label and on/off only. Removing one deletes its login
                # folder; account 1 (the machine's own login) stays (0.353.0).
                plan_accounts.save(m, pid, pa["items"], removed=pa.get("removed"))
            if kf and isinstance(pa.get("items"), list):
                items = []
                cur = {a["id"]: a for a in model_routing.accounts(m, pid, kf)}
                for it in pa["items"]:
                    if not isinstance(it, dict):
                        continue
                    aid = str(it.get("id") or "") or model_routing.new_account_id()
                    key = str(it.get("key") or "").strip()
                    if key.startswith("••••"):
                        key = ""
                    if not key and aid not in cur:
                        continue                      # a new account needs its key
                    items.append({"id": aid, "label": str(it.get("label") or ""),
                                  "enabled": it.get("enabled") is not False, "key": key or cur.get(aid, {}).get("key", "")})
                if pa["items"] and not items:
                    items = None                      # nothing valid in a non-empty list: never wipe the card for that
                if items is not None:
                    model_routing.save_accounts(m, pid, items, kf)
                if items:
                    model_routing.add_to_order(m, pid)
                elif items is not None:
                    model_routing.drop_from_order(m, pid)
        # Fast mode (composer bolt, 0.153.0). This POST drops unknown keys, so it needs its own branch.
        if "fast" in patch:
            m["fast"] = patch["fast"] is True
        # Daily Claude Code update switch (Models page). Same reason for its own branch as above.
        if claude_update.SETTING_KEY in patch:
            m[claude_update.SETTING_KEY] = patch[claude_update.SETTING_KEY] is True
        # Legacy trực tiếp (tương thích ngược)
        for k in ("engine", "claude_model", "openrouter_model"):
            if k in patch:
                m[k] = patch[k]
    elif section == "telegram":
        t = cfg["telegram"]
        if "enabled" in patch:
            t["enabled"] = bool(patch["enabled"])
        if "chat_id" in patch:
            # Nhận MỘT hoặc NHIỀU ID ("id1, id2" / list) → chuẩn hoá lưu "id1,id2".
            t["chat_id"] = ",".join(tg_parse_ids(patch["chat_id"]))
        if "owner_chat_id" in patch:
            # 0.186.0: the owner's OWN chat, where reports without a chat of their own go (_owner_telegram_id).
            # Only an id on the allow-list counts; anything else clears the link instead of storing a stranger.
            own = str(patch.get("owner_chat_id") or "").strip()
            t["owner_chat_id"] = own if own in tg_parse_ids(t.get("chat_id")) else ""
        if patch.get("token"):
            t["token"] = patch["token"]
    elif section == "push":
        # 0.187.0: "hidden" = push notifications say only that something arrived, without its text.
        if "preview" in patch:
            cfg.setdefault("push", {})["preview"] = "hidden" if patch.get("preview") == "hidden" else "full"
    elif section == "zalo_bot":
        # Cùng khuôn với telegram. Id Zalo là chuỗi HEX chứ không phải số, nhưng `tg_parse_ids`
        # chỉ tách và bỏ trùng chứ không ép kiểu nên dùng chung được.
        z = cfg.setdefault("zalo_bot", {"enabled": False, "token": "", "chat_id": ""})
        if "enabled" in patch:
            z["enabled"] = bool(patch["enabled"])
        if "chat_id" in patch:
            z["chat_id"] = ",".join(tg_parse_ids(patch["chat_id"]))
        if patch.get("token"):
            z["token"] = patch["token"]
    elif owner_channels.get(section):
        # Slack, WhatsApp, Discord, Lark: each channel describes its own fields
        # (owner_channels.OwnerChannel.plain / secret_fields). Secrets are only overwritten when
        # a new value is sent: the form shows masked values and an empty field means "keep what
        # is saved", like the Telegram token.
        _oc = owner_channels.get(section)
        sec = cfg.setdefault(section, {})
        if "enabled" in patch:
            sec["enabled"] = bool(patch["enabled"])
        if "allow" in patch:
            sec["allow"] = ", ".join(tg_parse_ids(patch["allow"]))
        for k, norm in _oc.plain.items():
            if k in patch:
                sec[k] = norm(patch[k])
        for k in _oc.secret_fields:
            v = str(patch.get(k) or "").strip()
            if v and not v.startswith("••••"):
                sec[k] = v
    elif section == "dashboard":
        cfg.setdefault("dashboard", {})
        if "graph_enabled" in patch:
            cfg["dashboard"]["graph_enabled"] = bool(patch["graph_enabled"])
        if "auto_resume" in patch:
            cfg["dashboard"]["auto_resume"] = bool(patch["auto_resume"])
        if "pet" in patch:
            # Linh vật góc màn hình (dashboard/pet.js). LỌC TỪNG KHOÁ chứ không nuốt cả
            # object: đây là thứ được ghi từ trình duyệt, và một object tự do trong
            # settings.json là chỗ để rác lọt vào rồi ở lại mãi.
            pet_cu = cfg["dashboard"].get("pet") or {}
            pet_moi = patch.get("pet") or {}
            if not isinstance(pet_moi, dict):
                pet_moi = {}
            pet = dict(pet_cu)
            if "enabled" in pet_moi:
                pet["enabled"] = bool(pet_moi["enabled"])
            for k in ("shape", "palette", "side", "size", "eye", "eyeSize"):
                v = pet_moi.get(k)
                # Từ 0.64.39 cỡ thân và cỡ mắt là THANH TRƯỢT nên tới đây dưới dạng SỐ (px và
                # hệ số). Kẹp vào khoảng pet.js cho phép; tên nấc cũ ("vua", "to") vẫn đi
                # nhánh chuỗi bên dưới cho client cũ. bool là con của int nên loại riêng.
                if k in ("size", "eyeSize") and isinstance(v, (int, float)) and not isinstance(v, bool):
                    if k == "size":
                        pet[k] = int(max(44, min(150, round(v))))
                    else:
                        pet[k] = round(max(0.8, min(1.5, float(v))), 2)
                    continue
                # Gạch dưới cũng là ký tự HỢP LỆ: khoá cỡ lớn nhất tên là "rat_lon", mà luật
                # cũ chỉ tha dấu gạch ngang nên isalnum() trả False và cỡ đó bị loại LẶNG LẼ -
                # người dùng chọn "Rất lớn", màn hình đổi ngay, F5 xong về cỡ cũ mà không có
                # một dòng lỗi nào (chủ dự án báo 15/09).
                if isinstance(v, str) and 0 < len(v) <= 24 and v.replace("-", "").replace("_", "").isalnum():
                    pet[k] = v
            # Mã màu của ô TỰ CHỌN (thân và mắt). Chỉ nhận đúng "#rrggbb": thứ này đi thẳng
            # vào thuộc tính style ở trình duyệt, không được để chuỗi tự do lọt qua.
            for k in ("color", "eyeColor"):
                v = pet_moi.get(k)
                if isinstance(v, str) and re.fullmatch(r"#[0-9a-fA-F]{6}", v):
                    pet[k] = v.lower()
            if "pos" in pet_moi:
                try:
                    pet["pos"] = max(0.0, min(1.0, float(pet_moi["pos"])))
                except (TypeError, ValueError):
                    pass
            cfg["dashboard"]["pet"] = pet
    elif section == "image":
        cfg.setdefault("image", {})
        if "strip_c2pa" in patch:
            cfg["image"]["strip_c2pa"] = bool(patch["strip_c2pa"])
    elif section == "voice":
        v = cfg.setdefault("voice", {})
        if patch.get("tts_provider") in ("edge", "openai", "elevenlabs"):
            v["tts_provider"] = patch["tts_provider"]
        for k in ("openai_tts_voice", "openai_tts_model", "elevenlabs_voice"):
            if patch.get(k):
                v[k] = str(patch[k]).strip()
        # 0.298.0: the Edge voice is kept here too, not only in one browser's localStorage. Before, a voice
        # picked on the laptop never reached the phone (it kept its old voice) nor the voice notes.
        if "edge_voice" in patch and voice_note.valid_edge_voice(patch.get("edge_voice")):
            v["edge_voice"] = str(patch["edge_voice"]).strip()
        import tts_eleven   # 0.255.0: only a model the settings page offers
        if str(patch.get("elevenlabs_model") or "").strip() in tts_eleven.MODELS:
            v["elevenlabs_model"] = str(patch["elevenlabs_model"]).strip()
        # Chỉ ghi khi có key mới THẬT: client lỡ gửi lại giá trị che "••••abcd" (lấy từ GET
        # /settings rồi POST nguyên object về) mà lưu thì đè mất key thật.
        if patch.get("elevenlabs_key") and not patch["elevenlabs_key"].strip().startswith("••••"):
            v["elevenlabs_key"] = patch["elevenlabs_key"].strip()
        # Voice V2 (chế độ nói chuyện, bộ não giọng, nghe bằng gì, nhà cung cấp Live). Ô CHỌN chỉ
        # nhận giá trị có trong danh sách gốc (voice_brain / voice_live) để giá trị lạ không âm
        # thầm làm hỏng lượt nói; ô GÕ nhận cả chuỗi rỗng vì "để trống" là lựa chọn THẬT (bỏ bộ
        # não giọng, hay dùng tên model mặc định của hãng).
        # Thêm ô mới ở thẻ cài đặt giọng nói thì PHẢI nối thêm vào đây: endpoint này dùng
        # allowlist từng key, quên là người dùng bấm Lưu thấy báo xong mà F5 là mất sạch
        # (test_luu_cai_dat_giong.py canh đúng chuyện đó).
        if patch.get("mode") in voice_brain.MODES:
            v["mode"] = patch["mode"]
        if "brain_provider" in patch and str(patch["brain_provider"] or "") in voice_brain.BRAIN_PROVIDERS:
            v["brain_provider"] = str(patch["brain_provider"] or "")
        if patch.get("stt_provider") in voice_brain.STT_PROVIDERS:
            v["stt_provider"] = patch["stt_provider"]
        # Tai nghe lại (0.65.15) thay cho stt_provider: auto | groq | openai | off (voice_ear.CHOICES).
        if patch.get("ear") in voice_ear.CHOICES:
            v["ear"] = patch["ear"]
        # Giọng của ChatGPT Live (realtime v3 chỉ nhận 9 giọng riêng, mặc định juniper).
        if patch.get("chatgpt_voice") in voice_live.CHATGPT_VOICES:
            v["chatgpt_voice"] = patch["chatgpt_voice"]
        # Đường gọi của nút mic (0.65.18): auto | chatgpt | api | basic (voice_call.ENGINES).
        if patch.get("call_engine") in voice_call.ENGINES:
            v["call_engine"] = patch["call_engine"]
        if patch.get("live_provider") in voice_live.PROVIDERS:
            v["live_provider"] = patch["live_provider"]
        # Live over an API key (0.220.0): ignore speech not meant for Javis, and the reply pace.
        if "live_proactive" in patch:
            v["live_proactive"] = bool(patch["live_proactive"])
        if patch.get("live_turn") in voice_live.TURN_PRESETS:
            v["live_turn"] = patch["live_turn"]
        # Focus is a browser attention gate. Keep the legacy setting for older clients.
        if "loc_tap_am" in patch:
            v["loc_tap_am"] = bool(patch["loc_tap_am"])
        if "focus_mode" in patch:
            v["focus_mode"] = bool(patch["focus_mode"])
        # 0.65.26: model của bộ não giọng lưu theo TỪNG bộ não (brain_models = {bộ não: model}); ô
        # Model gửi kèm brain_model_for. Client cũ không gửi brain_model_for thì vẫn ghi khoá chung
        # brain_model như trước, nhưng khoá đó nay bị bỏ qua lúc chạy (voice_brain.brain_model_for).
        model_for = str(patch.get("brain_model_for") or "")
        if "brain_model" in patch and model_for and model_for in voice_brain.BRAIN_PROVIDERS:
            models = dict(v["brain_models"]) if isinstance(v.get("brain_models"), dict) else {}
            name = str(patch["brain_model"] or "").strip()
            if name:
                models[model_for] = name
            else:
                models.pop(model_for, None)   # rỗng = về model mặc định của hãng
            v["brain_models"] = models
        for k in ("brain_model", "stt_model", "live_model", "live_voice"):
            if k in patch and not (k == "brain_model" and model_for):
                v[k] = str(patch[k] or "").strip()
        # Từ hay nghe nhầm (hotwords): chuỗi tự do, chuẩn hoá qua nghe_sua để lưu gọn; rỗng là
        # xoá hết từ người dùng khai (tên trợ lý vẫn luôn có, không cần lưu).
        if "hotwords" in patch:
            v["hotwords"] = ", ".join(nghe_sua.tach_tu_vung(patch.get("hotwords")))
    elif section == "password":
        # Đổi mật khẩu KHÔNG đi qua đây nữa - xem /auth/password. Đường này không đòi mật khẩu
        # hiện tại VÀ nhận cả token API scope `full`, nghĩa là một token rò ra là đổi được mật
        # khẩu chủ máy rồi khoá chính chủ ra ngoài. Nó cũng nhận mật khẩu 4 ký tự trong khi mọi
        # đường khác đòi 8.
        return JSONResponse({"ok": False, "error": localefmt.chu(
            "Đổi mật khẩu chuyển sang trang Tài khoản "
            "(phải nhập mật khẩu hiện tại). Tải lại trang "
            "nếu vẫn thấy form cũ.",
            "Changing the password moved to the Account page "
            "(the current password is required). Reload the page "
            "if you still see the old form.")}, status_code=400)
    else:
        return JSONResponse({"ok": False, "error": localefmt.chu("section không hợp lệ", "invalid section")}, status_code=400)

    cfgmod.write_settings(cfg)
    if section == "model":
        # Đổi Main Model / model việc nền / nguồn xác thực Claude xong thì đèn báo não phải
        # phản ánh cấu hình MỚI ngay lượt poll kế (90s), không chờ vòng probe 10 phút.
        # Đổi claude_auth là đổi hẳn cách xác thực → bằng chứng lỗi cũ (kể cả đèn đỏ do lượt
        # chạy bật) lỗi thời, xoá rồi probe lại; các thay đổi khác chỉ cần probe thường.
        try:
            if "claude_auth" in patch:
                connect_health.engine_reconnected("claude")
            elif set(patch) == {claude_update.SETTING_KEY}:
                pass   # the update switch changes no engine, so there is nothing to re-probe
            else:
                connect_health.probe_engines()
        except Exception as e:
            print(f"[engine health] probe sau đổi model lỗi: {e}", file=__import__('sys').stderr)
    if section == "telegram":
        try:
            restart_telegram()   # áp cấu hình bot ngay
        except Exception as e:
            print(f"[telegram restart] {e}", file=__import__('sys').stderr)
    if section == "zalo_bot":
        try:
            restart_zalo_bot()   # áp cấu hình bot ngay
        except Exception as e:
            print(f"[zalo restart] {e}", file=__import__('sys').stderr)
    if owner_channels.get(section):
        try:
            owner_channels.get(section).restart()
        except Exception as e:
            print(f"[{section} restart] {e}", file=__import__('sys').stderr)
    if section == "voice":
        cfgmod.apply_tool_env(cfg)   # key ElevenLabs -> env cho tool ngoài (video-use) ngay, không cần restart
    return {"ok": True}


# ============================================================
# ĐỒNG BỘ brain với GitHub - 2 CHIỀU (kéo về + hoà nhập + đẩy lên).
# Dùng được nhiều máy (local + VPS) chung 1 repo: các máy tự khớp nhau qua repo.
# UI + hướng dẫn ở trang Tự học (console.js renderLearn). Token lưu settings.json (gitignored).
# ============================================================
def _do_backup(brain: str = "") -> dict:
    """Đồng bộ 2 CHIỀU toàn bộ thư mục brains với repo GitHub. Tham số brain giữ cho
    tương thích chữ ký cũ nhưng KHÔNG dùng - luôn đồng bộ cả BRAINS_DIR.
    Cập nhật last_backup/last_status/last_report."""
    cfg = cfgmod.read_settings()
    b = cfg.get("backup", {}) or {}
    if not (b.get("repo_url") and b.get("token")):
        return {"ok": False, "error": localefmt.chu("Chưa cấu hình repo URL + token", "Repo URL and token are not configured yet")}
    mirror = str(cfgmod.STATE_DIR / "brains-backup")   # repo mirror riêng (tránh nested git từng brain)
    res = git_brain.sync_brains(BRAINS_DIR, mirror, b["repo_url"], b["token"], b.get("branch") or "main",
                                trash_dir=str(cfgmod.STATE_DIR / "brain-trash"),
                                protected_names={_default_brain_dir().name},
                                sync_images=bool(b.get("sync_images")))
    # Ghi lại trạng thái (đọc lại cfg mới nhất để không đè thay đổi song song)
    cfg = cfgmod.read_settings()
    cfg.setdefault("backup", {})
    cfg["backup"]["last_backup"] = time.time()
    if res.get("ok"):
        bits = []
        if res.get("applied"):
            bits.append(f"nhận {res['applied']} file")
        if res.get("deleted"):
            bits.append(f"xoá {res['deleted']}")
        if res.get("conflicts"):
            bits.append(f"{len(res['conflicts'])} xung đột (giữ cả 2 bản)")
        if res.get("restored"):
            bits.append("khôi phục từ backup")
        detail = (" · " + ", ".join(bits)) if bits else ""
        cfg["backup"]["last_status"] = "✓ Đồng bộ 2 chiều " + time.strftime("%H:%M %d/%m") + detail
    else:
        cfg["backup"]["last_status"] = "✗ " + (res.get("error") or "lỗi")[:150]
    cfg["backup"]["last_report"] = {
        "ts": time.time(), "ok": bool(res.get("ok")), "pushed": bool(res.get("pushed")),
        "applied": res.get("applied", 0), "deleted": res.get("deleted", 0),
        "conflicts": (res.get("conflicts") or [])[:20], "restored": bool(res.get("restored")),
        "error": (res.get("error") or "")[:200],
    }
    cfgmod.write_settings(cfg)
    return res


@app.get("/backup/status")
async def backup_status(brain: str = Query("brain")):
    cfg = cfgmod.read_settings()
    b = cfg.get("backup", {}) or {}
    # Đếm số brain trong BRAINS_DIR (để UI báo "backup N brain")
    try:
        n_brains = len([d for d in Path(BRAINS_DIR).iterdir() if d.is_dir() and not d.name.startswith(".")])
    except Exception:
        n_brains = 0
    return {
        "enabled": bool(b.get("enabled")),
        "repo_url": b.get("repo_url", ""),
        "branch": b.get("branch", "main"),
        "interval_hours": b.get("interval_hours", 6),
        "sync_images": bool(b.get("sync_images")),
        "token_set": bool(b.get("token")),
        "last_backup": b.get("last_backup", 0.0),
        "last_status": b.get("last_status", ""),
        "last_report": b.get("last_report") or {},
        "has_git": git_brain.has_git(),
        "brains_dir": BRAINS_DIR,
        "brains_count": n_brains,
    }


@app.post("/backup/config")
async def backup_config(
    repo_url: str = Form(None), token: str = Form(None), branch: str = Form(None),
    enabled: str = Form(None), interval_hours: str = Form(None),
    sync_images: str = Form(None),
):
    cfg = cfgmod.read_settings()
    b = cfg.setdefault("backup", {})
    if repo_url is not None:
        b["repo_url"] = repo_url.strip()
    if token:                     # chỉ ghi khi có token MỚI (tránh xoá bằng chuỗi che ••••)
        b["token"] = token.strip()
    if branch:
        b["branch"] = branch.strip() or "main"
    if enabled is not None:
        b["enabled"] = enabled in ("1", "true", "True", "on")
    if sync_images is not None:
        b["sync_images"] = sync_images in ("1", "true", "True", "on")
    if interval_hours is not None:
        try:
            b["interval_hours"] = max(1, int(interval_hours))
        except ValueError:
            pass
    cfgmod.write_settings(cfg)
    return {"ok": True}


@app.post("/backup/test")
async def backup_test():
    """Kiểm tra token + repo hợp lệ (git ls-remote) trước khi bật auto."""
    cfg = cfgmod.read_settings()
    b = cfg.get("backup", {}) or {}
    return await asyncio.to_thread(git_brain.remote_reachable, b.get("repo_url", ""), b.get("token", ""))


@app.post("/backup/now")
async def backup_now(brain: str = Form("brain")):
    return await asyncio.to_thread(_do_backup, brain)


_OR_MODELS_CACHE = {"data": None, "ts": 0.0}


async def openrouter_models_index():
    """Lõi thuần của GET /openrouter/models. Dùng chung với _fetch_provider_models."""
    """Lấy danh sách model OpenRouter (API công khai, không cần key). Cache 1 giờ."""
    now = time.time()
    if _OR_MODELS_CACHE["data"] and (now - _OR_MODELS_CACHE["ts"]) < 3600:
        return {"models": _OR_MODELS_CACHE["data"], "cached": True}
    try:
        import httpx
        async with httpx.AsyncClient(timeout=15) as client:
            r = await client.get("https://openrouter.ai/api/v1/models")
            r.raise_for_status()
            raw = r.json().get("data", [])
        models = [{"id": m.get("id"), "name": m.get("name") or m.get("id")} for m in raw if m.get("id")]
        models.sort(key=lambda x: x["name"].lower())
        _OR_MODELS_CACHE["data"] = models
        _OR_MODELS_CACHE["ts"] = now
        return {"models": models}
    except Exception as e:
        return {"models": [], "error": f"{type(e).__name__}: {e}"}


@app.get("/openrouter/models")
async def openrouter_models():
    return await openrouter_models_index()


# Model load ĐỘNG theo provider (không hardcode - provider đổi model không cần sửa code).
_PROV_MODELS_CACHE = {}   # provider -> {"ids":[...], "ts": float}

# Lọc danh sách model của OpenAI và Gemini theo kiểu LOẠI TRỪ, không phải theo danh sách tiền
# tố được phép. Đây là bài học từ ca Fable 5.1 (0.55.39), chỉ khác nhà: một danh sách "chỉ giữ
# mấy cái tên quen" thì mỗi lần nhà cung cấp mở dòng mới là dòng đó biến mất khỏi trình chọn,
# im lặng, không có gì báo. Còn LOẠI theo công dụng (nhúng, giọng nói, ảnh) thì mấy loại ấy
# nhiều năm không đổi tên, nên luật không lạc hậu theo từng đợt model mới.
_OPENAI_KHONG_CHAT = ("embed", "whisper", "tts", "dall-e", "moderation", "image",
                      "audio", "realtime", "transcribe", "sora", "davinci", "babbage")
# Gemini đã có `supportedGenerationMethods` nói model nào sinh được nội dung, nên đây chỉ là
# lưới thứ hai cho vài dòng khai generateContent mà thực tế không chat được.
_GEMINI_KHONG_CHAT = ("embed", "aqa", "imagen", "veo", "tts")


def _loc_model_chat(ids, cam):
    """Bỏ những model KHÔNG chat được, khớp theo chuỗi con không phân biệt hoa thường."""
    return [i for i in ids if i and not any(k in i.lower() for k in cam)]


def _anthropic_compat_typed(m) -> list:
    """Model names the owner typed for the Anthropic-compatible gateway (0.254.0)."""
    return [str(x).strip() for x in (m.get("anthropic_compat_models") or []) if str(x).strip()]


async def _anthropic_compat_models(m, base=None, key=None):
    """Models of an Anthropic-compatible gateway: the names the owner typed first, then whatever
    {base}/v1/models lists. Many gateways have no /v1/models at all (DeepSeek's and Kimi's
    "anthropic" endpoints, most resellers), so a failed list is not an error when names were typed.
    Returns None only when there is nothing at all."""
    import httpx
    typed = _anthropic_compat_typed(m)
    base = base if base is not None else engine.anthropic_compat_base()
    if not base:
        return None
    key = key if key is not None else ((m.get("anthropic_compat_key") or "").strip() or "none")
    live = []
    try:
        async with httpx.AsyncClient(timeout=20) as c:
            r = await c.get(base + "/v1/models", headers=engine.anthropic_headers(key, compat=True))
        if r.status_code == 200:
            data = r.json().get("data") or []
            live = [x.get("id") for x in data if isinstance(x, dict) and x.get("id")]
        elif not typed:
            r.raise_for_status()
    except Exception:
        if not typed:
            raise
    return _gop_giu_thu_tu(typed, live) or None


async def _fetch_provider_models(provider, m):
    """Danh sách model id LIVE từ API của provider, hoặc None (caller fallback catalog)."""
    import httpx
    if provider == "openrouter":
        d = await openrouter_models_index()
        return [x["id"] for x in d.get("models", []) if x.get("id")] or None
    if provider == "openai":
        key = m.get("openai_api_key")
        if not key:
            return None
        async with httpx.AsyncClient(timeout=20) as c:
            r = await c.get("https://api.openai.com/v1/models", headers={"Authorization": f"Bearer {key}"})
            r.raise_for_status()
            data = r.json().get("data", [])
        ids = sorted(x.get("id") for x in data if x.get("id"))
        # LỌC NGƯỢC (xem `_OPENAI_KHONG_CHAT`): bỏ dòng không chat được, thay vì chỉ giữ mấy
        # tiền tố quen mặt. Bản cũ giữ đúng `gpt/o1/o3/o4/chatgpt` nên OpenAI mở dòng tên khác
        # là dòng đó biến mất khỏi trình chọn - y hệt ca Fable 5.1, chỉ khác nhà.
        return _loc_model_chat(ids, _OPENAI_KHONG_CHAT) or None
    if provider == "anthropic-api":
        key = m.get("anthropic_api_key")
        if not key:
            return None
        async with httpx.AsyncClient(timeout=20) as c:
            r = await c.get("https://api.anthropic.com/v1/models",
                            headers={"x-api-key": key, "anthropic-version": "2023-06-01"})
            r.raise_for_status()
            data = r.json().get("data", [])
        return [x.get("id") for x in data if x.get("id")] or None
    if provider == "gemini":
        key = m.get("gemini_api_key")
        if not key:
            return None
        async with httpx.AsyncClient(timeout=20) as c:
            r = await c.get("https://generativelanguage.googleapis.com/v1beta/models", params={"key": key})
            r.raise_for_status()
            data = r.json().get("models", [])
        # name dạng 'models/gemini-2.5-flash' → lấy đuôi. Chính Google đã nói model nào sinh
        # được nội dung qua `supportedGenerationMethods`, nên đó là bộ lọc đúng.
        #
        # Bản cũ đòi THÊM tên phải bắt đầu bằng "gemini". Điều kiện đó không thêm gì về mặt
        # đúng-sai mà chỉ chặn: khoá nào được cấp dòng khác (gemma, learnlm, hay một dòng mới
        # Google đặt tên khác) thì dòng đó không bao giờ hiện ra, im lặng như ca Fable 5.1.
        ids = [(x.get("name") or "").split("/")[-1] for x in data
               if "generateContent" in (x.get("supportedGenerationMethods") or [])]
        return sorted(_loc_model_chat(ids, _GEMINI_KHONG_CHAT)) or None
    if provider == "groq":
        key = m.get("groq_api_key")
        if not key:
            return None
        async with httpx.AsyncClient(timeout=20) as c:
            r = await c.get("https://api.groq.com/openai/v1/models",
                            headers={"Authorization": f"Bearer {key}"})
            r.raise_for_status()
            data = r.json().get("data", [])
        # Groq phục vụ cả model whisper (chuyển giọng thành chữ) và guard trên cùng endpoint -
        # lọc ra kẻo picker chat hiện model không chat được.
        ids = [x.get("id") for x in data if x.get("id")
               and not any(s in x["id"].lower() for s in ("whisper", "tts", "guard", "embed"))]
        return sorted(ids) or None
    if provider == "deepseek":
        key = m.get("deepseek_api_key")
        if not key:
            return None
        async with httpx.AsyncClient(timeout=20) as c:
            r = await c.get(engine.DEEPSEEK_MODELS_URL, headers={"Authorization": f"Bearer {key}"})
            r.raise_for_status()
            data = r.json().get("data") or []
        return sorted(x.get("id") for x in data if isinstance(x, dict) and x.get("id")) or None
    if provider == "openai-compat":
        base = engine.openai_compat_base()
        if not base:
            return None
        key = (m.get("openai_compat_key") or "").strip() or "none"
        async with httpx.AsyncClient(timeout=20) as c:
            r = await c.get(base + "/models", headers={"Authorization": f"Bearer {key}"})
            r.raise_for_status()
            data = r.json().get("data") or []
        return sorted(x.get("id") for x in data if isinstance(x, dict) and x.get("id")) or None
    if provider == "anthropic-compat":
        return await _anthropic_compat_models(m)
    if provider == "ollama":
        key = m.get("ollama_key")
        if not key:
            return None
        # Hỏi HAI đường vì Ollama phục vụ cả hai và tài liệu của họ không nói rõ đường nào là
        # chính cho bản Cloud: /v1/models là chuẩn OpenAI, /api/tags là đường gốc của Ollama.
        # Thử chuẩn trước, hụt mới sang gốc. Lỗi của đường sau mới ném ra, vì đó là lỗi người
        # dùng cần đọc. Thà thừa một request còn hơn báo "chưa thấy model" với một key đúng.
        headers = {"Authorization": f"Bearer {key}"}
        async with httpx.AsyncClient(timeout=20) as c:
            try:
                r = await c.get(engine.OLLAMA_BASE + "/v1/models", headers=headers)
                r.raise_for_status()
                ids = sorted(x.get("id") for x in (r.json().get("data") or []) if x.get("id"))
                if ids:
                    return ids
            except Exception:  # noqa: BLE001 - còn một đường nữa, chưa phải lúc bỏ cuộc
                pass
            r = await c.get(engine.OLLAMA_BASE + "/api/tags", headers=headers)
            r.raise_for_status()
            data = r.json().get("models", [])
        # `name` là tên đầy đủ kèm tag (gpt-oss:120b-cloud) - đúng thứ phải gửi lại khi chat.
        return sorted(x.get("name") for x in data if x.get("name")) or None
    if provider == "ollama-local":
        # Vụ thật 02/09: đã nối Ollama, tab Local liệt kê đủ model, vậy mà ô chọn model chính
        # vẫn báo "chưa kết nối hoặc không có model". Hàm này không có nhánh cho nhà đó nên
        # trả None, và catalog của nó thì chưa bao giờ được ghi - hai lưới cùng thủng.
        ep = (m.get("ollama_local_endpoint") or "").strip()
        if not ep:
            return None
        p = await ollama_local.probe(ep, (m.get("ollama_local_key") or "").strip())
        if not p["reachable"]:
            return None
        ids = sorted((x.get("name") or x.get("model") or "") for x in p["models"])
        # Model embedding không chat được. Bày nó ra ô chọn là mời người dùng chọn một model
        # câm: lượt chat đầu tiên trả lỗi mà không có gì trên màn hình nói vì sao.
        return [i for i in ids if i and "embed" not in i.lower()] or None
    if provider == "openai-oauth":
        # app-server là subprocess đồng bộ; chạy ở worker để request FastAPI
        # khác không đứng hình trong lúc Codex nạp catalog.
        return await asyncio.to_thread(openai_oauth.list_models, openai_oauth.valid_creds())
    if provider == "grok-cli":
        # Chạy ở worker: `list_models` có thể đẻ tiến trình con (`grok --help` để dò cờ, rồi
        # `grok models` nếu bản này có) và mất vài giây.
        return await asyncio.to_thread(grok_cli.list_models)
    if provider == "antigravity-cli":
        # `agy models` là NGUỒN CHÂN LÝ, không có bảng chép tay nào để rơi về - chạy ở worker
        # vì nó đẻ tiến trình con và có thể mất vài giây.
        return await asyncio.to_thread(antigravity_cli.list_models)
    if provider == "anthropic-cli":
        # HAI nguồn, thử theo thứ tự đầy đủ dần:
        #   1. `anthropic_api_key` nếu máy có - /v1/models là danh sách CHÍNH THỨC.
        #   2. Danh mục model nhúng trong chính binary `claude` - không cần key, không chạm
        #      credential của ai, và tự mới theo mỗi lần cập nhật Claude Code.
        # Đường 2 là thứ thay cho việc mượn token OAuth đã gỡ ở 0.26.17: từ đó tới nay gói
        # thuê bao không có nguồn live nào, nên máy nào lỡ nhớ một catalog cũ là kẹt ở đó
        # vĩnh viễn - nâng cấp Javis cũng không thấy dòng model mới (Fable 5.1).
        ids = await claude_models.fetch_models(m.get("anthropic_api_key") or "")
        if ids:
            return ids
        # Chạy ở worker: quét file binary ~200MB, cỡ 0,3 giây lần đầu rồi nhớ theo mtime.
        return await asyncio.to_thread(claude_cli.list_models)
    return None


def _gop_giu_thu_tu(*ds):
    """Nối các danh sách, bỏ trùng, GIỮ nguyên thứ tự xuất hiện đầu tiên."""
    ra, thay = [], set()
    for d in ds:
        for x in d or []:
            if x and x not in thay:
                thay.add(x)
                ra.append(x)
    return ra


def _remember_catalog(cfg, d, ids):
    """Ghi danh sách live vừa lấy vào catalog settings.

    Để lần sau mất mạng / token OAuth hết hạn thì fallback vẫn là danh sách MỚI NHẤT
    từng thấy, chứ không rơi về mấy alias cũ hardcode trong config.py.
    """
    key = d.get("catalog_key")
    if not key:
        return
    # Chặn phình settings.json (OpenRouter vài trăm model). Endpoint tự khai thì giữ đủ: cắt ở 50
    # là thẻ báo "50 model" sai sự thật với proxy có nhiều hơn.
    keep = list(ids if key in ("openai-compat", "anthropic-compat") else ids[:50])
    cat = cfg.setdefault("model", {}).setdefault("catalog", {})
    if cat.get(key) == keep:
        return
    cat[key] = keep
    try:
        cfgmod.write_settings(cfg)
    except Exception as e:
        import sys
        print(f"[models] không ghi được catalog {key}: {e}", file=sys.stderr)


def _vi_sao_khong_co_model(provider: str, m: dict) -> str:
    """Vì sao provider này không trả về model nào - viết cho NGƯỜI ĐỌC, không phải log.

    Hầu hết đường lấy model hỏng theo kiểu IM LẶNG: hàm trả None chứ không ném lỗi, nên phía
    trên chỉ còn một danh sách rỗng và giao diện đành nói "không có model" - đúng nhưng vô
    dụng. ChatGPT là ca nặng nhất vì nó KHÔNG có catalog dự phòng (danh sách model do Codex
    quyết, Javis cố ý không ghim version), nên hỏng là thẻ hiện đúng "0 model" ngay sau khi
    người dùng vừa đăng nhập xong - trông y như đăng nhập hỏng.
    """
    d = _provider_def(provider) or {}
    if provider == "openai-oauth":
        if not (openai_oauth.valid_creds() or {}).get("access_token"):
            return localefmt.chu("Chưa kết nối ChatGPT (hoặc phiên đăng nhập đã hết hạn) - "
                                 "đăng nhập lại ở thẻ ChatGPT.",
                                 "ChatGPT is not connected (or the sign-in expired) - "
                                 "sign in again on the ChatGPT card.")
        if not find_codex_cli():
            return localefmt.chu(
                "Không thấy Codex CLI trên máy - danh sách model của gói ChatGPT do chính "
                "Codex cấp. Cài bằng `npm i -g @openai/codex` (macOS có thể dùng "
                "`brew install codex`) rồi bấm lại. Cài ở chỗ lạ thì trỏ thẳng bằng biến "
                "môi trường JAVIS_CODEX_BIN.",
                "Codex CLI was not found on this machine - the model list of the ChatGPT plan comes "
                "from Codex itself. Install it with `npm i -g @openai/codex` (on macOS you can use "
                "`brew install codex`), then click again. If it is installed somewhere unusual, point "
                "to it with the JAVIS_CODEX_BIN environment variable.")
        return localefmt.chu(
            "Có Codex CLI nhưng nó chưa trả được danh sách model. Thường là bản Codex quá "
            "cũ (`npm i -g @openai/codex@latest`), hoặc máy chưa chạy `codex login` lần nào.",
            "Codex CLI is present but has not returned a model list yet. Usually Codex is too "
            "old (`npm i -g @openai/codex@latest`), or `codex login` has never been run on this machine.")
    if provider == "ollama":
        return localefmt.chu("Không gọi được Ollama. Kiểm tra máy chủ Ollama còn chạy và key còn hạn.",
                             "Could not reach Ollama. Check that the Ollama server is running and the key is still valid.")
    if provider == "ollama-local":
        if not (m.get("ollama_local_endpoint") or "").strip():
            return localefmt.chu("Chưa đặt địa chỉ Ollama - vào trang Models, tab Local Model để kết nối.",
                                 "No Ollama address set - go to the Models page, Local Model tab, to connect.")
        return localefmt.chu("Không gọi được Ollama ở địa chỉ đã lưu. Mở trang Models, tab Local Model để "
                             "xem lỗi cụ thể.",
                             "Could not reach Ollama at the saved address. Open the Models page, Local Model "
                             "tab, to see the exact error.")
    if provider == "openai-compat":
        if not (m.get("openai_compat_base") or "").strip():
            return localefmt.chu("Chưa đặt Base URL cho OpenAI Compatible.",
                                 "No Base URL set for OpenAI Compatible.")
        return localefmt.chu("Không đọc được danh sách model từ {base}/models. Kiểm tra Base URL (tính tới /v1) "
                             "và key, hoặc gõ tên model bằng tay.",
                             "Could not read the model list from {base}/models. Check the Base URL (up to /v1) "
                             "and the key, or type the model name by hand.")
    if provider == "anthropic-compat":
        if not (m.get("anthropic_compat_base") or "").strip():
            return localefmt.chu("Chưa đặt Base URL cho Anthropic Compatible.",
                                 "No Base URL set for Anthropic Compatible.")
        return localefmt.chu("Cổng này không trả danh sách model. Vào trang Models, thẻ Anthropic Compatible, "
                             "gõ tên model bên bán đưa rồi bấm Lưu.",
                             "This gateway does not list its models. On the Models page, Anthropic Compatible "
                             "card, type the model name the seller gave you and press Save.")
    if d.get("key_field") and not m.get(d["key_field"]):
        return localefmt.chu("Chưa có API key cho nhà cung cấp này.", "No API key for this provider yet.")
    return ""


async def provider_models_index(provider: str, refresh: bool = False) -> dict:
    """Lõi thuần của GET /provider/models. Dùng chung với Telegram (menu chọn model)."""
    cfg = cfgmod.read_settings()
    m = cfg.get("model", {})
    d = _provider_def(provider) or {}
    cat = m.get("catalog", {}) or {}
    # HỢP hai danh sách chứ không phải "cái nhớ được ĐÈ cái mặc định". Đây là gốc của lỗi
    # "nâng cấp Javis rồi vẫn không có model mới": `_remember_catalog` ghi danh sách live vào
    # settings.json, mà `config._deep_merge` thì THAY danh sách chứ không nối - nên từ lần ghi
    # đó trở đi, bản mặc định mới trong config.py không bao giờ tới được người dùng nữa. Một
    # model đã ngừng bán mà còn nằm trong danh sách chỉ phiền lúc chọn nhầm; một model MỚI
    # không bao giờ hiện ra thì không có đường nào chữa ngoài sửa tay settings.json.
    fallback = _gop_giu_thu_tu(d.get("default_models", []),
                               cat.get(d.get("catalog_key", "")) or [])
    now = time.time()
    c = _PROV_MODELS_CACHE.get(provider)
    if not refresh and c and (now - c["ts"]) < 600 and c.get("ids"):
        return {"models": c["ids"], "live": True, "cached": True}
    try:
        ids = await _fetch_provider_models(provider, m)
    except Exception as e:
        ids = None
        last_err = f"{type(e).__name__}: {e}"
    else:
        last_err = None
    if ids:
        _PROV_MODELS_CACHE[provider] = {"ids": ids, "ts": now}
        _remember_catalog(cfg, d, ids)
        return {"models": ids, "live": True}
    return {"models": fallback, "live": False,
            "error": last_err or _vi_sao_khong_co_model(provider, m)}


@app.get("/provider/models")
async def provider_models(provider: str = Query(...), refresh: bool = Query(False)):
    """Model động cho 1 provider. ``refresh=1`` bỏ cache để picker hỏi Codex ngay."""
    return await provider_models_index(provider, refresh=refresh)


