@app.post("/files/delete")
async def files_delete(brain: str = Form("brain"), path: str = Form(...)):
    try:
        p = _safe_path(brain, path)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    if p == _files_root(brain) or p == Path(_brain_root(brain)).resolve():
        return JSONResponse({"error": localefmt.chu("Không thể xoá thư mục gốc / brain", "Cannot delete the root / brain folder")}, status_code=400)
    try:
        if p.is_dir():
            shutil.rmtree(p)
        elif p.exists():
            p.unlink()
    except Exception as e:
        return JSONResponse({"error": str(e)}, status_code=500)
    return {"ok": True}


@app.post("/files/rename")
async def files_rename(brain: str = Form("brain"), path: str = Form(...), newname: str = Form(...)):
    try:
        p = _safe_path(brain, path)
        parent_rel = str(Path(path).parent).replace("\\", "/")
        dst = _safe_path(brain, (("" if parent_rel == "." else parent_rel) + "/" + _sanitize_filename(newname)).lstrip("/"))
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    if not p.exists():
        return JSONResponse({"error": localefmt.chu("Không tìm thấy", "Not found")}, status_code=404)
    p.rename(dst)
    return {"ok": True}


# Tên LOGIC của thư mục -> (regex nhận diện, tên tạo mới nếu chưa có). Có bảng này để client
# KHÔNG phải đoán tên thật: brain đặt "05 - Attachments" mà frontend gửi chuỗi cứng
# "attachments" thì server đẻ ra một thư mục thứ hai, và file đi lạc khỏi chỗ người dùng nhìn.
_THU_MUC_LOGIC = {
    "sources": (r"^(\d+\s*[-_.]\s*)?sources$", "Sources"),
    "attachments": (r"^(\d+\s*[-_.]\s*)?attachments$", "Attachments"),
    # Images inserted into a note (dashboard/note-images.js). NOT shared with attachments/: media_gc
    # treats attachments/ as a cache and deletes files older than 30 days, while a note points here.
    "images": (r"^(\d+\s*[-_.]\s*)?images$", "images"),
}
# Note images are embedded and shown inline, so the "images" folder takes raster formats only.
# SVG can carry script and is never stored there.
_NOTE_IMAGE_EXTS = {".webp", ".jpg", ".jpeg", ".png", ".gif", ".avif", ".bmp"}


@app.post("/files/upload")
async def files_upload(file: UploadFile = File(...), brain: str = Form("brain"),
                       path: str = Form(""), folder: str = Form("")):
    """Tải file vào brain. Đưa `folder` (tên logic) thì server tự tìm đúng thư mục thật;
    không thì dùng `path` như cũ (tương đối TRẦN duyệt)."""
    if folder:
        mau = _THU_MUC_LOGIC.get(folder.strip().lower())
        if not mau:
            return JSONResponse({"error": localefmt.chu("Thư mục không hợp lệ", "Invalid folder")}, status_code=400)
        if folder.strip().lower() == "images" and \
                os.path.splitext(_sanitize_filename(file.filename))[1].lower() not in _NOTE_IMAGE_EXTS:
            return JSONResponse({"error": localefmt.chu(
                "Ảnh trong note chỉ nhận WebP, JPG, PNG, GIF, AVIF hoặc BMP",
                "Note images accept only WebP, JPG, PNG, GIF, AVIF or BMP")}, status_code=400)
        d = Path(_resolve_subfolder(_brain_root(brain), *mau))
        try:
            # Client lưu và mở file bằng đường dẫn tương đối TRẦN duyệt, nên phải quy về đó -
            # trả đường tuyệt đối là đẩy một đường dẫn máy chủ vào cơ sở dữ liệu project.
            # Note images are the exception: the path is EMBEDDED in the note (![[images/a.webp]])
            # and the renderer resolves it from the BRAIN ROOT, so it must be brain-root relative.
            # Locally the browse ceiling can be a whole drive; relative to that, the note would get
            # "Users/.../images/a.webp" and break as soon as the brain moves or changes machine.
            if folder.strip().lower() == "images":
                rel_dir = d.resolve().relative_to(Path(_brain_root(brain)).resolve()).as_posix()
            else:
                rel_dir = d.relative_to(_files_root(brain)).as_posix()
        except ValueError:
            return JSONResponse({"error": localefmt.chu("Thư mục nằm ngoài phạm vi duyệt", "The folder is outside the browsable area")}, status_code=400)
    else:
        try:
            d = _safe_path(brain, path)
        except ValueError as e:
            return JSONResponse({"error": str(e)}, status_code=400)
        rel_dir = (path or "").strip().replace("\\", "/").strip("/")
    d.mkdir(parents=True, exist_ok=True)
    dest = _unique_path(str(d), _sanitize_filename(file.filename))
    try:
        await _save_upload_stream(file, dest)
    except Exception as e:
        return JSONResponse({"error": localefmt.chu(f"Ghi file thất bại: {e}", f"Writing the file failed: {e}")}, status_code=500)
    ten = os.path.basename(dest)
    # Trả luôn đường dẫn ĐÃ DÙNG: caller khỏi phải ghép lại và khỏi đoán sai tên thư mục.
    return {"ok": True, "name": ten, "dir": rel_dir,
            "path": (rel_dir + "/" + ten) if rel_dir else ten}


@app.get("/files/download")
async def files_download(brain: str = Query("brain"), path: str = Query(...)):
    try:
        f = _safe_serve_path(brain, path)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    if f.is_dir():
        return await zip_dir_response(brain, path)   # trỏ vào thư mục → tự nén .zip
    if not f.is_file():
        return JSONResponse({"error": localefmt.chu("Không tìm thấy file", "File not found")}, status_code=404)
    return FileResponse(str(f), filename=f.name)


# Trần an toàn khi nén thư mục: trên localhost trần duyệt có thể là CẢ Ổ ĐĨA, một cú bấm nhầm
# ở thư mục gốc sẽ nén hàng trăm nghìn file. Dừng SỚM ngay khi vượt, không nén nửa vời.
_ZIP_MAX_BYTES = 2 * 1024 * 1024 * 1024      # 2GB dữ liệu thô
_ZIP_MAX_FILES = 20000                       # 20 nghìn file


class _ZipTooBig(Exception):
    """Thư mục vượt trần _ZIP_MAX_* - dừng nén, báo người dùng chọn thư mục con."""


def _zip_scan(src: Path, zf=None):
    """Duyệt src, đếm (số file, tổng byte); nếu zf khác None thì ghi luôn vào zip đó.
    Bỏ qua symlink để không đi vòng ra ngoài trần duyệt. Ném _ZipTooBig khi vượt trần.
    Chạy trong threadpool (I/O nặng) - KHÔNG gọi thẳng trên event loop."""
    files = total = 0
    for dirpath, dirnames, filenames in os.walk(src, followlinks=False):
        dirnames[:] = [d for d in dirnames if not os.path.islink(os.path.join(dirpath, d))]
        if zf is not None:
            rel_dir = Path(dirpath).relative_to(src)
            arc_dir = src.name if str(rel_dir) == "." else (Path(src.name) / rel_dir).as_posix()
            zf.writestr(arc_dir + "/", b"")          # giữ cả thư mục rỗng
        for fn in filenames:
            p = Path(dirpath) / fn
            if p.is_symlink():
                continue
            try:
                size = p.stat().st_size
            except OSError:
                continue                              # file bị khoá/biến mất giữa chừng: bỏ qua
            files += 1
            total += size
            if files > _ZIP_MAX_FILES or total > _ZIP_MAX_BYTES:
                raise _ZipTooBig()
            if zf is not None:
                try:
                    zf.write(p, (Path(src.name) / p.relative_to(src)).as_posix())
                except (OSError, ValueError):
                    continue
    return files, total


def _zip_dir_sync(src: Path, dst: str):
    """Nén CẢ thư mục src vào file zip dst. Trả (số file, tổng byte thô)."""
    import zipfile
    with zipfile.ZipFile(dst, "w", zipfile.ZIP_DEFLATED, compresslevel=6) as zf:
        return _zip_scan(src, zf)


def _rm_quiet(p):
    try:
        os.unlink(p)
    except OSError:
        pass


def _zip_too_big_msg():
    return localefmt.chu(f"Thư mục quá lớn để nén (trần {_ZIP_MAX_FILES:,} file hoặc "
                         f"{_ZIP_MAX_BYTES // (1024 ** 3)}GB). Hãy tải từng thư mục con.",
                         f"Folder too large to compress (limit {_ZIP_MAX_FILES:,} files or "
                         f"{_ZIP_MAX_BYTES // (1024 ** 3)}GB). Download the subfolders one by one.")


async def zip_dir_response(brain: str, path: str, probe: bool = False):
    """Lõi thuần của /files/zip (route handler KHÔNG được gọi nhau như hàm thường, xem
    test_handler_khong_goi_truc_tiep). Trả JSON đo khi probe=True, còn lại trả file .zip.

    Zip dựng ra file TẠM trong threadpool (không chặn event loop) rồi gửi; file tạm xoá
    sau khi gửi xong qua BackgroundTask."""
    import tempfile
    from starlette.background import BackgroundTask
    from starlette.concurrency import run_in_threadpool
    try:
        d = _safe_serve_path(brain, path)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    if not d.is_dir():
        return JSONResponse({"error": localefmt.chu("Không phải thư mục", "Not a folder")}, status_code=404)
    name = (d.name or "brain") + ".zip"
    if probe:
        try:
            files, total = await run_in_threadpool(_zip_scan, d, None)
        except _ZipTooBig:
            return JSONResponse({"error": _zip_too_big_msg()}, status_code=413)
        except Exception as e:
            return JSONResponse({"error": localefmt.chu(f"Không đọc được thư mục: {e}", f"Could not read the folder: {e}")}, status_code=500)
        return {"ok": True, "files": files, "bytes": total, "name": name}
    fd, tmp = tempfile.mkstemp(prefix="javis-zip-", suffix=".zip")
    os.close(fd)
    try:
        await run_in_threadpool(_zip_dir_sync, d, tmp)
    except _ZipTooBig:
        _rm_quiet(tmp)
        return JSONResponse({"error": _zip_too_big_msg()}, status_code=413)
    except Exception as e:
        _rm_quiet(tmp)
        return JSONResponse({"error": localefmt.chu(f"Nén thất bại: {e}", f"Compression failed: {e}")}, status_code=500)
    return FileResponse(tmp, media_type="application/zip", filename=name,
                        background=BackgroundTask(_rm_quiet, tmp))


@app.get("/files/zip")
async def files_zip(brain: str = Query("brain"), path: str = Query(""), probe: int = Query(0)):
    """Tải CẢ một thư mục về máy dưới dạng .zip (File Manager + cây file: nút ⤓).

    probe=1 chỉ ĐO trước (số file, dung lượng) và trả JSON - dashboard hỏi trước để báo
    lỗi tử tế / xin xác nhận khi thư mục nặng, thay vì để trình duyệt tải về một trang lỗi."""
    return await zip_dir_response(brain, path, probe=bool(probe))


def raw_file_response(brain: str, path: str, dl: bool = False):
    """Lõi thuần của /files/raw (route handler KHÔNG được gọi nhau như hàm thường, xem
    test_handler_khong_goi_truc_tiep). Trả file inline, hoặc ép tải khi dl=True."""
    try:
        f = _safe_serve_path(brain, path)
    except ValueError as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    if not f.is_file():
        return JSONResponse({"error": localefmt.chu("Không tìm thấy file", "File not found")}, status_code=404)
    if dl:
        return FileResponse(str(f), filename=f.name)   # ép tải (giữ tên, kể cả tên tiếng Việt)
    mt, _ = mimetypes.guess_type(f.name)
    # inline WITH the file name (#898): a browser that cannot show the type (.xlsx) saves it, and with a bare "inline"
    # it named the file after the last URL segment ("raw", no extension). Starlette writes a non-ASCII name as
    # RFC 5987 filename*=utf-8''..., so an accented name stays a valid header.
    resp = FileResponse(str(f), media_type=mt or "application/octet-stream", filename=f.name,
                        content_disposition_type="inline")   # hiển thị trong trình duyệt, không ép tải
    resp.headers["X-Content-Type-Options"] = "nosniff"
    return resp


@app.get("/files/raw")
async def files_raw(brain: str = Query("brain"), path: str = Query(...), dl: int = Query(0)):
    """Phục vụ file THÔ để XEM INLINE trong trình duyệt: ảnh hiện trong <img>, pdf mở thẳng trên
    tab, mọi file khác có URL tĩnh để mở/tải. Khác /files/download (luôn ép tải về): mặc định
    inline; truyền dl=1 để ép tải. Cùng rào chống traversal (_safe_serve_path)."""
    return raw_file_response(brain, path, dl=bool(dl))


# ---- CHIA SẺ CÔNG KHAI một file (nút Chia sẻ trong trình sửa) ----
# Người cầm link KHÔNG đăng nhập, nên đây là mặt tiền công khai duy nhất chạm vào file trong
# brain. Ba điều giữ nó lành:
#   1. token 144 bit, không đoán được (share_store);
#   2. CHỈ ĐỌC, và chỉ đọc đúng file đã chia sẻ cộng tài nguyên quanh nó (_share_asset);
#   3. mọi trang trả về đều mang header cách ly (share_render.CSP_*), nên nội dung không với
#      được cookie đăng nhập của người mở.


def _share_chan(ban) -> str:
    """Dòng chân trang: nói rõ đây là file được chia sẻ, để người xem biết mình đang xem gì."""
    if share_store.la_hoi_thoai(ban):
        return localefmt.chu("Đoạn hội thoại được chia sẻ từ Javis OS", "A conversation shared from Javis OS")
    ten = os.path.basename(str(ban.get("path") or "")) or "file"
    return share_render.esc(ten) + localefmt.chu(" · được chia sẻ từ Javis OS", " · shared from Javis OS")


def _share_file(ban):
    """File THẬT mà token trỏ tới. None nếu nó đã bị xoá hoặc đổi tên. Link hội thoại không có file."""
    if share_store.la_hoi_thoai(ban):
        return None
    try:
        f = _safe_serve_path(ban.get("brain") or "brain", ban.get("path") or "")
    except ValueError:
        return None
    return f if f.is_file() else None


def _ung_vien_tai_nguyen(duong_dan_file: str, p: str):
    """Các chỗ CÓ THỂ chứa tấm ảnh `p` được nhắc trong file `duong_dan_file`, theo thứ tự thử.

    Cùng một thứ tự với `ungVienAnh` trong dashboard/chat-render.js, và cùng một lý do:

      1. THEO THƯ MỤC CỦA CHÍNH FILE .md - cách Obsidian, VS Code và GitHub hiểu một đường dẫn
         tương đối, tức cái người viết note mong đợi. Trước bản này cả hai phía chỉ phân giải
         theo GỐC BRAIN, nên note nằm trong thư mục con mà viết ![](anh.jpg) là ảnh không bao
         giờ hiện (chủ dự án báo 18/09).
      2. THEO GỐC BRAIN - hành vi cũ, giữ để note đang trỏ kiểu đó vẫn chạy.
      3. attachments/<tên file> - nơi Javis tự cất ảnh nó sinh ra.

    Hàng rào phạm vi KHÔNG đổi: mỗi ứng viên vẫn phải qua đủ hai cổng của _share_asset, nên
    thêm ứng viên ở đây không mở rộng thêm thứ gì đọc được.
    """
    raw = (p or "").replace("\\", "/").strip().lstrip("/")
    if raw.startswith("./"):
        raw = raw[2:]
    if not raw:
        return []
    thu_muc = posixpath.dirname((duong_dan_file or "").replace("\\", "/"))
    ra = []
    for ban_sao in (posixpath.normpath(posixpath.join(thu_muc, raw)) if thu_muc else None,
                    posixpath.normpath(raw),
                    "attachments/" + posixpath.basename(raw)):
        # normpath để lại ".." khi đường dẫn vượt lên trên gốc; bỏ hẳn ứng viên đó thay vì
        # đưa một đường dẫn nửa vời cho _safe_serve_path.
        if not ban_sao or ban_sao.startswith("..") or ban_sao in ra:
            continue
        ra.append(ban_sao)
    return ra


def _share_asset(ban, p: str):
    """File TÀI NGUYÊN kèm theo (ảnh trong .md, css/js cạnh file .html).

    HAI hàng rào cùng lúc, và cần cả hai:

    1. VỊ TRÍ: trong thư mục chứa file được chia sẻ (kể cả thư mục con), hoặc trong
       `attachments` của brain - nơi Javis cất ảnh theo quy ước.
    2. LOẠI FILE: phải nằm trong `DUOI_TAI_NGUYEN`, tức chỉ ảnh, css, js, phông, âm thanh,
       phim. Không tài liệu.

    Thiếu hàng rào thứ hai thì có một lỗ thật, và test_share_link.py đã bắt được nó lúc vừa
    viết xong: file .md chia sẻ nằm ngay GỐC BRAIN thì "thư mục chứa nó" chính là cả brain,
    nên một token lẻ đọc được mọi ghi chú khác trong đó. Bó theo LOẠI FILE đóng cửa ấy lại mà
    vẫn giữ nguyên hai nhu cầu thật: .md cần ảnh, trang .html cần css/js của nó.
    """
    goc = _share_file(ban)
    if goc is None:
        return None
    brain = ban.get("brain") or "brain"
    thu_muc = goc.parent
    dinh_kem = (Path(_brain_root(brain)).resolve() / "attachments")

    def _qua_cong(f) -> bool:
        """Đúng hai hàng rào ở trên, hỏi cho MỘT ứng viên."""
        if not f.is_file() or f.suffix.lower() not in share_render.DUOI_TAI_NGUYEN:
            return False
        if thu_muc in f.parents or f.parent == thu_muc:
            return True
        return dinh_kem.is_dir() and (dinh_kem == f.parent or dinh_kem in f.parents)

    for ung_vien in _ung_vien_tai_nguyen(str(ban.get("path") or ""), p or ""):
        try:
            f = _safe_serve_path(brain, ung_vien)
        except ValueError:
            continue
        if _qua_cong(f):
            return f
    return None


def _share_tin_toi_moc(ban) -> list:
    """Tin của hội thoại được chia sẻ, dừng ở MỐC lúc bấm chia sẻ (xem share_store: ảnh chụp,
    không phải bản sống). Link cũ không có mốc thì lấy hết."""
    tin = get_store().get_messages(str(ban.get("session_id") or ""))
    moc = ban.get("moc")
    if isinstance(moc, (list, tuple)) and len(moc) == 2:
        try:
            ts_moc, id_moc = float(moc[0]), int(moc[1])
            tin = [m for m in tin if (float(m.get("ts") or 0), int(m.get("id") or 0)) <= (ts_moc, id_moc)]
        except (TypeError, ValueError):
            pass
    return tin


def _share_trang_hoi_thoai(ban):
    """Trang xem công khai của một hội thoại (0.171.0)."""
    sid = str(ban.get("session_id") or "")
    sess = get_store().get_session(sid)
    if not sess:
        return HTMLResponse(share_render.trang_loi(localefmt.chu("Hội thoại đã bị xoá.", "The conversation was deleted.")),
                            status_code=404)
    tin = share_render.tin_cong_khai(_share_tin_toi_moc(ban))
    ten = _share_ten(ban)
    meta = localefmt.chu(f"{len(tin)} tin nhắn", f"{len(tin)} messages")
    trang = share_render.trang_hoi_thoai(
        ten, tin, "/s/" + ban["token"] + "/asset", meta, _share_chan(ban),
        nhan_nguoi=localefmt.chu("Người hỏi", "Question"), nhan_javis="Javis")
    return HTMLResponse(trang, headers={"Content-Security-Policy": share_render.CSP_TINH,
                                        "X-Content-Type-Options": "nosniff",
                                        "Referrer-Policy": "no-referrer"})


def _share_anh_hoi_thoai(ban, p: str):
    """Ảnh trong một hội thoại được chia sẻ: CHỈ ảnh và tài nguyên trình bày nằm trong `attachments`
    của brain - nơi Javis cất ảnh nó tạo ra. Không ghi chú, không file nào khác của brain."""
    brain = str(ban.get("brain") or "brain")
    dinh_kem = Path(_brain_root(brain)).resolve() / "attachments"
    raw = (p or "").replace("\\", "/").strip().lstrip("/")
    for ung_vien in (raw, "attachments/" + raw.split("/")[-1]):
        try:
            f = _safe_serve_path(brain, ung_vien)
        except ValueError:
            continue
        if (f.is_file() and f.suffix.lower() in share_render.DUOI_TAI_NGUYEN
                and dinh_kem.is_dir() and dinh_kem in f.parents):
            return f
    return None


@app.post("/share/create")
async def share_create(body: dict = Body(...)):
    """Bật chia sẻ cho một file. Gọi lại trên cùng file thì trả đúng link cũ, không đẻ link mới."""
    nhan = str(body.get("nhan") or "").strip()
    if not nhan:
        # 0.65.30: link mới tự lấy tên theo TIÊU ĐỀ file (chủ dự án chọn 01/10), không có thì tên
        # thư mục của index.html hoặc tên file. Sửa lại được ở trang Chia sẻ (/share/rename).
        nhan = _share_ten_tu_dong({"brain": body.get("brain") or "brain", "path": body.get("path") or ""})
    try:
        ban = share_store.tao(body.get("brain") or "brain", body.get("path") or "", nhan)
    except ValueError as e:
        return JSONResponse({"ok": False, "error": str(e)}, status_code=400)
    # Trả ĐƯỜNG DẪN TƯƠNG ĐỐI, để trình duyệt tự ghép với location.origin. Dựng URL tuyệt đối ở
    # đây nghĩa là tin vào header Host, thứ mà chính repo này đã ghi chú là không được tin.
    return {"ok": True, "token": ban["token"], "path": "/s/" + ban["token"]}


@app.post("/share/revoke")
async def share_revoke(body: dict = Body(...)):
    """Thu hồi. Sau lệnh này link cũ trả 404 cho tất cả mọi người."""
    return {"ok": share_store.xoa(body.get("token") or "")}


@app.get("/share/of")
async def share_of(brain: str = Query("brain"), path: str = Query(...)):
    """File này đã có link chưa? Nút Chia sẻ hỏi câu này để biết mình đang bật hay tắt."""
    ban = share_store.cua_file(brain, path)
    return {"ok": True, "share": ({"token": ban["token"], "path": "/s/" + ban["token"]}
                                  if ban else None)}


def _share_ten_tu_dong(ban) -> str:
    """Tên tự đặt của một link: tiêu đề file, không có thì tên dự phòng (share_render).
    Link hội thoại: tiêu đề của hội thoại."""
    if share_store.la_hoi_thoai(ban):
        sess = get_store().get_session(str(ban.get("session_id") or "")) or {}
        return str(sess.get("title") or "").strip()[:120] or localefmt.chu("Hội thoại", "Conversation")
    f = _share_file(ban)
    return (share_render.tieu_de_file(f) if f else "") or share_render.ten_du_phong(ban.get("path") or "")


def _share_ten(ban) -> str:
    """Tên hiển thị: tên đã đặt (tự lúc tạo hoặc người dùng sửa), link cũ chưa có tên thì tự lấy."""
    return str(ban.get("nhan") or "").strip() or _share_ten_tu_dong(ban)


@app.get("/share/list")
async def share_list(brain: str = Query("")):
    ds = share_store.danh_sach(brain)
    # Link tạo trước 0.65.30 chưa có tên: đọc đầu file lấy tiêu đề. Luồng phụ vì có thể là vài
    # trăm file; kho không bị ghi đè (tên vẫn theo file cho tới khi người dùng đặt tên).
    ten = await asyncio.to_thread(lambda: [_share_ten(b) for b in ds])
    return {"ok": True, "items": [{"token": b["token"], "brain": b.get("brain"),
                                   "path": b.get("path"), "tao_luc": b.get("tao_luc"),
                                   "loai": b.get("loai") or "file", "session_id": b.get("session_id") or "",
                                   "ten": t, "url": "/s/" + b["token"]} for b, t in zip(ds, ten)]}


@app.get("/s/{token}")
async def share_xem(token: str):
    """TRANG XEM công khai. Không cần đăng nhập - xem chú thích đầu khối."""
    ban = share_store.doc(token)
    if not ban:
        return HTMLResponse(share_render.trang_loi(localefmt.chu("Link không tồn tại hoặc đã bị thu hồi.", "This link does not exist or has been revoked.")),
                            status_code=404)
    if share_store.la_hoi_thoai(ban):
        return await asyncio.to_thread(_share_trang_hoi_thoai, ban)
    f = _share_file(ban)
    if f is None:
        return HTMLResponse(share_render.trang_loi(localefmt.chu("File đã bị xoá hoặc đổi tên.", "The file was deleted or renamed.")), status_code=404)
    duoi = f.suffix.lower()
    goc_asset = "/s/" + ban["token"] + "/asset"
    chan = _share_chan(ban)
    if duoi in share_render.DUOI_HTML:
        # Trang .html sống ở `/s/<token>/` (CÓ dấu gạch cuối) chứ không phải `/s/<token>`.
        # Lý do là cách trình duyệt phân giải đường dẫn tương đối: trang mở ở `/s/abc` mà
        # gọi fetch("data.json") thì trình duyệt xin `/s/data.json`, không có gì ở đó; mở ở
        # `/s/abc/` thì xin `/s/abc/data.json`, đúng route `_share_sibling` phục vụ file cạnh
        # trang. Link đã gửi đi vẫn là `/s/<token>` nên chuyển hướng thay vì bắt gửi lại.
        return RedirectResponse(url="/s/" + ban["token"] + "/", status_code=307)
    if duoi in share_render.DUOI_XEM_THANG:
        resp = FileResponse(str(f), media_type=mimetypes.guess_type(f.name)[0]
                            or "application/octet-stream")
        resp.headers["Content-Disposition"] = "inline"
        resp.headers["X-Content-Type-Options"] = "nosniff"
        resp.headers["Content-Security-Policy"] = share_render.CSP_HTML
        return resp
    try:
        noi = f.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return HTMLResponse(share_render.trang_loi(localefmt.chu("Không đọc được file.", "Could not read the file.")), status_code=404)
    if duoi in share_render.DUOI_MD:
        trang = share_render.trang_markdown(f.stem, noi, goc_asset, chan)
    else:
        trang = share_render.trang_van_ban(f.name, noi, chan)
    # Trang này do CHÍNH server dựng và không có một dòng script nào, nên cách ly chặt hơn.
    return HTMLResponse(trang, headers={"Content-Security-Policy": share_render.CSP_TINH,
                                        "X-Content-Type-Options": "nosniff",
                                        "Referrer-Policy": "no-referrer"})


@app.get("/s/{token}/raw")
async def share_raw(token: str, dl: int = Query(0)):
    """File gốc, để tải về hoặc để trang .html nhúng thẳng."""
    ban = share_store.doc(token)
    if not ban:
        return JSONResponse({"error": "not found"}, status_code=404)
    f = _share_file(ban)
    if f is None:
        return JSONResponse({"error": "not found"}, status_code=404)
    if dl:
        return FileResponse(str(f), filename=f.name)
    resp = FileResponse(str(f), media_type=mimetypes.guess_type(f.name)[0] or "text/plain")
    resp.headers["Content-Disposition"] = "inline"
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["Content-Security-Policy"] = share_render.CSP_HTML
    return resp


@app.get("/s/{token}/asset")
async def share_asset(token: str, p: str = Query(...)):
    """Ảnh và tài nguyên kèm theo. Phạm vi bó hẹp, xem _share_asset."""
