def _notify_ready() -> tuple:
    """(sẵn_sàng, lý_do): Javis có đường BÁO kết quả cho người dùng hay chưa. Nhắc hẹn và việc
    nền chỉ có giá trị khi tới giờ nó nói được với ai đó - chưa đấu kênh nào thì việc chạy xong
    rồi kết quả rơi vào hư không, người dùng tưởng Javis quên. Dùng để chặn ngay lúc TẠO.

    ĐỦ MỘT kênh là đủ. Từ 0.26.8 Zalo cũng tính: người dùng chỉ đấu Zalo mà bị chặn tạo nhắc
    hẹn với lý do "bot Telegram chưa bật" là một câu vừa sai vừa không sửa được, và nó đẩy họ
    đi cài một app họ không cần.

    Từ 0.49.0 HÒM THƯ là kênh mặc định và nó luôn có, nên rào này gần như không còn chặn ai:
    kết quả bao giờ cũng có chỗ đậu ở server, mở dashboard là thấy. Vẫn giữ hàm (và vẫn liệt
    kê kênh còn thiếu) vì Telegram/Zalo mới là đường tới được ĐIỆN THOẠI lúc không mở
    dashboard - thiếu chúng không phải lỗi, nhưng là điều đáng nói ra ở trang Việc.
    """
    return True, ""


def _kenh_con_thieu() -> tuple:
    """(có_kênh_ngoài, mô_tả_thiếu) - phần soi Telegram/Zalo tách ra khỏi `_notify_ready`.
    Dùng để HIỂN THỊ chứ không để chặn."""
    try:
        cfg = cfgmod.read_settings()
    except Exception:
        return True, ""      # không đọc được cấu hình thì đừng dựng rào, cứ để tạo
    thieu = []
    for khoa, ten in (("telegram", "Telegram"), ("zalo_bot", "Zalo")):
        c = cfg.get(khoa, {}) or {}
        if not c.get("enabled"):
            thieu.append(localefmt.chu(f"bot {ten} chưa bật", f"{ten} bot is not enabled"))
        elif not c.get("token"):
            thieu.append(localefmt.chu(f"bot {ten} chưa có token", f"{ten} bot has no token"))
        elif not tg_parse_ids(c.get("chat_id")):
            thieu.append(localefmt.chu(f"bot {ten} chưa có Chat ID được phép",
                                       f"{ten} bot has no allowed Chat ID"))
        else:
            return True, ""
    for _oc in owner_channels.ALL:
        _m = _oc.missing()
        if not _m:
            return True, ""
        thieu.append(_m)
    return False, localefmt.chu(" và ", " and ").join(thieu)


def _notify_live_warn() -> str:
    """Cấu hình đủ nhưng bot Telegram ĐANG lỗi thật (token bị thu hồi, 409 poll trùng...) thì
    việc tới giờ vẫn chạy mà tin không đi được. KHÔNG dùng để chặn tạo việc (lỗi có thể thoáng
    qua và tự khỏi), chỉ để nói ra ở trang Việc. Rỗng = không có gì đáng báo."""
    try:
        loi = []
        if _TG_BOT and _TG_BOT.status in ("error", "conflict"):
            loi.append(localefmt.chu(
                f"bot Telegram đang lỗi ({_TG_BOT.status}): {(_TG_BOT.last_error or '')[:160]}",
                f"Telegram bot error ({_TG_BOT.status}): {(_TG_BOT.last_error or '')[:160]}"))
        if _ZALO_BOT and _ZALO_BOT.status == "error":
            loi.append(localefmt.chu(f"bot Zalo đang lỗi: {(_ZALO_BOT.last_error or '')[:160]}",
                                     f"Zalo bot error: {(_ZALO_BOT.last_error or '')[:160]}"))
        for _oc in owner_channels.ALL:
            if _oc.bot and _oc.bot.status == "error":
                loi.append(localefmt.chu(f"{_oc.label} đang lỗi: {(_oc.bot.last_error or '')[:160]}",
                                         f"{_oc.label} error: {(_oc.bot.last_error or '')[:160]}"))
        return "; ".join(loi)
    except Exception:
        return ""


async def _bao_nhac_hen(chat_id, text, viec=None, web="", brain="", dedup="") -> tuple:
    """Đường BÁO của nhắc hẹn. Cùng chữ ký (chat_id, text) -> (ok, err) như `_tg_send_to` cũ,
    nhưng đi qua `_notify_owner` nên nhắc hẹn được đúng ba thứ mà trước đây nó không có:
    hòm thư ở server, đẩy về khung chat web khi chat_id là "web:<sid>", và thông báo đẩy.
    Trước bản này nhắc hẹn là thứ DUY NHẤT còn gọi thẳng Telegram - đó cũng là lý do
    reminders.py phải chặn không cho tạo khi chưa đấu bot."""
    return await _notify_owner(chat_id, text, kind="report", source="reminder",
                               viec=viec, web=web, brain=brain, dedup=dedup)


async def _voice_note_rel(brain, text) -> str:
    """0.202.0: a reminder that reads its result aloud: the mp3 path inside the brain, "" on failure."""
    res = await voice_note.make(_brain_root(brain), text)
    return res.get("rel_path", "") if res.get("ok") else ""


async def _send_voice_file(chat_id, path, brain) -> tuple:
    """The voice note as an audio message where the channel needs the file itself. Telegram: the asking chat, or the
    owner's own chat when the reminder has none (same rule as _report_route). The web chat plays the link already."""
    cid = str(chat_id or "").strip()
    if cid.startswith(("web:", "zalo:")) or _TG_BOT is None:
        return False, "no file channel"
    cid = cid or _owner_telegram_id()
    if not cid:
        return False, "no Telegram chat"
    return await _TG_BOT.send_file(path, chat=cid)


