@app.get("/sw.js")
async def service_worker():
    """Service worker PHẢI phục vụ từ gốc site.

    Phạm vi (scope) mặc định của một service worker là thư mục chứa nó, nên đặt ở
    /static/sw.js thì nó chỉ điều khiển được /static/* - tức là không nhận được push cho
    trang chủ, và bấm vào thông báo không tìm thấy tab nào để focus. Trả thẳng ở "/" là
    cách gọn nhất, khỏi phải thêm header Service-Worker-Allowed.
    """
    f = DASHBOARD_PATH / "sw.js"
    if not f.exists():
        return Response("// no sw", media_type="application/javascript")
    return FileResponse(f, media_type="application/javascript",
                        headers={"Cache-Control": "no-cache", "Service-Worker-Allowed": "/"})


# ============================================
# Branding - logo/avatar đổi được qua UI (lưu ở STATE_DIR/branding, giữ qua update).
# Trong Docker code tree read-only → KHÔNG ghi đè dashboard/logo.png; lưu ở volume state.
# ============================================
_LOGO_EXTS = {".png", ".jpg", ".jpeg", ".webp", ".gif"}
_DEFAULT_LOGO = DASHBOARD_PATH / "logo.png"
_MAX_LOGO_BYTES = 5 * 1024 * 1024   # 5MB


def _current_logo_file():
    """File logo tùy chỉnh nếu có (theo branding.logo_ext), else None → dùng ảnh mặc định."""
    ext = (cfgmod.read_settings().get("branding", {}) or {}).get("logo_ext", "")
    if ext:
        p = cfgmod.BRANDING_DIR / f"logo{ext}"
        if p.exists():
            return p
    return None


_BRAND_THEME_MAX_BYTES = 512 * 1024
_BRAND_THEME_MODE_RE = re.compile(r"/\*\s*javis-default-mode:\s*(light|dark|auto)\s*\*/")


def _brand_theme_file():
    """Optional operator stylesheet at STATE_DIR/branding/theme.css, or None.

    Lives next to the custom logo so a white-label theme survives `git pull` and app
    updates the same way the logo does: the code tree is never edited."""
    p = cfgmod.BRANDING_DIR / "theme.css"
    try:
        if p.is_file() and 0 < p.stat().st_size <= _BRAND_THEME_MAX_BYTES:
            return p
    except OSError:
        pass
    return None


def _inject_brand_theme(html: str) -> str:
    """Append the operator theme AFTER the bundled stylesheets so it wins the cascade.

    The theme may carry `/* javis-default-mode: light */` to pick the theme for a device
    that has never chosen one. A manual choice already in localStorage always wins."""
    p = _brand_theme_file()
    if p is None:
        return html
    try:
        data = p.read_bytes()
    except OSError:
        return html
    m = _BRAND_THEME_MODE_RE.search(data[:4096].decode("utf-8", "ignore"))
    if m:
        # Must run before the inline theme script at the top of <head>, which reads this key.
        seed = ("<script>try{if(!localStorage.getItem('javis.theme'))"
                "localStorage.setItem('javis.theme','" + m.group(1) + "')}catch(e){}</script>")
        html = html.replace("<head>", "<head>\n  " + seed, 1)
    link = f'<link rel="stylesheet" href="/brand-theme.css?v={binascii.crc32(data):08x}">\n'
    return html.replace("</head>", link + "</head>", 1)


@app.get("/brand-theme.css")
async def brand_theme_css():
    p = _brand_theme_file()
    if p is None:
        return Response("/* no brand theme */", media_type="text/css",
                        headers={"Cache-Control": "no-cache"})
    # The URL carries a content hash, so the browser may keep it until the file changes.
    return FileResponse(str(p), media_type="text/css",
                        headers={"Cache-Control": "public, max-age=31536000, immutable"})


@app.get("/brand-logo")
async def brand_logo():
    p = _current_logo_file() or _DEFAULT_LOGO
    if not p.exists():
        return JSONResponse({"error": "no logo"}, status_code=404)
    # cache ngắn: đổi ảnh xong thấy ngay trong ~1 phút; JS còn bust bằng ?v= khi vừa upload.
    return FileResponse(str(p), headers={"Cache-Control": "public, max-age=60"})


@app.get("/favicon.ico")
async def favicon_ico():
    """Favicon = logo hiện tại. Trình duyệt LUÔN tự gọi /favicon.ico và cache rất lì;
    trước đây route này trả 404 nên tab giữ icon cũ. Trả thẳng ảnh logo cho khớp app."""
    p = _current_logo_file() or _DEFAULT_LOGO
    if not p.exists():
        return JSONResponse({"error": "no favicon"}, status_code=404)
    media = {".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg",
             ".webp": "image/webp", ".gif": "image/gif"}.get(p.suffix.lower(), "image/png")
    return FileResponse(str(p), media_type=media, headers={"Cache-Control": "public, max-age=300"})


# ============================================
# Ảnh đại diện tự tải lên cho trợ lý và nhóm (0.176.0, server/avatar_upload.py). Tải lên chỉ trả TÊN ảnh; gắn vào trợ lý
# qua POST /agents (avatar_image), vào nhóm qua PATCH /teams/{id} (avatar_image).
# ============================================
@app.post("/avatars/upload")
async def avatar_upload_post(file: UploadFile = File(...)):
    data = await file.read(avatar_upload.MAX_BYTES + 1)
    try:
        name = await asyncio.to_thread(avatar_upload.luu, data)
    except ValueError as exc:
        msg = {"avatar_too_big": localefmt.chu("Ảnh quá lớn (tối đa 2MB).", "Image too large (max 2MB)."),
               "avatar_empty": localefmt.chu("File rỗng.", "The file is empty.")}.get(
            str(exc), localefmt.chu("Chỉ nhận ảnh PNG, JPG, WEBP hoặc GIF.", "Only PNG, JPG, WEBP or GIF images are accepted."))
        return JSONResponse({"ok": False, "code": str(exc), "error": msg}, status_code=400)
    return {"ok": True, "image": name, "url": "/avatars/" + name}


@app.get("/avatars/{name}")
async def avatar_get(name: str):
    p = avatar_upload.duong_dan(name)
    if p is None:
        return JSONResponse({"error": "not found"}, status_code=404)
    # Tên là băm nội dung: đổi ảnh là đổi tên, nên trình duyệt giữ mãi được. nosniff: chỉ hiện như ảnh.
    return FileResponse(str(p), headers={"Cache-Control": "private, max-age=31536000, immutable",
                                         "X-Content-Type-Options": "nosniff"})


@app.post("/branding/logo")
async def branding_logo_set(file: UploadFile = File(...)):
    ext = os.path.splitext(file.filename or "")[1].lower()
    if ext == ".jpe":
        ext = ".jpg"
    if ext not in _LOGO_EXTS:
        return JSONResponse({"ok": False, "error": localefmt.chu("Chỉ nhận ảnh PNG / JPG / WEBP / GIF",
                                                                 "Only PNG / JPG / WEBP / GIF images are accepted")},
                            status_code=400)
    data = await file.read()
    if not data:
        return JSONResponse({"ok": False, "error": localefmt.chu("File rỗng", "File is empty")}, status_code=400)
    if len(data) > _MAX_LOGO_BYTES:
        return JSONResponse({"ok": False, "error": localefmt.chu("Ảnh quá lớn (tối đa 5MB)",
                                                                 "Image too large (max 5MB)")}, status_code=400)
    try:
        cfgmod.BRANDING_DIR.mkdir(parents=True, exist_ok=True)
        for old in cfgmod.BRANDING_DIR.glob("logo.*"):   # xoá ảnh cũ mọi đuôi, tránh file thừa
            try:
                old.unlink()
            except Exception:
                pass
        (cfgmod.BRANDING_DIR / f"logo{ext}").write_bytes(data)
    except Exception as e:
        return JSONResponse({"ok": False, "error": localefmt.chu(f"Lưu ảnh thất bại: {e}",
                                                                 f"Failed to save image: {e}")}, status_code=500)
    cfg = cfgmod.read_settings()
    cfg.setdefault("branding", {})
    cfg["branding"]["logo_ext"] = ext
    cfg["branding"]["logo_v"] = int(cfg["branding"].get("logo_v", 0) or 0) + 1
    cfgmod.write_settings(cfg)
    return {"ok": True, "logo_v": cfg["branding"]["logo_v"]}


@app.post("/branding/logo/reset")
async def branding_logo_reset():
    try:
        if cfgmod.BRANDING_DIR.exists():
            for old in cfgmod.BRANDING_DIR.glob("logo.*"):
                try:
                    old.unlink()
                except Exception:
                    pass
    except Exception:
        pass
    cfg = cfgmod.read_settings()
    cfg.setdefault("branding", {})
    cfg["branding"]["logo_ext"] = ""
    cfg["branding"]["logo_v"] = int(cfg["branding"].get("logo_v", 0) or 0) + 1
    cfgmod.write_settings(cfg)
    return {"ok": True}


