# ============================================
# TTS - Edge TTS (giọng Vietnamese chuẩn, miễn phí)
# ============================================
def _rate_to_speed(rate: str) -> float:
    """'+10%' / '-20%' → tốc độ 1.1 / 0.8 cho OpenAI (kẹp 0.25..4.0)."""
    try:
        pct = float((rate or "").strip().replace("%", ""))
        return max(0.25, min(4.0, 1.0 + pct / 100.0))
    except Exception:
        return 1.0


async def _tts_edge(text: str, voice: str, rate: str) -> bytes:
    import edge_tts   # lazy - xem ghi chú ở đầu file
    communicate = edge_tts.Communicate(text, voice, rate=rate)
    buf = bytearray()
    async for chunk in communicate.stream():
        if chunk["type"] == "audio":
            buf.extend(chunk["data"])
    return bytes(buf)


async def _tts_edge_stream(text: str, voice: str, rate: str):
    """Edge TTS STREAMING: trả (khúc đầu, generator các khúc sau).

    Vì sao tách khúc đầu ra: Voice V1 phát audio ngay khi Edge sinh khúc đầu thay vì gom cả
    câu (câu 600 ký tự gom xong mất 1-2 giây, người nghe tưởng máy treo). Nhưng lỗi Edge
    (mạng, giọng không tồn tại) phải thành 502 thật để client còn rơi về đường dự phòng, mà
    StreamingResponse đã gửi header 200 rồi thì không đổi được nữa. Nên đợi CHO ĐƯỢC khúc đầu
    trước khi trả response, lỗi thì nổ ở đây, còn các khúc sau mới stream.
    """
    import edge_tts   # lazy - xem ghi chú ở đầu file
    communicate = edge_tts.Communicate(text, voice, rate=rate)
    it = communicate.stream()
    first = b""
    async for chunk in it:
        if chunk["type"] == "audio" and chunk["data"]:
            first = chunk["data"]
            break
    if not first:
        raise RuntimeError("Edge TTS không trả audio.")

    async def _rest():
        yield first
        async for chunk in it:
            if chunk["type"] == "audio" and chunk["data"]:
                yield chunk["data"]

    return first, _rest()


async def _tts_openai(text: str, rate: str, cfg: dict) -> bytes:
    import httpx
    key = (cfg.get("model", {}) or {}).get("openai_api_key", "")
    if not key:
        raise RuntimeError("Chưa có OpenAI API key (đặt ở Models / Cài đặt).")
    v = cfg.get("voice", {}) or {}
    payload = {
        "model": v.get("openai_tts_model") or "gpt-4o-mini-tts",
        "voice": v.get("openai_tts_voice") or "alloy",
        "input": text, "response_format": "mp3", "speed": _rate_to_speed(rate),
    }
    async with httpx.AsyncClient(timeout=60) as client:
        r = await client.post("https://api.openai.com/v1/audio/speech",
                              headers={"Authorization": f"Bearer {key}"}, json=payload)
        r.raise_for_status()
        return r.content


async def _tts_elevenlabs(text: str, cfg: dict) -> bytes:
    import tts_eleven   # 0.255.0: model that speaks Vietnamese, shared with voice notes
    return await tts_eleven.synth(text, cfg)


@app.get("/tts")
async def tts(
    text: str = Query(...),
    voice: str = Query("en-US-EmmaMultilingualNeural"),
    rate: str = Query("+5%"),
):
    """Sinh audio đúng nhà cung cấp đã chọn; lỗi không được âm thầm đổi giọng."""
    import sys
    from fastapi import HTTPException, Response
    if voice == "auto":
        # "Auto by language" is resolved per chunk in the browser (voice-lang.js); a page cached
        # from before 0.220.0 can still send the raw value, which Edge would refuse.
        voice = "en-US-EmmaMultilingualNeural"
    from fastapi.responses import StreamingResponse
    cfg = cfgmod.read_settings()
    provider = ((cfg.get("voice", {}) or {}).get("tts_provider") or "edge").lower()
    # Edge đi đường STREAM (Voice V1): byte đầu tới trình duyệt ngay khi Edge sinh ra, thẻ
    # <audio> của Chrome phát dần mp3 chunked. `Accept-Ranges: none` để trình duyệt khỏi hỏi
    # Range trên một stream không có Content-Length.
    _stream_headers = {"Cache-Control": "no-cache", "Accept-Ranges": "none"}

    async def _edge_streaming():
        # Câu tiếng Việt xen từ tiếng Anh: đọc từ tiếng Anh theo kiểu người Việt nói ("GitHub
        # Actions" -> "ghít hắp ác sừn"), cả câu một giọng người dùng đã chọn. Chỉ đổi chữ ĐƯA
        # CHO LOA; khung chat vẫn hiện chữ gốc. Câu thuần tiếng Anh giữ nguyên. Xem phien_am.py.
        doc = phien_am.doc_viet(text)
        _first, gen = await _tts_edge_stream(doc, voice, rate)
        return StreamingResponse(gen, media_type="audio/mpeg", headers=_stream_headers)

    audio = b""
    try:
        if provider == "openai":
            audio = await _tts_openai(text, rate, cfg)
        elif provider == "elevenlabs":
            audio = await _tts_elevenlabs(text, cfg)
        else:
            return await _edge_streaming()
    except Exception as e:
        print(f"[TTS {provider}] {type(e).__name__}", file=sys.stderr)
        raise HTTPException(502, localefmt.chu(
            "Giọng đã chọn hiện không phát được. Vui lòng thử lại hoặc chọn giọng khác.",
            "The selected voice cannot play right now. Please try again or choose another voice."))
    if not audio:
        raise HTTPException(502, localefmt.chu("TTS không trả audio.", "TTS returned no audio."))
    return Response(content=audio, media_type="audio/mpeg", headers={"Cache-Control": "no-cache"})


# ============================================
# Voice V2 - nghe bằng Groq, tuỳ chọn giọng nói, nghe nói thẳng (Live)
# ============================================
@app.post("/stt")
async def stt_route(file: UploadFile = File(...), lang: str = Form(""), draft: str = Form("")):
    """Dashboard gửi file ghi âm (webm/opus) sau khi hết câu -> chữ qua Groq Whisper.

    Dùng lại đúng `stt.groq_nghe` của kênh Telegram/Zalo. Trả `{"ok": true, "text": ...}` hoặc
    `{"ok": false, "ly_do": ...}`; trình duyệt lỗi thì giữ chữ của Web Speech, không mất lượt.
    """
    cfg = cfgmod.read_settings()
    data = await file.read()
    # Tai đang được chọn (voice_ear.select_ear). Trình duyệt chỉ tải lên khi /voice/ear báo có
    # tai dạng tải lên; chặn thêm ở đây phòng trang cũ còn mở. Không có tai thì trả ok=false,
    # trình duyệt giữ chữ Web Speech như trước.
    ear = voice_ear.select_ear(cfg, _effective_main(cfg).get("provider", ""))
    if ear["kind"] != "upload":
        return {"ok": False, "text": "", "model": "",
                "ly_do": "tai_tat" if ear["reason"] == voice_ear.REASON_OFF else "thieu_key"}
    # Mồi từ vựng, sửa tên trợ lý, đối chiếu bản nháp: xem voice_ear.transcribe_upload.
    # WebSocket còn quét nghe_sua.sua thêm lần nữa (cho cả chữ Web Speech); hàm idempotent.
    return await voice_ear.transcribe_upload(cfg, data, file.filename or "voice.webm", lang, draft,
                                             provider=ear["provider"])


