# ============================================================
# OLLAMA TRÊN MÁY NHÀ
# ============================================================
# Mọi endpoint ở đây đọc địa chỉ/khoá TỪ SETTINGS chứ không nhận qua query: địa chỉ nội bộ
# nằm trong URL là nó nằm luôn trong log truy cập của mọi proxy trên đường đi.

def _ol_cfg():
    m = cfgmod.read_settings().get("model", {}) or {}
    return (m.get("ollama_local_endpoint") or "").strip(), (m.get("ollama_local_key") or "").strip()


def _ol_luu(patch: dict):
    """Ghi vài trường vào settings.model. Kho này không có hàm merge sẵn, mọi chỗ đều theo
    lối đọc - sửa - ghi, nên gói lại một chỗ cho ba endpoint dưới khỏi lặp."""
    cfg = cfgmod.read_settings()
    m = dict(cfg.get("model") or {})
    m.update(patch)
    cfg["model"] = m
    cfgmod.write_settings(cfg)


def _ol_specs_luu():
    m = cfgmod.read_settings().get("model", {}) or {}
    d = m.get("ollama_local_specs") or {}
    return dict(d) if isinstance(d, dict) else {}


def _ol_specs_hien_dung(endpoint: str) -> dict:
    """Cấu hình máy để gợi ý model.

    Thứ tự: KHAI TAY trước, rồi mới tới tự dò. Người dùng khai tay là họ biết một điều bộ dò
    không biết - máy bị giới hạn trong container, hay họ muốn chừa RAM cho việc khác. Để auto
    đè lên khai tay thì ô nhập kia thành ô trang trí: gõ vào rồi không thấy gì đổi.

    Tự dò chỉ chạy khi CHẮC CHẮN cùng máy (xem ollama_local.same_host). Ollama không có
    endpoint nào trả RAM/GPU của máy nó đang chạy, nên với một địa chỉ ở xa thì ngoài hỏi
    người dùng ra không còn đường nào.
    """
    d = _ol_specs_luu()
    if d.get("source") == "manual" and (d.get("ram_gb") or 0) > 0:
        return d
    if ollama_local.same_host(endpoint):
        return ollama_local.detect_specs()
    return {"source": "unknown", "ram_gb": 0, "has_gpu": False, "vram_gb": 0}


@app.get("/ollama-local/status")
async def ollama_local_status():
    ep, key = _ol_cfg()
    # Địa chỉ GỢI Ý phải là địa chỉ THẬT của máy này, không phải một ví dụ chung chung:
    #   - chạy thẳng trên máy   -> chính nó, 127.0.0.1
    #   - chạy trong Docker     -> cổng bridge DÒ ĐƯỢC (xem deploy_info.docker_gateway; viết
    #                              cứng 172.17.0.1 là sai với gần như mọi bản cài bằng compose)
    # Dò không ra thì trả rỗng để giao diện biết mà hỏi người dùng, thay vì điền sẵn một địa
    # chỉ sai rồi để họ bấm Kết nối và nhận lỗi không hiểu vì sao.
    cong = deploy_info.docker_gateway()
    goi_y = (f"http://{cong}:{ollama_local.CONG_MAC_DINH}" if cong
             else (ollama_local.GOI_Y_ENDPOINT if _deploy_mode() != "docker" else ""))
    ra = {"endpoint": ep, "deploy_mode": _deploy_mode(), "host_platform": _host_platform(),
          "same_host": ollama_local.same_host(ep), "goi_y_endpoint": goi_y,
          "docker_gateway": cong,
          "reachable": False, "error": None, "installed_count": 0}
    if not ep:
        return ra
    p = await ollama_local.probe(ep, key)
    ra.update({"reachable": p["reachable"], "error": p["error"],
               "installed_count": len(p["models"])})
    return ra


def _ol_quen_danh_sach(ca_catalog: bool):
    """Quên danh sách model của máy Ollama vừa rời.

    Ô chọn model nhớ danh sách live 10 phút (`_PROV_MODELS_CACHE`) và ghi bản gần nhất vào
    catalog để lúc MẤT MẠNG tạm thời vẫn có gì đó mà chọn. Đổi hay gỡ địa chỉ thì không phải
    mất mạng - đó là một máy khác, hoặc không còn máy nào. Giữ danh sách cũ là ô chọn bày
    model của một máy không còn nối, chọn vào là chat chết. Đổi địa chỉ chỉ cần bỏ cache
    (catalog sẽ bị đè ngay ở lần lấy sau); gỡ hẳn thì bỏ cả catalog.
    """
    _PROV_MODELS_CACHE.pop("ollama-local", None)
    if not ca_catalog:
        return
    cfg = cfgmod.read_settings()
    cat = (cfg.get("model") or {}).get("catalog") or {}
    if "ollama-local" in cat:
        cat.pop("ollama-local", None)
        cfgmod.write_settings(cfg)


@app.post("/ollama-local/endpoint")
async def ollama_local_set_endpoint(endpoint: str = Form(""), key: str = Form(None)):
    """Lưu địa chỉ rồi dò luôn. Chuỗi rỗng = gỡ kết nối."""
    ep = (endpoint or "").strip()
    if not ep:
        _ol_luu({"ollama_local_endpoint": "", "ollama_local_key": ""})
        _ol_quen_danh_sach(ca_catalog=True)
        return {"ok": True, "endpoint": "", "reachable": False}
    try:
        ep = ollama_local.chuan_hoa_endpoint(ep)
    except ollama_local.LoiEndpoint as e:
        return JSONResponse({"error": str(e)}, status_code=400)
    patch = {"ollama_local_endpoint": ep}
    if key is not None:
        patch["ollama_local_key"] = key.strip()
    _ol_luu(patch)
    _ol_quen_danh_sach(ca_catalog=False)
    p = await ollama_local.probe(ep, (key or "").strip() or _ol_cfg()[1])
    # Ollama KHÔNG có mật khẩu. Trỏ sang một IP công khai là hợp lệ (máy khác qua Internet),
    # nhưng nó cũng có nghĩa cả Internet gọi được model đó, nên phải nói ngay lúc kết nối chứ
    # không để trong một đoạn hướng dẫn phía trên mà ai cũng lướt qua.
    return {"ok": True, "endpoint": ep, "reachable": p["reachable"], "error": p["error"],
            "canh_bao_cong_khai": ollama_local.la_ip_cong_khai(ep)}


@app.post("/provider/openai-compat/connect")
async def openai_compat_connect(request: Request):
    """Lưu Base URL + key của provider OpenAI Compatible SAU KHI gọi thử {base}/models.

    Các provider API khác lưu key không kiểm, nhưng ở đây URL cũng do người dùng gõ: lưu bừa
    thì thẻ báo "Đã kết nối" với key sai, rồi hiện danh sách model cũ còn nhớ như thể thật.
    Key để trống = dùng lại key đang lưu (ô key chỉ để ĐỔI key)."""
    import httpx
    data = await request.json()
    base = str(data.get("base") or "").strip().rstrip("/")
    if base.endswith("/chat/completions"):
        base = base[: -len("/chat/completions")]
    if not base.lower().startswith(("http://", "https://")):
        return {"ok": False, "error": localefmt.chu("Base URL phải bắt đầu bằng http:// hoặc https://",
                                                    "Base URL must start with http:// or https://")}
    cfg = cfgmod.read_settings()
    m = cfg.setdefault("model", {})
    # A blank input reuses the secret only for the same endpoint. Reusing it for another URL
    # would send that secret to the new host during the validation request below.
    old_base = str(m.get("openai_compat_base") or "").strip().rstrip("/")
    key = str(data.get("key") or "").strip()
    if not key and base == old_base:
        key = m.get("openai_compat_key") or ""
    try:
        async with httpx.AsyncClient(timeout=20) as c:
            r = await c.get(base + "/models", headers={"Authorization": f"Bearer {key or 'none'}"})
    except Exception as e:
        return {"ok": False, "error": localefmt.chu(f"Không gọi được {base}/models ({type(e).__name__}). "
                                                    "Kiểm tra lại Base URL.",
                                                    f"Could not reach {base}/models ({type(e).__name__}). "
                                                    "Check the Base URL.")}
    if r.status_code in (401, 403):
        return {"ok": False, "error": localefmt.chu(f"API key không hợp lệ (HTTP {r.status_code}). Chưa lưu gì.",
                                                    f"Invalid API key (HTTP {r.status_code}). Nothing was saved.")}
    if r.status_code == 404:
        return {"ok": False, "error": localefmt.chu(f"Không thấy {base}/models (HTTP 404). Base URL phải tính tới "
                                                    "/v1, ví dụ https://api.example.com/v1.",
                                                    f"{base}/models not found (HTTP 404). The Base URL must include "
                                                    "/v1, for example https://api.example.com/v1.")}
    if r.status_code != 200:
        return {"ok": False, "error": localefmt.chu(f"Endpoint trả HTTP {r.status_code}: {r.text[:160]}",
                                                    f"Endpoint returned HTTP {r.status_code}: {r.text[:160]}")}
    try:
        ids = sorted(x.get("id") for x in (r.json().get("data") or [])
                     if isinstance(x, dict) and x.get("id"))
    except Exception:
        ids = []
    if not ids:
        return {"ok": False, "error": localefmt.chu("Endpoint trả lời nhưng không có model nào - không giống "
                                                    "endpoint chuẩn OpenAI.",
                                                    "The endpoint answered but lists no models - it does not "
                                                    "look like a standard OpenAI endpoint.")}
    m["openai_compat_base"] = base
    m["openai_compat_key"] = key
    m.setdefault("catalog", {})["openai-compat"] = ids
    cfgmod.write_settings(cfg)
    _PROV_MODELS_CACHE["openai-compat"] = {"ids": ids, "ts": time.time()}
    return {"ok": True, "models": len(ids)}


@app.post("/provider/anthropic-compat/connect")
async def anthropic_compat_connect(request: Request):
    """Save the base URL, key and model names of an Anthropic-compatible gateway (0.254.0), AFTER
    checking them.

    Same rule as OpenAI Compatible: the URL is typed by the owner, so saving blind would show
    "Connected" with a wrong key. The check differs because most such gateways have no
    /v1/models: when the list is missing, Javis sends one tiny /v1/messages request (max_tokens 1)
    with the first typed model instead. A blank key reuses the saved one, for the same URL only."""
    import httpx
    data = await request.json()
    raw = str(data.get("base") or "").strip()
    base = engine.normalize_anthropic_compat_base(raw)
    if not base.lower().startswith(("http://", "https://")):
        return {"ok": False, "error": localefmt.chu("Base URL phải bắt đầu bằng http:// hoặc https://",
                                                    "Base URL must start with http:// or https://")}
    typed_in = data.get("models")
    if isinstance(typed_in, str):
        typed_in = re.split(r"[,\n]+", typed_in)
    typed = _gop_giu_thu_tu([str(x).strip() for x in (typed_in or []) if str(x).strip()])
    cfg = cfgmod.read_settings()
    m = cfg.setdefault("model", {})
    # A blank input reuses the secret only for the same gateway: reusing it for another URL would
    # send that secret to the new host during the check below.
    old_base = engine.normalize_anthropic_compat_base(m.get("anthropic_compat_base") or "")
    key = str(data.get("key") or "").strip()
    if not key and base == old_base:
        key = m.get("anthropic_compat_key") or ""
    if not key:
        return {"ok": False, "error": localefmt.chu("Cần API key bên bán đưa cho bạn.",
                                                    "Enter the API key the seller gave you.")}
    headers = engine.anthropic_headers(key, compat=True)
    live = []
    try:
        async with httpx.AsyncClient(timeout=20) as c:
            r = await c.get(base + "/v1/models", headers=headers)
        if r.status_code in (401, 403):
            return {"ok": False, "error": localefmt.chu(f"API key không hợp lệ (HTTP {r.status_code}). Chưa lưu gì.",
                                                        f"Invalid API key (HTTP {r.status_code}). Nothing was saved.")}
        if r.status_code == 200:
            live = [x.get("id") for x in (r.json().get("data") or []) if isinstance(x, dict) and x.get("id")]
    except Exception:
        live = []   # no list is normal here; the message check below decides
    if not live:
        if not typed:
            # 0.308.0 (owner 24/10/2026: "không cần hiện tên model được không? người dùng phải được chọn chứ"): the card
            # no longer shows the model box up front. Only a gateway with no list needs names, so this reply opens the
            # box (need_models) with the usual Claude names to pick from (suggest), still free to type another.
            return {"ok": False, "need_models": True, "suggest": list(_provider_def("anthropic-api")["default_models"]),
                    "error": localefmt.chu(
                        "Cổng này không tự báo danh sách model. Chọn hoặc gõ model bên bán cho dùng ở ô vừa hiện ra, rồi bấm Kết nối lại.",
                        "This gateway does not list its models. Pick or type the model the seller gave you in the box "
                        "that just appeared, then press Connect again.")}
        url = base + "/v1/messages"
        payload = {"model": typed[0], "max_tokens": 1, "messages": [{"role": "user", "content": "ping"}]}
        try:
            async with httpx.AsyncClient(timeout=httpx.Timeout(45, connect=15)) as c:
                r = await c.post(url, headers=headers, json=payload)
        except Exception as e:
            return {"ok": False, "error": localefmt.chu(f"Không gọi được {url} ({type(e).__name__}). Kiểm tra lại Base URL.",
                                                        f"Could not reach {url} ({type(e).__name__}). Check the Base URL.")}
        if r.status_code in (401, 403):
            return {"ok": False, "error": localefmt.chu(f"API key không hợp lệ (HTTP {r.status_code}). Chưa lưu gì.",
                                                        f"Invalid API key (HTTP {r.status_code}). Nothing was saved.")}
        if r.status_code == 404:
            return {"ok": False, "error": localefmt.chu(f"Không thấy {url} (HTTP 404). Kiểm tra Base URL bên bán đưa, "
                                                        "thường có dạng https://ten-mien.com hoặc https://ten-mien.com/anthropic.",
                                                        f"{url} not found (HTTP 404). Check the Base URL the seller gave you, "
                                                        "usually https://domain.com or https://domain.com/anthropic.")}
        # 429/529: the key and the model were accepted, the gateway is only busy right now.
        if r.status_code not in (200, 429, 529):
            return {"ok": False, "error": localefmt.chu(f"Cổng trả HTTP {r.status_code} khi thử model {typed[0]}: {r.text[:160]}",
                                                        f"The gateway returned HTTP {r.status_code} for model {typed[0]}: {r.text[:160]}")}
    ids = _gop_giu_thu_tu(typed, live)
    m["anthropic_compat_base"] = base
    m["anthropic_compat_key"] = key
    m["anthropic_compat_models"] = typed
    m.setdefault("catalog", {})["anthropic-compat"] = ids
    cfgmod.write_settings(cfg)
    _PROV_MODELS_CACHE["anthropic-compat"] = {"ids": ids, "ts": time.time()}
    return {"ok": True, "models": len(ids), "listed": bool(live)}


@app.get("/ollama-local/specs")
async def ollama_local_get_specs():
    ep, _ = _ol_cfg()
    return {"specs": _ol_specs_hien_dung(ep), "same_host": ollama_local.same_host(ep)}


@app.post("/ollama-local/specs")
async def ollama_local_set_specs(ram_gb: float = Form(0), has_gpu: str = Form("0"),
                                 vram_gb: float = Form(0)):
    d = {"source": "manual", "ram_gb": max(0.0, float(ram_gb or 0)),
         "has_gpu": str(has_gpu).strip() in ("1", "true", "True", "on"),
         "vram_gb": max(0.0, float(vram_gb or 0))}
    # Mac chip Apple không có VRAM rời: ô VRAM để 0 nên trang gửi has_gpu=0, khai tay RAM xong là MẤT luôn GPU. Ollama chạy
    # ngay trên máy này và chip là Apple thì giữ GPU dùng chung.
    ep, _ = _ol_cfg()
    if not d["vram_gb"] and ollama_local.same_host(ep):
        tu_doc = await asyncio.to_thread(ollama_local.detect_specs)
        if tu_doc.get("gpu_name") == ollama_local.APPLE_GPU:
            d["has_gpu"], d["gpu_name"] = True, tu_doc["gpu_name"]
    _ol_luu({"ollama_local_specs": d})
    return {"ok": True, "specs": d}


@app.get("/ollama-local/installed")
async def ollama_local_installed():
    ep, key = _ol_cfg()
    if not ep:
        return {"ok": False, "models": [], "error": localefmt.chu("Chưa đặt địa chỉ Ollama",
                                                                  "Ollama address is not set")}
    p = await ollama_local.probe(ep, key)
    if not p["reachable"]:
        return {"ok": False, "models": [], "error": p["error"]}
    dang_nap = {(m.get("name") or "") for m in await ollama_local.running_models(ep, key)}
    ten_ds = [(m.get("name") or m.get("model") or "") for m in p["models"]]
    # Hỏi SONG SONG: `/api/show` là một lượt gọi cho mỗi model, xếp hàng thì màn hình đứng
    # bằng đúng số model nhân thời gian mạng. Hỏng thì trả [] và chat_duoc lui về đoán tên.
    kn_ds = await asyncio.gather(*[ollama_local.kha_nang(ep, t, key) for t in ten_ds],
                                 return_exceptions=True)
    ra = []
    for m, ten, kn in zip(p["models"], ten_ds, kn_ds):
        kn = kn if isinstance(kn, list) else []
        ra.append({"name": ten,
                   "size_gb": round(float(m.get("size") or 0) / (1024 ** 3), 1),
                   "modified_at": m.get("modified_at") or "",
                   # Chốt Ở SERVER: nơi này biết Ollama trả lời gì, giao diện thì không.
                   "chat_duoc": ollama_local.chat_duoc(ten, kn),
                   "loaded": ten in dang_nap})
    ra.sort(key=lambda x: x["name"])
    return {"ok": True, "models": ra}


@app.get("/ollama-local/recommended")
async def ollama_local_recommended():
    ep, key = _ol_cfg()
    specs = _ol_specs_hien_dung(ep)
    da_cai = set()
    if ep:
        p = await ollama_local.probe(ep, key)
        da_cai = {(m.get("name") or "") for m in p["models"]}
    ds = ollama_catalog.goi_y(specs)
    for m in ds:
        m["installed"] = m["name"] in da_cai
    tv = ollama_catalog.thu_vien()
    return {"ok": True, "specs": specs, "models": ds,
            "catalog_source": tv.get("source"), "fetched_at": tv.get("fetched_at")}


@app.get("/ollama-local/search")
async def ollama_local_search(q: str = Query(""), capability: str = Query(""),
                              sort: str = Query("pho-bien"), limit: int = Query(40)):
    ep, key = _ol_cfg()
    da_cai = set()
    if ep:
        p = await ollama_local.probe(ep, key)
        da_cai = {(m.get("name") or "") for m in p["models"]}
    ds = [dict(m) for m in ollama_catalog.tim(q, capability, sort)][:max(1, min(int(limit), 200))]
    for m in ds:
        m["installed"] = m["name"] in da_cai
    tv = ollama_catalog.thu_vien()
    return {"ok": True, "models": ds, "catalog_source": tv.get("source"),
            "fetched_at": tv.get("fetched_at")}


@app.post("/ollama-local/pull")
async def ollama_local_pull(model: str = Form(...)):
    """Tải model, đẩy tiến độ về dashboard bằng SSE.

    HUỶ TẢI = dashboard đóng EventSource. Ollama không có endpoint huỷ, và tài liệu ghi lần
    pull sau tiếp tục từ chỗ dở theo digest - nên không có gì phải dọn, cũng không mất phần đã
    tải. Vì vậy KHÔNG có endpoint /pull/cancel như spec phác: một endpoint không làm gì cả
    là một lời hứa suông trong API.
    """
    ep, key = _ol_cfg()
    ten = (model or "").strip()
    if not ep or not ten:
        return JSONResponse({"error": localefmt.chu("Thiếu địa chỉ Ollama hoặc tên model",
                                                    "Missing Ollama address or model name")}, status_code=400)

    async def phat():
        try:
            async for mo in ollama_local.pull_stream(ep, ten, key):
                yield "data: " + json.dumps(mo, ensure_ascii=False) + "\n\n"
        except Exception as e:
            yield "data: " + json.dumps({"status": "error", "error": str(e)[:200]},
                                        ensure_ascii=False) + "\n\n"
        yield "data: " + json.dumps({"status": "__done__"}) + "\n\n"

    return StreamingResponse(phat(), media_type="text/event-stream",
                             headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"})


@app.post("/ollama-local/delete")
async def ollama_local_delete(model: str = Form(...)):
    ep, key = _ol_cfg()
    if not ep:
        return JSONResponse({"error": localefmt.chu("Chưa đặt địa chỉ Ollama", "Ollama address is not set")},
                            status_code=400)
    r = await ollama_local.delete_model(ep, (model or "").strip(), key)
    return r if r.get("ok") else JSONResponse(r, status_code=502)


@app.get("/runtime/prompt-size")
async def runtime_prompt_size(brain: str = Query("brain")):
    """Bảng phân bổ ký tự của system prompt cho brain này. Xem `do_phan_bo_prompt`.

    Tách riêng khỏi `/runtime/diagnostics` để gọi được một mình: phép đo này lắp lại prompt
    thật nên nó là phép nặng nhất trong trang chẩn đoán, còn người đang gọt prompt thì muốn
    đo lại liên tục mà không phải kéo theo cả ảnh chụp runtime.
    """
    return do_phan_bo_prompt(brain)


@app.get("/runtime/diagnostics")
async def runtime_diagnostics(hours: float = Query(24.0), limit: int = Query(200),
                              brain: str = Query("brain")):
    """Spec mục 27: trang chẩn đoán cho admin.

    Chỉ trả metadata đã có sẵn trong runtime.db. Không objective (đang mã hoá),
    không actor hash, không excerpt evidence, không arguments. Trang này để trả lời
    "token đi đâu", không phải để đọc lại hội thoại.
    """
    snapshot = _CONTEXT_RUNTIME.diagnostics_snapshot(limit=limit, hours=hours)
    settings = cfgmod.read_settings().get("context_runtime") or {}
    canaries = {}
    for key, value in settings.items():
        if isinstance(value, dict) and "allocation_basis_points" in value:
            canaries[key] = {
                "allocation_basis_points": value.get("allocation_basis_points", 0),
                "policy_version": value.get("policy_version", ""),
                # Đếm thôi, không trả nội dung rule: chúng chứa hạn mức tài khoản thật.
                "quota_rules": len(value.get("quota_profiles") or value.get("models") or []),
                "allowlist": len(value.get("capability_profiles")
                                 or value.get("allowed_slugs") or []),
            }
    registry = {}
    try:
        registry = _CAPABILITY_REGISTRY.integrity_check()
    except Exception as exc:
        registry = {"error": type(exc).__name__}
    try:
        prompt_size = do_phan_bo_prompt(brain)
    except Exception as exc:   # noqa: BLE001 - một khối hỏng không được làm mất cả trang
        prompt_size = {"loi": type(exc).__name__}
    return {**snapshot, "canaries": canaries, "registry": registry,
            # Ký tự cố định đi kèm MỌI lượt chat, tách theo khối. Trang này sinh ra để trả
            # lời "token đi đâu", mà phần đi đều đặn nhất thì trước đây không có ở đây.
            "prompt_size": prompt_size,
            # Provider đã tra được hạn mức gợi ý - để trang Chẩn đoán dựng ô chọn thay vì
            # bắt người vận hành nhớ tên provider nào có preset.
            "quota_presets": model_limits.known_providers(),
            # Token đã đốt trong 60 giây qua, gộp MỌI nguồn. Đây là thứ trả lời được câu
            # "sao canary bị chặn trong khi tôi có chat gì đâu": loop nền vừa ăn hết hạn mức.
            "tpm_window": quota_scheduler.snapshot(60),
            # Hạn mức Javis TỰ HỌC từ lỗi nhà cung cấp trả về. Khác quota_presets ở chỗ
            # đây là số thật của tài khoản này, do chính nhà cung cấp nói ra.
            "learned_limits": limit_learner.snapshot(),
            # Mức tiết kiệm token đang chọn + danh sách mức, để giao diện vẽ ba nút thay
            # vì bắt người dùng tự hiểu 10 đường canary và đơn vị basis point.
            "preset": current_preset(settings),
            "presets": [{"id": k, **_preset_chu(k, v)}
                        for k, v in RUNTIME_PRESETS.items()],
            # Mức đang chạy là do NGƯỜI DÙNG chọn, hay chỉ là mặc định của bản đã cài? Hai
            # thứ đó trông y hệt nhau trên màn hình mà ý nghĩa ngược nhau: cái sau sẽ đi lên
            # theo bản cập nhật, cái trước thì không. Nói ra để người dùng biết mình đang ở
            # đâu, và biết rằng bấm một mức là ghim lại.
            "preset_nguon": str((settings.get("preset_choice") or {}).get("source") or ""),
            "preset_mac_dinh": cfgmod.PRESET_MAC_DINH,
            # Bộ não đang chạy có ăn được phần tiết kiệm này không. Câu hỏi đầu tiên của
            # người dùng khi mở trang, mà trước đây trang không trả lời được: bảng canary
            # chỉ hiện allocation, còn việc engine của họ có nằm trong provider_kinds hay
            # không thì phải SSH đọc settings.json mới biết.
            "engine_hien_tai": _engine_runtime_view(settings),
            # Mỗi mức tiết kiệm được bao nhiêu phần trăm. Không có con số này thì ba nút chỉ
            # là ba cái tên, người dùng bấm mà không biết đổi được gì.
            "uoc_tinh": await _uoc_tinh_tiet_kiem(brain),
            # Và con số ĐO ĐƯỢC từ chính các lượt đã chạy, đáng tin hơn hẳn ước lượng.
            "do_duoc": _do_duoc_tiet_kiem(snapshot.get("tasks") or [],
                                          snapshot.get("window_hours") or 24,
                                          cfgmod.read_settings().get("model", {}) or {}),
            # Lý do LẶP LẠI nhiều nhất khiến lượt không đi được đường tắt. Đây là câu trả lời
            # cho "sao chưa lần nào thấy chữ Tức thì" - thứ trước đây chỉ đoán được.
            "vi_sao": _vi_sao_chua_di_tat(snapshot.get("tasks") or [])}


def _ctx_frame(trace, tokens_in, tokens_cache=0) -> dict:
    """Cho khung chat biết lượt vừa rồi đi đường nào và tốn bao nhiêu token vào.

    Vì sao cần: trước đây không có cách nào biết một lượt đã đi đường tiết kiệm hay lặng lẽ
    tụt về đường cũ - phải đợi tới lúc nhà cung cấp báo vượt hạn mức mới lộ ra, mà lúc đó thì
    đã muộn. Một dòng nhỏ dưới câu trả lời biến thứ vô hình thành thứ nhìn thấy được.

    Không có trace thì coi như đường cũ: nói "chưa rõ" ở đây chỉ làm người đọc phân vân, mà
    đường cũ đúng là thứ chạy khi runtime chưa gắn vào."""
    try:
        path = str(getattr(trace, "execution_path", "") or "")
    except Exception:  # noqa: BLE001 - phần hiển thị, không được phá lượt chat
        path = ""
    tin = max(0, int(tokens_in or 0))
    out = {"ctx_path": path if path and path != "unassigned" else "legacy", "ctx_in": tin}
    # 0.345.0: phần đọc lại từ cache. `ctx_in` là TỔNG mọi vòng gọi model trong lượt, gồm cả phần cache rẻ hơn nhiều,
    # nên một câu chào trên Claude Code hiện "60k token" và người dùng tưởng mình vừa tiêu 60k token mới.
    ca = max(0, min(int(tokens_cache or 0), tin))
    if ca:
        out["ctx_cache"] = ca
    return out


async def _uoc_tinh_tiet_kiem(brain: str = "brain") -> dict:
    """Mỗi mức tiết kiệm được bao nhiêu PHẦN TRĂM token mỗi request.

    Đo trên prompt THẬT của brain đang chọn, không phải con số quảng cáo. Người dùng bấm một
    mức mà không biết nó đổi được gì thì bấm cũng như không - đó là lý do trang này bị chê
    "không hiểu dùng như nào".

    Ba con số:
      - Tắt: gửi nguyên CLAUDE.md + chỉ mục bộ nhớ + khối skill + mô tả tool.
      - Tối ưu: capsule nhỏ thay chỗ CLAUDE.md, vẫn kèm mô tả tool.
      - Siêu tiết kiệm: như trên, và câu hỏi đơn giản đi thẳng không kèm mô tả tool.

    Dùng CHÍNH hệ số ký tự-trên-token mà runtime đang dùng để ước lượng, để con số ở đây và
    con số ở chỗ khác không đá nhau. Đây là ƯỚC LƯỢNG: bộ đếm token thật của từng nhà cung
    cấp khác nhau, và tiếng Việt có dấu tốn hơn tiếng Anh. Giao diện phải nói rõ là ước lượng.
    """
    # Gọi thẳng hàm endpoint trong test thì tham số mặc định vẫn là object Query(...) chứ
    # không phải chuỗi. Không chặn ở đây là cả bảng ước tính im lặng trả rỗng, và test đi qua
    # endpoint chỉ đo được cái vỏ.
    if not isinstance(brain, str) or not brain.strip():
        brain = "brain"
    try:
        cfg = cfgmod.read_settings().get("context_runtime") or {}
        ratio = max(1.0, float(cfg.get("estimate_chars_per_token") or 3.0))
    except Exception:  # noqa: BLE001 - phần thông tin, không được làm sập trang
        ratio = 3.0

    def tok(text: str) -> int:
        return int(math.ceil(len(str(text or "")) / ratio))

    def _dung_prompt_cu() -> str:
        return build_system_prompt(brain) + channel_context.build_channel_block(
            "dashboard", {"session_id": "uoc-tinh"}, telegram_running=bool(_TG_BOT),
            port=_javis_port(), brain_root=_brain_root(brain))

    try:
        # build_system_prompt quét cây skill và đọc file, khoảng 18ms - đẩy sang thread để
        # trang chẩn đoán không chặn vòng lặp sự kiện.
        cu = tok(await asyncio.to_thread(_dung_prompt_cu))
    except Exception:  # noqa: BLE001
        return {}
    try:
        cc = context_compiler
        vien = tok(cc.CORE_CONTRACT
                   + "Runtime identity: provider=x; model=y. "
                   + cc.ContextCompiler._channel_contract("dashboard")
                   + cc.dong_ho()
                   + cc.ContextCompiler._output_contract_text("dashboard"))
    except Exception:  # noqa: BLE001
        return {}
    try:
        # discover_all trả danh sách ĐÃ qua tầng lazy - tức đúng thứ được gửi đi thật, không
        # phải kho tool đầy đủ. Lấy nhầm bản đầy đủ là thổi phồng con số tiết kiệm.
        spec, _route = await mcp_hub.discover_all(mode="full", vault_root=_brain_root(brain))
        cong_cu = tok(json.dumps(spec, ensure_ascii=False))
    except Exception:  # noqa: BLE001 - thiếu tool thì tính phần còn lại, đừng bỏ cả bảng
        cong_cu = 0

    goc = max(1, cu + cong_cu)

    def muc(token_moi_request: int) -> int:
        return max(0, min(99, round((1 - token_moi_request / goc) * 100)))

    # Đường tắt của mức "Siêu tiết kiệm" (fast path) CHỈ chạy trên engine dùng API key: nó
    # nằm trong nhánh `kind == "api"` của _do_turn, và provider_kinds mặc định của nó cũng
    # chỉ có "api". Với gói thuê bao (Claude Code, ChatGPT) thì mức đó y hệt mức Tối ưu.
    # Vẫn khoe "giảm 96%" cho họ là hứa một con số không bao giờ tới - đúng kiểu knob xoay
    # mà đèn không sáng. Nên đo xong thì kiểm luôn xem bộ não đang chạy có ăn được không.
    # ĐỌC cấu hình thật, KHÔNG gõ cứng. Bản trước viết `fast_hop = _kind == "api"` vì lúc đó
    # đường tắt mới chỉ chạy trên engine API key. Tới 0.14.0 nó mở cho cả gói ChatGPT, mà dòng
    # gõ cứng này không ai nhớ sửa - nên trang vẫn dán nhãn "không áp cho bộ não đang dùng"
    # lên đúng mức vừa được mở, và chủ repo bấm vào rồi tưởng mình bấm nhầm. Đọc thẳng
    # provider_kinds của đường tắt thì lần sau mở thêm bộ não nào, trang tự đúng theo.
    try:
        _st = cfgmod.read_settings()
        _prov, _kind, _k, _m = _chat_provider(_st.get("model", {}) or {})
        _kinds_tat = [str(x) for x in (((_st.get("context_runtime") or {}).get("canary") or {})
                                       .get("provider_kinds") or ["api"])]
    except Exception:  # noqa: BLE001 - phần thông tin, không được làm sập trang
        _kind, _kinds_tat = "api", ["api"]
    fast_hop = _kind in _kinds_tat
    max_token = vien if fast_hop else (vien + cong_cu)
    return {
        "chu_ky_ky_tu_tren_token": ratio,
        "la_uoc_luong": True,
        "kind_bo_nao": _kind,
        "chi_tiet": {"claude_md_va_bo_nho": cu, "capsule": vien, "mo_ta_cong_cu": cong_cu},
        "muc": {
            "off": {"token_moi_request": goc, "phan_tram": 0, "ap_dung": True,
                    "ghi_chu": localefmt.chu("Gửi nguyên bộ luật, bộ nhớ và danh sách skill mỗi lượt.",
                                             "Sends the full rules, memory and skill list every turn.")},
            "saving": {"token_moi_request": vien + cong_cu, "phan_tram": muc(vien + cong_cu),
                       "ap_dung": True,
                       "ghi_chu": localefmt.chu(
                           "Thay bộ luật dài bằng bản rút gọn; nhớ và skill chỉ nạp phần liên quan.",
                           "Replaces the long rules with a short version; memory and skills load only "
                           "what is relevant.")},
            "max": {"token_moi_request": max_token, "phan_tram": muc(max_token),
                    "ap_dung": fast_hop,
                    "ghi_chu": (localefmt.chu(
                                    "Như trên, và câu hỏi đơn giản đi thẳng không kèm mô tả công cụ. "
                                    "Câu cần tra cứu vẫn đi đường đầy đủ, nên không phải lượt nào "
                                    "cũng thấy khác.",
                                    "As above, and simple questions go straight through without tool "
                                    "descriptions. Questions that need a lookup still take the full "
                                    "route, so not every turn looks different.")
                                if fast_hop else
                                localefmt.chu(
                                    "Đường tắt cho câu hỏi đơn giản chưa mở cho loại bộ não đang "
                                    "chạy, nên bấm mức này cũng chỉ bằng mức Tối ưu.",
                                    "The shortcut for simple questions is not open for the kind of "
                                    "brain in use, so this level is the same as Optimized.")),
                    },
        },
    }


# Giá THAM KHẢO của 1 TRIỆU token ĐẦU VÀO, đơn vị USD. Chỉ để quy đổi phần token tiết kiệm
# được ra một con số tiền cho dễ hình dung - "giảm 38%" không nói lên điều gì với người đang
# trả tiền, còn "khoảng 40 nghìn một tháng" thì có.
#
# Đây là con số THAM KHẢO và sẽ cũ đi: giá của các nhà cung cấp đổi vài tháng một lần. Nên
# giao diện phải nói rõ là ước lượng, và người dùng đặt được số của chính mình qua
# settings.model.gia_input_1m (USD cho 1 triệu token vào) để đè lên bảng này.
#
# Khớp theo CHUỖI CON của tên model, dài trước ngắn sau, nên "claude-opus-5" ăn mục "opus-5"
# chứ không rơi về mục "opus" trần, càng không rơi về mức mặc định.
#
# Dòng Claude khai theo TỪNG BẢN chứ không gộp một mục "opus": Anthropic đã hạ giá dòng Opus
# từ 15$ xuống 5$ mỗi triệu token đầu vào kể từ 4.5, còn Fable thì ĐẮT HƠN Opus (10$). Gộp
# một mục là khai vống chi phí của người chạy Opus 5 lên gấp ba, và khai hụt của người chạy
# Fable đi ba lần - cả hai đều rơi thẳng vào con số tiền trên trang Mức dùng. Mục "opus" trần
# giữ lại cho các bản 4.1 trở về trước, vẫn đúng giá của chúng.
_GIA_INPUT_1M = {
    "fable": 10.0, "mythos": 10.0,
    "opus-5": 5.0, "opus-4-8": 5.0, "opus-4-7": 5.0, "opus-4-6": 5.0, "opus-4-5": 5.0,
    "opus": 15.0, "sonnet-5": 2.0, "sonnet": 3.0, "haiku": 1.0,
    "gpt-5-mini": 0.25, "gpt-5": 1.25, "gpt-4o-mini": 0.15, "gpt-4o": 2.5, "o3": 2.0,
    "gemini-2.5-pro": 1.25, "gemini-2.5-flash": 0.30, "gemini": 0.30,
    "deepseek": 0.30, "llama": 0.10, "qwen": 0.20, "mistral": 0.20, "grok": 2.0,
}
_GIA_INPUT_MAC_DINH = 3.0     # không đoán được model thì lấy mức phổ biến tầm trung
# Mọi con số tiền trên trang Mức dùng đều để nguyên USD. Trước đây có thêm một lớp quy đổi ra
# đồng bằng tỉ giá gõ cứng, và lớp đó chỉ tạo ra một con số thứ ba để sai: giá của mọi nhà
# cung cấp đều niêm yết bằng USD, còn tỉ giá thì trôi và không ai đi cập nhật hằng số đó.


def _ten_model_chinh(mcfg: dict) -> str:
    """Tên model chính đang chạy, lấy từ ĐÚNG chỗ nó nằm.

    `settings["model"]` KHÔNG có khoá `"model"` - tên model nằm ở `main.model`, và với cấu
    hình cũ thì ở `claude_model` / `openrouter_model`. Đọc `mcfg.get("model")` luôn ra rỗng,
    nên mọi phép quy đổi tiền rơi về đơn giá mặc định 3$ bất kể người dùng đang chạy Opus
    (15$) hay Haiku (1$). Sai im lặng: con số vẫn hiện ra, chỉ là sai vài lần.
    """
    m = mcfg or {}
    # Thứ tự có chủ ý:
    #   1. `main.model` - chỗ trang Models ghi vào, đúng nhất khi có.
    #   2. khoá `model` phẳng - KHÔNG tồn tại trong settings thật, nhưng vài chỗ trong server
    #      gọi hàm này với một dict tự dựng kiểu {"model": "..."} để hỏi giá của một model cụ
    #      thể. Bỏ qua nó là lặng lẽ trả lời về một model khác với model được hỏi.
    #   3. `_chat_provider` - bộ giải mà chính đường chat dùng, hiểu cả cấu hình cũ (`engine`).
    #   4. các khoá cũ, chỉ khi ba bước trên đều câm.
    # Bước 4 phải nằm SAU bước 3: `openrouter_model` có sẵn giá trị "openai/gpt-4o-mini" ngay
    # trong cấu hình xuất xưởng, kể cả khi engine đang là anthropic-cli chạy Opus. Dò tay
    # trước là lấy $0,15 thay cho $15 - lệch 100 lần, theo hướng khai thấp phần tiết kiệm.
    ten = ((m.get("main") or {}).get("model") or "").strip()
    if ten:
        return ten
    ten = str(m.get("model") or "").strip()
    if ten:
        return ten
    try:
        _prov, _kind, _key, model = _chat_provider(m)
        if str(model or "").strip():
            return str(model).strip()
    except Exception:  # noqa: BLE001 - phần thông tin, rơi về cách dò tay bên dưới
        pass
    for khoa in ("claude_model", "openrouter_model"):
        v = str(m.get(khoa) or "").strip()
        if v:
            return v
    return ""


def _gia_input_1m(model: str, settings_model: dict = None) -> tuple:
    """(giá USD cho 1 triệu token vào, nguồn của con số đó)."""
    try:
        tay = float((settings_model or {}).get("gia_input_1m") or 0)
        if tay > 0:
            return tay, "tay"
    except (TypeError, ValueError):
        pass
    m = str(model or "").lower()
    for khoa in sorted(_GIA_INPUT_1M, key=len, reverse=True):
        if khoa in m:
            return _GIA_INPUT_1M[khoa], "bang"
    return _GIA_INPUT_MAC_DINH, "mac_dinh"


def _do_duoc_tiet_kiem(tasks: list, window_hours: float = 24.0,
                       settings_model: dict = None) -> dict:
    """Tiết kiệm ĐO ĐƯỢC từ chính các lượt đã chạy, không phải ước lượng.

    Con số này đáng tin hơn hẳn phần ước lượng vì nó là token nhà cung cấp thật sự tính. Đổi
    lại, nó chỉ có khi đã chạy cả hai đường trong cùng cửa sổ thời gian - nên giao diện phải
    chịu được ca "chưa đủ dữ liệu" thay vì hiện 0% một cách vô nghĩa.

    Ngoài phần trăm, trả thêm SỐ TOKEN thật đã tiết kiệm và quy đổi ra tiền. Phần trăm một
    mình không trả lời được câu người dùng thật sự muốn hỏi: "cái công tắc này đáng bao
    nhiêu?". Cách tính token tiết kiệm: mỗi lượt đi đường mới đáng lẽ tốn bằng trung bình của
    đường cũ, nên phần chênh nhân số lượt là phần không phải trả.
    """
    cu, moi = [], []
    for t in tasks or []:
        n = int(t.get("actual_input_tokens") or t.get("estimated_input_tokens") or 0)
        if n <= 0:
            continue
        duong = str(t.get("execution_path") or "")
        if duong in ("legacy", "unassigned"):
            cu.append(n)
        elif duong in ("sources", "fast"):
            moi.append(n)
    out = {"so_luot_cu": len(cu), "so_luot_moi": len(moi),
           "tb_cu": round(sum(cu) / len(cu)) if cu else 0,
           "tb_moi": round(sum(moi) / len(moi)) if moi else 0,
           "phan_tram": 0, "du_du_lieu": bool(cu and moi),
           "token_tiet_kiem": 0, "gio_do": round(float(window_hours or 24), 1),
           "token_thang": 0, "tien": {}}
    if not (out["du_du_lieu"] and out["tb_cu"] > 0):
        return out
    out["phan_tram"] = max(0, min(99, round((1 - out["tb_moi"] / out["tb_cu"]) * 100)))
    chenh = max(0, out["tb_cu"] - out["tb_moi"])
    out["token_tiet_kiem"] = chenh * out["so_luot_moi"]
    # Chiếu ra một tháng theo đúng nhịp của cửa sổ vừa đo. Là PHÉP CHIẾU chứ không phải số đã
    # xảy ra, nên giao diện phải gọi nó là "theo nhịp này" chứ đừng ghi như một hoá đơn.
    gio = max(1.0, float(out["gio_do"]))
    out["token_thang"] = round(out["token_tiet_kiem"] * (24 * 30 / gio))
    gia, nguon = _gia_input_1m(_ten_model_chinh(settings_model or {}), settings_model)
    out["tien"] = {
        "gia_1m_usd": gia, "nguon_gia": nguon,
        "usd": round(out["token_tiet_kiem"] / 1_000_000 * gia, 4),
        "usd_thang": round(out["token_thang"] / 1_000_000 * gia, 2),
    }
    return out


def _vi_sao_chua_di_tat(tasks: list) -> dict:
    """Gộp lý do của những lượt KHÔNG đi đường tắt, xếp theo số lần.

    Vì sao cần con số gộp trong khi bảng "Lượt gần nhất" đã ghi lý do từng lượt: một lý do
    lặp lại 18 trên 20 lượt là một CÁI HỎNG, còn cùng lý do đó xuất hiện 2 lần là chuyện
    bình thường. Bảng từng dòng không phân biệt nổi hai ca đó, và chủ repo đã phải nói bằng
    lời "chưa lần nào thấy chữ Tức thì" thay vì chỉ vào một con số. Đó là lúc trang chẩn đoán
    thua: người dùng biết có gì đó sai mà trang không nói được sai ở đâu.
    """
    dem: dict[str, int] = {}
    tong = 0
    for t in tasks or []:
        if str(t.get("execution_path") or "") == "fast":
            continue
        ly = str(t.get("ly_do") or "").strip()
        if not ly:
            continue
        tong += 1
        dem[ly] = dem.get(ly, 0) + 1
    top = sorted(dem.items(), key=lambda kv: (-kv[1], kv[0]))[:3]
    return {"tong": tong, "top": [{"ma": k, "so_lan": v} for k, v in top]}


def _engine_runtime_view(settings: dict) -> dict:
    """Bộ não đang dùng ăn được những đường tiết kiệm nào. Cho trang Tiết kiệm token.

    Mọi lỗi nuốt về một khối "chưa biết": đây là phần THÔNG TIN của trang chẩn đoán, không
    được phép làm chính trang chẩn đoán sập."""
    try:
        prov, kind, _key, model = _chat_provider(cfgmod.read_settings().get("model", {}) or {})
        label = (_provider_def(prov) or {}).get("label") or prov
        thue_bao = kind in ("cli", "oauth")
        hop, khong = [], []
        for name, value in (settings or {}).items():
            if not (isinstance(value, dict) and "allocation_basis_points" in value):
                continue
            if int(value.get("allocation_basis_points") or 0) <= 0:
                continue
            kinds = [str(x) for x in (value.get("provider_kinds") or ["api"])]
            (hop if kind in kinds else khong).append(name)
        if not (hop or khong):
            giai_thich = localefmt.chu("Chưa bật mảng nào, nên mọi lượt vẫn đi đường cũ. Chọn một mức ở trên.",
                                       "No saving path is on, so every turn still takes the old route. "
                                       "Pick a level above.")
        elif hop:
            giai_thich = (localefmt.chu(f"{label} đang ăn được {len(hop)} mảng tiết kiệm.",
                                        f"{label} benefits from {len(hop)} saving path(s).")
                          + (localefmt.chu(f" {len(khong)} mảng khác không áp cho loại bộ não này.",
                                           f" {len(khong)} other path(s) do not apply to this kind of brain.")
                             if khong else ""))
        else:
            giai_thich = localefmt.chu(f"Đã bật {len(khong)} mảng nhưng không mảng nào áp cho {label}, "
                                       "nên thực tế chưa tiết kiệm được gì.",
                                       f"{len(khong)} path(s) on, but none applies to {label}, "
                                       "so nothing is actually being saved yet.")
        return {"provider": prov, "nhan": label, "kind": kind, "model": model or "",
                "loai": localefmt.chu("Gói thuê bao", "Subscription plan") if thue_bao else "API key",
                # Cờ máy đọc: `loai` là nhãn tiếng Việt, giao diện không được so chuỗi với nó.
                "thue_bao": bool(thue_bao),
                "duong_hop": sorted(hop), "duong_khong_hop": sorted(khong),
                "giai_thich": giai_thich}
    except Exception:   # noqa: BLE001 - xem docstring
        return {"provider": "", "nhan": "", "kind": "", "model": "", "loai": "",
                "thue_bao": False, "duong_hop": [], "duong_khong_hop": [],
                "giai_thich": localefmt.chu("Chưa đọc được cấu hình bộ não.",
                                            "Could not read the brain configuration.")}


def _shrink_messages(messages: list, target_tokens: int) -> list:
    """Co danh sách message xuống dưới `target_tokens`, giữ thứ cần nhất.

    Thứ tự hy sinh, từ bỏ được nhất tới không bỏ được:
      1. Lịch sử hội thoại cũ (bỏ từ cũ nhất).
      2. Phần đuôi của system prompt.
    KHÔNG bao giờ bỏ câu hỏi hiện tại của người dùng - bỏ nó thì có trả lời cũng vô nghĩa.

    target_tokens <= 0 nghĩa là không biết hạn mức: vẫn co bằng cách bỏ lịch sử, vì đó là
    thứ duy nhất chắc chắn giúp được mà không làm hỏng câu trả lời.
    """
    if not messages:
        return messages
    system = [m for m in messages if m.get("role") == "system"]
    rest = [m for m in messages if m.get("role") != "system"]
    last_user = rest[-1:] if rest else []
    kept = system + last_user           # bỏ sạch lịch sử, giữ prompt lõi + câu hỏi
    if target_tokens <= 0:
        return kept
    # Vẫn quá thì cắt bớt đuôi system prompt. Ước lượng thô là đủ: đây đã là đường cứu hộ.
    budget_chars = max(1000, int(target_tokens) * 3)
    total = sum(len(str(m.get("content") or "")) for m in kept)
    if total <= budget_chars or not system:
        return kept
    over = total - budget_chars
    trimmed = []
    for m in kept:
        if m.get("role") == "system" and over > 0:
            body = str(m.get("content") or "")
            cut = min(over, max(0, len(body) - 500))
            if cut > 0:
                over -= cut
                body = body[:len(body) - cut] + "\n[... đã rút gọn để vừa hạn mức ...]"
            trimmed.append({**m, "content": body})
        else:
            trimmed.append(m)
    return trimmed


_LIMIT_KIND_LABEL = {
    "tpm": "token mỗi phút", "tpd": "token mỗi ngày",
    "rpm": "số lượt mỗi phút", "rpd": "số lượt mỗi ngày",
    "context": "cửa sổ ngữ cảnh", "rate": "nhịp gọi",
}
# Bản tiếng Anh cho dòng trạng thái trên màn hình (khung `javis_autoshrink`). Câu trả lời
# `_limit_autoshrink_message` vẫn dùng bản tiếng Việt ở trên vì nó vào lịch sử hội thoại.
_LIMIT_KIND_LABEL_EN = {
    "tpm": "tokens per minute", "tpd": "tokens per day",
    "rpm": "requests per minute", "rpd": "requests per day",
    "context": "context window", "rate": "request rate",
}


def _limit_autoshrink_message(provider: str, model: str, hit: dict) -> str:
    """Câu nói khi nhà cung cấp chặn vì hạn mức. Lời khuyên phải khớp ĐÚNG loại hạn mức.

    Bản trước gộp mọi thứ thành "request quá lớn, rút gọn yêu cầu đi". Với gói Groq - siết
    bốn chiều cùng lúc và cả bốn đều mở đầu bằng "Rate limit reached" - lời khuyên đó sai với
    ba trong bốn trường hợp, và người dùng thấy đúng câu này:

        "groq báo request quá lớn ... Lượt này cần khoảng 0 token, trong khi groq giới hạn
         12,000 token mỗi phút."

    Con số 0 là vì không đọc được gì từ lỗi; con 12.000 thì lấy từ BẢNG TRA SẴN trong code
    chứ không phải từ Groq. Ghép hai thứ đó lại thành một câu nghe như đã hiểu chuyện là kiểu
    hỏng tệ nhất: nó vừa sai, vừa che mất bằng chứng để lần ra cái sai.

    Nguyên tắc bây giờ: biết tới đâu nói tới đó, không biết thì đưa nguyên văn lời nhà cung
    cấp ra chứ không bịa một câu cho tròn.
    """
    limit = int(hit.get("limit") or 0)
    requested = int(hit.get("requested") or 0)
    used = int(hit.get("used") or 0)
    remedy = str(hit.get("remedy") or "")
    nhan = _LIMIT_KIND_LABEL.get(str(hit.get("kind") or ""), "hạn mức")
    raw = str(hit.get("raw") or "").strip()
    cho = float(hit.get("retry_after") or 0)

    if not limit:
        # Không đọc được con số nào. Đây là lúc TUYỆT ĐỐI không được nói như thể đã hiểu.
        loi = f'\n\n{provider} nói nguyên văn: "{raw}"' if raw else ""
        if remedy == "wait" and cho:
            return (f"{provider} đang chặn nhịp gọi, bảo chờ {cho:.0f} giây. "
                    f"Bạn hỏi lại sau chừng đó là được.{loi}")
        return (f"{provider} từ chối lượt này vì hạn mức, nhưng không nói rõ hạn mức nào nên "
                f"Javis chưa biết phải làm gì để qua.{loi}")

    dau = f"{provider} báo vượt {nhan}: hạn mức {limit:,}"
    if used:
        dau += f", đã dùng {used:,}"
    if requested:
        dau += f", lượt này xin thêm {requested:,}"
    dau += ". "

    if remedy == "wait_long":
        # Cửa sổ NGÀY. Rút gọn hoàn toàn vô ích ở đây - nói thẳng ra thay vì để người dùng
        # ngồi cắt câu hỏi cho ngắn rồi vẫn lỗi.
        return (dau + "Đây là hạn mức theo NGÀY nên rút gọn câu hỏi không giúp gì cả. "
                "Phải chờ sang ngày mới, hoặc đổi tạm sang bộ não khác ở trang Models, "
                "hoặc nâng gói với nhà cung cấp.")
    if remedy == "wait":
        khi_nao = f" khoảng {cho:.0f} giây nữa" if cho else " một lát"
        return (dau + f"Cửa sổ hiện tại đã đầy vì các lượt trước, hỏi lại{khi_nao} là được. "
                "Rút gọn câu hỏi không giúp vì hạn mức này đếm theo thời gian.")
    return (dau + "Javis đã tự rút gọn ngữ cảnh và thử lại một lần nhưng vẫn không vừa. "
            + model_limits.blocked_hint(provider, model, requested or limit,
                                        _configured_api_providers()))


def _configured_api_providers() -> tuple:
    """Provider API mà người dùng ĐÃ cắm khoá - để gợi ý đường lui CÓ THẬT.

    Chỉ đọc SỰ TỒN TẠI của khoá, không đọc giá trị. Đây là phần phụ của một câu báo lỗi nên
    mọi trục trặc đều nuốt về rỗng: gợi ý sai còn đỡ hơn làm hỏng chính câu báo lỗi."""
    try:
        mcfg = (cfgmod.read_settings() or {}).get("model") or {}
    except Exception:   # noqa: BLE001 - xem docstring
        return ()
    out = []
    for pdef in PROVIDER_DEFS:
        field = pdef.get("key_field")
        if field and str(mcfg.get(field) or "").strip():
            out.append(pdef["label"])
    return tuple(out)


def _subscription_limit_event(raw: str, engine_hint: str):
    """(câu người dùng hiểu, SubscriptionLimit) cho lỗi "gói thuê bao hết lượt"; ("", None) nếu
    không phải loại lỗi này. Khung chat cần cả hai: câu chữ để hiện, mốc reset để hẹn chạy lại."""
    try:
        hit = limit_learner.parse_subscription_limit(raw, engine_hint=engine_hint)
        if not hit:
            return "", None
        return model_limits.subscription_blocked_hint(hit, _configured_api_providers()), hit
    except Exception:   # noqa: BLE001 - không được để câu báo lỗi tự nó nổ
        return "", None


# Nhà chạy agent (AGENT_PROVIDERS) -> tên engine mà limit_learner hiểu. Nhà không có trong
# bảng (API key thuần) thì để rỗng: gói thuê bao chỉ là chuyện của bốn nhà dưới đây, gán bừa
# một cái tên là câu báo lỗi nói sai tên gói người dùng phải đi gia hạn.
# Bảng thật nằm ở limit_learner.ENGINE_HINT_BY_PROVIDER để hàng đợi Kanban (tasks.py) dùng
# chung; tên cũ giữ lại cho các chỗ gọi trong file này.
_NHA_SANG_ENGINE = limit_learner.ENGINE_HINT_BY_PROVIDER


# Tên cũ, giữ cho test và chỗ gọi; giá trị thật ở limit_learner.
_TRAN_OUT_HET_LUOT = limit_learner.DOMINATES_MAX_CHARS
_DAU_DONG_HET_LUOT = limit_learner.DOMINATES_LINE_START


def _het_luot_ap_dao(raw: str) -> bool:
    """Câu báo hết lượt có CHIẾM output này không, hay chỉ được trích trong một bài viết?

    Đây là hàng rào chống chính cái loại hỏng mà bản vá hết lượt sinh ra để dập. Một agent viết
    bài hoàn toàn có thể viết: Khi gặp thông báo "You have reached your session limit" thì nên
    chờ. Nhận nhầm câu đó là bước bị vứt nguyên bài viết thật (không có step_done nên không
    sang {{prev}}) và người dùng bị báo là hết gói trong khi gói vẫn còn - tệ hơn hẳn lỗi cũ.

    Ba điều kiện, phải đúng cả: output ngắn (bài thật thì dài hơn nhiều), câu báo mở đầu dòng
    của nó HOẶC chiếm quá nửa dòng đó. Câu nhà cung cấp in ra luôn thoả; câu trích giữa một câu
    văn thì không. Thân hàm nay ở `limit_learner.subscription_dominates` để việc Kanban dùng
    chung một bộ nhận dạng (tasks.py không import được main).
    """
    return limit_learner.subscription_dominates(raw or "")


def _loi_het_luot_cua_buoc(out: str, loi: str, provider: str, agent_name: str) -> str:
    """Câu tiếng Việt khi một BƯỚC workflow dừng vì gói thuê bao hết lượt. "" = không phải.

    Vì sao phải soi cả `out` chứ không chỉ `loi`: nhà cung cấp thường KHÔNG báo hết lượt như
    một lỗi, mà in nguyên văn câu tiếng Anh ra đúng chỗ câu trả lời ("You've hit your session
    limit - resets 12pm (UTC)"). Không soi `out` thì bước coi như chạy xong, và người dùng đọc
    được câu tiếng Anh đó như thể nó là KẾT QUẢ của quy trình - đúng cái đã xảy ra 15/09.

    Dùng lại bộ nhận dạng của khung chat (`_subscription_limit_event`) chứ không viết bộ thứ
    hai: hai bộ nhận dạng thì mẫu câu mới chỉ được thêm vào một chỗ."""
    hint = _NHA_SANG_ENGINE.get(str(provider or "").strip(), "")
    for raw, phai_ap_dao in ((out, True), (loi, False)):
        if phai_ap_dao and not _het_luot_ap_dao(raw or ""):
            continue
        noi, _lim = _subscription_limit_event(raw or "", hint)
        if not noi:
            continue
        ten = str(agent_name or "").strip()
        if ten:
            noi += (f" Bước này chạy bằng trợ lý \"{ten}\", nên muốn chạy tiếp ngay thì trỏ "
                    "riêng trợ lý đó sang model khác ở trang Models.")
        return noi
    return ""


def _subscription_limit_message(raw: str, engine_hint: str) -> str:
    """Đổi lỗi thô "gói thuê bao hết lượt" thành câu người dùng hiểu. "" nếu không phải.

    Vì sao cần: Claude Code và Codex in ra nguyên văn câu tiếng Anh của nhà cung cấp, có khi
    còn là dạng máy đọc ("Claude AI usage limit reached|1730000000"). Đẩy thẳng chuỗi đó ra
    khung chat là người dùng thấy một lỗi lạ mà không biết phải làm gì - đúng cái kiểu hỏng
    mà dải đỏ "mở terminal gõ /login" từng mắc.

    Ranh giới: KHÔNG tự đổi engine hộ. Chuyển sang một bộ não khác là tiêu hạn mức của một
    tài khoản khác, có khi mất tiền thật - đó là quyết định của người dùng. Việc của câu này
    là nói rõ hết lượt tới bao giờ và bộ não nào đang sẵn sàng.
    """
    return _subscription_limit_event(raw, engine_hint)[0]


def _canary_keys() -> set:
    """Tên các đường canary hợp lệ, lấy từ CHÍNH _DEFAULT chứ không chép tay.

    Chép tay thì thêm phase mới là danh sách lệch, và endpoint sẽ từ chối một đường có
    thật với lý do 'không tồn tại'. Nguồn sự thật duy nhất là cấu hình mặc định."""
    rt = (cfgmod._DEFAULT.get("context_runtime") or {})
    return {k for k, v in rt.items()
            if isinstance(v, dict) and "allocation_basis_points" in v}


def _canary_inert_reason(entry: dict) -> str:
    """Vì sao đặt allocation > 0 cho đường này sẽ KHÔNG có tác dụng gì. "" nếu ổn.

    Thiết kế fail-closed: thiếu quota profile hoặc allowlist rỗng thì mọi task đều rơi về
    legacy. Cộng với việc canary không báo lỗi khi rơi về legacy (đúng theo thiết kế), kết
    quả là người vận hành bật knob lên rồi ngồi đợi một thứ không bao giờ xảy ra. Chặn ở
    đây để cái im lặng đó thành một câu nói ra được.

    Chỉ soát trường mà đường đó THẬT SỰ CÓ. Hai ca đã cắn:
      - fast path không gọi tool nên không có `capability_profiles`;
      - ba canary Phase 8 (memory, lazy_skill, conversation_state) không có
        `quota_profiles` riêng vì chúng đọc ké từ `context_sources`/`canary`.
    Đòi trường mà đường đó không có nghĩa là từ chối oan một cấu hình hợp lệ, và người vận
    hành nhận một lý do SAI - còn khó hiểu hơn là không chặn."""
    has_quota_field = "quota_profiles" in entry or "models" in entry
    if has_quota_field and not (entry.get("quota_profiles") or entry.get("models")):
        return localefmt.chu("chưa khai quota profile (rolling_tpm, context_window, giá) nên fail-closed "
                             "sẽ cho mọi task rơi về legacy",
                             "no quota profile declared (rolling_tpm, context_window, price), so "
                             "fail-closed will send every task to legacy")
    has_allowlist_field = "capability_profiles" in entry or "allowed_slugs" in entry
    if has_allowlist_field and not (entry.get("capability_profiles")
                                    or entry.get("allowed_slugs")):
        return localefmt.chu("allowlist rỗng nên fail-closed sẽ cho mọi task rơi về legacy",
                             "the allowlist is empty, so fail-closed will send every task to legacy")
    return ""


def canary_set_decision(path: str, allocation_basis_points, entry: dict, allow_inert: bool,
                        mode: str = "canary"):
    """Quyết định cho POST /runtime/canary. Hàm THUẦN, trả (status_code, payload).

    Tách khỏi endpoint vì hai lý do. Một, đây là hàng rào duy nhất chặn việc bật một đường
    chắc chắn vô tác dụng, mà hàng rào không kiểm được là hàng rào không tin được. Hai, gọi
    thẳng một hàm FastAPI trong test thì tham số mặc định vẫn là object `Form(...)` (truthy),
    nên test đi qua endpoint chỉ đo được cái vỏ chứ không đo được quyết định.
    status_code 0 nghĩa là cho phép ghi."""
    keys = _canary_keys()
    if path not in keys:
        return 400, {"ok": False, "error": localefmt.chu(f"đường canary '{path}' không tồn tại",
                                                         f"canary path '{path}' does not exist"),
                     "hop_le": sorted(keys)}
    try:
        bp = int(allocation_basis_points)
    except (TypeError, ValueError):
        return 400, {"ok": False, "error": localefmt.chu("allocation_basis_points phải là số",
                                                         "allocation_basis_points must be a number")}
    if not 0 <= bp <= 10000:
        return 400, {"ok": False,
                     "error": localefmt.chu("allocation_basis_points phải trong khoảng 0..10000 "
                                            "(10000 = 100 phần trăm)",
                                            "allocation_basis_points must be between 0 and 10000 "
                                            "(10000 = 100 percent)")}
    # Tắt về 0 LUÔN được phép: đường lui phải rẻ hơn đường tiến, nếu không thì người vận
    # hành sẽ ngại thử.
    if bp > 0 and not allow_inert:
        # `mode` là điều kiện TRÙM: mọi canary đều đòi mode canary/on, nên còn ở shadow thì
        # đặt allocation bao nhiêu cũng vô nghĩa. Bản đầu của rào này soát quota mà QUÊN
        # mode, nên nó để lọt đúng cái kiểu hỏng nó sinh ra để chặn: người vận hành bật lên,
        # endpoint trả ok, và không có gì chạy.
        if str(mode or "").strip().casefold() not in ("canary", "on"):
            return 409, {"ok": False, "can_force": True,
                         "error": localefmt.chu(f"context_runtime.mode đang là '{mode}', mọi canary chỉ "
                                                "chạy khi mode là 'canary' hoặc 'on'",
                                                f"context_runtime.mode is '{mode}', and every canary only "
                                                "runs when mode is 'canary' or 'on'"),
                         "goi_y": localefmt.chu("đổi mode sang canary trước (POST /runtime/mode), "
                                                "hoặc gửi lại với allow_inert=true nếu cố ý",
                                                "switch mode to canary first (POST /runtime/mode), "
                                                "or resend with allow_inert=true if intended")}
        reason = _canary_inert_reason(entry)
        if reason:
            # Cùng quy ước với POST /reminders: trả can_force kèm lý do thay vì âm thầm làm.
            return 409, {"ok": False, "can_force": True, "error": reason,
                         "goi_y": localefmt.chu("khai quota profile trước, hoặc gửi lại với "
                                                "allow_inert=true nếu cố ý bật để quan sát",
                                                "declare a quota profile first, or resend with "
                                                "allow_inert=true if you mean to turn it on just to observe")}
    return 0, {"ok": True, "allocation_basis_points": bp}


_RUNTIME_MODES = cfgmod.RUNTIME_MODES

# Đường canary nào ĐỌC hạn mức ở chỗ nào. Mặc định là đọc của chính mình; ba đường Phase 8 thì
# không có `quota_profiles` riêng mà đọc ké `context_sources` (xem AdaptiveContextCanary._quota).
#
# Vì sao phải viết ra thành bảng: vòng khai hạn mức của /runtime/preset duyệt theo TÊN ĐƯỜNG và
# bỏ qua đường nào không có sẵn khoá `quota_profiles` - tức là bỏ qua đúng ba đường Phase 8. Kết
# quả: bấm mức "Tiết kiệm" thì allocation lên 10000, mode sang canary, mà _quota() vẫn trả None
# nên MỌI lượt rơi về legacy. Knob xoay, đèn không sáng - đúng lỗi người dùng đã báo.
QUOTA_OWNER_OF = {
    "conversation_state_canary": "context_sources",
    "memory_canary": "context_sources",
    "lazy_skill_canary": "context_sources",
}

# Ba MỨC tiết kiệm token, thay cho việc bắt người dùng tự hiểu 10 đường canary và đơn vị
# basis point. Người dùng chỉ cần biết "tiết kiệm ít hay nhiều", còn bên dưới bật đường nào
# là việc của Javis.
#
# Chỉ đưa vào đây những đường CHẠY ĐƯỢC với cấu hình mặc định. readonly_canary,
# orchestrator_canary, write_canary... đều đòi allowlist capability mà mặc định rỗng, nên
# bật chúng chỉ tạo cảm giác đã bật trong khi mọi lượt vẫn rơi về đường cũ.
#
# `mode` và `duong` KHÔNG gõ ở đây mà lấy từ `cfgmod.PRESET_DUONG`. Vì sao: `_ap_muc_mac_dinh`
# bên config phải biết mức xuất xưởng bật những đường nào, mà config không import được main.
# Chép bảng ra hai chỗ thì tới lúc thêm một đường vào mức nào đó, chỗ nâng mặc định vẫn nâng
# theo bảng cũ - lệch âm thầm, đúng kiểu lỗi không ai phát hiện cho tới khi hoá đơn token nói.
def _muc(key: str, nhan: str, mo_ta: str) -> dict:
    p = cfgmod.PRESET_DUONG[key]
    return {"nhan": nhan, "mo_ta": mo_ta, "mode": p["mode"], "duong": dict(p["duong"])}


# Bản tiếng Anh của nhãn và mô tả ba mức, cho màn hình. RUNTIME_PRESETS dựng lúc nạp module,
# lúc đó chưa có request nào để biết người đang nhìn đọc thứ tiếng gì, nên chọn bản lúc TRẢ VỀ
# qua `_preset_chu`. Nhật ký mốc (`usage_saving.ghi_moc`) vẫn ghi bản tiếng Việt.
_RUNTIME_PRESETS_EN = {
    "off": ("Off", "Full mode: sends everything to the model every turn. "
                   "Safest, uses the most tokens."),
    "saving": ("Optimized", "Sends only what is relevant to the question: selective memory, "
                            "skills loaded when needed. Cuts tokens per turn sharply, good for "
                            "models with tight limits."),
    "max": ("Max saving", "Like the Saving level, plus a shortcut for simple questions that need "
                          "no lookup. Fastest and cheapest, but newest, so the least tested."),
}


def _preset_chu(key: str, v: dict) -> dict:
    """Nhãn + mô tả của một mức, đúng ngôn ngữ giao diện của người đang nhìn."""
    en = _RUNTIME_PRESETS_EN.get(key) or (v["nhan"], v["mo_ta"])
    return {"nhan": localefmt.chu(v["nhan"], en[0]), "mo_ta": localefmt.chu(v["mo_ta"], en[1])}


RUNTIME_PRESETS = {
    # Nhắc tên "Đầy đủ" ngay trong mô tả để nối với nhãn chế độ hiện dưới mỗi câu trả lời và
    # trong bảng đo. Nút thì tên "Tắt" (tắt phần tiết kiệm), còn thứ đang chạy khi tắt thì tên
    # "Đầy đủ" - không buộc hai tên đó lại là người dùng thấy hai thứ khác nhau.
    "off": _muc("off", "Tắt",
                "Chế độ Đầy đủ: gửi mọi thứ cho model mỗi lượt. "
                "An toàn nhất, tốn token nhất."),
    "saving": _muc("saving", "Tối ưu",
                   "Chỉ gửi phần liên quan tới câu hỏi: nhớ có chọn lọc, skill nạp khi cần. "
                   "Giảm mạnh token mỗi lượt, hợp với model bị siết hạn mức."),
    "max": _muc("max", "Siêu tiết kiệm",
                "Như mức Tiết kiệm, cộng thêm đường tắt cho câu hỏi đơn giản không cần "
                "tra cứu gì. Nhanh và rẻ nhất, nhưng mới nhất nên ít được thử nhất."),
}


def _ky_ten_muc(runtime_cfg: dict, level: str) -> dict:
    """Đóng dấu "chính người dùng đã chọn mức này" vào config.

    Đây là thứ duy nhất phân biệt được "cố ý chọn Tắt" với "chưa ai chọn gì, mặc định cũ
    đóng băng lại trong settings.json". Thiếu nó thì mọi lần nâng mặc định về sau đều phải
    chọn giữa hai cái sai: giẫm lên quyết định của người dùng, hoặc để mặc định mới không bao
    giờ tới được máy đã cài. Xem `config._ap_muc_mac_dinh`.

    Gọi từ MỌI endpoint đổi mức tiết kiệm, kể cả đổi tay từng đường: người vào tận phần Nâng
    cao chỉnh allocation rõ ràng là người có ý kiến riêng, đừng nâng của họ lên sau lưng.
    """
    from datetime import datetime, timezone
    dau = {"level": str(level or ""), "source": "user",
           "at": datetime.now(timezone.utc).isoformat(timespec="seconds")}
    runtime_cfg["preset_choice"] = dau
    return dau


def current_preset(runtime_cfg: dict) -> str:
    """Cấu hình hiện tại khớp mức nào. "custom" nếu người dùng tự chỉnh tay khác cả ba."""
    cfg = runtime_cfg or {}
    mode = str(cfg.get("mode") or "").casefold()
    on = {k: int((v or {}).get("allocation_basis_points") or 0)
          for k, v in cfg.items()
          if isinstance(v, dict) and "allocation_basis_points" in v}
    bat = {k for k, v in on.items() if v > 0}
    for name, preset in RUNTIME_PRESETS.items():
        want = set(preset["duong"])
        if bat != want:
            continue
        # Mức off không quan tâm mode là gì, vì không đường nào bật thì mode vô nghĩa.
        if name == "off" or mode in ("canary", "on"):
            return name
    return "custom"


@app.get("/runtime/muc")
async def runtime_muc(brain: str = Query("brain")):
    """Đúng những gì trang Mức dùng cần để vẽ khối chọn mức tiết kiệm. Không hơn.

    Tách khỏi `/runtime/diagnostics` có chủ ý. Endpoint kia sinh ra cho người vận hành soi
    máy: nó gánh theo bảng canary tính bằng phần vạn, cửa sổ token 60 giây, hạn mức tự học,
    danh sách task kèm execution_path, kết quả integrity_check của registry. Không thứ nào
    trong đó trả lời được câu hỏi của người dùng cuối - *"tôi nên bấm mức nào"* - mà mỗi thứ
    đều tốn một lượt đọc runtime.db hoặc một vòng quét registry.

    Người dùng cần đúng bốn thứ: có những mức nào, đang ở mức nào, mỗi mức tiết kiệm bao
    nhiêu, và thực tế 24 giờ qua đo được bao nhiêu. Trang Mức dùng gọi endpoint này sau mỗi
    lần đổi mức, nên nó phải rẻ.
    """
    settings = cfgmod.read_settings().get("context_runtime") or {}
    tasks = []
    try:
        tasks = (_CONTEXT_RUNTIME.diagnostics_snapshot(limit=200, hours=24.0) or {}).get("tasks") or []
    except Exception as exc:  # noqa: BLE001 - không đọc được trace thì vẫn phải vẽ được nút
        print(f"[runtime/muc] đọc trace hỏng: {type(exc).__name__}: {exc}", file=sys.stderr)
    return {
        "muc": current_preset(settings),
        "danh_sach": [{"id": k, **_preset_chu(k, v)}
                      for k, v in RUNTIME_PRESETS.items()],
        # Người dùng đã tự chọn mức, hay đây chỉ là mặc định của bản đã cài? Hai thứ trông y
        # hệt nhau trên màn hình mà ý nghĩa ngược nhau: cái sau còn đi lên theo bản cập nhật.
        "tu_chon": str((settings.get("preset_choice") or {}).get("source") or "") == "user",
        "uoc_tinh": await _uoc_tinh_tiet_kiem(brain),
        "do_duoc": _do_duoc_tiet_kiem(tasks, 24.0, cfgmod.read_settings().get("model", {}) or {}),
        # Cần để nói ĐÚNG về phần quy đổi tiền: người dùng gói thuê bao không trả theo token,
        # nên con số tiền với họ là mức quy đổi chứ không phải tiền mặt tiết kiệm được.
        "engine": _engine_runtime_view(settings),
    }


@app.post("/runtime/preset")
async def runtime_preset_set(level: str = Form(...)):
    """Đặt mức tiết kiệm token. Một thao tác thay cho việc chỉnh mode + 10 allocation.

    Trả về ĐÚNG những gì đã đổi, để giao diện nói được "đã bật cái gì" thay vì im lặng.
    """
    key = str(level or "").strip().casefold()
    preset = RUNTIME_PRESETS.get(key)
    if not preset:
        return JSONResponse({"ok": False, "error": localefmt.chu(f"mức '{level}' không có",
                                                                 f"level '{level}' does not exist"),
                             "hop_le": list(RUNTIME_PRESETS)}, status_code=400)
    cfg = cfgmod.read_settings()
    runtime_cfg = cfg.setdefault("context_runtime", {})
    # Đóng mốc TRƯỚC khi đổi, để còn biết mức cũ là gì. Nhật ký mốc là thứ duy nhất cho phép
    # tính đúng tiết kiệm của một kỳ có đổi mức giữa chừng: không có nó thì phải lấy mức hôm
    # nay áp ngược cho cả tháng, và người vừa bật tiết kiệm hôm qua sẽ được khoe một con số
    # tiết kiệm của cả tháng mà họ chưa từng nhận.
    _muc_cu = current_preset(runtime_cfg)
    if _muc_cu != key:
        usage_saving.ghi_moc("muc", key, _muc_cu,
                             f"Đổi chế độ tiết kiệm sang {preset['nhan']}")
    runtime_cfg["mode"] = preset["mode"]
    # Ký tên TRƯỚC khi ghi: từ đây trở đi mức này là quyết định của người dùng, không bản
    # cập nhật nào được nâng nó lên sau lưng.
    _ky_ten_muc(runtime_cfg, key)

    # Đường nào cần hạn mức mà chưa khai thì TỰ KHAI cho provider đang dùng. Không làm bước
    # này thì bấm một mức sẽ bật một đường fail-closed: knob xoay được, đèn không sáng - đúng
    # cái người dùng đã phàn nàn là "ấn vào đặt thì không có gì diễn ra".
    canh_bao = []
    prov, kind_hien_tai, _key, model = _chat_provider(cfg.get("model", {}) or {})
    goi_y = [model_limits.as_quota_profile(x)
             for x in model_limits.suggest_profiles(prov, model or "")]
    for name in sorted({QUOTA_OWNER_OF.get(n, n) for n in preset["duong"]}):
        entry = dict(runtime_cfg.get(name) or {})
        if "quota_profiles" not in entry:
            continue
        # BỔ SUNG chứ không phải "trống thì mới ghi". Bản trước bỏ qua khi danh sách đã có
        # gì đó, nên người đổi bộ não (đúng thứ Javis mời chào: đổi được bộ não) bị kẹt với
        # hạn mức của bộ não CŨ: `_quota` lọc theo provider nên không khớp cái nào, và mức
        # tiết kiệm lặng lẽ ngừng chạy trong khi trang vẫn ghi đang bật.
        co_san = [x for x in (entry.get("quota_profiles") or []) if isinstance(x, dict)]
        da_co = {str(x.get("id") or "") for x in co_san}
        them = [x for x in goi_y if str(x.get("id") or "") not in da_co]
        if them:
            entry["quota_profiles"] = co_san + them
            runtime_cfg[name] = entry
            continue
        if co_san or goi_y:
            continue        # đã có hạn mức dùng được cho bộ não này
        if kind_hien_tai in ("cli", "oauth"):
            # Gói thuê bao không có hạn mức token để khai, và cũng không cần: Phase 8 dùng
            # trần ngữ cảnh ở context_runtime.subscription_context. Cảnh báo ở đây là cảnh
            # báo oan, sẽ dạy người dùng bỏ qua mọi cảnh báo khác.
            continue
        canh_bao.append(
            localefmt.chu(
                f"Chưa có bảng hạn mức sẵn cho '{prov}', nên Javis biên soạn ngữ cảnh theo trần "
                "mặc định (context_runtime.api_context). Vẫn tiết kiệm được ngay; sau lần đầu "
                "nhà cung cấp báo vượt hạn mức, Javis dùng đúng con số thật của họ.",
                f"There is no built-in limit table for '{prov}' yet, so Javis builds the context "
                "under the default ceiling (context_runtime.api_context). It still saves right "
                "away; the first time the provider reports a limit hit, Javis uses their real "
                "numbers."))

    da_bat, da_tat = [], []
    for name in _canary_keys():
        entry = dict(runtime_cfg.get(name) or {})
        muon = int(preset["duong"].get(name, 0))
        truoc = int(entry.get("allocation_basis_points") or 0)
        entry["allocation_basis_points"] = muon
        runtime_cfg[name] = entry
        if muon > 0 and truoc == 0:
            da_bat.append(name)
        elif muon == 0 and truoc > 0:
            da_tat.append(name)
    cfgmod.write_settings(cfg)
    return {"ok": True, "level": key, "nhan": _preset_chu(key, preset)["nhan"],
            "mode": preset["mode"], "da_bat": da_bat, "da_tat": da_tat,
            "dang_bat": sorted(preset["duong"]), "canh_bao": canh_bao,
            "co_hieu_luc_ngay": True}


@app.post("/runtime/mode")
async def runtime_mode_set(mode: str = Form(...)):
    """Đổi `context_runtime.mode`. Đây là công tắc TRÙM của mọi đường canary.

    Vì sao phải có endpoint riêng: mọi canary đều đòi mode là `canary` hoặc `on`, nên còn ở
    `shadow` thì đặt allocation bao nhiêu cũng không có gì chạy. Trước khi có nút này, cách
    duy nhất để đổi là SSH sửa tay settings.json.
    """
    value = str(mode or "").strip().casefold()
    if value not in _RUNTIME_MODES:
        return JSONResponse({"ok": False, "error": localefmt.chu(f"mode '{mode}' không hợp lệ",
                                                                 f"invalid mode '{mode}'"),
                             "hop_le": list(_RUNTIME_MODES)}, status_code=400)
    cfg = cfgmod.read_settings()
    runtime_cfg = cfg.setdefault("context_runtime", {})
    runtime_cfg["mode"] = value
    # Đổi công tắc trùm cũng là một quyết định về mức tiết kiệm: hạ xuống shadow là cố ý tắt
    # hết. Không ký ở đây thì lần nâng mặc định sau sẽ kéo mode trở lại canary sau lưng.
    _ky_ten_muc(runtime_cfg, current_preset(runtime_cfg))
    cfgmod.write_settings(cfg)
    active = [k for k, v in (cfgmod.read_settings().get("context_runtime") or {}).items()
              if isinstance(v, dict) and int(v.get("allocation_basis_points") or 0) > 0]
    return {"ok": True, "mode": value, "duong_dang_bat": active,
            "luu_y": localefmt.chu("Mode đã sang canary nhưng chưa đường nào có allocation > 0, "
                                   "nên vẫn chưa có gì đổi.",
                                   "Mode is now canary but no path has allocation > 0, "
                                   "so nothing has changed yet.") if value in ("canary", "on") and not active
                     else ""}


@app.post("/runtime/quota")
async def runtime_quota_apply(provider: str = Form(...), model: str = Form(""),
                              paths: str = Form("")):
    """Khai quota profile cho các đường canary từ bộ hạn mức gợi ý (model_limits).

    Vì sao cần: fail-closed nghĩa là thiếu quota profile thì mọi task rơi về legacy, nên
    trước bước này mọi thao tác bật canary đều vô nghĩa. Trước đây cách duy nhất để khai là
    gõ tay JSON lồng ba tầng vào settings.json.

    `paths` bỏ trống = áp cho MỌI đường canary có trường quota_profiles. Con số là GỢI Ý dựa
    trên tài liệu công khai, người vận hành phải đối chiếu với gói cước thật của mình.
    """
    suggestions = model_limits.suggest_profiles(provider, model)
    if not suggestions:
        return JSONResponse({
            "ok": False,
            "error": localefmt.chu(f"chưa có hạn mức gợi ý cho provider '{provider}'",
                                   f"no suggested limits for provider '{provider}'")
                     + (f" model '{model}'" if model else ""),
            "provider_da_biet": model_limits.known_providers(),
            "goi_y": localefmt.chu("khai tay quota_profiles cho đường canary, hoặc bổ sung mục vào "
                                   "server/model_limits.py nếu đã tra được hạn mức chính thức",
                                   "declare quota_profiles for the canary path by hand, or add an "
                                   "entry to server/model_limits.py once you have the official limits"),
        }, status_code=404)

    profiles = [model_limits.as_quota_profile(s) for s in suggestions]
    wanted = {p.strip() for p in (paths or "").split(",") if p.strip()}
    keys = _canary_keys()
    if wanted - keys:
        return JSONResponse({"ok": False, "error": localefmt.chu("có đường canary không tồn tại",
                                                                 "some canary paths do not exist"),
                             "sai": sorted(wanted - keys), "hop_le": sorted(keys)},
                            status_code=400)

    cfg = cfgmod.read_settings()
    runtime_cfg = cfg.setdefault("context_runtime", {})
    applied = []
    for key in sorted(keys):
        if wanted and key not in wanted:
            continue
        entry = dict(runtime_cfg.get(key) or {})
        # Đường nào dùng 'models' (model router) có hình dạng rule khác hẳn - không áp bừa.
        if "quota_profiles" not in entry:
            continue
        entry["quota_profiles"] = profiles
        runtime_cfg[key] = entry
        applied.append(key)
    cfgmod.write_settings(cfg)
    return {"ok": True, "provider": provider, "model": model or "(mọi model)",
            "so_rule": len(profiles), "da_ap_cho": applied,
            "can_doi_chieu": [s.get("source") for s in suggestions if s.get("verify")],
            "luu_y": localefmt.chu("Đây là hạn mức GỢI Ý theo tài liệu công khai. Đối chiếu với gói cước "
                                   "thật của tài khoản trước khi tin vào nó.",
                                   "These are SUGGESTED limits from public documentation. Check them "
                                   "against your account's real plan before relying on them.")}


@app.post("/runtime/canary")
async def runtime_canary_set(
    path: str = Form(...),
    allocation_basis_points: int = Form(...),
    allow_inert: bool = Form(False),
):
    """Đặt allocation cho MỘT đường canary, an toàn hơn sửa tay settings.json.

    Vì sao cần endpoint riêng thay vì bảo người vận hành tự sửa file: knob nằm sâu hai tầng
    (`context_runtime.<path>.allocation_basis_points`). Endpoint này đọc-sửa-ghi trọn cấu
    hình nên không bao giờ làm mất field anh em, và nó CHẶN trước khi bật một đường chắc
    chắn vô tác dụng (xem `_canary_inert_reason`).
    """
    cfg = cfgmod.read_settings()
    runtime_cfg = cfg.get("context_runtime") or {}
    entry = dict(runtime_cfg.get(path) or {})
    status, payload = canary_set_decision(path, allocation_basis_points, entry,
                                          bool(allow_inert),
                                          str(runtime_cfg.get("mode") or "off"))
    if status:
        return JSONResponse(payload, status_code=status)
    entry["allocation_basis_points"] = payload["allocation_basis_points"]
    rt = cfg.setdefault("context_runtime", {})
    rt[path] = entry
    # Người vào tận phần Nâng cao chỉnh từng đường là người có ý kiến riêng. Ký tên để bản
    # cập nhật sau không nâng cấu hình tay của họ lên theo mặc định mới.
    _ky_ten_muc(rt, current_preset(rt))
    cfgmod.write_settings(cfg)
    # Không cần restart: read_settings cache theo mtime nên lượt kế tiếp đã ăn giá trị mới.
    after = (cfgmod.read_settings().get("context_runtime") or {}).get(path) or {}
    return {"ok": True, "path": path,
            "allocation_basis_points": after.get("allocation_basis_points"),
            "quota_rules": len(after.get("quota_profiles") or after.get("models") or []),
            "allowlist": len(after.get("capability_profiles")
                             or after.get("allowed_slugs") or []),
            "co_hieu_luc_ngay": True}


@app.get("/runtime/tasks/{task_id}")
async def runtime_task_status(task_id: str):
    """Phase 7 status tối thiểu; không trả objective, checkpoint ciphertext hay actor hash."""
    task = _CONTEXT_RUNTIME.get_task(task_id)
    if not task:
        return JSONResponse({"error": "task_not_found"}, status_code=404)
    return {
        "task_id": task["id"], "session_id": task["session_id"],
        "status": task["status"],
        "orchestration_status": task.get("orchestration_status") or "",
        "execution_path": task.get("execution_path") or "",
        "runtime_version": task.get("runtime_version") or "",
        "registry_revision": task.get("registry_revision") or "",
        "policy_version": task.get("canary_policy_version") or "",
        "updated_at": task.get("updated_at"),
    }


@app.post("/runtime/tasks/{task_id}/resume")
async def runtime_task_resume(task_id: str):
    """Resume explicit sau restart; OCC claim ngăn hai request chạy cùng task."""
    task = _CONTEXT_RUNTIME.get_task(task_id)
    if not task:
        return JSONResponse({"error": "task_not_found"}, status_code=404)
    if task.get("execution_path") != "orchestrator" or task.get("status") != "RUNNING":
        return JSONResponse({"error": "task_not_resumable"}, status_code=409)
    if _CHAT_RUNTIME.get_job(str(task.get("session_id") or "")):
        return JSONResponse({"error": "session_is_running"}, status_code=409)
    mcfg = cfgmod.read_settings().get("model", {})
    provider, kind, api_key, model = _chat_provider(mcfg)
    if kind != "api" or not api_key:
        return JSONResponse({"error": "api_provider_required"}, status_code=409)
    try:
        result = await _get_readonly_orchestrator().resume(
            task_id, str(task["session_id"]), provider, model or "?", api_key,
            str(mcfg.get("reasoning") or "off"), None, _api_stream,
        )
    except (ValueError, PermissionError, RuntimeError) as exc:
        return JSONResponse({"error": str(exc)[:160]}, status_code=409)
    if result.tokens_in or result.tokens_out:
        usage_store.record(
            provider, result.model or model or "?", result.tokens_in,
            result.tokens_out, result.cost_usd,
        )
    if result.text:
        get_store().append_message(str(task["session_id"]), "assistant", result.text)
    _CONTEXT_RUNTIME.finish(
        _CONTEXT_RUNTIME.resume_trace(task_id),
        "COMPLETED" if result.status == "COMPLETED" else "COMPLETED_WITH_ERROR",
        result.stop_reason if result.status != "COMPLETED" else "",
    )
    return {
        "ok": result.status == "COMPLETED", "task_id": result.task_id,
        "status": result.status, "stop_reason": result.stop_reason,
        "content": result.text, "model": result.model,
        "model_rounds": result.model_rounds,
        "tokens_in": result.tokens_in, "tokens_out": result.tokens_out,
        "cost_usd": result.cost_usd, "evidence_refs": list(result.evidence_refs),
    }


# ============================================================
# Telegram bot - nhắn Telegram ↔ Javis (dùng engine theo Settings; CLI thì có cả MCP)
# ============================================================
_TG_BOT = None
# ĐA PHIÊN theo tài khoản: mỗi chat_id giữ NGỮ CẢNH RIÊNG để không lẫn hội thoại giữa
# các người dùng chung 1 bot. Map chat_id(str) -> phiên:
#   {"cli": engine Claude|None,   # session Claude riêng (giữ session_id để resume)
#    "or":  list|None,        # lịch sử hội thoại engine OpenRouter/API
#    "last": str|None,        # câu hỏi gần nhất của chat này (cho /retry)
#    "sent": set,             # path đã gửi qua /telegram/send-file trong lượt (chống gửi trùng)
#    "brain": str|None}       # brain RIÊNG của phiên (path); None = brain mặc định (theo Settings)
_TG_SESS = {}

# Map BỀN chat_id -> TÊN brain, sống sót qua restart (khác _TG_SESS bị .clear() mỗi lần bot bật
# lại). Lưu theo TÊN (không phải path tuyệt đối) để bền qua Docker/local + brain đổi chỗ; đọc mới
# resolve tên -> path. Ghi STATE_DIR/tg_brain.json (server state, gitignored, xuyên brain).
_TG_BRAIN_PATH = cfgmod.STATE_DIR / "tg_brain.json"

# Map BỀN chat_id -> id phiên hội thoại, sống sót qua restart. Cùng lý do tồn tại với
# _TG_BRAIN_MAP ngay trên, và chữa một lỗi người dùng báo thẳng (28/08/2026):
#
#   "mỗi lần update bản mới bấm nút update thì bên telegram nó mất hết ký ức, quên sạch mọi
#    thứ, từ cách xưng hô tới quy trình đặt tên file. Còn ở localhost thì bình thường."
#
# Đúng như vậy, và đây là chỗ hỏng: `sess["sid"]` chỉ sống trong `_TG_SESS` (RAM), nên restart
# là mất liên kết chat -> hội thoại, lượt kế đẻ một phiên TRỐNG. Bản ghi cũ vẫn nằm nguyên
# trong SQLite, chỉ là không còn ai nối vào. Dashboard không dính vì trình duyệt giữ
# `session_id` và gửi kèm mỗi request; Telegram thì không có ai giữ hộ.
#
# Lý do cũ ghi trong docstring `_tg_conv_sid` ("restart là mạch ngữ cảnh đã mất rồi") chỉ đúng
# với MẠCH NATIVE của engine CLI. Nó KHÔNG đúng với bản ghi hội thoại: transcript nằm trong
# SQLite, sống sót qua restart, và đó mới là thứ dựng lại ngữ cảnh - đúng cách dashboard vẫn
# làm cho cả engine CLI lẫn engine API.
_TG_SID_PATH = cfgmod.STATE_DIR / "tg_sid.json"


def _tg_load_sid_map() -> dict:
    try:
        if _TG_SID_PATH.exists():
            d = json.loads(_TG_SID_PATH.read_text(encoding="utf-8"))
            if isinstance(d, dict):
                return {str(k): str(v) for k, v in d.items()}
    except Exception:
        pass
    return {}


_TG_SID_MAP = _tg_load_sid_map()


def _tg_save_sid_map() -> None:
    try:
        _atomic_write_text(_TG_SID_PATH, json.dumps(_TG_SID_MAP, ensure_ascii=False, indent=2))
    except Exception as e:
        import sys
        print(f"[tg sid map write] {type(e).__name__}: {e}", file=sys.stderr)


def _tg_nho_sid(sess, sid: str) -> None:
    """Ghi nhớ chat này đang ở phiên nào, để restart xong còn nối lại."""
    key = str(sess.get("key") or "")
    if not key or not sid or _TG_SID_MAP.get(key) == sid:
        return
    _TG_SID_MAP[key] = sid
    _tg_save_sid_map()


def _tg_quen_sid(sess) -> None:
    """Bỏ liên kết bền (đổi brain, /reset). Không xoá bản ghi hội thoại, chỉ thôi nối vào nó."""
    key = str(sess.get("key") or "")
    if key and _TG_SID_MAP.pop(key, None) is not None:
        _tg_save_sid_map()


# Bốn engine tự giữ mạch hội thoại trong đối tượng nằm ở `sess`. Gom thành MỘT bảng vì mỗi
# chỗ tự liệt kê tay là có ngày sót một cái: nhánh đổi provider đã sót `cli` một thời gian, và
# `antigravity` thì sót ở cả ba chỗ.
_TG_ENGINE_MACH = (("cli", "cli"), ("codex", "codex"), ("grok-cli", "grok"),
                   ("antigravity-cli", "antigravity"))


def _tg_ngat_mach(sess, tru=None):
    """Cắt liên kết mạch native của các engine trong phiên, GIỮ nguyên đối tượng engine.

    `tru` = nhãn engine được tha (dùng khi engine khác vừa chen một lượt: engine ĐANG chạy
    không việc gì phải mất mạch). Không truyền thì cắt sạch - đúng ý /reset và đổi brain.

    Giữ đối tượng lại vì cwd/instructions vẫn dùng được; lượt sau của engine đó tự mồi lại từ
    kho phiên (xem `_tg_lich_su_kho`).
    """
    for nhan, khoa in _TG_ENGINE_MACH:
        if nhan == tru or sess.get(khoa) is None:
            continue
        try:
            obj = sess[khoa]
            # Dùng API công khai khi engine có (Claude Code), rơi về gán thẳng cho engine
            # chưa có - khỏi phải rẽ nhánh theo tên engine ở đây.
            if hasattr(obj, "reset_session"):
                obj.reset_session()
            else:
                obj.session_id = None
        except Exception:
            sess[khoa] = None


def _tg_load_brain_map() -> dict:
    try:
        if _TG_BRAIN_PATH.exists():
            d = json.loads(_TG_BRAIN_PATH.read_text(encoding="utf-8"))
            if isinstance(d, dict):
                return {str(k): str(v) for k, v in d.items()}
    except Exception:
        pass
    return {}


_TG_BRAIN_MAP = _tg_load_brain_map()


def _tg_save_brain_map() -> None:
    try:
        _atomic_write_text(_TG_BRAIN_PATH, json.dumps(_TG_BRAIN_MAP, ensure_ascii=False, indent=2))
    except Exception as e:
        import sys
        print(f"[tg brain map write] {type(e).__name__}: {e}", file=sys.stderr)


def _agent_sess_key(chat_id, agent) -> str:
    """Session key of one chat's turns with one agent: `<chat>@<slug>`, or the chat itself without an agent.

    One session per agent, for the reason given at `_cli_turn`: sharing the plain session made the
    first turn's prompt stick. Idempotent, because the CLI already sends the suffixed key."""
    key = str(chat_id or "default")
    slug = str((agent or {}).get("slug") or "")
    if not slug or key.endswith("@" + slug):
        return key
    return f"{key}@{slug}"


def _tg_session(chat_id):
    """Lấy (tạo nếu chưa có) phiên riêng của 1 chat_id. chat_id rỗng → gộp vào 'default'."""
    key = str(chat_id or "default")
    s = _TG_SESS.get(key)
    if s is None:
        s = {
            "cli": None, "codex": None, "or": None,
            "last": None, "sent": set(), "brain": None,
            # Khoá của chính phiên này. `_tg_conv_sid` cần nó để đọc/ghi map BỀN chat -> sid
            # mà không phải đổi chữ ký ở mọi chỗ gọi (khoá có thể là chat_id, hoặc
            # "bot:<id>:<chat>" với bot chuyên trách).
            "key": key,
        }
        _TG_SESS[key] = s
    return s


def _tg_brain(chat_id):
    """Brain của phiên Telegram này. Ưu tiên: phiên sống (RAM) -> map BỀN (chat đã /brain, kể cả
    trước restart) -> brain mặc định (Settings/loop). Map bền lưu TÊN brain nên brain đã xoá/đổi
    tên thì tự dọn entry cũ và rơi về mặc định, không kẹt vào brain không còn."""
    key = str(chat_id or "default")
    sess = _TG_SESS.get(key) or {}
    b = sess.get("brain")
    if b and os.path.isdir(b):
        return b
    name = _TG_BRAIN_MAP.get(key)
    if name:
        p = str(Path(BRAINS_DIR) / name)
        if os.path.isdir(p):
            return p
        _TG_BRAIN_MAP.pop(key, None)   # brain đã biến mất → dọn, khỏi kẹt
        _tg_save_brain_map()
    return _read_loop_config().get("brain", "brain")


def _tg_set_brain(chat_id, brain_path):
    """Đổi brain cho 1 phiên Telegram + reset ngữ cảnh (brain khác = bộ nhớ/skill khác,
    giữ mạch cũ sẽ trộn tri thức 2 vault). Ghi cả phiên sống lẫn map BỀN để sống qua restart."""
    sess = _tg_session(chat_id)
    sess["brain"] = str(brain_path)
    try:
        _TG_BRAIN_MAP[str(chat_id or "default")] = Path(str(brain_path)).name
        _tg_save_brain_map()
    except Exception:
        pass
    _tg_ngat_mach(sess)    # cả bốn engine, không riêng Claude Code + Codex như bản cũ
    sess["or"] = None
    sess["last"] = None
    sess["sid"] = None     # brain khác = hội thoại khác → mở phiên mới trong kho, đừng trộn
    _tg_quen_sid(sess)     # ...và cắt cả liên kết BỀN, kẻo restart xong lại nối về brain cũ


def _tg_chat_busy(chat) -> bool:
    """Chat này đang có lượt trả lời chạy dở không (đa phiên: _current là dict theo chat)."""
    cur = getattr(_TG_BOT, "_current", None)
    if not isinstance(cur, dict):
        return False
    t = cur.get(str(chat)) if chat else None
    return bool(t and not t.done())


def _javis_port() -> int:
    try:
        return int(os.getenv("JAVIS_PORT", "7777"))
    except ValueError:
        return 7777


def _tg_compact_bg(sess, prov, api_key, api_model):
    """Đẩy vòng nén lịch sử in-memory của phiên Telegram sang chạy NỀN.

    Trước đây `compact_mem` được await thẳng trong đường request: phiên đủ dài là user phải
    ngồi chờ xong một vòng tóm tắt (một request LLM nữa) rồi mới thấy câu trả lời của mình.
    Dashboard vốn đã nén nền qua `compaction.maybe_compact`; đây là bản tương ứng.

    Chỉ ÁP kết quả khi lịch sử chưa đổi kể từ lúc bắt đầu nén. Có lượt chen vào giữa thì bản
    nén đã lỗi thời - đè vào là nuốt mất lượt vừa nói; bỏ đi, lượt sau nén lại.
    """
    msgs = sess.get("or")
    if not msgs or sess.get("dang_nen"):
        return
    n = len(msgs)
    sess["dang_nen"] = True

    async def _chay():
        try:
            moi = await compaction.compact_mem(list(msgs), prov, api_key, api_model, _api_stream)
            if sess.get("or") is msgs and len(msgs) == n:
                sess["or"] = moi
        except Exception as _e:
            print(f"[compact_mem nền] {_e}", file=__import__('sys').stderr)
        finally:
            sess["dang_nen"] = False

    try:
        asyncio.create_task(fast_mode.normal(_chay()))
    except Exception as _e:
        sess["dang_nen"] = False
        print(f"[compact_mem nền] {_e}", file=__import__('sys').stderr)


# ---- XOAY phiên Telegram: nghỉ lâu hoặc đủ dài thì sang phiên mới ----
# Trên dashboard người dùng tự bấm "+ Hội thoại mới" nên phiên không bao giờ dài mãi. Trên
# Telegram thì gần như KHÔNG AI gõ /reset, nên một Chat ID gắn với một phiên là phiên đó dài
# vô tận chừng nào server chưa restart. Mở nó ra đọc là kéo về cả nghìn tin: openStoredSession
# (dashboard/app.js) vẽ TOÀN BỘ sess.messages, không phân trang - nút "Xem thêm" ở thanh bên
# chỉ phân trang DANH SÁCH hội thoại chứ không phân trang tin trong một cuộc.
#
# Xoay phiên biến một phiên vô hạn thành nhiều phiên hữu hạn, nên phần đọc không phải sửa gì:
# cái tăng lên là SỐ hội thoại, đúng thứ nút "Xem thêm" đã lo sẵn.
#
# QUAN TRỌNG: xoay chỉ xoay BẢN GHI. Ngữ cảnh engine (sess['cli'] của Claude CLI, thread Codex,
# sess['or'] của nhánh API vốn đã có compact_mem lo cửa sổ) KHÔNG bị đụng tới, nên người dùng
# Telegram không hề thấy Javis quên gì - chỉ dashboard là thấy hội thoại chia thành khúc đọc được.
_TG_CONV_IDLE_S = 12 * 3600      # nghỉ quá ngần này → lượt kế mở phiên mới
_TG_CONV_MAX_MSGS = 200          # ~100 lượt hỏi-đáp/phiên → mở phiên mới dù đang chat liên tục
_TG_CONV_ARCHIVE_DAYS = 30       # phiên Telegram nguội quá ngần này → tự cất vào kho lưu


def _tg_conv_sid(store, sess, brain, engine_label, model, channel="telegram"):
    """Phiên kho cho lượt này, tự xoay theo hai ngưỡng trên.

    `channel` là KÊNH THẬT của lượt, và phải được truyền vào: vỏ `_tg_answer` phục vụ bốn kênh
    (Telegram, Zalo, CLI, bot chuyên trách), nhưng tới 0.59.28 hàm này đóng cứng
    `channel="telegram"` cho MỌI bản ghi nó mở. Hậu quả nhìn thấy ở thanh Lịch sử: hội thoại
    Zalo, hội thoại gõ từ terminal và việc nền của giọng nói đều đeo nhãn "TG" (chủ dự án báo
    17/09: "chạy nền xong đang trả lời tag là TG thì không đúng"), còn bộ lọc theo kênh và
    nhãn riêng `bot:<slug>` thì không bao giờ khớp được cái gì.

    sess['sid'] chỉ sống trong RAM, nên sau restart phải hỏi lại map BỀN `_TG_SID_MAP` (lý do
    đầy đủ ở chú thích `_TG_SID_PATH`) mới nối được vào đúng bản ghi cũ. Trước 0.50.1 chỗ này
    CỐ Ý mở phiên mới sau restart với lý do "restart là mạch ngữ cảnh đã mất rồi" - lý do đó
    chỉ đúng với MẠCH NATIVE của engine CLI; bản ghi hội thoại thì nằm trong SQLite và còn
    nguyên, nên người dùng Telegram đang trả giá bằng việc mất sạch ngữ cảnh mỗi lần cập nhật.

    Nối lại xong vẫn đi qua ĐÚNG hai ngưỡng xoay bên dưới: sid khôi phục mà đã nguội quá 12
    tiếng hoặc đã dài quá 200 tin thì vẫn sang khúc mới. Khôi phục không phải là được miễn
    luật xoay. Đổi brain và /reset gọi `_tg_quen_sid` nên xoá luôn cả liên kết bền.
    """
    sid = sess.get("sid") or _TG_SID_MAP.get(str(sess.get("key") or ""))
    ly_do = "chưa có phiên nào cho chat này"
    # The project of the session a rotation retires: the next chunk is the same conversation, so it
    # stays in that project. Only a rotation carries it, never a missing record or a brain change.
    carry_project = ""
    if sid:
        row = store.get_session(sid)
        if not row:
            ly_do = f"bản ghi {sid[:8]} không còn trong kho (đã xoá trên dashboard?)"
            sid = None      # user đã xoá hội thoại đó trên dashboard → đừng hồi sinh id cũ
        elif (row.get("brain") or "") and row["brain"] not in _brain_keys(brain):
            # Brain đổi lúc server tắt (Settings, hoặc brain bị đổi tên). Nối tiếp thì
            # `get_or_create` lặng lẽ ghi đè cột brain của bản ghi cũ, tức trộn hội thoại của
            # hai bộ não vào một chỗ. Thà mở khúc mới.
            #
            # `_brain_keys` chứ không `_brain_key`: cột này từng được mỗi kênh ghi một kiểu cho
            # CÙNG một brain (xem docstring của nó), nên so bằng dấu bằng là mọi phiên Telegram
            # có từ trước bản chuẩn hoá đều bị coi là "khác brain" và bị bỏ - MỖI LƯỢT một
            # phiên mới, đúng cái hỏng mà khối ngay dưới đang canh. Cột rỗng cũng tha, vì rỗng
            # là không biết chứ không phải là khác.
            ly_do = (f"brain của bản ghi {sid[:8]} là {row.get('brain')!r}, "
                     f"lượt này là {_brain_key(brain)!r}")
            sid = None
        else:
            # Chỉ xoay khi có BẰNG CHỨNG phiên đã cũ/đã dài. Thiếu số liệu thì giữ nguyên,
            # kẻo một cột rỗng bất ngờ làm mỗi lượt đẻ một phiên.
            nghi = time.time() - float(row.get("updated_at") or time.time())
            so_tin = int(row.get("msg_count") or 0)
            if nghi >= _TG_CONV_IDLE_S or so_tin >= _TG_CONV_MAX_MSGS:
                ly_do = f"phiên cũ nghỉ {nghi / 3600:.1f} tiếng, dài {so_tin} tin"
                carry_project = str(row.get("project_id") or "")
                sid = None      # nghỉ lâu / đã dài → sang khúc mới
    if sid:
        # Còn dùng tiếp: đồng bộ engine/model vì người dùng có thể vừa đổi bằng /model.
        sess["sid"] = store.get_or_create(sid, brain=_brain_key(brain), engine=engine_label,
                                          model=model)
        _tg_nho_sid(sess, sess["sid"])
        return sess["sid"]
    # `_brain_key`: Telegram cầm ĐƯỜNG DẪN brain, dashboard gửi tên gọi tắt "brain" - ghi
    # nguyên văn thì hai bên lệch khoá và thanh bên không thấy hội thoại Telegram đâu.
    sess["sid"] = store.create_session(brain=_brain_key(brain), engine=engine_label, model=model,
                                       channel=channel or "telegram")
    _tg_nho_sid(sess, sess["sid"])
    if carry_project:
        try:
            if store.get_project(carry_project):   # a project deleted meanwhile is not revived
                store.set_project(sess["sid"], carry_project)
        except Exception as e:  # noqa: BLE001 - losing the label must not lose the turn
            print(f"[{channel or 'telegram'} project carry] {type(e).__name__}: {e}",
                  file=__import__('sys').stderr)
    # VÌ SAO mở phiên mới - in ra mỗi lần, vì đây là thứ không tài nào đoán được từ giao diện:
    # ở Lịch sử chỉ thấy một loạt hội thoại ngắn mà không biết chúng bị cắt ra bởi luật nghỉ
    # 12 tiếng, bởi brain lệch, hay bởi liên kết bền không ghi được (chủ dự án báo 16/09).
    print(f"[{channel or 'telegram'}] mở phiên mới {sess['sid'][:8]} cho chat "
          f"{sess.get('key')}: {ly_do}", file=__import__('sys').stderr)
    # Dọn theo nhịp XOAY (hiếm, cỡ vài ngày một lần) chứ không mỗi lượt - đủ để thanh bên
    # không ngập dần vì các khúc cũ. Dọn ĐÚNG kênh vừa xoay, không phải cứ thế quét Telegram.
    try:
        n = store.archive_stale(channel or "telegram",
                                time.time() - _TG_CONV_ARCHIVE_DAYS * 86400)
        if n:
            print(f"[{channel or 'telegram'}] cất {n} phiên nguội quá {_TG_CONV_ARCHIVE_DAYS} "
                  f"ngày vào kho lưu", file=__import__('sys').stderr)
    except Exception as e:
        print(f"[{channel or 'telegram'} archive] {type(e).__name__}: {e}",
              file=__import__('sys').stderr)
    return sess["sid"]


# Số TIN (không phải lượt) mồi lại tối đa khi dựng lịch sử từ transcript. Bằng
# BOT_LICH_SU_MAX bên dưới cho dễ nhớ: ~10 lượt hỏi-đáp, đủ để "cái đó", "như lần trước" còn
# nghĩa, mà không thổi phồng lượt đầu sau mỗi lần restart.
_TG_MOI_LAI_MAX = 20


def _tg_lich_su_kho(store, conv_sid, text):
    """Transcript đã lưu của phiên này, để MỒI LẠI ngữ cảnh sau restart.

    Vì sao cần: mọi mạch hội thoại của Telegram sống trong RAM - `sess['or']` của engine API,
    `session_id` của Claude Code / Codex / Grok / Antigravity. Restart server (bấm nút cập
    nhật là restart) xoá sạch chúng, nên lượt kế mở mạch TAY KHÔNG dù bản ghi vẫn còn nguyên
    trong SQLite. Người dùng báo đúng triệu chứng đó ngày 28/08/2026: mỗi lần cập nhật là
    phải dạy lại từ cách xưng hô tới quy ước đặt tên file, trong khi localhost:7777 không sao
    (trình duyệt giữ `session_id` và dashboard đọc lại transcript mỗi lượt).

    Trả về `(danh sách tin, tóm tắt đã nén)`. Bỏ lượt user ĐANG hỏi - `_tg_answer` đã ghi nó
    vào kho trước khi gọi engine, gửi lại là hỏi hai lần. So khớp nội dung chứ không cắt cứng
    phần tử cuối: lệnh ghi kia nằm trong try/except, hụt một cái mà vẫn cắt là ăn mất một tin
    thật.
    """
    if store is None or not conv_sid:
        return [], ""
    try:
        raw = store.get_messages(conv_sid)
    except Exception as e:
        print(f"[telegram mồi lại] {type(e).__name__}: {e}", file=__import__('sys').stderr)
        return [], ""
    msgs = [{"role": m["role"], "content": m["content"]} for m in raw
            if m.get("role") in ("user", "assistant") and isinstance(m.get("content"), str)
            and m["content"].strip()]
    if msgs and msgs[-1]["role"] == "user" and msgs[-1]["content"] == text:
        msgs.pop()
    tom_tat = ""
    try:
        tom_tat = (store.get_session(conv_sid) or {}).get("compact_summary") or ""
    except Exception:
        pass
    return msgs, tom_tat


def _tg_quota_out(out: str, prov: str, kind: str, api_key: str, mcfg, account: str = None) -> bool:
    """Whether a channel turn's error string says the route ran out of quota (0.354.0). When it does, the account
    that ran out rests, as on the web chat, so the next route and the next turns skip it."""
    hint = _NHA_SANG_ENGINE.get(prov, "")
    noi, lim = _subscription_limit_event(out or "", hint) if hint else ("", None)
    quota = bool(noi) or aux_engine.cooldown_for(out or "") == aux_engine.COOLDOWN_QUOTA_S
    if not quota:
        return False
    if kind == "api":
        _note_api_limit(mcfg, prov, api_key, out)
    elif hint:
        _note_pin_limit(getattr(lim, "engine", "") or hint, float(getattr(lim, "reset_epoch", 0) or 0),
                        account=account)
    return True


def _tg_turn_account(sess, prov: str):
    """The plan account a channel turn just ran on: plan_accounts.use left it on that chat's engine object."""
    eng = (sess or {}).get({"openai-oauth": "codex", "grok-cli": "grok", "anthropic-cli": "cli"}.get(prov, ""))
    acc = getattr(eng, "account_id", None)
    return acc if isinstance(acc, str) and acc else None


async def _tg_answer(text, meta=None, progress=None, channel="telegram", bot=None,
                     phien_kho="", ghi_kho=True, agent=None, project_id=""):
    """Vỏ ngoài một lượt KHÔNG-WEBSOCKET: khớp phiên trong kho -> chạy engine -> LƯU lượt.

    `channel` mở hàm này cho kênh thứ ba là CLI (xem docs/dev/2026-08-cli-spec.md). Cố ý
    THÊM THAM SỐ chứ không viết một vỏ riêng: vỏ này là chỗ duy nhất biết cách khớp phiên,
    ghi bộ nhớ hội thoại, gắn trace runtime và chấm chất lượng. Viết bản thứ hai là lượt CLI
    sẽ vắng mặt ở /sessions và ở vòng tự học - đúng lỗ hổng mà nhánh Telegram từng dính
    trước 0.9.244, chỉ khác là lần này biết trước mà vẫn làm.

    Vì sao tách vỏ khỏi lõi: trước 0.9.244 nhánh Telegram không lưu gì cả, nên hội thoại
    Telegram vắng mặt ở `/sessions`, ở `brain/memory/conversations`, và ở vòng tự học -
    lỗ hổng chức năng lớn nhất trong danh sách trôi lệch giữa hai bản dispatch.

    Quy ước trả về của lõi: **dict = câu trả lời thật** (đáng lưu), **chuỗi = thông báo lỗi**
    (không lưu). Đó là lý do nhánh gateway lịch cũng trả dict chứ không trả chuỗi như trước.

    `phien_kho` + `ghi_kho`: cho người gọi MƯỢN vỏ này mà không để nó tự khớp phiên. Mặc định
    vỏ tra `chat_id` -> phiên kho và tự mở phiên mới khi chưa có, đúng cho Telegram/Zalo/CLI
    nơi chat_id là một cuộc trò chuyện bền. Việc nền của giọng nói thì KHÔNG: mỗi việc mang
    một `chat_id` dùng một lần (`voice:<sid>:<uuid>`, cố ý, để hai việc chạy song song không
    xếp hàng chung một mạch engine), nên vỏ tưởng lượt nào cũng là một cuộc trò chuyện mới và
    mở cho nó một bản ghi riêng - chủ dự án 17/09 thấy hàng loạt hội thoại chỉ 1-2 tin sinh ra
    trong lúc nói chuyện. Truyền `phien_kho` = phiên chat đang nói để lượt chạy NGAY TRONG đó,
    và `ghi_kho=False` khi người gọi tự lo phần ghi (việc nền ghi bằng `push_to_chat`), nên
    lịch sử chỉ được ĐỌC làm ngữ cảnh chứ không bị chèn thêm tin nào.

    `agent` = {"brain", "slug"}, ALREADY CHECKED (see `_cli_agent`): an OWNER turn that runs with the
    prompt, skills and model of one agent of that brain. Unlike `bot`, the person asking is still
    the owner: permissions and storage are those of a normal turn; the prompt, the model and the
    end of turn (lessons, rules, run log) are the agent's.

    `project_id`: an ALREADY CHECKED project (see `_cli_project`) to attach the conversation to
    before the prompt is built, as the dashboard's project panel does. Kept on the conversation, so
    later turns without it stay in that project.
    """
    # Gỡ ký tự vô hình (tag U+E0000, ghi đè hướng chữ, zero-width...) ngay ở cửa chung của mọi kênh: người lạ
    # giấu lệnh vào đó, model đọc được còn chủ thì không thấy. Gỡ TRƯỚC khi ghi kho vì vòng tự học đọc lại kho (0.83.2).
    if isinstance(text, str):
        text = chatbot_reply_policy.strip_hidden(text)
    # Who is talking, for tool hooks. Taken BEFORE `channel` is renamed to bot:<slug> below: a
    # hook needs the real channel ("zalo_personal"...), and `user_id` is the sender even in a
    # group. A dedicated bot is never the owner, whatever its permission level; every other
    # caller of this shell is an owner surface (admin channels, CLI, voice).
    _luot = turn_context.from_meta(channel, meta, la_chu=not bot)
    if bot:
        # 0.429.0: jobs this turn creates (reminders, loops, Kanban) are stamped with the bot, so the Tasks page
        # shows them under the bot's assistant instead of Javis Core.
        # A plain string, so a hook reading the turn (a shallow copy) cannot edit it for the next reader.
        _luot["bot_id"] = str(bot["id"])
    # ĐA PHIÊN: định tuyến theo chat_id → ngữ cảnh của mỗi tài khoản tách biệt.
    chat_id = str((meta or {}).get("chat_id") or "default")
    if bot:
        # Bot chuyên trách: brain RIÊNG của bot, không phải brain của chủ. Khoá phiên gắn id bot
        # nên hai bot cùng nói chuyện với một khách vẫn là hai mạch tách bạch, và không cái nào
        # đụng vào phiên của chủ. Nhãn kênh "bot:<slug>" để hội thoại khách nằm riêng ở /sessions.
        sess = _tg_session(f"bot:{bot['id']}:{chat_id}")
        brain = bot["brain"]
        channel = f"bot:{bot.get('slug') or bot['id']}"
    else:
        # An agent turn gets its own RAM session and stored conversation (`<chat>@<slug>`, see
        # `_agent_sess_key`), while `chat_id` stays the real chat: /stop, background results and
        # the channel block keep pointing at the chat the owner is typing in.
        sess = _tg_session(_agent_sess_key(chat_id, agent))
        # The session's own brain (changed with /brain), Settings by default. An agent turn runs in
        # EXACTLY the brain the agent was checked in, without a second lookup: a lookup that landed
        # elsewhere would put the agent's prompt in one brain and its files and memory in another.
        brain = agent["brain"] if agent else _tg_brain(chat_id)
    mcfg = cfgmod.read_settings().get("model", {})
    # Chủ chat trên Telegram thì theo ghim của kênh (nếu có). Bot chuyên trách KHÔNG ăn theo
    # ghim của chủ: nó phục vụ khách, và model của nó là model của chính Agent nó trỏ tới.
    # An agent turn borrows that same path (same fall back to the main model when the agent is on
    # "Default").
    prov, kind, api_key, api_model = (_chat_provider_bot(mcfg, bot) if bot
                                      else _chat_provider_bot(mcfg, {"agent": agent}) if agent
                                      else _chat_provider_kenh(mcfg, channel, str(chat_id)))
    # Nhãn engine phải do VỎ quyết định rồi truyền xuống lõi: hai bên tự suy ra độc lập là
    # có ngày phiên bị dán nhãn 'cli' trong khi lượt thật chạy qua OpenRouter.
    engine_label = ("codex" if prov == "openai-oauth"
                    else "grok-cli" if prov == "grok-cli"
                    else "antigravity-cli" if prov == "antigravity-cli"
                    else prov if ((kind == "api" and api_key) or kind == "oauth")
                    else "cli")

    # Bản tương ứng của `store.clear_native_threads` bên dashboard, cho bốn engine giữ phiên.
    # Cùng một bất biến: engine khác vừa chen một lượt thì mạch của MỌI engine còn lại không
    # chứa lượt đó, nối tiếp là mù đúng đoạn ở giữa. Xoá liên kết thôi, giữ nguyên đối tượng;
    # lượt sau của engine đó bootstrap từ kho phiên.
    #
    # Câu "bootstrap từ kho phiên" đó mãi tới 0.50.1 mới đúng với cả bốn: trước đó chỉ Codex
    # làm thật, ba engine còn lại mở mạch tay không nên đoạn ở giữa vẫn mất.
    _tg_ngat_mach(sess, tru=engine_label)

    store = get_store()
    conv_sid = ""
    try:
        conv_sid = str(phien_kho or "")
        if not conv_sid and ghi_kho:
            # Chỉ TỰ MỞ phiên khi vỏ này còn là nơi ghi. Không ghi mà vẫn mở là để lại một bản
            # ghi hội thoại rỗng tanh trong thanh Lịch sử - đúng thứ đang phải dọn.
            conv_sid = _tg_conv_sid(store, sess, brain, engine_label,
                                    api_model or mcfg.get("claude_model"), channel=channel)
        if conv_sid and project_id:
            store.set_project(conv_sid, project_id)
        if conv_sid and ghi_kho:
            store.append_message(conv_sid, "user", text)
            # 0.213.0: a message the owner sent while this turn runs (bot_gateway._steer) joins the history when the
            # turn reads it, so it sits between this question and the answer, as it happened.
            steer_inbox.INBOX.set_sink(steer_inbox.current_sid(), lambda texts, _s=conv_sid: [
                store.append_message(_s, "user", t) for t in texts])
            if bot and chatbot_runtime._rp_is_group(meta):
                # Phiên của bot trong nhóm đặt tên theo NHÓM, không theo tin đầu của người nhắn đầu tiên.
                store.name_group_session(conv_sid, (meta or {}).get("chat_title"))
    except Exception as e:
        print(f"[{channel} session] {e}", file=__import__('sys').stderr)

    runtime_trace = _CONTEXT_RUNTIME.start_turn(
        conv_sid or f"{channel}:{chat_id}", brain, channel)
    _CONTEXT_RUNTIME.set_route(runtime_trace, engine_label,
                               api_model or mcfg.get("claude_model") or "mặc định")
    _trace_token = context_runtime.bind_trace(runtime_trace)
    _luot_token = turn_context.bind(_luot)
    try:
        _hop_acted = [False]

        async def _hop_progress(s):
            # 0.354.0: a "⚙" line is a tool call; after one, a quota error never reruns the turn elsewhere.
            if str(s or "").startswith("⚙"):
                _hop_acted[0] = True
            if progress:
                await progress(s)
        out = await _tg_answer_engine(
            text, meta, _hop_progress, chat_id=chat_id, sess=sess, brain=brain,
            mcfg=mcfg, prov=prov, kind=kind, api_key=api_key, api_model=api_model,
            store=store, conv_sid=conv_sid, channel=channel, bot=bot, agent=agent)
        # 0.354.0 (spec 6.4): out of quota before any tool ran -> the same message again on the next route, with
        # one progress line saying why. Customer bots keep their own model and never hop.
        _tried = []
        while (isinstance(out, str) and not bot and not _hop_acted[0] and len(_tried) < REROUTE_MAX_HOPS
               and _tg_quota_out(out, prov, kind, api_key, mcfg, account=_tg_turn_account(sess, prov))):
            _nxt = _chat_next_route(mcfg, prov, api_key if kind == "api" else "", _tried,
                                    failed_account=_tg_turn_account(sess, prov))
            if not _nxt:
                break
            _tried = _nxt["tried"]
            prov, kind, api_key, api_model = _nxt["route"]
            _tg_ngat_mach(sess, tru=("codex" if prov == "openai-oauth" else prov if prov in ("grok-cli", "antigravity-cli")
                                     else prov if ((kind == "api" and api_key) or kind == "oauth") else "cli"))
            _CONTEXT_RUNTIME.set_route(runtime_trace, prov, api_model or mcfg.get("claude_model") or "mặc định")
            if progress:
                try:
                    await progress("↻ " + _nxt["status"])
                except Exception:  # noqa: BLE001
                    pass
            out = await _tg_answer_engine(
                text, meta, _hop_progress, chat_id=chat_id, sess=sess, brain=brain, mcfg=mcfg,
                prov=prov, kind=kind, api_key=api_key, api_model=api_model,
                store=store, conv_sid=conv_sid, channel=channel, bot=bot, agent=agent)

        if agent and isinstance(out, dict):
            # The agent prompt asks for JAVIS_LESSON / JAVIS_RULE lines and says they are saved. The
            # /chat caller is the authenticated owner, as on the dashboard, so end the turn through
            # the same handler as an agent chat there: owner rules and lessons are recorded, the run
            # is logged, and the lines are stripped before the turn is stored or returned.
            out["text"] = _ket_luot_agent(brain, agent["slug"], text, out.get("text") or "",
                                          conv_sid=conv_sid)

        # Cùng luật với dashboard: hứa "xong em báo" mà không có việc nền nào thì nói thẳng.
        # Ở kênh này tin nhắn CHƯA gửi đi nên nối luôn vào cuối, khỏi phải bắn thêm một tin.
        # Bot chuyên trách đứng ngoài: nó nói chuyện với người lạ và không có quyền giao việc
        # nền, nên dán một dòng nội bộ về điều phối Kanban vào đó là lạc chỗ.
        if not bot and isinstance(out, dict) and channel == "telegram":
            # Engine bỏ lại lệnh chạy ngầm trong lượt Telegram: theo dõi, xong báo về đúng người.
            # Lượt nối tiếp tự động chỉ có ở khung chat web; ở đây mời nhắn "làm tiếp".
            try:
                _cau_nuoi = await _nhan_nuoi_tien_trinh(
                    f"telegram:{chat_id}", brain, str(chat_id or ""), out.get("text") or "",
                    tu_lam_tiep=False)
                if _cau_nuoi:
                    out["text"] = (out.get("text") or "") + "\n\n" + _cau_nuoi
            except Exception as e:
                print(f"[tien trinh nen telegram] {type(e).__name__}: {e}", file=__import__('sys').stderr)
        if not bot and isinstance(out, dict):
            try:
                _canh_bao = await _canh_bao_hua_suong(
                    brain, str(chat_id or ""), out.get("text") or "", runtime_trace)
                if _canh_bao:
                    out["text"] = (out.get("text") or "") + "\n\n" + _canh_bao
            except Exception as e:
                print(f"[hua suong telegram] {type(e).__name__}: {e}", file=__import__('sys').stderr)
            # Cùng luật với dashboard: link trỏ vào hư không thì nói ra, nối vào cuối tin.
            try:
                _thieu = _link_file_khong_thay(_brain_root(brain), out.get("text") or "")
                if _thieu:
                    out["text"] = (out.get("text") or "") + "\n\n" + _cau_link_khong_thay(_thieu)
            except Exception as e:
                print(f"[link file telegram] {type(e).__name__}: {e}", file=__import__('sys').stderr)
        if conv_sid and ghi_kho and isinstance(out, dict):
            try:
                await _persist_turn(store, conv_sid, brain, text, out.get("text") or "")
            except Exception as e:
                print(f"[{channel} persist] {e}", file=__import__('sys').stderr)
        if isinstance(out, str):
            # Lượt HỎNG: lõi trả chuỗi, và tới 0.59.20 vỏ này KHÔNG lưu gì cả - câu lỗi bay
            # thẳng ra Telegram rồi biến mất. Hậu quả nhìn thấy ở Lịch sử: một hội thoại đúng
            # MỘT TIN (câu người dùng), không tên, không câu trả lời, mở ra chẳng hiểu vì sao
            # (chủ dự án báo 16/09: "một loạt tin từ telegram chỉ có 1 tin"). Nay ghi câu lỗi
            # vào kho như một tin của trợ lý, y hệt cách `_persist_limit_notice` làm cho lượt
            # vấp hạn mức: đủ để mở lại còn đọc được chuyện gì đã xảy ra.
            #
            # Cố ý KHÔNG đi qua `_persist_turn`: câu lỗi không đáng vào nhật ký Memory lẫn
            # hàng đợi tự học. `ghi_kho=False` thì cũng không ghi ở đây: người gọi đang tự lo
            # phần ghi, và câu lỗi này được TRẢ VỀ cho họ nên không mất đi đâu cả.
            if conv_sid and ghi_kho:
                _persist_limit_notice(store, conv_sid, text, str(out))
            _CONTEXT_RUNTIME.note_error(runtime_trace, f"{channel}_error_response")
        _record_quality_shadow(
            runtime_trace, text,
            (out.get("text") or "") if isinstance(out, dict) else str(out or ""),
            channel,
        )
        _CONTEXT_RUNTIME.finish(
            runtime_trace,
            "COMPLETED_WITH_ERROR" if runtime_trace and runtime_trace.had_error else "COMPLETED",
        )
        return out
    except asyncio.CancelledError:
        _CONTEXT_RUNTIME.finish(runtime_trace, "CANCELLED", "cancelled")
        raise
    except Exception as e:
        _CONTEXT_RUNTIME.note_error(runtime_trace, type(e).__name__)
        _CONTEXT_RUNTIME.finish(runtime_trace, "FAILED", type(e).__name__)
        raise
    finally:
        turn_context.reset(_luot_token)
        context_runtime.reset_trace(_trace_token)


def _manual_session_probe(key: str):
    """(sid trong kho, số tin lịch sử RAM) của phiên bot `key`, cho BẢN NHÁP ở Hộp thư (0.65.5): nháp đọc kho làm ngữ cảnh
    nhưng không được để lại dấu vết (xem `chatbot_runtime.manual_answer`)."""
    s = _tg_session(key)
    return str(s.get("sid") or _TG_SID_MAP.get(key, "") or ""), len(s.get("bot") or [])


def _manual_session_undo(key: str, keep: int) -> None:
    """Gỡ dấu vết một lượt NHÁP: cắt lịch sử RAM về `keep` tin và cắt mạch native của engine (lượt thật sau mồi lại từ kho phiên,
    vốn không có lượt nháp vì nháp chạy với ghi_kho=False)."""
    s = _tg_session(key)
    lich = s.get("bot")
    if isinstance(lich, list) and len(lich) > keep:
        del lich[keep:]
    _tg_ngat_mach(s)


def _tg_ket(clean_out, files, canh_bao="", loi=(), khach=False):
    """Gói câu trả lời Telegram: cảnh báo hệ thống lên đầu, lỗi giữa lượt xuống cuối.

    Lỗi giữa lượt KHÔNG huỷ câu trả lời (dashboard vốn coi lỗi là không chí mạng), nhưng cũng
    không được giấu: giấu đi thì user tưởng lượt chạy sạch trong khi có tool đã hỏng.

    `khach=True` (a full-access dedicated bot, 0.102.1): the person reading is a CUSTOMER, not the owner.
    The system warning and the mid-turn error then go to `canh_bao`, which the bot log shows the owner,
    instead of being glued to the reply ("⚠ Có lỗi giữa lượt: ..." in a customer group)."""
    if khach:
        ghi_chu = [str(canh_bao or "").strip()] + (["Có lỗi giữa lượt: " + str(loi[0])] if loi else [])
        ket = {"text": clean_out or "", "files": files or []}
        if any(ghi_chu):
            ket["canh_bao"] = " · ".join(x for x in ghi_chu if x)[:500]
        return ket
    txt = (canh_bao or "") + (clean_out or "")
    if loi:
        txt += "\n\n⚠ Có lỗi giữa lượt: " + str(loi[0])
    return {"text": txt, "files": files or []}


# Số lượt hội thoại (user+assistant) giữ lại cho một người nói chuyện với bot. Cắt cứng thay
# vì nén như đường chat của chủ: nén là thêm một lượt gọi model nữa, mà bot trả lời người lạ
# thì cần nhanh và rẻ hơn là cần nhớ dai.
BOT_LICH_SU_MAX = 20

# Danh sách tool cho phép của bot khi phải chạy qua CLI: một chuỗi KHÔNG khớp tool nào.
#
# Không dùng list rỗng được: `claude_sdk_engine` kiểm `if self.allowed_tools:` nên [] là falsy,
# và engine hiểu thành "không có allowlist" rồi chạy thẳng permission_mode="bypassPermissions"
# - tức mở TOÀN QUYỀN đúng lúc mình định khoá chặt nhất. Một chuỗi vô nghĩa thì truthy, cổng
# can_use_tool bật lên, và mọi tool đều rớt khỏi allowlist nên bị từ chối từng lượt gọi.
BOT_KHONG_TOOL = ["__javis_bot_khong_tool__"]


# ------------------------------------------------------------
# Mảnh dùng chung của MỘT lượt bot
# ------------------------------------------------------------
# Hai mức quyền của bot khác nhau đúng MỘT chỗ: có tool hay không. Mọi thứ còn lại (lịch sử,
# ghim đường đo, đọc stream, tính usage, cắt lịch sử) phải giống hệt nhau, nên chúng nằm ở đây
# chứ không chép hai bản. Chép hai bản là cách chắc chắn để một hôm nào đó `usage_store.record`
# có ở đường này mà thiếu ở đường kia - hoá đơn thiếu, và không ai nhìn ra được từ bên ngoài.
def _bot_lich_su(sess):
    if sess.get("bot") is None:
        sess["bot"] = []
    return sess["bot"]


def _bot_cat_lich_su(lich_su):
    if len(lich_su) > BOT_LICH_SU_MAX:
        del lich_su[:len(lich_su) - BOT_LICH_SU_MAX]


def _bot_ghim_duong(runtime_trace, prov, api_model, messages, tools=()):
    """Ghim lượt này vào đường 'bot' trên trang Tiết kiệm token.

    Không ghim thì `pin_execution_path` xếp nó vào 'Đầy đủ' - đường ĐẮT NHẤT - trong khi lượt
    bot là đường rẻ nhất hệ thống (không CLAUDE.md, không MEMORY.md). Trang đo nói ngược sự thật.
    """
    if not runtime_trace:
        return
    _CONTEXT_RUNTIME.set_route(runtime_trace, prov, api_model or "?")
    _CONTEXT_RUNTIME.pin_execution_path(
        runtime_trace, "bot", None, context_runtime.RUNTIME_VERSION, "bot_chuyen_trach")
    _CONTEXT_RUNTIME.observe_payload(runtime_trace, messages, list(tools or []),
                                     provider=prov, model=api_model or "?")


async def _bot_doc_stream(stream, *, progress, runtime_trace, prov, api_model):
    """Đọc MỘT stream của bot: trả (text, [lỗi]). Tính usage, báo tiến độ, không đụng lịch sử.

    Lỗi giữa lượt KHÔNG dừng vòng lặp: một tool hỏng không có nghĩa là cả lượt hỏng, và luồng
    thường vẫn chạy tiếp ra câu trả lời. Đúng cách đường chat của chủ vẫn xử lý.
    """
    out, loi, actual_model = "", [], api_model or "?"
    _pinged = False
    try:
        async for ev in stream:
            t = ev.get("type")
            if t == "text":
                if not _pinged:
                    _pinged = True
                    await progress("✍ Đang soạn câu trả lời…")
                out += ev.get("content") or ""
            elif t == "meta":
                actual_model = ev.get("model") or actual_model
            elif t == "tool_call":
                await progress(f"⚙ Đang dùng công cụ: {ev.get('name', '')}")
            elif t == "usage":
                usage_store.record(prov, actual_model, ev.get("input", 0), ev.get("output", 0))
                _CONTEXT_RUNTIME.record_usage(runtime_trace, ev.get("input", 0), ev.get("output", 0))
            elif t == "error":
                loi.append(str(ev.get("content") or "lỗi không rõ"))
    except Exception as e:
        print(f"[bot {prov}] {type(e).__name__}: {e}", file=__import__('sys').stderr)
        loi.append(str(e))
    return out, loi


def _bot_ket(out, lich_su):
    """Đóng gói câu trả lời của một lượt bot đã chạy được."""
    lich_su.append({"role": "assistant", "content": out})
    _bot_cat_lich_su(lich_su)   # cắt SAU khi thêm, không thì trần bị vượt đúng một lượt mỗi vòng
    return {"text": channel_context.strip_control_blocks(out), "files": []}


# `_bot_cli_du_phong` đã gỡ ở 0.26.17. Nó là đường LUI cho ca "đọc không ra token OAuth nên
# /v1/messages trả 401". Nay không còn token nào để đọc: gói Claude Code chạy thẳng qua binary
# `claude` ngay từ `_api_stream`, nên một đường lui cũng dẫn tới đúng engine ấy là vô nghĩa.


def _anh_khong_gui_duoc(prov) -> str:
    """Cảnh báo cho nhật ký bot khi bộ não của bot không có đường gửi ảnh (Antigravity, Grok Build)."""
    return (f"Bot không xem được ảnh khách gửi: bộ não {prov} của bot không nhận ảnh. Đổi model của bot sang "
            f"Claude, ChatGPT hoặc một model API nhìn được ảnh.")


def _bot_gan_anh(messages, prov, text, images):
    """Gắn ẢNH khách gửi vào tin user CUỐI của lượt (0.81.0). Trả (messages để gửi, True nếu đã gắn ảnh thật).

    Chủ dự án chốt 05/10: ảnh đi THẲNG vào lượt chat, chính model đang chạy bot nhìn ảnh. Từ 0.94.0 (chủ chốt 11/10) model
    nào không nhìn được thì một bộ não khác đã kết nối xem hộ, xem `_bot_anh_mat_muon` và borrowed_eyes.py.
    Bộ não không có đường gửi ảnh (Antigravity, Grok Build) hoặc ảnh không đọc được thì nhận dòng nhãn thật thà "kèm một
    ảnh mà bạn không xem được", để model khỏi trả lời như thể đã thấy ảnh. Lịch sử giữ chữ trơn (xem `_bot_tra_loi`)."""
    if not images:
        return messages, False
    import chatbot_runtime
    parts = vision_input.user_parts(text, images) if vision_input.supported(prov) else None
    last = {"role": "user", "content": parts if parts else chatbot_runtime._KEM_ANH + str(text or "")}
    return messages[:-1] + [last], bool(parts)


def _bot_bo_anh(messages, text):
    """Bản gửi lại khi model TỪ CHỐI ảnh (model chữ thuần trên Groq, Ollama...): bỏ ảnh, gắn nhãn thật thà."""
    import chatbot_runtime
    return messages[:-1] + [{"role": "user", "content": chatbot_runtime._KEM_ANH + str(text or "")}]


async def _mat_muon_stream(prov, model, messages):
    """Stream for ONE borrowed look at a customer's photo (0.94.0, see borrowed_eyes). No tools, reasoning off.

    The ChatGPT candidate uses `image_vision.VISION_MODEL` as is: `_codex_safe_model` would swap a model missing from the saved
    catalog for the catalog's first entry, which may be the very model that just refused the photo. Claude Code that is not
    signed in answers with a short "Not logged in" text instead of an error; that is turned into an error so it is never taken
    for a description of the photo."""
    if prov == "openai-oauth" and model == image_vision.VISION_MODEL:
        creds = openai_oauth.valid_creds() or {}
        inner = engine.openai_responses_stream(creds.get("access_token", ""), creds.get("account_id", ""), model, messages, "off")
    else:
        inner = _api_stream(prov, aux_engine.api_key_for(prov), model, messages, "off")
    parts, actual = [], model or "?"
    async for ev in inner:
        t = ev.get("type")
        if t == "meta":
            actual = ev.get("model") or actual
        elif t == "usage":
            usage_store.record(prov, actual, ev.get("input", 0), ev.get("output", 0))
        elif t == "text":
            parts.append(str(ev.get("content") or ""))
        elif t == "error":
            yield ev
    text = "".join(parts)
    if aux_engine.final_loi_dang_nhap(text):
        yield {"type": "error", "content": text.strip()}
    elif text:
        yield {"type": "text", "content": text}


def _mat_muon_ung_vien(prov, api_model):
    """Brains the owner already connected that may look at a photo for this bot, in borrowed_eyes order."""
    s = cfgmod.read_settings()
    main = _effective_main(s)
    try:
        main_ok = bool(aux_engine.availability(main, s)[0])
        if main["provider"] == "anthropic-cli":
            main_ok = main_ok and bool(find_claude_cli())
    except Exception:      # noqa: BLE001 - an unreadable setting only means one fewer pair of eyes
        main_ok = False
    try:
        claude_ok = bool(find_claude_cli())
    except Exception:      # noqa: BLE001
        claude_ok = False
    return borrowed_eyes.candidates(
        prov, api_model, main_prov=main["provider"], main_model=main.get("model") or "", main_ok=main_ok,
        chatgpt_ok=image_vision.connected(), chatgpt_model=image_vision.VISION_MODEL, claude_ok=claude_ok)


async def _bot_xem_ho(images, text, prov, api_model, chat_id=""):
    """Another connected brain describes the customer's photos. Returns (description, who, why it failed)."""
    try:
        res = await borrowed_eyes.describe(list(images or []), text, _mat_muon_ung_vien(prov, api_model), _mat_muon_stream)
    except Exception as e:      # noqa: BLE001 - borrowed eyes failing must never cost the customer the reply
        res = {"ok": False, "errors": [f"{type(e).__name__}: {e}"]}
    if res.get("ok"):
        print(f"[bot {prov} chat {chat_id}] ảnh khách gửi do {res.get('who')} xem hộ", file=sys.stderr)
        return res["text"], res.get("who") or "", ""
    why = "; ".join(res.get("errors") or [])[:300]
    print(f"[bot {prov} chat {chat_id}] không bộ não nào xem hộ được ảnh: {why}", file=sys.stderr)
    return "", "", why


async def _bot_anh_mat_muon(messages, lich_su, text, images, prov, api_model, chat_id, ly_do):
    """The bot's own model cannot see this turn's photos: let another brain describe them (0.94.0).

    Returns (messages to send, warning for the bot card). With a description the last user turn carries it as photo content and
    the history keeps a short version; without one the turn falls back to the old honest label, and the warning says why the
    bot could not see the photo AND why no other brain could look for it."""
    mo_ta, who, why = await _bot_xem_ho(images, text, prov, api_model, chat_id)
    if not mo_ta:
        return _bot_bo_anh(messages, text), f"{ly_do} Không bộ não nào khác xem hộ được: {why}"[:400]
    n = len(images)
    if lich_su:
        lich_su[-1] = {"role": "user", "content": borrowed_eyes.history_text(text, mo_ta, n)}
    return messages[:-1] + [{"role": "user", "content": borrowed_eyes.turn_text(text, mo_ta, n)}], ""


def _bot_lich_su_chu(text, images):
    """Câu user GHI VÀO LỊCH SỬ: chữ trơn, kèm một dòng ghi chú nếu lượt có ảnh. Ảnh không gửi lại ở lượt sau (tốn token),
    nhưng model vẫn biết khách từng gửi ảnh khi họ hỏi tiếp "cái áo trong ảnh lúc nãy"."""
    if not images:
        return text
    return f"{text}\n(khách gửi kèm {len(images)} ảnh ở tin này)"


async def _bot_tra_loi(text, *, sess, sysprompt, prov, api_key, api_model, reasoning,
                       progress, runtime_trace, brain=None, chat_id="", images=None):
    """Một lượt của Bot chuyên trách. MỘT đường duy nhất cho CẢ TÁM bộ não.

    Vì sao không đi theo bốn nhánh engine như đường chat của chủ:

    1. **Để đổi bộ não không đổi trải nghiệm.** Đó là lời hứa gốc của Javis. Đi bốn nhánh thì
       Claude Code có Bash, Codex có kho MCP riêng, engine API bị trần vòng gọi tool - ba
       kiểu hành xử khác nhau cho cùng một con bot, và chủ đổi model là khách thấy khác ngay.
       Ở đây mọi engine nhận CÙNG system prompt, CÙNG tài liệu, CÙNG lịch sử, và đều không có
       tool. Khác biệt còn lại đúng bằng khác biệt giữa các model, không phải giữa các đường ống.

    2. **Để cách ly brain là thật, không phải là rào.** Bot không được cấp tool nào cả, nên nó
       KHÔNG CÓ cách nào chạm vào đĩa - khỏi cần cổng duyệt, khỏi cần sandbox, khỏi phải hy
       vọng cwd giữ chân được nó. Trước đó bản 0.21.0 phải khoá allowed_tools cho Claude Code
       và TỪ CHỐI chạy trên Codex vì Codex không khoá được phạm vi đọc. Cả hai chỗ chắp vá đó
       biến mất: không có tool thì không có gì để khoá.

    Tài liệu đã được `chatbot_grounding` tra sẵn bằng Python TRƯỚC khi model chạy và nằm trong
    `sysprompt`, nên bỏ tool không làm bot mất khả năng đọc brain - chỉ bỏ khả năng đi lang
    thang trong đó.

    `_api_stream` phục vụ sáu provider API cộng gói ChatGPT (đi `openai_responses_stream`).
    Gói Claude Code là ngoại lệ DUY NHẤT: nó rẽ sang `_bot_cli_du_phong` ngay dưới đây, tức
    chạy qua binary `claude`. Đắt hơn một nhịp khởi động tiến trình, đổi lại không phải mượn
    token đăng nhập của ai - thứ Anthropic cấm và có khoá tài khoản thật (xem claude_auth.py).

    Đây là đường của mức **Chỉ đọc** - mức mặc định. Bot đặt ở mức Được ghi / Toàn quyền đi
    `_bot_tra_loi_co_tool`. Hai đường tách hẳn nhau CÓ CHỦ Ý: đường này phải soi được bằng mắt
    là không có tool nào, và một test canh đúng thân hàm này (test_chatbot_cach_ly.py mục B2).
    """
    lich_su = _bot_lich_su(sess)
    lich_su.append({"role": "user", "content": _bot_lich_su_chu(text, images)})
    _bot_cat_lich_su(lich_su)

    # System dựng LẠI mỗi lượt: tài liệu tra được đổi theo từng câu hỏi. Giữ system cũ là bot
    # trả lời câu này bằng tài liệu của câu trước.
    messages = [{"role": "system", "content": sysprompt}] + lich_su
    _bot_ghim_duong(runtime_trace, prov, api_model, messages)
    gui, co_anh = _bot_gan_anh(messages, prov, text, images)
    canh_bao_anh = ""
    if images and not co_anh:
        # Bộ não này không có đường gửi ảnh: mượn mắt bộ não khác đã kết nối tả ảnh thành chữ (0.94.0).
        gui, canh_bao_anh = await _bot_anh_mat_muon(messages, lich_su, text, images, prov, api_model, chat_id,
                                                    _anh_khong_gui_duoc(prov))

    out, loi = await _bot_doc_stream(
        _api_stream(prov, api_key, api_model, gui, reasoning),
        progress=progress, runtime_trace=runtime_trace, prov=prov, api_model=api_model)
    if not out and co_anh:
        # Model nhận ảnh mà trả rỗng hoặc lỗi: mượn mắt bộ não khác rồi trả lời lại. Lỗi GỐC đi vào cảnh báo, vì trước 0.94.0
        # mọi lỗi ở đây đều bị ghi chung là "từ chối ảnh" và không ai biết model thật sự nói gì.
        goc = (loi[0] if loi else "không trả lời gì")[:200]
        print(f"[bot {prov} chat {chat_id}] model không nhận ảnh ({goc}), mượn mắt bộ não khác",
              file=__import__('sys').stderr)
        gui, canh_bao_anh = await _bot_anh_mat_muon(
            messages, lich_su, text, images, prov, api_model, chat_id,
            f"Bot không xem được ảnh khách gửi: model {api_model or prov} không nhận ảnh (lỗi gốc: {goc}).")
        if not canh_bao_anh:
            canh_bao_anh = (f"Model {api_model or prov} của bot không nhận ảnh (lỗi gốc: {goc}), "
                            f"nên một bộ não khác đã xem hộ ảnh.")
        out, loi = await _bot_doc_stream(
            _api_stream(prov, api_key, api_model, gui, reasoning),
            progress=progress, runtime_trace=runtime_trace, prov=prov, api_model=api_model)

    if not out:
        lich_su.pop()   # lượt hỏng thì đừng để câu hỏi treo lơ lửng không có câu trả lời
        if prov == "openai-oauth" and not (openai_oauth.valid_creds() or {}).get("access_token"):
            # Codex không chạy không-tool được nên không có đường dự phòng. Nói đúng việc cần
            # làm thay vì để chủ đọc một mã lỗi HTTP.
            return ("⚠ Chưa đăng nhập được ChatGPT nên bot không gọi được model. "
                    "Vào trang Models kết nối lại tài khoản ChatGPT rồi nhắn lại.")
        return "⚠ " + (loi[0] if loi else "Không nhận được nội dung nào.")
    # Không gửi kèm file: bot ở mức này không tạo được file (không có tool), và quét thư mục
    # brain để tìm file "mới" thì lại là một đường rò tài liệu ra ngoài.
    ket = _bot_ket(out, lich_su)
    if canh_bao_anh:
        ket["canh_bao"] = canh_bao_anh
    return ket


# ============================================================
# Bot ở mức Được ghi / Toàn quyền - CÓ tool
# ============================================================
def _bot_stream_co_tool(prov, key, model, messages, reasoning, tools, route,
                        *, brain=None, tag_bot="bot", muc_quyen="full"):
    """Vòng gọi tool cho một lượt bot, đủ CẢ TÁM bộ não.

    Vẫn giữ nguyên lời hứa gốc: đổi bộ não thì trải nghiệm không đổi. Nên hai gói thuê bao
    không bị bỏ lại - ChatGPT đi `responses_with_mcp`, Claude Code đi engine Claude Code thật
    (`_claude_sub_stream_tools`) thay cho đường mượn token OAuth đã gỡ ở 0.26.17.

    Điều đó có một hệ quả PHẢI biết: nhánh Claude Code nay CÓ tool native (Bash, Read,
    WebFetch), khác hẳn sáu nhánh kia. Rào an toàn vì thế không còn tựa vào "không engine nào
    mở CLI" được nữa, mà tựa vào allowlist per-call của `can_use_tool` - xem `_bot_allowlist`.

    `tools` rỗng (hub tắt, hoặc chưa đấu nguồn nào) → rơi về stream không tool. Bot vẫn trả lời
    được thay vì im; chỗ gọi báo cho chủ biết là lượt đó không có công cụ nào.
    """
    if not tools:
        return _api_stream(prov, key, model, messages, reasoning)

    def _vong():
        if prov == "openrouter":
            return engine.openrouter_chat_with_mcp(key, model, messages, reasoning, tools, route)
        if prov == "openai":
            return engine.openai_chat_with_mcp(key, model, messages, reasoning, tools, route)
        if prov == "gemini":
            return engine.gemini_chat_with_mcp(key, model, messages, reasoning, tools, route)
        if prov == "groq":
            return engine.groq_chat_with_mcp(key, model, messages, reasoning, tools, route)
        if prov == "deepseek":
            return engine.deepseek_chat_with_mcp(key, model, messages, reasoning, tools, route)
        if prov == "ollama":
            return engine.ollama_chat_with_mcp(key, model, messages, reasoning, tools, route)
        if prov == "ollama-local":
            return engine.ollama_local_chat_with_mcp(key, model, messages, reasoning, tools, route)
        if prov == "openai-compat":
            return engine.openai_compat_chat_with_mcp(key, model, messages, reasoning, tools, route)
        if prov == "anthropic-compat":
            return engine.anthropic_compat_chat_with_mcp(key, model, messages, reasoning, tools, route)
        if prov == "openai-oauth":
            creds = openai_oauth.valid_creds() or {}
            return engine.responses_with_mcp(creds.get("access_token", ""), creds.get("account_id", ""),
                                             _codex_safe_model(model), messages, reasoning, tools, route)
        if prov == "anthropic-cli":
            # Gói Claude Code: qua binary `claude` + hub, không mượn token đăng nhập của ai.
            # `tools` chỉ dùng để BIẾT lượt này có công cụ hay không - engine tự đấu hub bằng
            # config riêng mang brain của bot, nên không phải chuyển danh sách schema sang.
            # Bốn lớp rào giữ đúng hợp đồng cách ly: xem `_claude_sub_stream_tools`.
            return _claude_sub_stream_tools(model, messages, reasoning, brain=brain,
                                            tag=tag_bot, mode=muc_quyen)
        return engine.anthropic_chat_with_mcp(key, model, messages, reasoning, tools, route)

    # Nhà cung cấp gãy tạm thời thì thử lại - nhưng dừng ngay khi tool đầu tiên đã chạy, vì từ
    # đó lượt này đã chạm vào thế giới thật.
    return engine.thu_lai_khi_tam_thoi(_vong, nhan=f"bot {prov}/{model or 'mặc định'}")


class _BoQua(Exception):
    """Nhảy qua một khối try khi bước đó không áp cho lượt này (bot Toàn quyền bỏ nguồn chọn lọc)."""


# Engines of the owner's channel that open an image FILE themselves (Claude Code's Read, Codex's image viewer). A full-access
# bot on any other engine gets the borrowed-eyes description added to the turn as well (0.94.0).
_MO_ANH_BANG_CONG_CU = ("anthropic-cli", "openai-oauth")


def _bot_full_prompt(brain, sys_bot, lang, conv_sid=""):
    """Prompt của bot mức Toàn quyền (0.85.3): ĐỦ prompt của kênh admin (CLAUDE.md, bộ nhớ, kỹ năng,
    hướng dẫn điều phối) cho brain của bot, rồi VAI của Agent đè lên.

    Đủ prompt admin vì chủ muốn bot Toàn quyền làm được đúng những gì kênh admin làm, và phần hướng
    dẫn công cụ, kỹ năng, giao việc nằm ở đó. Vai Agent đứng SAU và nói rõ nó thắng phần giới thiệu
    Javis ở trên, để bot vẫn là con bot chủ dựng chứ không tự xưng Javis với khách."""
    base = build_system_prompt(brain, lang=lang, session_id=conv_sid or "")
    return (base + "\n\n# === BOT TOÀN QUYỀN: VAI CỦA BẠN TRONG CUỘC CHAT NÀY ===\n"
            "Bạn đang trả lời qua một bot chuyên trách mà chủ đã đặt ở mức TOÀN QUYỀN: bạn có đủ công "
            "cụ, kết nối, kỹ năng và quyền thao tác như khi chủ chat trực tiếp với Javis. Người đang "
            "nhắn có thể KHÔNG phải chủ. Nói chuyện theo đúng vai và quy định dưới đây; chỗ nào khác "
            "phần giới thiệu Javis ở trên thì làm theo phần dưới.\n\n" + str(sys_bot or ""))


async def _bot_tra_loi_co_tool(text, *, sess, sysprompt, prov, api_key, api_model, reasoning,
                               progress, runtime_trace, brain, chat_id, muc_quyen, images=None):
    """Một lượt của bot ở mức **Đọc tài liệu** (read_docs), **Được ghi** (auto) hoặc **Toàn quyền** (full).

    Mức Đọc tài liệu (0.80.0) đi chung đường này, chỉ khác ở bộ tool: `mcp_hub.discover_all` trả về
    đúng ba tool chỉ-đọc của `chatbot_doc_tools` cho brain của bot, không nguồn nào, không ghi gì.

    Khác `_bot_tra_loi` đúng một thứ: có tool. Mọi thứ còn lại - prompt của Agent, tài liệu tra
    sẵn, lịch sử, cách đọc stream - dùng chung mã, nên hai mức không trôi xa nhau.

    **Tool ở đây CHỈ đến từ hub MCP, không có tool native nào.** Đó là điều kiện để nới quyền
    mà không phá rào đã có:

    1. **Cách ly brain vẫn nguyên.** Tool file của hub đi qua `mcp_hub._safe_path(vault_root,…)`
       với `vault_root` là brain CỦA CHÍNH BOT, nên trèo sang brain khác thì nổ ValueError chứ
       không trả rỗng. Nếu mở tool native của Claude Code thì `Read` đọc được đường dẫn tuyệt
       đối bất kỳ - đúng lỗ mà 0.21.0 đã phải vá.
    2. **Không lệnh máy, không lang thang web.** Không Bash, không WebFetch, không WebSearch,
       không Task - vì chúng vốn không nằm trong hub.
    3. **Mức quyền là lớp CỨNG, không phải lời dặn.** `muc_quyen` đi thẳng vào `discover_all`
       rồi thành header `X-Javis-Mode`: mức `auto` thì hub tự chặn nhóm nguy hiểm (tiền, đơn,
       gửi tin, đăng bài) ngay tại chỗ gọi, bất kể prompt nói gì và khách dụ khéo cỡ nào.

    Cái KHÔNG còn nữa, và chủ phải biết trước khi bật: ở mức này người điều khiển tool là KHÁCH
    LẠ. Rào còn lại chỉ là quy định trong file Agent, mà chữ thì lách được. Vì thế nâng mức đòi
    một cú xác nhận có ý thức (`chatbot_store.can_xac_nhan`), và trang Chatbot nói thẳng cái
    mất được trước khi chủ bấm.

    Vẫn KHÔNG tự đính kèm file như đường chat của chủ, dù ở mức này bot tạo được file thật.
    `collect_turn_files` quét thư mục brain tìm file "mới", và với người lạ thì đó là một đường
    rò tài liệu: hỏi một câu vu vơ đúng lúc có file khác vừa sinh ra là nhận được nó. Bot muốn
    đưa file cho khách thì nói đường dẫn trong câu trả lời.
    """
    lich_su = _bot_lich_su(sess)
    lich_su.append({"role": "user", "content": _bot_lich_su_chu(text, images)})
    _bot_cat_lich_su(lich_su)
    messages = [{"role": "system", "content": sysprompt}] + lich_su
    gui, co_anh = _bot_gan_anh(messages, prov, text, images)
    canh_bao_anh = ""
    if images and not co_anh:
        # Bộ não này không có đường gửi ảnh: mượn mắt bộ não khác đã kết nối tả ảnh thành chữ (0.94.0).
        gui, canh_bao_anh = await _bot_anh_mat_muon(messages, lich_su, text, images, prov, api_model, chat_id,
                                                    _anh_khong_gui_duoc(prov))

    # vault_root = brain CỦA BOT. Đây là một tham số, không phải một quy ước - truyền nhầm brain
    # của chủ vào đây là mở toang đúng thứ cả tính năng này đang giữ.
    tools, route = [], {}
    # Grok Build và Antigravity là CLI có lệnh máy riêng, chưa có đường công cụ HẸP nào giữ được rào của
    # hai mức này (chỉ brain của bot, không lệnh máy). Trước 0.85.3 chúng không có nhánh nào ở
    # `_bot_stream_co_tool` và rơi vào lời gọi Anthropic API với khoá sai: lượt nào cũng hỏng rồi mới
    # lùi về chỉ chat. Giờ nói thẳng ngay từ đầu: lượt này không công cụ, và chủ biết đường ra.
    cli_khong_tool = prov in ("grok-cli", "antigravity-cli")
    try:
        if not cli_khong_tool:
            # for_bot=True: khách lạ đang lái model, nên tool chỉ-của-chủ (bộ phán xử, 0.77.0) bị bỏ khỏi danh sách.
            tools, route = await mcp_hub.discover_all(muc_quyen, vault_root=_brain_root(brain), for_bot=True)
    except Exception as e:
        print(f"[bot {prov} chat {chat_id}] nạp tool hỏng: {type(e).__name__}: {e}",
              file=__import__('sys').stderr)
    _bot_ghim_duong(runtime_trace, prov, api_model, messages, tools)

    # Engine KHÔNG chạy nổi vòng tool: trả lời lại lượt này mà bỏ tool đi.
    #
    # Không phải phòng xa. Bản 0.24.0 nối mức Được ghi của gói ChatGPT vào
    # `engine.responses_with_mcp`, một hàm tới lúc đó CHƯA TỪNG được gọi từ đâu và tự ghi
    # EXPERIMENTAL trong docstring. Chạy thật thì nó trả rỗng, và hậu quả không dừng ở "tính
    # năng mới chưa chạy": MỌI câu người ta nhắn cho bot đều nhận một lời xin lỗi kỹ thuật, tức
    # nâng mức quyền làm HỎNG con bot vốn đang chạy tốt. Nâng quyền không được phép lấy đi năng
    # lực đã có.
    #
    # Nên đường lui: vẫn trả lời, chỉ là không có công cụ. Và tuyệt đối KHÔNG im lặng về việc
    # đó - chủ đặt mức Được ghi mà bot lặng lẽ chạy như mức Chỉ đọc là đúng kiểu hỏng tệ nhất.
    # Cảnh báo đi kèm câu trả lời, lên thẻ bot, và nói luôn việc cần làm.
    async def _mot_lan(gui_):
        """Một lần thử: vòng tool, rỗng thì chính lượt đó KHÔNG tool. Trả (out, loi, đã rơi về không-tool)."""
        out_, loi_ = await _bot_doc_stream(
            _bot_stream_co_tool(prov, api_key, api_model, gui_, reasoning, tools, route,
                                brain=brain, tag_bot=f"bot:{chat_id}", muc_quyen=muc_quyen),
            progress=progress, runtime_trace=runtime_trace, prov=prov, api_model=api_model)
        if out_ or not tools:
            return out_, loi_, False
        print(f"[bot {prov} chat {chat_id}] vòng tool rỗng ({loi_[0] if loi_ else '?'}), "
              f"trả lời lại KHÔNG tool", file=__import__('sys').stderr)
        out2, loi2 = await _bot_doc_stream(
            _api_stream(prov, api_key, api_model, gui_, reasoning),
            progress=progress, runtime_trace=runtime_trace, prov=prov, api_model=api_model)
        if out2:
            return out2, [], True
        # Gãy CẢ đường không-tool thì lỗi đáng báo là lỗi của đường đó, không phải lỗi vòng
        # tool. Đường không-tool là lời gọi đơn giản nhất còn lại, nên nó nói đúng bệnh hơn:
        # hết quota, sai token, mạng chết. Báo lỗi vòng tool trước là đẩy chủ đi tìm xem
        # engine có hỗ trợ tool không, trong khi thứ hỏng là cái khác hẳn.
        return "", loi2 + loi_, False

    # Lần đầu GIỮ ẢNH cho cả đường không-tool (0.94.0). Trước đó vòng tool rỗng là ảnh bị đổ lỗi ngay: bot "Javis Vũ" trên gói
    # ChatGPT bị ghi "từ chối ảnh" ở những lượt mà thứ hỏng thật là vòng tool (cùng ngày nó báo 129 lượt không gọi được công cụ).
    out, loi, roi_tool = await _mot_lan(gui)
    if not out and co_anh:
        # Có ảnh mà vẫn rỗng cả khi bỏ tool: lỗi nằm ở ảnh. Mượn mắt bộ não khác (0.94.0), thử lại với ảnh đã thành chữ (không
        # ai xem hộ được thì chỉ chữ + nhãn thật thà). Mất ảnh gốc, không mất công cụ. Lỗi GỐC đi vào cảnh báo.
        goc = (loi[0] if loi else "không trả lời gì")[:200]
        print(f"[bot {prov} chat {chat_id}] model không nhận ảnh ({goc}), mượn mắt bộ não khác",
              file=__import__('sys').stderr)
        gui, canh_bao_anh = await _bot_anh_mat_muon(
            messages, lich_su, text, images, prov, api_model, chat_id,
            f"Bot không xem được ảnh khách gửi: model {api_model or prov} không nhận ảnh (lỗi gốc: {goc}).")
        if not canh_bao_anh:
            canh_bao_anh = (f"Model {api_model or prov} của bot không nhận ảnh (lỗi gốc: {goc}), "
                            f"nên một bộ não khác đã xem hộ ảnh.")
        out, loi, roi_tool = await _mot_lan(gui)
    canh_bao = ""
    if roi_tool:
        canh_bao = (f"Engine đang chạy ({_api_label(prov)}) không gọi được công cụ cho bot, "
                    f"nên lượt vừa rồi trả lời ở mức Chỉ đọc chứ không phải mức "
                    f"{chatbot_store.MUC_NHAN.get(muc_quyen, muc_quyen)} bạn đã đặt. "
                    f"Cần bot làm việc thật thì đổi engine ở trang Models, hoặc hạ mức bot "
                    f"xuống Chỉ đọc cho khỏi hiểu nhầm.")

    if not out:
        lich_su.pop()   # lượt hỏng thì đừng để câu hỏi treo lơ lửng không có câu trả lời
        if prov == "openai-oauth" and not (openai_oauth.valid_creds() or {}).get("access_token"):
            return ("⚠ Chưa đăng nhập được ChatGPT nên bot không gọi được model. "
                    "Vào trang Models kết nối lại tài khoản ChatGPT rồi nhắn lại.")
        return "⚠ " + (loi[0] if loi else "Không nhận được nội dung nào.")
    if not tools:
        # Bot được đặt ở mức có quyền mà lại chẳng có công cụ nào - im lặng ở đây thì chủ tưởng
        # bot đang làm việc, còn thực tế nó chỉ đang nói chuyện.
        if cli_khong_tool:
            canh_bao = (f"Bộ não {_api_label(prov)} chưa dùng được công cụ ở mức "
                        f"{chatbot_store.MUC_NHAN.get(muc_quyen, muc_quyen)} của bot, nên lượt vừa rồi chỉ "
                        f"trả lời. Cần công cụ thì đặt bot ở mức Toàn quyền (chạy như kênh admin) hoặc "
                        f"chọn bộ não khác cho Agent.")
        elif muc_quyen == "read_docs":
            # Mức này không cần nguồn nào: thiếu tool chỉ có thể là không mở được brain của bot.
            canh_bao = (f"Bot đang ở mức {chatbot_store.MUC_NHAN.get(muc_quyen, muc_quyen)} nhưng "
                        f"không mở được brain của nó, nên lượt vừa rồi chỉ dùng phần tài liệu tra sẵn. "
                        f"Kiểm tra brain của bot còn tồn tại không.")
        else:
            canh_bao = (f"Bot đang ở mức {chatbot_store.MUC_NHAN.get(muc_quyen, muc_quyen)} nhưng "
                        f"chưa có nguồn dữ liệu nào đấu vào, nên không có công cụ nào để dùng. "
                        f"Đấu thêm ở trang Kết nối, hoặc hạ mức bot xuống Chỉ đọc.")
        print(f"[bot {prov} chat {chat_id}] mức '{muc_quyen}' nhưng hub không trả tool nào - "
              f"lượt này chỉ chat", file=__import__('sys').stderr)
    ket = _bot_ket(out, lich_su)
    canh_bao = " · ".join(x for x in (canh_bao, canh_bao_anh) if x)
    if canh_bao:
        ket["canh_bao"] = canh_bao
    return ket


async def _tg_answer_engine(text, meta, progress, *, chat_id, sess, brain, mcfg,
                            prov, kind, api_key, api_model, store=None, conv_sid="",
                            channel="telegram", bot=None, agent=None):
    """Lõi 4 nhánh engine của một lượt Telegram. Trả dict khi có câu trả lời thật,
    trả CHUỖI khi là thông báo lỗi (vỏ `_tg_answer` dựa vào đó để biết lượt nào đáng lưu)."""
    sess["last"] = text
    sess["sent"] = set()    # lượt mới → reset dedupe (endpoint /telegram/send-file add vào đây)
    reasoning = _chat_reasoning(mcfg, prov)   # 0.350.0: effort of the card this turn runs on
    # The bolt is the owner's: customer chatbots answering strangers never inherit it.
    fast_mode.use(mcfg.get("fast") is True and not bot)
    runtime_trace = context_runtime.current_trace()

    # NGÔN NGỮ cho lượt này. Dính theo TỪNG CUỘC CHAT (chat_id), không theo tiến trình: một
    # bot Telegram phục vụ nhiều người, và ngôn ngữ của người này không được tràn sang người
    # kia.
    #
    # Với bot chuyên trách thì ngôn ngữ do BẢN GHI BOT quyết, và cố ý KHÔNG truyền
    # `reply_pref` của chủ xuống: bot ghim "auto" nghĩa là "bám theo khách", còn tràn cài đặt
    # của chủ vào đó là phá đúng lý do trường `ngon_ngu` tồn tại - chủ người Việt bán cho
    # khách Nhật thì ngôn ngữ của chủ là thông tin SAI để suy ra ngôn ngữ của bot.
    _lc_kenh = cfgmod.read_settings().get("locale") or {}
    _lang_qd = lang_mod.resolve(
        turn_text=text,
        chatbot_pin=(bot or {}).get("ngon_ngu") or "",
        reply_pref=("" if bot else (_lc_kenh.get("reply_lang") or "auto")),
        channel_default=(_ngon_ngu_cuoc_goi(meta) or ("vi" if channel == "zalo" and not bot else "")),
        ui_lang=("" if bot else (_lc_kenh.get("ui_lang") or "")),
    )
    try:
        _CONTEXT_RUNTIME.record_runtime_event(runtime_trace, "lang.resolved", _lang_qd.as_trace())
    except Exception:
        pass

    async def _p(s):
        # Báo trạng thái trung gian về kênh (Telegram) cho user đỡ lo khi chờ. Bỏ qua nếu lỗi.
        if progress:
            try:
                await progress(s)
            except Exception:
                pass
    # Block kênh (port gateway hermes-agent): engine biết đang trả lời qua đâu, ai đang nhắn,
    # và cách gửi file trả về (auto-attach + endpoint send-file).
    # telegram_running phải theo kênh THẬT: bật cờ đó cho lượt CLI là dạy Javis một công thức
    # gửi file qua Telegram trong khi người hỏi đang ngồi ở terminal.
    # Bot chuyên trách KHÔNG dùng system prompt của Javis: prompt đó dạy cách điều phối, ghi
    # vault, giao việc - toàn thứ bot trả lời người ngoài không được làm. Nó dùng prompt của
    # chính Agent nó trỏ tới. Xem chatbot_runtime.build_bot_prompt.
    _bot_full = False   # bot mức Toàn quyền: chạy ĐÚNG đường engine của kênh admin (0.85.3)
    if bot:
        import chatbot_runtime
        # Prompt của bot KHÔNG kèm block kênh: block đó dạy cách tự gửi file qua Telegram và
        # nêu đường dẫn thư mục thật của brain - kiến thức vận hành, không phải thứ đưa cho
        # một con bot đang nói chuyện với người lạ.
        _sys_bot = chatbot_runtime.build_bot_prompt(bot)
        # Mức quyền đọc từ BẢN GHI, và giá trị lạ (file sửa tay, bản ghi cũ) rơi về Chỉ đọc.
        # Fail-closed là bắt buộc ở đây: đoán sai theo hướng kia là cấp tool cho một con bot
        # đang nói chuyện với người lạ.
        _muc = str((bot or {}).get("muc_quyen") or "").strip().lower()
        # Ảnh khách gửi ở lượt này (0.81.0), do chatbot_runtime gắn vào bản ghi bot của lượt.
        _anh = list((bot or {}).get("_anh") or [])
        # Toàn quyền = giống hệt kênh admin (chủ chốt 2026-10-07: "bot nếu có toàn quyền sẽ giống như
        # kênh admin"). Trước đó mức này vẫn đi đường hẹp của bot bên dưới, nên: Grok Build và
        # Antigravity không có nhánh nào (rơi vào lời gọi Anthropic API sai khoá, lượt nào cũng tụt về
        # chỉ chat), Claude Code chỉ thấy công cụ của hub và tắt hẳn kết nối claude.ai (Gmail, Drive,
        # lịch...), ChatGPT đi vòng tool tự dựng thay vì Codex CLI. Chủ bật Toàn quyền mà bot không
        # dùng nổi MCP nào anh vẫn dùng ở kênh admin.
        #
        # Nên mức này KHÔNG dừng ở đây: nó rơi xuống đúng các nhánh engine của chủ bên dưới (công cụ
        # gốc, MCP hub, kết nối của tài khoản Claude/ChatGPT, kỹ năng), chỉ khác hai chỗ: prompt mang
        # VAI của Agent, và brain là brain của bot. Đường tắt, nguồn chọn lọc và gateway huỷ lịch của
        # chủ bị bỏ qua vì chúng thay prompt bằng giọng Javis.
        if _muc == "full":
            _bot_full = True
            _sys_bot_full = _sys_bot
            if _anh:
                # Ảnh khách gửi: engine của chủ đọc ảnh bằng công cụ mở file (như ảnh chủ gửi qua
                # Telegram), nên đưa đường dẫn vào câu hỏi thay cho cổng ảnh riêng của bot.
                text = (str(text or "") + "\n" + "\n".join(
                    f"[Người nhắn gửi kèm ảnh, đã lưu tại: {a}]" for a in _anh)).strip()
                if prov not in _MO_ANH_BANG_CONG_CU:
                    # Engine API chỉ nhận chữ từ công cụ đọc file, Antigravity và Grok Build không chắc mở được ảnh:
                    # đưa luôn mô tả ảnh do bộ não khác xem hộ vào câu hỏi (0.94.0).
                    _mo_ta, _who, _ly_do = await _bot_xem_ho(_anh, text, prov, api_model, chat_id)
                    if _mo_ta:
                        text = borrowed_eyes.turn_text(text, _mo_ta, len(_anh))
        elif _muc in chatbot_store.MUC_CO_TOOL:
            return await _bot_tra_loi_co_tool(
                text, sess=sess, sysprompt=_sys_bot, prov=prov, api_key=api_key,
                api_model=api_model, reasoning=reasoning, progress=_p,
                runtime_trace=runtime_trace, brain=brain, chat_id=chat_id, muc_quyen=_muc, images=_anh)
        else:
            return await _bot_tra_loi(text, sess=sess, sysprompt=_sys_bot,
                                      prov=prov, api_key=api_key, api_model=api_model,
                                      reasoning=reasoning, progress=_p, runtime_trace=runtime_trace,
                                      brain=brain, chat_id=chat_id, images=_anh)
    # ===== Hệ Tiết kiệm cho kênh NGOÀI dashboard =====
    #
    # Tới 0.23.1, cả Tối ưu lẫn Siêu tiết kiệm chỉ được nối vào đúng handler WebSocket của
    # dashboard: mọi lệnh gọi prepare() ở đó truyền cứng chữ "dashboard", và khối này không
    # có một dòng nào chạm tới chúng. Hệ quả là người dùng bấm mức tiết kiệm ở trang Cài đặt,
    # trang báo xanh "đã bật", rồi mỗi lượt Telegram vẫn gửi nguyên CLAUDE.md + MEMORY.md.
    # Không lỗi, không cảnh báo - chỉ có hoá đơn token không giảm ở đúng kênh dùng nhiều nhất.
    #
    # Hai tầng nối ở đây, theo thứ tự rẻ dần:
    #   1. Đường tắt (Phase 5): câu không cần tra cứu thì gọi model MỘT vòng với capsule nhỏ.
    #   2. Nguồn chọn lọc (Phase 8): thay CLAUDE.md + MEMORY.md bằng prompt gọn hơn.
    #
    # Bot chuyên trách KHÔNG đi qua đây - nó thoát khỏi hàm này từ trên, và prompt của nó
    # (~20 token) vốn đã nhỏ hơn capsule của mức Siêu tiết kiệm (~460 token) hơn hai chục lần.
    # Phase 8 (mức Tối ưu): thay CLAUDE.md + MEMORY.md bằng nguồn chọn lọc. Gọi qua
    # `_get_adaptive_context()` chứ không kiểm biến global - biến đó dựng LƯỜI, còn None cho
    # tới lần gọi đầu tiên, nên kiểm nó là khối này không bao giờ chạy.
    #
    # Truyền [] làm lịch sử: `conversation_state_canary` cố ý KHÔNG mở cho kênh này, vì phiên
    # Telegram đã giữ mạch hội thoại riêng (sess["or"] cho engine API, session/thread cho hai
    # gói thuê bao). Đưa thêm transcript vào system prompt là gửi lịch sử HAI LẦN.
    sysprompt = ""

    # Project của phiên này (Telegram cũng gán project được, nên không loại trừ kênh nào).
    # Đọc MỘT lần: dùng cho cả nhánh Phase 8 lẫn nhánh prompt đầy đủ bên dưới.
    _pid = ""
    try:
        if store is not None and conv_sid:
            _pid = (store.get_session(conv_sid) or {}).get("project_id") or ""
    except Exception:
        _pid = ""

    def _nen_goc(include_memory: bool, include_skills: bool) -> str:
        # HƯỚNG DẪN project đi cả vào đường tiết kiệm; danh sách tài liệu thì không.
        # Hướng dẫn là hợp đồng hành xử ("luôn trả lời bằng tiếng Anh"), vài trăm ký tự, và bỏ
        # nó đi nghĩa là cùng một project cùng một câu hỏi mà lượt này tuân luật lượt kia
        # không - người dùng không có cách nào biết vì sao, chỉ thấy Javis bướng. Danh sách
        # tài liệu là dữ liệu tra cứu, bỏ thì cùng lắm model phải hỏi lại.
        _n = build_adaptive_source_prompt(
            brain, include_memory=include_memory, include_skills=include_skills, routing_overlays=kind == "api")
        if _pid:
            try:
                _n += _project_block(_pid, chi_huong_dan=True)
            except Exception:
                pass
        return _n

    if _bot_full:
        sysprompt = _bot_full_prompt(brain, _sys_bot_full, _lang_qd, conv_sid)
    elif agent:
        sysprompt = _cli_agent_prompt(brain, agent["slug"], conv_sid,
                                      channel=("telegram" if channel == "telegram" else "cli"))
    try:
        if _bot_full or agent:
            raise _BoQua()   # selected sources swap the prompt for Javis's voice: not for a bot or an agent
        _p8 = await asyncio.to_thread(
            _get_adaptive_context().prepare, runtime_trace, text, _brain_root(brain),
            str(conv_sid or chat_id), [], channel, prov,
            api_model or mcfg.get("claude_model") or "mặc định", kind, _nen_goc)
        if _p8.action == "use":
            sysprompt = _p8.system_prompt
    except _BoQua:
        pass
    except Exception as _e:
        _CONTEXT_RUNTIME.record_runtime_event(
            runtime_trace, "adaptive_context.prepare_error",
            {"error_type": type(_e).__name__, "channel": channel})
    # "reject" của Phase 8 KHÔNG được chặn lượt ở đây. Rơi về prompt đầy đủ là sai chiều trên
    # dashboard (bản đầy đủ còn TO HƠN cái vừa bị từ chối vì quá to), nhưng ở kênh này ta chưa
    # có đường nào khác để đi, nên cứ chạy tiếp và để nhà cung cấp nói nếu thật sự quá hạn mức.
    if not sysprompt:
        sysprompt = build_system_prompt(brain, lang=_lang_qd, project_id=_pid,
                                        session_id=conv_sid or "")
    if not _bot_full:
        # Khối kênh dạy cách tự gửi file qua Telegram của CHỦ và cách báo kết quả việc nền về chủ:
        # với bot thì người nhắn là người khác, nên bỏ.
        sysprompt += channel_context.build_channel_block(
            channel, meta, telegram_running=(channel == "telegram"), port=_javis_port(),
            brain_root=_brain_root(brain))
    if kind in ("cli", "oauth"):
        _schedule_registry_discovery_shadow(
            runtime_trace, brain, text,
            "codex" if prov == "openai-oauth" else "cli",
            api_model or mcfg.get("claude_model") or "mặc định", kind,
        )
    # The plain-words schedule cancel gateway is the owner's shortcut; a full-access bot and an agent
    # turn still cancel through the javis_schedule tool. The shortcut answers in Javis's voice, not
    # in the agent's role.
    schedule_action = None if (_bot_full or agent) else await _schedule_cancel_action(text, brain)
    if schedule_action:
        for call in schedule_action.get("calls") or []:
            await _p(f"⚙ Lịch: {call.split(':')[-1]}")
        # dict (không phải chuỗi): đây là câu trả lời THẬT nên vỏ phải lưu nó lại.
        return {"text": channel_context.strip_control_blocks(_schedule_cancel_reply(schedule_action)),
                "files": []}

    if _FAST_PATH is not None and not _bot_full and not agent and not _project_has_rules(_pid):
        try:
            _fp = await asyncio.to_thread(
                _FAST_PATH.prepare, runtime_trace, text, _brain_root(brain), channel, prov,
                api_model or mcfg.get("claude_model") or "mặc định", kind, False,
                _lang_qd.lang_cau_hoi, _lang_qd.lang)
        except Exception as _e:
            _fp = None
            _CONTEXT_RUNTIME.record_runtime_event(
                runtime_trace, "fast_path.prepare_error",
                {"error_type": type(_e).__name__, "channel": channel})
        # CHỈ nhận "execute". "reject" của đường tắt dựa trên trần TỰ KHAI, không phải hạn mức
        # nhà cung cấp nói ra - lấy nó chặn lượt chat là vượt quyền (cùng lý do với dashboard).
        if _fp is not None and _fp.action == "execute":
            steer_inbox.INBOX.set_live(steer_inbox.current_sid(), False)   # 0.213.0: one model call, no step to read at
            await _p("⚡ Đường tắt…")
            _txt, _mdl, _ = await _fast_path_core(
                _fp, prov, api_key, api_model or mcfg.get("claude_model") or "mặc định",
                reasoning, runtime_trace, text, im_lang_khi_loi=True, channel=channel)
            # Rỗng = đường tắt hụt (token gói thuê bao hết hạn, model không trả gì). Rơi
            # xuống engine đầy đủ bên dưới, người dùng vẫn có câu trả lời.
            if _txt.strip():
                return {"text": channel_context.strip_control_blocks(_txt), "files": []}

    if prov in ("grok-cli", "antigravity-cli") or (prov == "openai-oauth" and not codex_steer.enabled()):
        # 0.213.0: one-shot engines take nothing mid-turn; what the owner sends meanwhile runs as the next turn.
        steer_inbox.INBOX.set_live(steer_inbox.current_sid(), False)
    if prov == "grok-cli":
        # Cùng engine với dashboard: Grok Build CLI + tool native + MCP hub, chỉ khác chỗ giữ
        # mạch. Phiên Telegram giữ luôn object engine trong `sess` (như Codex), nên mạch hội
        # thoại nối tiếp qua các tin nhắn mà không phải đụng SQLite.
        actual_model = api_model or None
        kcli = sess.get("grok")
        if kcli is None:
            kcli = grok_cli.GrokCLI(cwd=_brain_root(brain), model=actual_model,
                                    tag=f"telegram:{chat_id}", instructions=sysprompt)
            sess["grok"] = kcli
        else:
            kcli.cwd = _brain_root(brain)
            kcli.model = actual_model
            kcli.instructions = sysprompt
        kcli.mode = "full"
        _apply_grok_hub(kcli, _brain_root(brain))
        _plan_account_apply(kcli, "grok-cli")   # 0.353.0: the Grok account that should run now
        if not kcli.is_available():
            return ("⚠ Chưa cài Grok Build CLI trên máy chạy Javis. Cài một lần:\n"
                    f"`{grok_cli.lenh_cai()}`\n"
                    "Rồi đăng nhập ở thẻ Grok trên trang Models.")
        _hoi = text
        if not getattr(kcli, "session_id", None):
            # Chưa có mạch native (phiên mới, hoặc vừa restart nên object engine dựng lại từ
            # đầu) thì mồi transcript đã lưu vào ĐÚNG MỘT lượt, y như dashboard vẫn làm. Có mạch
            # rồi thì engine tự nhớ, gửi lại là tốn token vô ích.
            _raw_cu, _tom_cu = _tg_lich_su_kho(store, conv_sid, text)
            _hoi = compaction.bootstrap_prompt(_raw_cu, _hoi, summary=_tom_cu)
        out, loi = "", []
        async for ev in kcli.query(_hoi):
            et = ev.get("type")
            if et == "tool_call":
                await _p(f"⚙ Đang gọi: {ev.get('name', '')}")
            elif et == "final":
                out = ev.get("content") or ""
            elif et == "error":
                loi.append(str(ev.get("content") or ""))
        if not out and loi:
            _noi = _subscription_limit_message(loi[0], "grok-cli")
            return _noi or ("⚠ Grok Build CLI lỗi: " + loi[0][:400])
        # Câu trả lời THẬT phải là dict (quy ước ở `_tg_answer`: chuỗi = thông báo lỗi). Trước 0.85.3
        # nhánh này trả chuỗi, nên mọi câu trả lời qua Telegram/Zalo/Slack... bằng bộ não này bị lưu
        # như một câu lỗi: không vào nhật ký bộ nhớ, không vào vòng tự học.
        if not out:
            return "(không có nội dung)"
        return {"text": channel_context.strip_control_blocks(out), "files": []}

    if prov == "antigravity-cli":
        # Cùng khuôn nhánh Grok Build ngay trên: giữ object engine trong `sess` để mạch hội
        # thoại nối tiếp qua các tin nhắn mà không phải đụng SQLite.
        actual_model = api_model or None
        acli = sess.get("antigravity")
        if acli is None:
            acli = antigravity_cli.AntigravityCLI(cwd=_brain_root(brain), model=actual_model,
                                                  tag=f"telegram:{chat_id}",
                                                  instructions=sysprompt)
            sess["antigravity"] = acli
        else:
            acli.cwd = _brain_root(brain)
            acli.model = actual_model
            acli.instructions = sysprompt
        acli.mode = "full"
        _apply_antigravity_hub(acli, _brain_root(brain))
        if not acli.is_available():
            return ("⚠ Chưa cài Antigravity CLI trên máy chạy Javis. Cài một lần:\n"
                    f"`{antigravity_cli.lenh_cai()}`\n"
                    "Rồi gõ `agy` một lần để đăng nhập Google.")
        _hoi = text
        if not getattr(acli, "session_id", None):
            # Chưa có mạch native (phiên mới, hoặc vừa restart nên object engine dựng lại từ
            # đầu) thì mồi transcript đã lưu vào ĐÚNG MỘT lượt, y như dashboard vẫn làm. Có mạch
            # rồi thì engine tự nhớ, gửi lại là tốn token vô ích.
            _raw_cu, _tom_cu = _tg_lich_su_kho(store, conv_sid, text)
            _hoi = compaction.bootstrap_prompt(_raw_cu, _hoi, summary=_tom_cu)
        out, loi = "", []
        async for ev in acli.query(_hoi):
            et = ev.get("type")
            if et == "tool_call":
                await _p(f"⚙ Đang gọi: {ev.get('name', '')}")
            elif et == "final":
                out = ev.get("content") or ""
            elif et == "error":
                loi.append(str(ev.get("content") or ""))
        if not out and loi:
            _noi = _subscription_limit_message(loi[0], "antigravity-cli")
            return _noi or ("⚠ Antigravity CLI lỗi: " + loi[0][:400])
        # Câu trả lời THẬT phải là dict (quy ước ở `_tg_answer`: chuỗi = thông báo lỗi). Trước 0.85.3
        # nhánh này trả chuỗi, nên mọi câu trả lời qua Telegram/Zalo/Slack... bằng bộ não này bị lưu
        # như một câu lỗi: không vào nhật ký bộ nhớ, không vào vòng tự học.
        if not out:
            return "(không có nội dung)"
        return {"text": channel_context.strip_control_blocks(out), "files": []}

    if prov == "openai-oauth":
        # Telegram dùng cùng Codex CLI + MCP native như dashboard. Trước đây nhánh OAuth
        # rơi vào Responses chat-thuần nên model nói đúng là phiên không có tool.
        actual_model = _codex_safe_model(api_model)
        canh_bao = ""
        if api_model and actual_model != api_model:
            # Tự chữa như dashboard: ghi lại model đúng để lượt sau khỏi ép lại nữa, VÀ nói cho
            # user biết. Trước đây Telegram lặng lẽ đổi, user cứ tưởng đang chạy model mình chọn.
            # NOT for a dedicated bot (0.102.1): its model is the Agent's, and writing the owner's MAIN
            # model because a customer bot's Agent named a stale model changed the owner's own brain.
            # Nor for an agent turn (POST /chat with `agent`): same reason, the stale model is the agent's.
            if not _bot_full and not agent:
                try:
                    _fix = cfgmod.read_settings()
                    _set_main_model(_fix, "openai-oauth", actual_model)
                    cfgmod.write_settings(_fix)
                except Exception as _e:
                    print(f"[codex model self-heal] {_e}", file=__import__('sys').stderr)
            if agent:
                # The main model was not touched, so pointing at the Models page would be wrong: the
                # model to change is the one in the agent's settings.
                canh_bao = localefmt.chu(
                    f"⚠ Model '{api_model}' của agent '{agent['slug']}' không chạy được qua Codex (tài khoản "
                    f"ChatGPT) - lượt này dùng '{actual_model or 'mặc định của Codex'}'. Đổi model trong cài đặt "
                    f"của agent để hết thông báo này.",
                    f"⚠ Model '{api_model}' of agent '{agent['slug']}' does not run through Codex (ChatGPT "
                    f"account) - this turn fell back to '{actual_model or 'the Codex default'}'. Change the model "
                    f"in the agent's settings to stop this notice.") + "\n\n"
            else:
                canh_bao = localefmt.chu(
                    f"⚠ Model '{api_model}' không chạy được qua Codex (tài khoản ChatGPT) - "
                    f"đã tự đổi sang '{actual_model}'. Đổi model khác ở trang Models nếu muốn.",
                    f"⚠ Model '{api_model}' does not run through Codex (ChatGPT account) - switched to "
                    f"'{actual_model}' automatically. Pick another model on the Models page if you like.") + "\n\n"
        openai_oauth.write_codex_auth()
        ccli = sess.get("codex")
        if ccli is None:
            ccli = CodexCLI(
                cwd=_brain_root(brain),
                model=actual_model,
                tag=f"telegram:{chat_id}",
                instructions=sysprompt,
            )
            sess["codex"] = ccli
        else:
            ccli.cwd = _brain_root(brain)
            ccli.model = actual_model
            ccli.instructions = sysprompt
        _apply_codex_hub(ccli, _brain_root(brain))
        _plan_account_apply(ccli, "openai-oauth")   # 0.353.0: the ChatGPT account that should run now
        ccli.steer = True   # 0.213.0: a channel turn takes messages mid-way when its gateway opened an inbox (codex_steer.py)
        if not ccli.is_available():
            return "⚠ Chưa cài Codex CLI trong container nên ChatGPT chưa dùng được tool."
        t0 = time.time()
        out = ""
        loi = []
        written = []   # đường dẫn moi từ payload tool call (xem candidate_paths_from_tool)

        async def _nuot_codex(prompt, bo_qua_loi_resume=False):
            """Tiêu thụ một lượt Codex. Trả về: lượt này có chết vì resume hỏng không."""
            nonlocal out
            resume_hong = False
            _CONTEXT_RUNTIME.observe_payload(
                runtime_trace,
                [{"role": "system", "content": sysprompt},
                 {"role": "user", "content": prompt}],
                provider="codex", model=actual_model,
            )
            async for ev in ccli.query(prompt):
                et = ev.get("type")
                if et in ("tool_call", "item"):
                    if et == "tool_call":
                        await _p(f"⚙ Đang gọi: {ev.get('name', '')}")
                    # Codex KHÔNG phát file_path có cấu trúc như Claude nên phải moi từ payload,
                    # nếu không thì file nó ghi ra chỉ được gửi kèm khi tình cờ được nhắc tên.
                    # 'item' = item lạ (vd bản vá file) - không in ra nhưng vẫn moi đường dẫn.
                    try:
                        written.extend(channel_context.candidate_paths_from_tool(ev.get("item")))
                    except Exception:
                        pass
                elif et == "text":
                    out += ev.get("content") or ""
                    await _p("✍ Đang soạn câu trả lời…")
                elif et == "retry":
                    await _p("↻ " + claude_cli.cau_ket_noi_lai(ev.get("content")))
                elif et == "final":
                    out = ev.get("content") or out
                    usage_store.record(
                        "codex", actual_model,
                        ev.get("tokens_in", 0), ev.get("tokens_out", 0),
                    )
                    _CONTEXT_RUNTIME.record_usage(
                        runtime_trace, ev.get("tokens_in", 0), ev.get("tokens_out", 0))
                elif et == "error":
                    if ev.get("resume_failed"):
                        resume_hong = True
                        if bo_qua_loi_resume:
                            continue    # còn cửa dựng lại, chưa phải lúc kêu lỗi với user
                    loi.append(str(ev.get("content") or "Codex lỗi"))
                    _CONTEXT_RUNTIME.note_error(runtime_trace, "codex_error_event")
            return resume_hong

        # Lịch sử để dựng lại thread khi cần. Bỏ lượt cuối NẾU nó đúng là câu đang hỏi, chứ
        # không cắt cứng phần tử cuối: vỏ chung có chế độ không ghi câu hỏi vào kho
        # (`ghi_kho=False`, việc nền của giọng), và khi đó cắt bừa là ăn mất một tin thật.
        # Cùng cách so khớp với `_tg_lich_su_kho`.
        _raw = []
        if store is not None and conv_sid:
            try:
                _raw = [{"role": m["role"], "content": m["content"]}
                        for m in store.get_messages(conv_sid)
                        if m.get("role") in ("user", "assistant") and m.get("content")]
                if _raw and _raw[-1]["role"] == "user" and _raw[-1]["content"] == text:
                    _raw.pop()
            except Exception:
                _raw = []
        _hien_tai = _codex_do_sau(ccli, reasoning, text)
        _codex_fast(ccli)
        thread_cu = (getattr(ccli, "session_id", None) or "")
        # Chưa có thread (phiên mới, hoặc vừa bị xoá liên kết vì provider khác chen vào) thì
        # seed transcript đúng một lượt; có thread rồi thì resume native, khỏi gửi lại lịch sử.
        _resume_hong = await _nuot_codex(
            _hien_tai if thread_cu else compaction.codex_bootstrap_prompt(_raw, _hien_tai),
            bo_qua_loi_resume=bool(thread_cu))
        if thread_cu and _resume_hong and not out:
            # Rollout local có thể bị dọn/mất sau nâng cấp máy. Trước đây Telegram bỏ luôn lượt
            # và mất sạch ngữ cảnh; dashboard thì dựng lại. Giờ Telegram cũng có kho phiên nên
            # dựng lại được y hệt: thread mới từ transcript đã lưu, các lượt sau resume nó.
            await _p("Phiên Codex cũ không còn trên máy - đang khôi phục ngữ cảnh từ lịch sử đã lưu.")
            ccli.session_id = None
            loi.clear()
            await _nuot_codex(compaction.codex_bootstrap_prompt(_raw, _hien_tai))
        if not out:
            return "⚠ " + (loi[0] if loi else "Codex không trả về nội dung nào.")
        files = channel_context.collect_turn_files(
            out, written, t0, cwd=_brain_root(brain), exclude=sess["sent"],
            vault_root=_brain_root(brain),
        )
        clean_out = channel_context.strip_attached_media(
            channel_context.strip_control_blocks(out), files, _brain_root(brain)
        )
        return _tg_ket(clean_out, files, canh_bao, loi, khach=_bot_full)
    if (kind == "api" and api_key) or kind == "oauth":
        label = _api_label(prov)
        ident = (f"\n\n[Sự thật hệ thống: bạn chạy qua {label}, model '{api_model}'. "
                 f"Hỏi model nào thì khai đúng tên này, KHÔNG nhận là model khác.]")
        if sess["or"] and sess["or"][0].get("role") == "system":
            # Refresh the head every turn, as the CLI engines get `sysprompt` every turn. Built once
            # per RAM session, it froze the prompt of the first turn: a project attached to the
            # conversation afterwards (dashboard, `project` on /chat, carried over by a rotation)
            # never reached an API engine on Telegram or the CLI until the server restarted.
            sess["or"][0] = {"role": "system", "content": sysprompt + ident}
        if sess["or"] is None:
            sess["or"] = [{"role": "system", "content": sysprompt + ident}]
            # Lịch sử này chỉ sống trong RAM, nên restart là mất. Dựng lại từ transcript đã
            # lưu (xem `_tg_lich_su_kho`) - đây là nửa THẬT SỰ quan trọng với người dùng chạy
            # engine API: nối lại được id phiên mà lịch sử vẫn rỗng thì Javis vẫn quên sạch.
            #
            # Chỉ chạy khi `sess["or"]` rỗng, tức phiên vừa dựng: đang chat liên tục thì khối
            # này không đụng tới. /reset và đổi brain xoá cả sid lẫn liên kết bền nên
            # `conv_sid` khi đó là phiên mới tinh, mồi lại ra rỗng - đúng ý người dùng.
            _cu, _tom = _tg_lich_su_kho(store, conv_sid, text)
            if _tom:
                sess["or"].append({"role": "system", "content": compaction.SUMMARY_HEADER + _tom})
            sess["or"] += _cu[-_TG_MOI_LAI_MAX:]
        sess["or"].append({"role": "user", "content": text})
        t0 = time.time()
        out = ""
        actual_model = api_model or "?"
        loi = []
        _pinged = False
        # 0.259.0: Telegram của CHỦ có cùng hộp công cụ như dashboard (thư mục làm việc, terminal,
        # mốc khôi phục). Bot mức Toàn quyền cũng đi đường này nhưng KHÔNG nhận: terminal không
        # bao giờ thuộc về người lạ nhắn tới bot.
        _chu_tg = not bot
        async for ev in (await _api_stream_mcp(
                prov, api_key, api_model, sess["or"], reasoning, brain=brain,
                mode=_muc_quyen_luot_chat(None, text) if _chu_tg else "full",
                owner_sid=(str(conv_sid or f"{channel}-{chat_id}") if _chu_tg else ""),
                owner_chat=(str(chat_id) if _chu_tg and channel == "telegram" else ""))):
            if ev["type"] == "text":
                if not _pinged:
                    _pinged = True; await _p("✍ Đang soạn câu trả lời…")
                out += ev["content"]
            elif ev["type"] == "meta":
                actual_model = ev.get("model") or actual_model   # model THẬT (OpenRouter tính tiền theo cái này)
                _CONTEXT_RUNTIME.set_route(runtime_trace, prov, actual_model)
            elif ev["type"] == "usage":
                # Thiếu dòng này tới 0.9.244: mọi lượt Telegram không đi qua Codex đều không
                # được tính vào bảng Mức dùng.
                usage_store.record(prov, actual_model, ev.get("input", 0), ev.get("output", 0))
                _CONTEXT_RUNTIME.record_usage(
                    runtime_trace, ev.get("input", 0), ev.get("output", 0))
            elif ev["type"] == "tool_call":
                await _p(f"⚙ Đang gọi công cụ: {ev.get('name', '')}")
            elif ev["type"] == "error":
                # KHÔNG return ngay: một tool hỏng giữa chừng không có nghĩa là cả lượt hỏng,
                # luồng thường chạy tiếp và vẫn ra câu trả lời. Dashboard vốn xử lý như vậy.
                loi.append(str(ev.get("content") or "lỗi không rõ"))
                _CONTEXT_RUNTIME.note_error(runtime_trace, "api_error_event")
        if not out:
            return "⚠ " + (loi[0] if loi else "Không nhận được nội dung nào.")
        sess["or"].append({"role": "assistant", "content": out})
        # Nén (KHÔNG cắt câm) phần cũ rơi khỏi cửa sổ, chạy NỀN. Phiên Telegram giữ lịch sử
        # in-memory nên dùng compact_mem - bản in-memory của cơ chế nén dashboard: phần cũ vào
        # tóm tắt thay vì bị trim cứng bỏ mất. Chạy nền vì đây là một request LLM nữa; await
        # thẳng ở đây là bắt user ngồi chờ tóm tắt xong mới thấy câu trả lời của chính mình.
        _tg_compact_bg(sess, prov, api_key, api_model)
        # MCP đa-model có thể tạo ảnh/file dù engine không có tool Write native. Thu đường dẫn
        # Markdown giống nhánh Codex/Claude để OpenRouter cũng gửi media thật qua Telegram.
        files = channel_context.collect_turn_files(
            out, [], t0, cwd=_brain_root(brain), exclude=sess["sent"],
            vault_root=_brain_root(brain),
        )
        clean_out = channel_context.strip_attached_media(
            channel_context.strip_control_blocks(out), files, _brain_root(brain)
        )
        return _tg_ket(clean_out, files, "", loi, khach=_bot_full)
    else:
        _goc = _brain_root(brain)
        if sess["cli"] is None or getattr(sess["cli"], "cwd", None) != _goc:
            # tag riêng theo chat → /stop chỉ giết đúng subprocess của chat này, không đụng người khác.
            # cwd = thư mục brain (0.55.58, cùng lý do với nhánh dashboard). Đổi brain bằng /brain
            # thì `_tg_ngat_mach` chỉ cắt mạch mà giữ đối tượng engine, nên phải dựng lại ở đây
            # khi cwd không còn khớp brain - không thì lượt sau vẫn ghi file vào brain cũ.
            sess["cli"] = claude_engine(system_prompt=sysprompt, cwd=_goc, tag=f"telegram:{chat_id}")
        cli = sess["cli"]
        cli.system_prompt = sysprompt
        # Cùng luật với nhánh CLI của web: tên model nhà khác không đưa cho `claude`.
        cli.model = ((api_model if prov == "anthropic-cli" else "")
                     or mcfg.get("claude_model") or None)
        _apply_mcp(cli, brain=brain)
        _plan_account_apply(cli, "anthropic-cli", mcfg)   # 0.353.0: the Claude account that should run now
        t0 = time.time()
        written = []   # file agent ghi bằng tool Write trong lượt này (ứng viên auto-gửi)
        out = ""
        _streamed = ""   # phần đã stream - phương án dự phòng khi luồng đứt trước 'final'
        loi = []
        _pinged = False
        _cli_prompt = _gio_luot_noi_mach(cli, _cli_do_sau(cli, reasoning, text))
        _cli_fast(cli)
        if not getattr(cli, "session_id", None):
            # Chưa có mạch native (phiên mới, hoặc vừa restart nên object engine dựng lại từ
            # đầu) thì mồi transcript đã lưu vào ĐÚNG MỘT lượt, y như dashboard vẫn làm. Có mạch
            # rồi thì engine tự nhớ, gửi lại là tốn token vô ích.
            _raw_cu, _tom_cu = _tg_lich_su_kho(store, conv_sid, text)
            _cli_prompt = compaction.bootstrap_prompt(_raw_cu, _cli_prompt, summary=_tom_cu)
        _CONTEXT_RUNTIME.observe_payload(
            runtime_trace,
            [{"role": "system", "content": sysprompt},
             {"role": "user", "content": _cli_prompt}],
            provider="cli", model=cli.model or mcfg.get("claude_model") or "mặc định",
        )
        async def _chay_claude(prompt):
            """Một lần gọi `claude`. Trả True nếu mạch cũ không còn (resume trượt)."""
            nonlocal out, _streamed, _pinged
            resume_failed = False
            async for ev in cli.query(prompt):
                et = ev["type"]
                if et == "final":
                    out = ev.get("content") or out
                    # Thiếu dòng này tới 0.9.244 (xem nhánh API ngay trên): lượt Telegram qua
                    # Claude Code không được tính vào bảng Mức dùng.
                    usage_store.record("cli", cli.model or mcfg.get("claude_model") or "mặc định",
                                       ev.get("tokens_in", 0), ev.get("tokens_out", 0),
                                       ev.get("cost_usd") or 0)
                    _CONTEXT_RUNTIME.record_usage(
                        runtime_trace, ev.get("tokens_in", 0), ev.get("tokens_out", 0))
                elif et == "tool_call":
                    nm = ev.get("name", "")
                    if nm in ("Write", "NotebookEdit"):
                        fp = (ev.get("input") or {}).get("file_path") or (ev.get("input") or {}).get("notebook_path")
                        if fp:
                            written.append(str(fp))
                    # Nhặt rộng cả đường dẫn lẫn trong lệnh Bash; tầng sau lọc "có thật + vừa đổi".
                    try:
                        written.extend(channel_context.candidate_paths_from_tool(ev.get("input") or {}))
                    except Exception:
                        pass
                    await _p(f"⚙ Đang gọi: {nm}")
                elif et == "tool_result":
                    await _p("✓ Nhận kết quả - đang phân tích…")
                elif et == "text":
                    _streamed += ev.get("content") or ""
                    if not _pinged:
                        _pinged = True; await _p("✍ Đang soạn câu trả lời…")
                elif et == "error":
                    if ev.get("resume_failed"):
                        resume_failed = True      # mồi lại ngay dưới, không tính là lỗi của lượt
                        continue
                    # Xem nhánh API: lỗi giữa lượt không chí mạng, cứ chạy tiếp rồi báo ở cuối.
                    loi.append(str(ev.get("content") or "lỗi không rõ"))
                    _CONTEXT_RUNTIME.note_error(runtime_trace, "cli_error_event")
            return resume_failed

        _co_mach = bool(getattr(cli, "session_id", None))
        _rf = await _chay_claude(_cli_prompt)
        if _co_mach and _rf and not (out or _streamed):
            # Mạch cũ không còn (đổi thư mục làm việc ở 0.55.58, hoặc transcript bị dọn): mồi lại
            # từ kho phiên rồi chạy lại - cùng cách nhánh dashboard và Codex.
            await _p("↻ Phiên Claude cũ không còn trên máy - đang khôi phục ngữ cảnh từ lịch sử đã lưu…")
            cli.session_id = None
            _raw_cu2, _tom_cu2 = _tg_lich_su_kho(store, conv_sid, text)
            await _chay_claude(compaction.bootstrap_prompt(_raw_cu2, _cli_prompt, summary=_tom_cu2))
        out = out or _streamed
        if not out:
            return "⚠ " + (loi[0] if loi else "Engine không trả về nội dung nào.")
        # Link file → dạng khung chat/Telegram mở được, ưu tiên file vừa ghi trong lượt này.
        try:
            out = _chuan_hoa_link_file(_brain_root(brain), out,
                                       _files_vua_ghi(_brain_root(brain), written, t0))
        except Exception as _e:
            print(f"[link file telegram] {type(_e).__name__}: {_e}", file=sys.stderr)
        # File sinh ra trong lượt → bot gửi đính kèm SAU câu trả lời (xem telegram_bot._handle_turn).
        # vault_root = brain phiên này: ảnh Javis tạo nhúng dạng ![](attachments/x.png) (path tương
        # đối) được resolve về gốc vault để tự đính kèm về ĐÚNG người đang chat, khỏi phải curl.
        files = channel_context.collect_turn_files(out, written, t0,
                                                   cwd=_brain_root(brain), exclude=sess["sent"],
                                                   vault_root=_brain_root(brain))
        # Lọc SAU collect_turn_files: hàm đó dò đường dẫn file trong text gốc, lọc trước là mất dấu.
        clean_out = channel_context.strip_attached_media(
            channel_context.strip_control_blocks(out), files, _brain_root(brain)
        )
        return _tg_ket(clean_out, files, "", loi, khach=_bot_full)


