def _tg_brain_header(chat_key):
    cur = brain_label.display(_brain_root(_tg_brain(chat_key)))
    return ("🧠 Brain của phiên này: " + cur + "\n"
            "Chọn brain khác (chỉ đổi cho phiên CỦA BẠN, người khác và dashboard không đổi):")


def _tg_brain_kb(brains, chat_key):
    try:
        cur = str(Path(_brain_root(_tg_brain(chat_key))).resolve())
    except Exception:
        cur = ""
    rows = []
    for i, b in enumerate(brains[:20]):   # Telegram giới hạn nút; >20 brain thì gõ /brain <tên>
        try:
            mark = "✓ " if str(Path(b["path"]).resolve()) == cur else ""
        except Exception:
            mark = ""
        rows.append([{"text": f"{mark}{b.get('label') or b['name']} · {b.get('notes', 0)} note",
                      "callback_data": f"bs:{i}"}])
    rows.append([{"text": "✕ Đóng", "callback_data": "bx"}])
    return {"inline_keyboard": rows}


async def _tg_callback(data, chat=None):
    """Xử lý khi user bấm nút inline. Trả {'text','reply_markup','alert'} hoặc None.
    chat = chat_id người bấm → nút brain chỉ đổi cho PHIÊN của họ (model vẫn đổi toàn cục)."""
    data = data or ""
    chat_key = str(chat or "default")
    if data == "mx":
        return {"text": "Đã đóng bảng chọn model.", "alert": "Đã đóng"}
    # ---- nút chọn brain (bs:<idx> | bx) - tác động PHIÊN của người bấm ----
    if data == "bx":
        return {"text": "Đã đóng bảng chọn brain.", "alert": "Đã đóng"}
    if data.startswith("bs:"):
        try:
            i = int(data.split(":", 1)[1])
        except ValueError:
            return {"alert": "Dữ liệu nút lỗi"}
        d = await asyncio.to_thread(_list_brains_sync); brains = d.get("brains") or []
        if i < 0 or i >= len(brains):
            return {"alert": "Danh sách brain đã đổi - gõ /brain lại"}
        hit = brains[i]
        _tg_set_brain(chat_key, hit["path"])
        return {"text": f"🧠 Đã chuyển phiên này sang brain: {hit.get('label') or hit['name']}\n"
                        "(hội thoại reset để nạp đúng bộ nhớ/skill của brain mới)",
                "alert": "Đã đổi brain"}
    if data == "noop":
        return None   # nút chỉ-hiển-thị (số trang) - answer callback cho tắt spinner, không sửa tin
    if data in ("mp:back", "model"):
        return {"text": _model_header(chat_key), "reply_markup": await _model_provider_kb()}
    if data.startswith("mp:"):
        pid = data.split(":", 1)[1]
        if pid not in dict(_tg_providers()):
            return {"alert": "Provider không hợp lệ - gõ /model lại"}
        if not _tg_prov_ready(pid, cfgmod.read_settings().get("model", {})):
            return {"alert": f"{_tg_prov_label(pid)} chưa kết nối - vào dashboard trang Models"}
        await _tg_models_for(pid)   # nạp danh sách mới nhất trước khi vẽ trang 1
        return {"text": _tg_model_list_text(pid), "reply_markup": _model_list_kb(pid, 0)}
    if data.startswith("ml:"):
        # lật trang danh sách model
        try:
            _, pid, pg = data.split(":")
            page = int(pg)
        except ValueError:
            return {"alert": "Dữ liệu nút lỗi"}
        if pid not in _TG_MODEL_LISTS:
            await _tg_models_for(pid)   # server vừa restart → nạp lại rồi vẽ tiếp
        return {"text": _tg_model_list_text(pid), "reply_markup": _model_list_kb(pid, page)}
    if data.startswith("ms:"):
        try:
            _, pid, idx = data.split(":")
            i = int(idx)
        except ValueError:
            return {"alert": "Dữ liệu nút lỗi"}
        ids = _TG_MODEL_LISTS.get(pid) or []
        if i < 0 or i >= len(ids):
            return {"alert": "Danh sách đã đổi - gõ /model lại"}
        mdl = ids[i]
        s = cfgmod.read_settings(); m = s["model"]
        if not _tg_prov_ready(pid, m):
            return {"alert": f"{_tg_prov_label(pid)} chưa kết nối - vào dashboard trang Models"}
        if pid == "anthropic-cli":
            mdl = mdl.lower()   # alias opus/sonnet/haiku/fable
        _tg_dat_model(s, pid, mdl, chat_key); cfgmod.write_settings(s)
        note = {"anthropic-cli": "Claude Code - đầy đủ MCP/skill",
                "openai-oauth": "ChatGPT qua Codex CLI - có MCP",
                "openrouter": "OpenRouter - chat + MCP đa-model",
                "anthropic-api": "Claude API - chat + MCP đa-model",
                "openai": "OpenAI API - chat + MCP đa-model"}.get(pid, pid)
        return {"text": f"✅ {note}\nModel: {mdl}", "alert": "Đã đổi model"}
    return None


async def _tg_command(cmd, arg, chat=None, meta=None):
    """Xử lý lệnh Telegram cho 1 chat. Trả {'reply':...} hoặc {'ask':...} hoặc None.
    chat = chat_id của người gõ lệnh → reset/stop/retry/brain chỉ tác động PHIÊN của họ."""
    chat_key = str(chat or "default")
    brain = _tg_brain(chat_key)   # brain riêng của phiên (đổi bằng /brain)
    if cmd == "stop":
        # Chỉ giết subprocess Claude của CHÍNH chat này (tag telegram:<chat>), không đụng người khác.
        cancel_all(f"telegram:{chat_key}")
        return {"reply": "⏹ Đã dừng lệnh đang chạy."}
    if cmd in ("reset", "new", "clear"):
        # `_tg_session` chứ không `_TG_SESS.get`: sau restart phiên RAM chưa tồn tại nhưng liên
        # kết BỀN chat -> sid thì còn, và /reset phải cắt được đúng cái đó. Tạo phiên rỗng ở đây
        # không tốn gì - lượt kế cũng tạo.
        sess = _tg_session(chat_key)
        # Cắt mạch của CẢ BỐN engine. Trước đây chỉ Claude Code được reset và Codex bị vứt đối
        # tượng, còn Grok/Antigravity giữ nguyên mạch native - /reset xong Javis vẫn nhớ y
        # nguyên, đúng thứ người dùng gõ lệnh này để thoát khỏi.
        _tg_ngat_mach(sess)
        sess["or"] = None
        sess["last"] = None
        sess["sid"] = None     # hội thoại mới → phiên mới trong kho, khỏi nối vào mạch cũ
        _tg_quen_sid(sess)
        return {"reply": "🔄 Đã reset hội thoại (chỉ phiên của bạn)."}
    if cmd in ("cli", "claude"):
        s = cfgmod.read_settings()
        _tg_dat_model(s, "anthropic-cli", (s["model"].get("main") or {}).get("model") or s["model"].get("claude_model") or "opus", chat_key)
        cfgmod.write_settings(s)
        return {"reply": "✅ Provider: Anthropic (Claude Code) - đầy đủ MCP, hỏi POS/Ads/vault được."}
    if cmd in ("or", "openrouter"):
        s = cfgmod.read_settings()
        if not s["model"].get("openrouter_key"):
            return {"reply": "⚠ Chưa có OpenRouter key - đặt trong Models trên dashboard trước."}
        _tg_dat_model(s, "openrouter", s["model"].get("openrouter_model"), chat_key); cfgmod.write_settings(s)
        return {"reply": f"✅ Provider: OpenRouter ({s['model'].get('openrouter_model')}) - chat + MCP đa-model."}
    if cmd in ("help", "menu", "start"):
        return {"reply": await _tg_help_text(brain)}
    if cmd == "skills":
        return {"reply": await _tg_skills_text(brain)}
    if cmd == "status":
        prov, model, ghim = _tg_model_hieu_luc(chat_key)
        busy = _tg_chat_busy(chat_key)
        bname = brain_label.display(_brain_root(brain))
        return {"reply": ("📊 Trạng thái Javis\n"
                          f"Provider: {prov}\n"
                          f"Model: {model}"
                          + (localefmt.chu(" (📌 ghim riêng cho cuộc trò chuyện này)", " (📌 pinned to this chat)")
                             if ghim else localefmt.chu(" (theo model chính)", " (follows the main model)")) + "\n"
                          f"Brain: {bname} (đổi bằng /brain)\n"
                          f"Phiên: {chat_key} (ngữ cảnh riêng)\n"
                          f"Đang xử lý: {'có (gửi /stop để dừng)' if busy else 'rảnh'}")}
    if cmd == "model":
        s = cfgmod.read_settings(); m = s["model"]
        a = arg.strip()
        # 0.350.0: every pin belongs to THIS chat only. /model ghim: pin the model this chat runs now, so web changes no
        # longer move it. /model theo: drop the pin, this chat follows MAIN again.
        if a.lower() in ("ghim", "pin"):
            prov_now, model_now, _g = _tg_model_hieu_luc(chat_key)
            model_now = "" if model_now == "mặc định" else model_now
            _tg_dat_model(s, prov_now, model_now, chat_key); cfgmod.write_settings(s)
            return {"reply": localefmt.chu(
                f"📌 Đã ghim cuộc trò chuyện này vào {_tg_prov_label(prov_now)}: {model_now or 'mặc định'}.\n"
                "Đổi model trên web không còn kéo cuộc trò chuyện này theo. /model theo để bỏ ghim.",
                f"📌 This chat is pinned to {_tg_prov_label(prov_now)}: {model_now or 'default'}.\n"
                "Changing the model on the web no longer moves this chat. /model theo removes the pin.")}
        if a.lower() in ("theo", "bo-ghim", "unpin"):
            _tg_dat_model(s, "", "", chat_key)
            if (s["model"].get("telegram") or {}).get("provider"):
                s["model"]["telegram"] = {"provider": "", "model": ""}   # old shared pin (settings not yet moved)
            cfgmod.write_settings(s)
            em = _effective_main(s)
            return {"reply": localefmt.chu(
                f"🔗 Đã bỏ ghim. Cuộc trò chuyện này theo model chính: {_tg_prov_label(em['provider'])} {em['model'] or 'mặc định'}.",
                f"🔗 Pin removed. This chat follows the main model: {_tg_prov_label(em['provider'])} {em['model'] or 'default'}.")}
        if a:
            # HỎI DANH SÁCH THẬT TRƯỚC, đoán sau. Mấy luật đoán bên dưới ra đời khi Telegram chỉ
            # biết 3 provider, và giờ chúng gán nhầm một cách im lặng: gõ tên model của
            # Antigravity (vd `gemini-3-flash-high`) thì rơi vào nhánh cuối rồi bị đặt làm model
            # CLAUDE, lượt chat sau mới báo lỗi mà chẳng ai hiểu vì sao.
            _pid, _ung_vien = await _tg_provider_cho_model(a, m)
            if _pid:
                _tg_dat_model(s, _pid, a, chat_key); cfgmod.write_settings(s)
                return {"reply": f"✅ {_tg_prov_label(_pid)}: {a}."}
            if len(_ung_vien) > 1:
                _ten = ", ".join(_tg_prov_label(p) for p in _ung_vien)
                return {"reply": f"⚠ '{a}' có ở nhiều nhà cung cấp ({_ten}) nên không đoán "
                                 f"được ý bạn. Gõ /model rồi chọn bằng nút cho chắc."}
            # Không provider nào khai model này (danh sách hỏng, hoặc tên mới tinh) → về mấy
            # luật đoán cũ: id chứa "/" = OpenRouter; gpt*/*-codex = ChatGPT; còn lại = Claude.
            if "/" in a:
                _tg_dat_model(s, "openrouter", a, chat_key); cfgmod.write_settings(s)
                return {"reply": f"✅ OpenRouter model: {a}."}
            if _is_codex_model(a):
                if not _tg_prov_ready("openai-oauth", m):
                    return {"reply": "⚠ Chưa kết nối ChatGPT (OpenAI OAuth) - nối ở dashboard trang Models trước."}
                _tg_dat_model(s, "openai-oauth", a, chat_key); cfgmod.write_settings(s)
                return {"reply": f"✅ ChatGPT (Codex) model: {a}."}
            _tg_dat_model(s, "anthropic-cli", a.lower(), chat_key); cfgmod.write_settings(s)
            return {"reply": f"✅ Model Claude: {a.lower()}. Nếu CLI chưa hỗ trợ tên này, query sẽ báo lỗi."}
        # Không tham số → mở menu nút bấm (chọn provider → chọn model, phân trang)
        return {"reply": _model_header(chat_key), "reply_markup": await _model_provider_kb()}
    if cmd == "usage":
        try:
            _or = await _openrouter_credits(cfgmod.read_settings().get("model", {}) or {})
        except Exception:
            _or = None    # số dư là phần thêm: hỏng thì vẫn in số Javis tự đo
        return {"reply": lenh_he_thong.dinh_dang_muc_dung(usage_store.summary(), _or)}
    if cmd in ("tasks", "viec"):
        try:
            _view = await asyncio.to_thread(tasks_feature.board_view, brain)
        except Exception as _e:
            return {"reply": f"⚠ Không đọc được bảng việc: {type(_e).__name__}."}
        return {"reply": lenh_he_thong.dinh_dang_viec(_view)}
    if cmd == "memory":
        _bn = await asyncio.to_thread(_doc_muc_luc_bo_nho, brain, 3000)
        return {"reply": lenh_he_thong.dinh_dang_bo_nho(_bn["text"])}
    if cmd == "plan":
        # Cùng khối chỉ dẫn với web (lenh_he_thong.khoi_ke_hoach). Ở Telegram chỉ có lời dặn, chưa
        # có cổng chặn ở hub: lượt Telegram chưa mang mức quyền riêng từng lượt.
        if not arg.strip():
            return {"reply": "Gõ /plan kèm việc cần lên kế hoạch, ví dụ: /plan dọn lại kho hàng "
                             "cuối tháng. Javis chỉ đọc và đề xuất, chưa làm gì ra ngoài."}
        return {"ask": lenh_he_thong.khoi_ke_hoach() + arg.strip()}
    if cmd == "agents":
        ags = agents_index(brain, kem_prompt=False)   # lệnh này chỉ in tên + vai trò
        busy = _tg_chat_busy(chat_key)
        if not ags:
            return {"reply": "Chưa có agent nào (tạo trong Studio trên dashboard)."}
        lines = [f"• {a.get('name')} - {(a.get('role') or '')[:50]}" for a in ags[:20]]
        return {"reply": f"🤖 Agents ({len(ags)}):\n" + "\n".join(lines) + f"\n\nĐang chạy lượt: {'có' if busy else 'không'}"}
    if cmd == "workflows":
        wfs = workflows_index(brain)
        if not wfs:
            return {"reply": "Chưa có workflow (tạo trong Studio trên dashboard)."}
        lines = [f"• {w.get('name')} ({w.get('status')})" for w in wfs[:20]]
        return {"reply": "⚡ Workflows:\n" + "\n".join(lines) + "\n\n(Hiện chạy trên dashboard; chạy qua Telegram sẽ thêm sau.)"}
    if cmd == "retry":
        last = (_TG_SESS.get(chat_key) or {}).get("last")
        if not last:
            return {"reply": "Chưa có câu nào để gửi lại."}
        return {"ask": last}
    if cmd in ("brain", "vault"):
        d = await asyncio.to_thread(_list_brains_sync); brains = d.get("brains") or []
        if not brains:
            return {"reply": "Chưa có brain nào (tạo trong dashboard, nút + cạnh dropdown brain)."}
        a = arg.strip()
        if a:
            # match theo tên: khớp đúng trước, khớp một phần sau (không phân biệt hoa thường)
            # 0.219.0: khớp cả tên hiển thị (đổi tên) lẫn tên thư mục, để tên cũ người dùng quen vẫn gọi được.
            def _ten(b):
                return [x.lower() for x in (b.get("label") or "", b["name"]) if x]
            hit = (next((b for b in brains if a.lower() in _ten(b)), None)
                   or next((b for b in brains if any(a.lower() in t for t in _ten(b))), None))
            if not hit:
                names = ", ".join(b.get("label") or b["name"] for b in brains[:15])
                return {"reply": f"⚠ Không thấy brain '{a}'. Có: {names}"}
            _tg_set_brain(chat_key, hit["path"])
            return {"reply": f"🧠 Đã chuyển phiên này sang brain: {hit.get('label') or hit['name']}\n"
                             "(hội thoại reset để nạp đúng bộ nhớ/skill của brain mới)"}
        # Không tham số → menu nút bấm chọn brain
        return {"reply": _tg_brain_header(chat_key), "reply_markup": _tg_brain_kb(brains, chat_key)}
    # /<slug> khác → coi là gọi skill (cần CLI)
    if cfgmod.read_settings().get("model", {}).get("engine") == "openrouter":
        return {"reply": f"⚠ Skill cần engine Claude CLI. Gửi /cli để đổi, rồi /{cmd} lại."}
    # KHỐI NGỮ CẢNH đặt trước câu người dùng, KHÔNG viết lại câu đó. Phải khớp đúng mẫu của
    # dashboard (chat-slash.js: buildSkillInvocation) để hai kênh nói cùng một thứ - chuỗi cũ
    # nhồi câu của người dùng vào giữa một câu của máy rồi lưu nguyên thế làm tin của họ, nên
    # mở lại hội thoại là đọc được một câu mình chưa từng gõ (khách báo 16/09).
    dan = "Hãy dùng skill này để làm việc dưới đây."
    try:
        co_that = any((x or {}).get("slug") == cmd for x in skills_index(_tg_brain(chat)))
    except Exception:
        co_that = False
    if not co_that:
        dan += " Brain không có skill tên này thì cứ xử lý yêu cầu bên dưới như bình thường."
    return {"ask": f"[SKILL: {cmd}\n{dan}]\n\n" + (arg.strip() if arg else f"/{cmd}")}


# ---- Talking to an agent (partner) from the owner's Telegram bot ----
# Customer report 0.270 (Code 24): "@TEST-Thẩm định viên ..." over Telegram was answered by Javis,
# and the partner's run log had no turn; the only command was /agents, which just lists them.
# Now, in the OWNER's bot and only in a chat on its whitelist:
#   - a message that starts with `@<agent name or slug>` is one turn of that agent;
#   - `/agent <name>` makes that agent answer every message of the chat, `/agent off` goes back to Javis;
#   - `@javis ...` asks Javis one question while an agent is picked.
# The turn itself is the CLI agent turn (`_tg_answer(..., agent=...)`, from #744): agent prompt, model,
# own session, lessons, rules and run log. Customer-facing bot accounts (chatbot_runtime) have their own
# answer and command functions, so none of this is reachable from them.
_TG_AGENT_PATH = cfgmod.STATE_DIR / "tg_agent.json"


def _tg_load_agent_map() -> dict:
    try:
        if _TG_AGENT_PATH.exists():
            d = json.loads(_TG_AGENT_PATH.read_text(encoding="utf-8"))
            if isinstance(d, dict):
                return {str(k): v for k, v in d.items()
                        if isinstance(v, dict) and v.get("slug") and v.get("brain")}
    except Exception:
        pass
    return {}


_TG_AGENT_MAP = _tg_load_agent_map()   # chat -> {"brain": brain root, "slug": agent slug}


def _tg_save_agent_map() -> None:
    try:
        _atomic_write_text(_TG_AGENT_PATH, json.dumps(_TG_AGENT_MAP, ensure_ascii=False, indent=2))
    except Exception as e:
        print(f"[tg agent map write] {type(e).__name__}: {e}", file=__import__('sys').stderr)


def _agent_name_key(s) -> str:
    """Comparison key of an agent name or slug: no case, no diacritics, and `-`, `_` and spaces all
    alike, so "TEST-Thẩm định viên" and its slug `test-tham-dinh-vien` give the same key."""
    return re.sub(r"[\s_\-]+", " ", _fold_accents(str(s or ""))).strip()


# What `@...` or `/agent ...` call Javis itself (the main assistant, not an agent of the brain).
_TG_JAVIS_KEYS = frozenset({"javis", _agent_name_key(javis_core.NAME), _agent_name_key(javis_core.SLUG)})
_TG_AGENT_OFF = frozenset({"off", "tat", "huy", "none", "stop"}) | _TG_JAVIS_KEYS


def _tg_agent_rows(brain_root) -> list:
    """[{"slug", "name"}] of the brain's agents. `slug` is the REAL file stem (see `_cli_agent`)."""
    out = []
    try:
        for f in sorted(_agents_dir(brain_root).glob("*.md")):
            if javis_core.is_core_slug(f.stem):
                continue
            try:
                meta, _ = _read_md(f)
            except Exception:
                meta = {}
            out.append({"slug": f.stem, "name": str((meta or {}).get("name") or f.stem)})
    except Exception as e:
        print(f"[tg agents] {type(e).__name__}: {e}", file=__import__('sys').stderr)
    return out


def _tg_agent_find(rows, query) -> list:
    """Agents whose name or slug is exactly `query` (case and diacritics insensitive). No partial
    match: two partners with similar names must never be swapped by a guess."""
    k = _agent_name_key(query)
    if not k:
        return []
    return [r for r in rows if k in (_agent_name_key(r["slug"]), _agent_name_key(r["name"]))]


_TG_MENTION_WORDS = 8   # longest agent name, in words, that a mention is tried against


def _tg_agent_mention(text, rows, bot_username=""):
    """Read a leading `@<agent>` mention. Returns (kind, hits, rest):

    kind "" (no mention: `rest` is the text unchanged), "agent" (one agent, `hits[0]`), "javis",
    "ambiguous" (several agents share that name, `hits`) or "unknown". Names have spaces, so the
    LONGEST run of words that names an agent wins ("@Writer Pro ..." picks "Writer Pro" over
    "Writer"). A leading mention of the bot itself (`@my_bot`, as in a group) is skipped first.
    """
    s = str(text or "")
    st = s.lstrip()
    if bot_username:
        m = re.match(r"@" + re.escape(str(bot_username)) + r"(?![A-Za-z0-9_])[\s,:]*", st, re.I)
        if m:
            st = st[m.end():]
    if len(st) < 2 or st[0] != "@" or not st[1].isalnum():
        return "", [], s
    body = st[1:]
    words = list(re.finditer(r"\S+", body))[:_TG_MENTION_WORDS]
    for n in range(len(words), 0, -1):
        end = words[n - 1].end()
        key = _agent_name_key(body[:end].rstrip(",.:;!?"))
        hits = [r for r in rows if key in (_agent_name_key(r["slug"]), _agent_name_key(r["name"]))]
        if hits or key in _TG_JAVIS_KEYS:
            rest = re.sub(r"^[\s,:;]*(?:-\s+)?", "", body[end:])
            if not hits:
                return "javis", [], rest
            return ("agent" if len(hits) == 1 else "ambiguous"), hits, rest
    return "unknown", [], s


def _tg_owner_chat(chat) -> bool:
    """A chat on the owner bot's whitelist. An empty whitelist answers anyone, so it allows no agent."""
    ids = tg_parse_ids((cfgmod.read_settings().get("telegram") or {}).get("chat_id", ""))
    return bool(chat) and str(chat) in ids


def _tg_agent_list_text(rows, head="") -> str:
    lines = [f"• {r['name']}" + (f" ({r['slug']})" if _agent_name_key(r["name"]) != _agent_name_key(r["slug"]) else "")
             for r in rows[:30]]
    return ((head + "\n\n") if head else "") + "\n".join(lines) + "\n\n" + localefmt.chu(
        "Gõ @<tên> <câu hỏi> để hỏi một câu, hoặc /agent <tên> để cộng sự đó trả lời cả chat (/agent off để về Javis).",
        "Type @<name> <question> to ask once, or /agent <name> to let that partner answer the whole chat "
        "(/agent off to go back to Javis).")


def _tg_agent_pinned(chat, root, rows):
    """(row, notice) of the agent picked with /agent for this chat. A pick whose brain changed (/brain)
    or whose agent is gone is dropped, with a notice saying Javis answers again."""
    pin = _TG_AGENT_MAP.get(str(chat))
    if not pin:
        return None, ""
    hit = next((r for r in rows if r["slug"] == pin.get("slug")), None)
    if hit and str(pin.get("brain")) == str(root):
        return hit, ""
    _TG_AGENT_MAP.pop(str(chat), None)
    _tg_save_agent_map()
    return None, localefmt.chu(
        f"(Cộng sự '{pin.get('slug')}' đã chọn không còn trong brain này, Javis trả lời lại từ đây.)",
        f"(The partner '{pin.get('slug')}' picked earlier is not in this brain any more, Javis answers from here.)")


def _tg_agent_route(chat, text, bot_username="") -> dict:
    """Who answers this owner message: {"agent": {"brain", "slug", "name"} | None, "text": what the
    turn receives, "reply": a direct answer instead of a turn | None, "notice": a line to prepend}."""
    out = {"agent": None, "text": text, "reply": None, "notice": ""}
    key = str(chat or "")
    if not _tg_owner_chat(key):
        return out
    root = _brain_root(_tg_brain(key))
    rows = _tg_agent_rows(root)
    if not rows:
        return out   # nothing to pick: an `@someone` message is just a message to Javis
    kind, hits, rest = _tg_agent_mention(text, rows, bot_username)
    if kind == "javis":
        out["text"] = rest or text
        return out
    if kind == "unknown":
        out["reply"] = _tg_agent_list_text(rows, localefmt.chu(
            "Không thấy cộng sự nào tên như vậy trong brain này. Có:",
            "No partner by that name in this brain. There are:"))
        return out
    if kind == "ambiguous":
        out["reply"] = _tg_agent_list_text(hits, localefmt.chu(
            "Có nhiều cộng sự trùng tên này, gọi bằng mã (slug) cho chắc:",
            "Several partners share that name, call one by its slug:"))
        return out
    if kind == "agent":
        if not rest.strip():
            out["reply"] = localefmt.chu(
                f"Viết câu hỏi ngay sau tên, ví dụ: @{hits[0]['name']} <câu hỏi>. "
                f"Muốn {hits[0]['name']} trả lời cả chat thì gõ /agent {hits[0]['slug']}.",
                f"Write the question right after the name, e.g. @{hits[0]['name']} <question>. "
                f"To let {hits[0]['name']} answer the whole chat, type /agent {hits[0]['slug']}.")
            return out
        out["agent"] = {"brain": root, **hits[0]}
        out["text"] = rest
        return out
    row, out["notice"] = _tg_agent_pinned(key, root, rows)
    if row:
        out["agent"] = {"brain": root, **row}
    return out


def _tg_owner_precheck(text, meta):
    """Owner bot precheck: a mention that names no agent, or several, is answered with the list
    BEFORE a turn starts (no "Javis is working" message, no turn spent on a guess)."""
    m = meta or {}
    r = _tg_agent_route(m.get("chat_id"), text, m.get("bot_username") or "")
    return {"reply": r["reply"]} if r["reply"] else None


async def _tg_owner_answer(text, meta=None, progress=None):
    """Answer function of the OWNER's Telegram bot: `_tg_answer`, routed to an agent when asked."""
    m = meta or {}
    chat = str(m.get("chat_id") or "")
    r = _tg_agent_route(chat, text, m.get("bot_username") or "")
    if r["reply"]:
        return {"text": r["reply"], "files": []}
    ag = r["agent"]
    if not ag:
        out = await _tg_answer(r["text"], meta, progress)
    else:
        out = await _tg_answer(r["text"], meta, progress, agent={"brain": ag["brain"], "slug": ag["slug"]})
        try:
            # The agent turn ran in its own session: /retry reads the chat's, and must resend the
            # message as written (mention included) so it reaches the same agent again.
            _tg_session(chat)["last"] = text
        except Exception:
            pass
    if isinstance(out, dict):
        head = "\n\n".join(x for x in (r["notice"], f"🤝 {ag['name']}" if ag else "") if x)
        if head:
            out["text"] = head + "\n\n" + (out.get("text") or "")
    elif r["notice"]:
        out = r["notice"] + "\n\n" + str(out or "")
    return out


async def _tg_owner_command(cmd, arg, chat=None, meta=None):
    """Command function of the OWNER's Telegram bot: `_tg_command` plus /agent. Kept out of
    `_tg_command` because the owner's Zalo bot and owner channels share it and have no agent routing."""
    chat_key = str(chat or "default")
    if cmd == "agent":
        if not _tg_owner_chat(chat_key):
            return {"reply": localefmt.chu(
                "Chỉ chat nằm trong danh sách cho phép của bot (trang Kênh) mới chọn được cộng sự.",
                "Only a chat on the bot's allow list (Channels page) can pick a partner.")}
        root = _brain_root(_tg_brain(chat_key))
        rows = _tg_agent_rows(root)
        a = arg.strip()
        if a and _agent_name_key(a) in _TG_AGENT_OFF:
            had = _TG_AGENT_MAP.pop(chat_key, None)
            if had:
                _tg_save_agent_map()
            return {"reply": localefmt.chu("Javis trả lời chat này như thường.",
                                           "Javis answers this chat as usual.")}
        if not rows:
            return {"reply": localefmt.chu("Brain này chưa có cộng sự nào (tạo ở trang Cộng sự trên dashboard).",
                                           "This brain has no partner yet (create one on the Partners page).")}
        if not a:
            cur, notice = _tg_agent_pinned(chat_key, root, rows)
            head = (localefmt.chu(f"Đang trả lời chat này: {cur['name']}.", f"Answering this chat: {cur['name']}.")
                    if cur else localefmt.chu("Đang trả lời chat này: Javis.", "Answering this chat: Javis."))
            return {"reply": _tg_agent_list_text(rows, "\n".join(x for x in (notice, head) if x))}
        hits = _tg_agent_find(rows, a)
        if len(hits) != 1:
            return {"reply": _tg_agent_list_text(hits or rows, localefmt.chu(
                "Có nhiều cộng sự trùng tên này, chọn bằng mã (slug):" if hits
                else f"Không thấy cộng sự '{a}' trong brain này. Có:",
                "Several partners share that name, pick one by its slug:" if hits
                else f"No partner '{a}' in this brain. There are:"))}
        _TG_AGENT_MAP[chat_key] = {"brain": str(root), "slug": hits[0]["slug"]}
        _tg_save_agent_map()
        name = hits[0]["name"]
        return {"reply": localefmt.chu(
            f"🤝 Từ giờ {name} trả lời chat này. Gõ @javis <câu hỏi> để hỏi Javis một câu, /agent off để về Javis.",
            f"🤝 {name} answers this chat from now on. Type @javis <question> to ask Javis once, /agent off to go back.")}
    res = await _tg_command(cmd, arg, chat, meta)
    if cmd in ("reset", "new", "clear"):
        # The chat's agent conversations live in their own sessions (`_agent_sess_key`): /reset
        # starts those over too, not only Javis's.
        pre = chat_key + "@"
        for k in {k for k in list(_TG_SESS) + list(_TG_SID_MAP) if str(k).startswith(pre)}:
            s = _tg_session(k)
            _tg_ngat_mach(s)
            s["or"] = None
            s["last"] = None
            s["sid"] = None
            _tg_quen_sid(s)
    elif cmd in ("agents", "help", "menu", "start") and isinstance(res, dict) and "reply" in res:
        res["reply"] += "\n\n" + localefmt.chu(
            "/agent <tên> - chọn cộng sự trả lời chat này (/agent off: về Javis) · @<tên> <câu hỏi> - hỏi cộng sự một câu",
            "/agent <name> - pick the partner that answers this chat (/agent off: back to Javis) · "
            "@<name> <question> - ask a partner once")
    elif cmd == "status" and isinstance(res, dict) and "reply" in res:
        pin = _TG_AGENT_MAP.get(chat_key)
        if pin:
            res["reply"] += "\n" + localefmt.chu(f"Cộng sự: {pin.get('slug')} (/agent off để về Javis)",
                                                 f"Partner: {pin.get('slug')} (/agent off to go back to Javis)")
    return res


def _tg_inbox_dir(chat=None):
    """Nơi lưu file user gửi lên Telegram - đặt trong brain CỦA PHIÊN người gửi
    (đổi bằng /brain; chưa đổi thì brain mặc định) để agent đọc được ngay."""
    root = _brain_root(_tg_brain(chat))
    return str(Path(root) / "inbox" / "telegram")


async def _stt_nghe(data, ten=""):
    """Nghe tin thoại của kênh chat -> chữ. Đọc key Groq TẠI THỜI ĐIỂM GỌI, cố ý.

    Dán key ở trang Models xong là tin thoại tiếp theo nghe được ngay, không phải tắt bật lại
    bot. Đọc lúc dựng bot thì key mới dán nằm im tới lần khởi động sau, mà chẳng có gì trên
    màn hình nói cho người ta biết điều đó.
    """
    _cfg = cfgmod.read_settings()
    key = (_cfg.get("model") or {}).get("groq_api_key") or ""
    # Gợi ý ngôn ngữ theo cấu hình. reply_lang="auto" -> truyền "" để Whisper TỰ DÒ, thay vì
    # ép "vi" như trước: người nói tiếng Anh vào một Javis đang để "auto" thì cái ép đó biến
    # câu của họ thành một câu tiếng Việt sai nghĩa.
    _lc2 = _cfg.get("locale") or {}
    # Thứ tự: ngôn ngữ trả lời đã GHIM -> ngôn ngữ giao diện -> để Whisper tự dò.
    #
    # `ui_lang` ở giữa là để CHỮA MỘT HỒI QUY chứ không phải cho đẹp: `reply_lang` mặc định
    # là "auto", nên nếu chỉ đọc mỗi nó thì mọi máy đang chạy đột nhiên mất gợi ý "vi" mà chủ
    # máy không đổi cài đặt gì. Whisper không có gợi ý thì câu tiếng Việt NGẮN hay bị đoán
    # nhầm sang tiếng khác rồi dịch luôn, ra một câu không ai gõ bao giờ - đúng lý do gợi ý
    # này tồn tại từ đầu.
    _ma = (lang_registry.chuan_hoa(_lc2.get("reply_lang") or "")
           or lang_registry.chuan_hoa(_lc2.get("ui_lang") or ""))
    # Cùng bộ từ vựng và lớp sửa nghe nhầm như mic trên dashboard (nghe_sua): tin thoại Telegram
    # hay Zalo nói "David" cũng phải ra "Javis" trước khi vào bộ não.
    _tv = nghe_sua.tu_vung(_cfg)
    res = await stt.groq_nghe(data, ten, key,
                              ngon_ngu=(lang_registry.get(_ma).stt if _ma else ""),
                              hotwords=nghe_sua.goi_y_whisper(_tv))
    if res.get("ok") and res.get("text"):
        res["text"] = nghe_sua.sua(res["text"], _tv)
    return res


# ============================================================
# Kênh Zalo Bot của CHỦ (API chính thức). Xem docs/dev/2026-08-zalo-bot-spec.md
# ============================================================
_ZALO_BOT = None
# Hàng chờ ghép nối: người lạ nhắn cho bot -> vào đây kèm MÃ, chủ bấm một nút là vào whitelist.
#
# Vì sao không chép cách của Telegram: bên đó bắt chủ đi tìm Chat ID bằng @userinfobot rồi tự
# dán vào ô. Zalo KHÔNG có công cụ tương đương, và id là chuỗi hex như "6ede9afa66b88fe6d6a9" -
# không ai đọc ra được nó là ai. Nên đảo chiều: bot thấy người lạ thì đưa họ lên đây kèm tên
# hiển thị THẬT và một mã ngắn để chủ đối chiếu đúng người khi hai người trùng tên.
_ZALO_CHO = {}                 # chat_id -> {chat_id, ten, ma, ts, lan}
_ZALO_CHO_MAX = 20             # trần: hộp thư mở cho người lạ, không được phình theo
_ZALO_CHO_TTL = 30 * 60        # mục cũ hơn 30 phút thì rụng
_ZALO_CHO_NHAC = 10 * 60       # mỗi chat_id lạ chỉ nhận MỘT câu từ chối trong 10 phút
ZALO_CHAT_PREFIX = "zalo:"     # owner_chat của việc giao từ Zalo: "zalo:<chat_id>"


def _zalo_don_cho():
    het = [k for k, v in _ZALO_CHO.items() if time.time() - v.get("ts", 0) > _ZALO_CHO_TTL]
    for k in het:
        _ZALO_CHO.pop(k, None)


def _zalo_ghi_cho(meta) -> str:
    """Đưa một chat lạ lên hàng chờ, trả câu bot nên đáp ("" = im, vừa đáp gần đây rồi)."""
    _zalo_don_cho()
    cid = str((meta or {}).get("chat_id") or "").strip()
    if not cid:
        return ""
    cu = _ZALO_CHO.get(cid)
    if cu:
        cu["lan"] = cu.get("lan", 0) + 1
        cu["ten"] = str((meta or {}).get("user_name") or cu.get("ten") or "")[:80]
        nhac_lai = time.time() - cu.get("nhac", 0) > _ZALO_CHO_NHAC
        cu["ts"] = time.time()
        if not nhac_lai:
            return ""      # im: không để người lạ bơm tin làm ngập cả hàng chờ lẫn chat của họ
        cu["nhac"] = time.time()
        return _zalo_cau_tu_choi(cu["ma"])
    if len(_ZALO_CHO) >= _ZALO_CHO_MAX:
        _ZALO_CHO.pop(min(_ZALO_CHO, key=lambda k: _ZALO_CHO[k].get("ts", 0)), None)
    ma = f"{secrets.randbelow(9000) + 1000}"
    _ZALO_CHO[cid] = {"chat_id": cid, "ten": str((meta or {}).get("user_name") or "")[:80],
                      "ma": ma, "ts": time.time(), "nhac": time.time(), "lan": 1}
    return _zalo_cau_tu_choi(ma)


def _zalo_cau_tu_choi(ma: str) -> str:
    return ("Bạn chưa được cấp quyền dùng Javis này.\n"
            f"Mã ghép nối của bạn: {ma}\n"
            "Đưa mã này cho chủ máy để họ cho phép ở trang Kênh.")


def _zalo_inbox_dir(chat=None):
    """Nơi lưu ảnh user gửi lên Zalo - trong brain CỦA PHIÊN người gửi, y như Telegram."""
    root = _brain_root(_tg_brain(ZALO_CHAT_PREFIX + str(chat or "")))
    return str(Path(root) / "inbox" / "zalo")


async def _zalo_answer(text, meta=None, progress=None, channel="zalo", bot=None):
    """Vỏ cho kênh Zalo: gắn TIỀN TỐ vào chat_id rồi mới vào lõi chung.

    Vì sao phải gắn: `_tg_answer` dùng `meta["chat_id"]` làm khoá phiên, khoá brain, và làm
    `owner_chat` cho việc nền. Id Zalo là chuỗi hex còn id Telegram là số, nên trùng nhau thì
    khó, nhưng "khó" không phải là một bảo đảm - và cái giá của một lần trùng là hai người
    khác nhau dùng chung một mạch hội thoại. Tiền tố cũng chính là thứ `_notify_owner` đọc để
    biết đường nào gửi kết quả về.

    KHÔNG gắn tiền tố vào `meta` mà lớp vận chuyển đang cầm: nó dùng chat_id THẬT để gửi tin.
    """
    m = dict(meta or {})
    goc = str(m.get("chat_id") or "").strip()
    m["chat_id"] = (ZALO_CHAT_PREFIX + goc) if goc else "default"
    return await _tg_answer(text, m, progress, channel="zalo", bot=bot)


def _zalo_precheck(text, meta):
    """Chốt chặn TRƯỚC khi tốn một lượt: người lạ thì đưa vào hàng chờ ghép nối.

    Whitelist của lớp vận chuyển cũng chặn được, nhưng nó chỉ trả một câu cụt. Chặn ở đây thì
    người lạ nhận được MÃ, và chủ có một nút để bấm - thay vì phải đi tra một chuỗi hex.
    """
    z = cfgmod.read_settings().get("zalo_bot", {})
    ids = tg_parse_ids(z.get("chat_id"))
    cid = str((meta or {}).get("chat_id") or "").strip()
    if cid and cid in ids:
        return None
    # DANH SÁCH RỖNG = CHƯA AI ĐƯỢC PHÉP, không phải "ai cũng được".
    #
    # Đây là chỗ CỐ Ý khác Telegram, đừng "sửa" cho giống. Bên Telegram ô trống nghĩa là mở
    # cho tất cả, và tài liệu phải đi kèm một câu dặn đừng để trống - vì bên đó user tự tra
    # được id của mình bằng @userinfobot rồi điền vào trước khi bật.
    #
    # Zalo không có công cụ đó, nên luồng đúng là bật bot với ô TRỐNG rồi tự nhắn cho nó một
    # câu để hiện lên hàng chờ. Nếu ô trống lại mở cho tất cả thì đúng cái luồng mà giao diện
    # đang hướng dẫn sẽ tạo ra một con bot ai nhắn cũng chạm được vào brain của chủ, trong
    # khoảng thời gian giữa lúc bật và lúc bấm Cho phép. Fail-closed.
    return {"reply": _zalo_ghi_cho(meta)}


def restart_zalo_bot():
    """Bật lại bot Zalo theo cấu hình settings.zalo_bot (tắt bot cũ nếu có)."""
    global _ZALO_BOT
    z = cfgmod.read_settings().get("zalo_bot", {})
    if _ZALO_BOT:
        _ZALO_BOT.stop()
        _ZALO_BOT = None
    if z.get("enabled") and z.get("token"):
        # KHÔNG truyền whitelist xuống lớp vận chuyển: `_zalo_precheck` lo phần đó và còn trả
        # về mã ghép nối. Truyền cả hai là người lạ ăn hai câu từ chối cho một tin.
        _ZALO_BOT = zalo_bot.ZaloBot(z["token"], "", _zalo_answer, _tg_command,
                                     download_dir=_zalo_inbox_dir,
                                     precheck_fn=_zalo_precheck, stt_fn=_stt_nghe)
        _ZALO_BOT.start()
        return True
    return False


@app.get("/zalo-bot/status")
async def zalo_bot_status():
    z = cfgmod.read_settings().get("zalo_bot", {})
    running = bool(_ZALO_BOT and _ZALO_BOT._task and not _ZALO_BOT._task.done())
    _zalo_don_cho()
    cho = sorted(_ZALO_CHO.values(), key=lambda x: x.get("ts", 0), reverse=True)
    return {"enabled": bool(z.get("enabled")), "token_set": bool(z.get("token")),
            "chat_id": z.get("chat_id", ""), "chat_ids": tg_parse_ids(z.get("chat_id")),
            "running": running,
            "status": (_ZALO_BOT.status if _ZALO_BOT else "off"),
            "last_error": (_ZALO_BOT.last_error if _ZALO_BOT else ""),
            "bot_name": (_ZALO_BOT.bot_username if _ZALO_BOT else ""),
            "loi_danh_tinh": (_ZALO_BOT.loi_danh_tinh if _ZALO_BOT else ""),
            "cho": cho}


@app.post("/zalo-bot/restart")
async def zalo_bot_restart():
    return {"ok": True, "running": restart_zalo_bot()}


@app.post("/zalo-bot/allow")
async def zalo_bot_allow(chat_id: str = Form(...), on: str = Form("1")):
    """Cho phép (hoặc bỏ qua) một chat đang chờ, bằng ĐÚNG một cú bấm."""
    cid = str(chat_id or "").strip()
    if not cid:
        return JSONResponse({"ok": False, "error": localefmt.chu("Thiếu chat_id", "Missing chat_id")}, status_code=400)
    if str(on).strip() not in ("", "0", "false"):
        z = cfgmod.read_settings().get("zalo_bot", {})
        ids = tg_parse_ids(z.get("chat_id"))
        if cid not in ids:
            ids.append(cid)
        cfgmod.update_settings({"zalo_bot": {"chat_id": ", ".join(ids)}})
    # Ra khỏi hàng chờ dù chủ chọn gì: cho phép rồi thì hết chờ, mà bấm bỏ qua cũng là đã quyết.
    _ZALO_CHO.pop(cid, None)
    z = cfgmod.read_settings().get("zalo_bot", {})
    return {"ok": True, "chat_ids": tg_parse_ids(z.get("chat_id"))}


@app.post("/zalo-bot/test")
async def zalo_bot_test():
    """Gửi tin test tới TẤT CẢ chat ID trong whitelist - báo rõ ID nào lỗi."""
    z = cfgmod.read_settings().get("zalo_bot", {})
    ids = tg_parse_ids(z.get("chat_id"))
    if not z.get("token") or not ids:
        return {"ok": False, "error": localefmt.chu("Thiếu token hoặc chat ID (lưu trước đã)",
                                                    "Missing token or chat ID (save them first)")}
    import httpx
    sent, errs = 0, []
    url = f"https://bot-api.zaloplatforms.com/bot{z['token']}/sendMessage"
    try:
        async with httpx.AsyncClient(timeout=15) as c:
            for cid in ids:
                try:
                    r = await c.post(url, json={"chat_id": cid,
                                                "text": "Javis Zalo đã kết nối. Nhắn câu hỏi bất kỳ nhé."})
                    d = r.json() if r.content else {}
                    if d.get("ok"):
                        sent += 1
                    else:
                        errs.append(f"{cid}: {str(d.get('description') or localefmt.chu('lỗi', 'error'))[:80]}")
                except Exception as e:
                    errs.append(f"{cid}: {type(e).__name__}")
    except Exception as e:
        return {"ok": False, "error": f"{type(e).__name__}: {e}"}
    return {"ok": sent > 0, "sent": sent, "total": len(ids), "error": "; ".join(errs)[:300]}


# ============================================================
# Owner's control channels on Slack and WhatsApp (0.71.0). The logic lives in
# server/owner_channels.py; this block only wires it and exposes the same four endpoints the
# Zalo control bot has (status, restart, allow, test), plus the WhatsApp webhook.
# ============================================================
def _wa_verify_token() -> str:
    """The handshake string Meta echoes when the webhook is set up. Generated once."""
    w = cfgmod.read_settings().get("whatsapp", {}) or {}
    tok = str(w.get("verify_token") or "").strip()
    if not tok:
        tok = secrets.token_urlsafe(24)
        cfgmod.update_settings({"whatsapp": {"verify_token": tok}})
    return tok


def _wa_account_secrets() -> list:
    """App secrets of the customer-bot WhatsApp accounts (one Meta app per account)."""
    out = []
    try:
        for a in channel_accounts.list_accounts(channel="whatsapp"):
            cr = whatsapp_bot.split_credentials(channel_accounts.get_token(a.get("id", "")))
            if cr.get("app_secret"):
                out.append(cr["app_secret"])
    except Exception as e:
        print(f"[whatsapp secrets] {type(e).__name__}: {e}", file=sys.stderr)
    return out


def _owner_channel_routes(ch):
    @app.get(f"/{ch.key}/status", name=f"{ch.key}_status")
    async def _status(request: Request):
        d = ch.status()
        if ch.key == "whatsapp":
            base = web_security.external_base(
                request.url.scheme, request.url.netloc,
                request.headers.get("x-forwarded-proto", ""),
                request.headers.get("x-forwarded-host", ""))
            d["webhook_url"] = base + "/whatsapp/webhook"
            d["verify_token"] = _wa_verify_token()
            d["https"] = d["webhook_url"].startswith("https://")
        return d

    @app.post(f"/{ch.key}/restart", name=f"{ch.key}_restart")
    async def _restart():
        return {"ok": True, "running": ch.restart()}

    @app.post(f"/{ch.key}/allow", name=f"{ch.key}_allow")
    async def _allow(chat_id: str = Form(...), on: str = Form("1")):
        if not str(chat_id or "").strip():
            return JSONResponse({"ok": False, "error": localefmt.chu("Thiếu ID", "Missing ID")},
                                status_code=400)
        ids = ch.allow(chat_id, str(on).strip() not in ("", "0", "false"))
        return {"ok": True, "allow_ids": ids}

    @app.post(f"/{ch.key}/test", name=f"{ch.key}_test")
    async def _test():
        return await ch.test()


for _ch in owner_channels.ALL:
    _owner_channel_routes(_ch)


@app.get("/whatsapp/webhook")
async def whatsapp_webhook_verify(request: Request):
    """Meta's setup handshake: echo `hub.challenge` only when the verify token matches."""
    q = request.query_params
    want = _wa_verify_token()
    got = str(q.get("hub.verify_token") or "")
    if q.get("hub.mode") == "subscribe" and got and secrets.compare_digest(got, want):
        return PlainTextResponse(str(q.get("hub.challenge") or ""))
    return PlainTextResponse("forbidden", status_code=403)


@app.post("/whatsapp/webhook")
async def whatsapp_webhook(request: Request):
    """Inbound WhatsApp messages. Public URL, so nothing is trusted before the signature check;
    a request no known app secret signed is dropped with 401 and never parsed further."""
    raw = await request.body()
    if len(raw) > 2_000_000:
        return PlainTextResponse("too large", status_code=413)
    sig = request.headers.get("x-hub-signature-256", "")
    if not whatsapp_bot.verify_signature(raw, sig, owner_channels.whatsapp_app_secrets(_wa_account_secrets())):
        return PlainTextResponse("bad signature", status_code=401)
    try:
        payload = json.loads(raw.decode("utf-8") or "{}")
    except Exception:
        return PlainTextResponse("bad json", status_code=400)
    # Answer 200 right away (Meta retries anything slower); the messages run as tasks.
    n = await whatsapp_bot.handle_webhook(payload)
    return {"ok": True, "messages": n}


# ============================================================
# Messenger (0.134.0): customer bots on a Facebook Page. Meta calls one webhook for every Page;
# `messenger_bot.handle_webhook` routes by Page id. No owner control channel here.
# ============================================================
def _ms_verify_token() -> str:
    """The handshake string Meta echoes when the Messenger webhook is set up. Generated once."""
    m = cfgmod.read_settings().get("messenger", {}) or {}
    tok = str(m.get("verify_token") or "").strip()
    if not tok:
        tok = secrets.token_urlsafe(24)
        cfgmod.update_settings({"messenger": {"verify_token": tok}})
    return tok


def _ms_account_secrets() -> list:
    """App secrets of the Messenger accounts (one Meta app per account, often one app for all)."""
    out = []
    try:
        for a in channel_accounts.list_accounts(channel="messenger"):
            cr = messenger_bot.split_credentials(channel_accounts.get_token(a.get("id", "")))
            if cr.get("app_secret"):
                out.append(cr["app_secret"])
    except Exception as e:
        print(f"[messenger secrets] {type(e).__name__}: {e}", file=sys.stderr)
    return out


@app.get("/channels/webhook-info")
async def channels_webhook_info(request: Request, channel: str = ""):
    """Address and verify token to paste into the platform for a channel that receives messages
    by webhook (Messenger, Zalo OA). Shown on the Add account form; the verify token is not a secret."""
    kenh = str(channel or "").strip().lower()
    if kenh == "zalo_oa":
        url = _zo_webhook_url(request)
        return {"ok": True, "webhook_url": url, "verify_token": "", "https": url.startswith("https://"),
                "site_verify": True, "site_codes": _zo_site_codes()}
    if kenh != "messenger":
        return JSONResponse({"ok": False, "error": localefmt.chu("Kênh này không dùng webhook",
                                                                 "This channel does not use a webhook")},
                            status_code=400)
    base = web_security.external_base(
        request.url.scheme, request.url.netloc,
        request.headers.get("x-forwarded-proto", ""), request.headers.get("x-forwarded-host", ""))
    url = base + "/messenger/webhook"
    return {"ok": True, "webhook_url": url, "verify_token": _ms_verify_token(),
            "https": url.startswith("https://")}


@app.get("/messenger/webhook")
async def messenger_webhook_verify(request: Request):
    """Meta's setup handshake: echo `hub.challenge` only when the verify token matches."""
    q = request.query_params
    want = _ms_verify_token()
    got = str(q.get("hub.verify_token") or "")
    if q.get("hub.mode") == "subscribe" and got and secrets.compare_digest(got, want):
        return PlainTextResponse(str(q.get("hub.challenge") or ""))
    return PlainTextResponse("forbidden", status_code=403)


@app.post("/messenger/webhook")
async def messenger_webhook(request: Request):
    """Inbound Messenger events. Public URL, so nothing is trusted before the signature check;
    a request no known app secret signed is dropped with 401 and never parsed further."""
