@app.post("/messenger/check")
async def messenger_check(request: Request):
    """Rerun the checklist on a saved Messenger account. `repair: true` first re-registers the
    app webhook and re-subscribes the Page."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    aid = str(body.get("account_id") or "").strip()
    a, cr = _ms_account_creds(aid)
    if not a:
        return JSONResponse({"ok": False, "error": localefmt.chu("Không có tài khoản Messenger này",
                                                                 "No such Messenger account")}, status_code=404)
    meta = a.get("meta") or {}
    url = _ms_webhook_url(request)
    if not url.startswith("https://"):
        url = meta.get("webhook_url", "")
    errs = []
    import httpx
    async with httpx.AsyncClient(timeout=25) as c:
        app_id = meta.get("app_id", "")
        if not app_id:
            info = await messenger_setup.debug_token(c, cr["access_token"])
            app_id = info.get("app_id", "") if info.get("ok") else ""
            if app_id:
                channel_accounts.update_account(aid, {"meta": {**meta, "app_id": app_id}})
        if body.get("repair") and app_id:
            rep = await messenger_setup.repair(c, cr["page_id"], cr["access_token"], app_id,
                                               cr["app_secret"], url, _ms_verify_token())
            errs = rep.get("errors", [])
        chk = await messenger_setup.run_checks(c, cr["page_id"], cr["access_token"], cr["app_secret"],
                                               app_id, url, _ms_bot_running(aid, cr["page_id"]))
    return {"ok": True, "account": _ms_account_view(channel_accounts.get_account(aid) or a),
            "check": chk, "repair_errors": errs}


# ============================================================
# Zalo OA (0.412.0): customer bots on a Zalo Official Account. Zalo calls one webhook for every
# OA; `zalo_oa_bot.handle_webhook` routes by OA id. No owner control channel here.
# ============================================================
def _zo_webhook_url(request: Request) -> str:
    base = web_security.external_base(
        request.url.scheme, request.url.netloc,
        request.headers.get("x-forwarded-proto", ""), request.headers.get("x-forwarded-host", ""))
    return base + "/zalo-oa/webhook"


def _zo_site_codes() -> list:
    z = cfgmod.read_settings().get("zalo_oa", {}) or {}
    return [str(c) for c in (z.get("site_codes") or []) if str(c or "").strip()]


def _zo_account_secrets() -> list:
    """(App ID, OA secret key) of every Zalo OA account, for the webhook signature check."""
    out = []
    try:
        for a in channel_accounts.list_accounts(channel="zalo_oa"):
            cr = zalo_oa_bot.split_credentials(channel_accounts.get_token(a.get("id", "")))
            if cr.get("oa_secret"):
                out.append((cr.get("app_id", ""), cr["oa_secret"]))
    except Exception as e:
        print(f"[zalo_oa secrets] {type(e).__name__}: {e}", file=sys.stderr)
    return out


@app.post("/zalo-oa/webhook")
async def zalo_oa_webhook(request: Request):
    """Inbound Zalo OA events. Public URL, so nothing is trusted before the signature check; a
    request no known OA secret key signed is dropped with 401 and never handed to a bot."""
    raw = await request.body()
    if len(raw) > 2_000_000:
        return PlainTextResponse("too large", status_code=413)
    sig = request.headers.get("x-zevent-signature", "") or request.headers.get("mac", "")
    if not zalo_oa_bot.verify_signature(raw, sig, _zo_account_secrets()):
        return PlainTextResponse("bad signature", status_code=401)
    try:
        payload = json.loads(raw.decode("utf-8") or "{}")
    except Exception:
        return PlainTextResponse("bad json", status_code=400)
    # Answer 200 right away (Zalo wants it within about 2 seconds and retries otherwise); the
    # events run as tasks.
    n = await zalo_oa_bot.handle_webhook(payload if isinstance(payload, dict) else {})
    return {"ok": True, "events": n}


@app.post("/zalo-oa/site-verification")
async def zalo_oa_site_verification(request: Request):
    """Save the domain verification code Zalo shows (file name, meta tag or bare code), so that
    /zalo_verifier<code>.html answers and the owner can press Verify on developers.zalo.me.
    `remove: true` forgets it."""
    try:
        body = await request.json()
    except Exception:
        body = {}
    code = zalo_oa_bot.parse_site_code(body.get("code"))
    if not code:
        return JSONResponse({"ok": False, "error": localefmt.chu(
            "Không đọc được mã xác thực. Dán tên file zalo_verifier...html, thẻ meta hoặc chính mã đó.",
            "Could not read a verification code. Paste the zalo_verifier...html file name, the meta tag or the code itself.")},
            status_code=400)
    codes = [c for c in _zo_site_codes() if c != code]
    if not body.get("remove"):
        codes = ([code] + codes)[:10]
    cfgmod.update_settings({"zalo_oa": {"site_codes": codes}})
    return {"ok": True, "code": code, "site_codes": codes,
            "file": f"/zalo_verifier{code}.html"}


@app.get("/zalo_verifier{code}.html")
async def zalo_oa_verifier_file(code: str):
    """The file Zalo fetches to verify the webhook domain. Only codes the owner saved exist."""
    if code not in _zo_site_codes():
        return PlainTextResponse("not found", status_code=404)
    return HTMLResponse(zalo_oa_bot.verifier_html(code))


def restart_telegram():
    """Bật lại bot theo cấu hình settings.telegram (tắt bot cũ nếu có)."""
    global _TG_BOT
    t = cfgmod.read_settings().get("telegram", {})
    if _TG_BOT:
        _TG_BOT.stop()
        _TG_BOT = None
    _TG_SESS.clear()   # xoá mọi phiên hội thoại cũ khi khởi động lại bot
    if t.get("enabled") and t.get("token"):
        # `_tg_owner_*`: the shared turn and commands, plus talking to an agent (`@<agent>`, /agent).
        _TG_BOT = TelegramBot(t["token"], t.get("chat_id", ""), _tg_owner_answer, _tg_owner_command, _tg_callback,
                              download_dir=_tg_inbox_dir, stt_fn=_stt_nghe, precheck_fn=_tg_owner_precheck)
        _TG_BOT.start()
        return True
    return False


@app.get("/telegram/status")
async def telegram_status():
    t = cfgmod.read_settings().get("telegram", {})
    running = bool(_TG_BOT and _TG_BOT._task and not _TG_BOT._task.done())
    return {"enabled": bool(t.get("enabled")), "token_set": bool(t.get("token")),
            "chat_id": t.get("chat_id", ""), "chat_ids": tg_parse_ids(t.get("chat_id")),
            "running": running,
            "status": (_TG_BOT.status if _TG_BOT else "off"),
            "last_error": (_TG_BOT.last_error if _TG_BOT else ""),
            # Menu lệnh "/" đặt hụt: bot vẫn chạy, chỉ là gõ "/" không sổ ra danh sách. Tách
            # khỏi last_error vì vòng poll xoá last_error sau mỗi lượt thành công.
            "loi_menu_lenh": (getattr(_TG_BOT, "loi_menu_lenh", "") if _TG_BOT else "")}


@app.post("/telegram/restart")
async def telegram_restart():
    return {"ok": True, "running": restart_telegram()}


# ============================================================
# Bot chuyên trách - chatbot chuyên một lĩnh vực, trả lời KHÁCH
# Xem docs/dev/2026-08-bot-chuyen-trach-spec.md
# ============================================================
@app.get("/chatbots")
async def chatbots_list(brain: str = ""):
    """Danh sách bot kèm trạng thái SỐNG (không phải trạng thái mong muốn).

    Gộp cấu hình với trạng thái thật ngay tại đây: tách hai lời gọi thì giao diện có lúc vẽ
    'đang chạy' cho một con vừa chết, và 'bot chết âm thầm' đúng là thứ tính năng này phải
    chống.

    `brain` lọc theo brain - trang Chatbot chỉ hiện bot của brain đang mở, đúng như trang
    Agents và trang Skills. Bỏ trống thì trả TẤT CẢ (bộ giám sát và các lời gọi nội bộ cần
    thấy hết, chúng không đứng ở brain nào cả).
    """
    loc = str(brain or "").strip()
    out = []
    for b in chatbot_store.list_bots():
        # Same brain in any spelling: "brain", "path:<dir>" or the absolute path a bot was saved with (#716).
        if loc and not brain_ident.same_brain(b.get("brain"), loc):
            continue
        b = dict(b)
        b["status"] = chatbot_runtime.status(b["id"])
        a = b.get("agent") or {}
        meta, _ = _read_md(_agents_dir(a.get("brain") or "brain") / f"{a.get('slug')}.md")
        b["agent_name"] = meta.get("name") or ""
        b["agent_missing"] = not bool(meta)   # Agent bị xoá/đổi slug -> thẻ phải báo, đừng im
        # Model bot CHẠY THẬT ra ngoài = model của Agent nó trỏ tới (rỗng = Agent để Mặc định,
        # tức theo model chính). Thẻ phải nói ra: từ 0.62.3 bot mượn model của Agent, mà không
        # hiện thì đổi model cho trợ lý xong không có cách nào biết bot đã đổi theo hay chưa.
        b["agent_model"] = _model_cua_agent(a.get("brain") or "brain",
                                            a.get("slug") or "").get("model") or ""
        # Poller sống KHÔNG có nghĩa là bot trả lời được: model gọi hỏng thì thẻ vẫn chấm xanh
        # trong khi khách nhận toàn câu xin lỗi. Lấy lỗi của lượt gần nhất lên thẻ luôn.
        b["loi_luot"] = chatbot_log.loi_gan_nhat(b["id"])
        # Lượt gần nhất chạy được nhưng KHÔNG đúng mức đã đặt. Không gộp vào `loi_luot`: hai
        # chuyện sửa khác nhau, gộp lại là thẻ báo sai loại việc.
        b["canh_bao_luot"] = chatbot_log.canh_bao_gan_nhat(b["id"])
        # Nhóm có người gọi bot mà chủ chưa cho phép. Không đưa lên đây thì hành vi đúng ("bot
        # không tự nhận việc trong nhóm lạ") trông hệt hành vi hỏng: gọi tên bot trong nhóm và
        # không có gì xảy ra, không chỗ nào nói vì sao.
        b["nhom_cho"] = chatbot_runtime.nhom_cho(b["id"])
        # Hộp thư hội thoại: vài con số cho thẻ (tổng, hôm nay, chưa đọc). Kho hỏng thì thẻ
        # chỉ thiếu dòng này chứ không được làm đỏ cả trang Chatbot.
        try:
            b["hoi_thoai"] = conversations.thong_ke(bot_id=b["id"])
        except Exception:
            b["hoi_thoai"] = {}
        out.append(b)
    # Nhãn + cảnh báo rủi ro của từng mức quyền đi kèm luôn: giao diện KHÔNG được giữ bản chép
    # riêng. Chép riêng thì một hôm server siết thêm một rào mà ô cảnh báo vẫn hứa như cũ, và
    # chủ bấm đồng ý dựa trên một câu đã sai.
    return {"bots": out, "lang_list": lang_registry.cho_giao_dien(), "muc_quyen": [
        {"id": m, "nhan": chatbot_store.nhan_muc(m),
         "canh_bao": chatbot_store.canh_bao_muc(m),
         "can_xac_nhan": m in chatbot_store.MUC_NANG}
        for m in chatbot_store.MUC_QUYEN
    ], "kenh": [
        # Cùng lý do với mức quyền: giao diện KHÔNG giữ bản chép riêng. Từ 0.61.0 danh sách
        # kênh gắn được bot và năng lực của chúng đọc từ SỔ ĐĂNG KÝ KÊNH (server/channels).
        k for k in channels.cho_giao_dien() if (k.get("nang_luc") or {}).get("bot")
    ], "tai_khoan": [
        # Tài khoản kênh chưa bot nào trực (0.61.0): form tạo bot cho CHỌN thay vì bắt dán token.
        # Lọc theo BRAIN đang mở (0.62.4) đúng như danh sách bot ngay trên: bot thuộc một brain,
        # nên nó chỉ được chọn tài khoản của brain đó. Không lọc thì form vẫn bày tài khoản của
        # brain khác, gắn vào là tạo ra một liên kết chéo brain mà tab Tài khoản bot không hiện.
        # `loc` rỗng (lời gọi nội bộ) thì trả hết như cũ.
        #
        # Cộng thêm Zalo cá nhân (0.64.80): kết nối ở trang Kết nối, không thuộc brain nào nên
        # brain nào cũng thấy. Thiếu dòng này thì người dùng nối Zalo xong mở "Bot mới" và
        # không thấy kênh nào để chọn (chủ repo báo 29/09).
        a for a in (channel_accounts.list_accounts(brain=loc) + channel_accounts.tai_khoan_ao())
        if not chatbot_store.bots_using_account(a["id"])
    ], "tai_khoan_ban": [
        # Tài khoản đang do một BOT trực (0.65.9): form Bot mới hiện chúng mờ kèm ổ khoá, ghi rõ bot nào (và brain nào, nếu khác
        # brain đang mở) đang giữ. Trước đây form giấu hẳn các kênh này, người dùng thấy kênh "biến mất" mà không biết vì sao.
        # Giao diện tự loại các kênh của chính bot đang sửa.
        {"id": a["id"], "channel": a.get("channel") or "", "label": a.get("label") or "",
         "external_id": a.get("external_id") or "", "bot_id": u[0].get("id") or "",
         "bot_name": u[0].get("name") or "", "bot_brain": u[0].get("brain") or ""}
        for a in (channel_accounts.list_accounts(brain=loc) + channel_accounts.tai_khoan_ao())
        for u in [chatbot_store.bots_using_account(a["id"])] if u
    ]}


@app.post("/chatbots/verify-token")
async def chatbots_verify_token(token: str = Form(...), bot_id: str = Form(""),
                                channel: str = Form("")):
    """Hỏi nền tảng xem token này là con bot nào (getMe), và chặn trùng.

    Từ 0.61.0 việc hỏi đúng nền tảng nằm ở module kênh trong sổ đăng ký (`channels`), và đường
    này chỉ là bí danh của `POST /channels/verify-token` để giao diện cũ và bookmark cũ chạy.
    """
    return await channels_routes.verify_token(channel, token, bot_id=bot_id)


def _chan_nang_quyen(muc, xac_nhan):
    """Chặn nâng mức quyền khi chủ chưa xác nhận đã đọc rủi ro. None = cho qua.

    Cùng khuôn với `POST /reminders` lúc chưa đấu kênh báo: trả `can_force` kèm LÝ DO cụ thể
    để giao diện hỏi lại, chứ không im lặng hạ mức. Hạ mức im lặng thì chủ tưởng bot đang làm
    việc, còn nó thì từ chối mọi công cụ mà không ai biết.
    """
    if not chatbot_store.can_xac_nhan(muc, xac_nhan):
        return None
    m = str(muc).strip().lower()
    return JSONResponse({"ok": False, "error": chatbot_store.LOI_CHUA_XAC_NHAN,
                         "can_force": True, "muc_quyen": m,
                         "nhan": chatbot_store.nhan_muc(m),
                         "canh_bao": chatbot_store.canh_bao_muc(m)}, status_code=400)


def _chan_ngoai_le(raw, cu, xac_nhan):
    """Same gate as `_chan_nang_quyen`, for per-chat exceptions (0.172.0): an exception that raises a chat to a level
    needing the risk confirmation answers `can_force` with that level's warnings, so the form asks instead of failing.
    `xac_nhan` is the exception's OWN flag (`xac_nhan_ngoai_le`), and the answer names it in `co` so a caller knows
    which flag to resend. A list that does not parse is left to the store, which answers with the reason."""
    moi, loi = chatbot_store.parse_ngoai_le(raw)
    if loi or not chatbot_store.can_xac_nhan_ngoai_le(moi, cu, xac_nhan):
        return None
    m = "full" if any(e["muc_quyen"] == "full" for e in moi) else "auto"
    return JSONResponse({"ok": False, "error": chatbot_store._loi(chatbot_store.LOI_CHUA_XAC_NHAN_NGOAI_LE),
                         "can_force": True, "co": "xac_nhan_ngoai_le", "muc_quyen": m,
                         "nhan": chatbot_store.nhan_muc(m),
                         "canh_bao": chatbot_store.canh_bao_muc(m)}, status_code=400)


@app.get("/chatbots/chats")
async def chatbots_chats(account_ids: str = "", bot_id: str = "", q: str = "", limit: int = 60):
    """Các cuộc chat ĐÃ BIẾT (người và nhóm) cho ô "chọn người và nhóm" của form bot.

    Nguồn là Hộp thư (`conversations`) nên có tên hiển thị thật thay vì id. `account_ids` (cách nhau
    bằng dấu phẩy) là các tài khoản kênh ĐANG TÍCH trong form, kể cả khi bot chưa tồn tại; `bot_id`
    thêm hàng chờ duyệt và cờ "đã chọn". Phải đăng ký TRƯỚC mọi route có `{bot_id}` để "chats" không
    bị coi là id bot.
    """
    bot = chatbot_store.get_bot(bot_id) if bot_id else None
    ids = [x.strip() for x in str(account_ids or "").split(",") if x.strip()]
    if ids:
        tk = [channel_accounts.get_account(i) for i in ids]
        tk = [a for a in tk if a]
    else:
        tk = list((bot or {}).get("accounts") or [])
    cho = chatbot_runtime.nhom_cho(bot_id) if bot else []
    return {"ok": True, "chats": chatbot_cuoc_chat.danh_sach(tk, q, limit, cho, bot)}


@app.get("/chatbots/zalo-labels")
async def chatbots_zalo_labels(account_ids: str = "", bot_id: str = ""):
    """Zalo label names (tags the owner set in the Zalo app) of the personal Zalo accounts ticked in the bot form, for
    "Never answer chats tagged" (0.281.0). Same account rules as `/chatbots/chats`; registered before `{bot_id}` routes.
    `supported` is False when no ticked personal Zalo account could return labels (javis-zalo older than 1.6.0, or
    signed out), so the form can say why the list is empty."""
    import zalo_personal_channel
    bot = chatbot_store.get_bot(bot_id) if bot_id else None
    ids = [x.strip() for x in str(account_ids or "").split(",") if x.strip()]
    if not ids:
        ids = [str((a or {}).get("id") or a) if isinstance(a, dict) else str(a) for a in ((bot or {}).get("accounts") or [])]
    names, supported = [], False
    for aid in ids:
        acc = channel_accounts.get_account(aid) or {}
        if acc.get("channel") != "zalo_personal":
            continue
        for n in await zalo_personal_channel.label_names(aid):
            if n not in names:
                names.append(n)
        supported = supported or bool((zalo_personal_channel._LABELS.get(aid) or {}).get("ok"))
    return {"ok": True, "labels": names, "supported": supported}


@app.post("/chatbots/{bot_id}/people")
async def chatbots_people(bot_id: str, chat_id: str = Form(...), on: str = Form("1")):
    """Cho phép (hoặc gỡ) MỘT người nhắn riêng cho bot, bằng đúng một cú bấm. Đôi của
    `/chatbots/{bot_id}/groups` cho audience `chon`. Không khởi động lại poller: `_answer` đọc lại
    bản ghi bot MỖI LƯỢT, nên người vừa cho phép ăn ngay từ tin kế tiếp."""
    bot = chatbot_store.get_bot(bot_id)
    if not bot:
        return JSONResponse({"ok": False, "error": localefmt.chu("Không có bot nào id đó", "No bot with that id")},
                            status_code=404)
    cid = str(chat_id or "").strip()
    if not cid:
        return JSONResponse({"ok": False, "error": localefmt.chu("Thiếu id người", "Missing person id")}, status_code=400)
    bat = str(on).strip() not in ("0", "false", "")
    ds = [str(x) for x in (bot.get("people") or [])]
    if bat:
        if cid not in ds:
            ds.append(cid)
    else:
        ds = [x for x in ds if x != cid]
    ok, err = chatbot_store.update_bot(bot_id, {"people": ds})
    if not ok:
        return JSONResponse({"ok": False, "error": err}, status_code=400)
    chatbot_runtime.bo_nhom_cho(bot_id, cid)
    return {"ok": True, "people": (chatbot_store.get_bot(bot_id) or {}).get("people") or []}


@app.post("/chatbots")
async def chatbots_create(name: str = Form(...), agent_slug: str = Form(...),
                          brain: str = Form(""), agent_brain: str = Form(""),
                          icon: str = Form(""), token: str = Form(""),
                          bot_username: str = Form(""), handoff_to: str = Form(""),
                          nguon_tra_loi: str = Form(""), muc_quyen: str = Form(""),
                          groups: str = Form(""), reply_when: str = Form(""),
                          audience: str = Form(""), people: str = Form(""),
                          channel: str = Form(""), xac_nhan_rui_ro: str = Form(""),
                          ngon_ngu: str = Form(""), account_ids: str = Form(""),
                          account_label: str = Form(""), reply_policy: str = Form(""),
                          gio_truc: str = Form(""), nhuong_tay_phut: str = Form(""),
                          ngoai_le: str = Form(""), xac_nhan_ngoai_le: str = Form(""),
                          nhan_ket_ban: str = Form(""), skip_labels: str = Form("")):
    # Bot sống TRONG một brain: Agent nó dùng và tài liệu nó đọc là cùng một chỗ. Nhận cả hai
    # tên tham số và tự bù cho nhau, nên người gọi chỉ cần gửi một cái.
    br = (brain or agent_brain or "").strip()
    ack = str(xac_nhan_rui_ro).strip() not in ("", "0", "false")
    ack_nl = str(xac_nhan_ngoai_le).strip() not in ("", "0", "false")
    chan = _chan_nang_quyen(muc_quyen, ack) or _chan_ngoai_le(ngoai_le, [], ack_nl)
    if chan is not None:
        return chan
    bid, err = chatbot_store.create_bot({
        "name": name, "agent_slug": agent_slug, "agent_brain": br, "brain": br,
        "icon": icon, "token": token, "bot_username": bot_username, "handoff_to": handoff_to,
        "nguon_tra_loi": nguon_tra_loi, "muc_quyen": muc_quyen, "xac_nhan_rui_ro": ack,
        "channel": channel,
        # Tài khoản kênh (0.61.0): chọn tài khoản có sẵn ở tab Tài khoản bot, hoặc dán token mới (ở trên).
        "account_ids": account_ids, "account_label": account_label,
        # Nhóm khai được NGAY LÚC TẠO. Bản trước chỉ cho khai ở form Sửa, nên đường đi tự nhiên
        # nhất ("tạo bot, thả vào nhóm, gọi tên") luôn kết thúc bằng một con bot im lặng.
        "groups": groups, "reply_when": reply_when,
        # "Bot trả lời ai" (0.64.85): mọi cuộc chat / chat riêng thoải mái nhóm thì chọn / chỉ người
        # và nhóm đã chọn. Chọn "mọi cuộc chat" đòi cùng ô xác nhận rủi ro với mức quyền nâng, và
        # rào đó nằm ở KHO (`chatbot_store.can_xac_nhan_doi_tuong`), không chỉ ở đây.
        "audience": audience, "people": people,
        # Ngôn ngữ bot trả lời KHÁCH. "auto" = bám theo khách; ghim một mã khi khách của chủ
        # nói cùng một thứ tiếng. Cố ý KHÔNG thừa hưởng ngôn ngữ của chủ, xem chatbot_store.
        "ngon_ngu": ngon_ngu,
        # Bộ phán xử hội thoại nhóm (0.65.0): JSON, giá trị lạ rơi về phía hẹp nhất (xem merge_config).
        "reply_policy": reply_policy,
        # Giờ trực (0.130.0): JSON {"tu","den"} HH:MM theo múi giờ cài đặt; rỗng = cả ngày.
        "gio_truc": gio_truc,
        # Owner yield (0.172.0): minutes, 0 = never yield; blank or invalid = not set (channel default: 10 minutes,
        # groups stay silent for the whole window as before 0.172.0).
        "nhuong_tay_phut": nhuong_tay_phut,
        # Per-chat exceptions (0.172.0): JSON list of {chat_id, ten, muc_quyen, cho_giay}; raised levels need the ack.
        "ngoai_le": ngoai_le,
        "xac_nhan_ngoai_le": ack_nl,
        # Tự nhận lời mời kết bạn và đọc lời giới thiệu (0.172.0, Zalo cá nhân): "1" = bật, mặc định tắt.
        "nhan_ket_ban": nhan_ket_ban,
        # Zalo labels the bot stays out of (0.281.0, personal Zalo): JSON list of label names.
        "skip_labels": skip_labels,
    })
    if err:
        return JSONResponse({"ok": False, "error": err}, status_code=400)
    _rp_sau_khi_luu(bid)
    return {"ok": True, "id": bid}


def _rp_sau_khi_luu(bot_id: str) -> None:
    """Bot ở chế độ Tự đánh giá thì soạn hồ sơ vai ở nền ngay, khỏi chờ tới tin nhóm đầu tiên."""
    try:
        bot = chatbot_store.get_bot(bot_id) or {}
        if bot.get("reply_when") == "auto":
            chatbot_runtime._RP_CHECKED.pop(bot_id, None)
            chatbot_runtime._rp_schedule_profile(bot)
    except Exception as e:      # noqa: BLE001 - soạn hồ sơ hỏng không được làm hỏng việc lưu bot
        print(f"[reply_policy] lên lịch soạn hồ sơ sau khi lưu lỗi: {type(e).__name__}", file=__import__('sys').stderr)


@app.post("/chatbots/{bot_id}/update")
async def chatbots_update(bot_id: str, request: Request):
    form = dict(await request.form())
    # Giữ hai trường brain luôn bằng nhau: Agent và tài liệu của bot ở cùng một chỗ. Sửa lệch
    # được thì bot trỏ vào Agent nằm ngoài brain nó đọc, và không có gì báo.
    br = (form.get("brain") or form.get("agent_brain") or "").strip()
    if br:
        form["brain"] = form["agent_brain"] = br
    form["xac_nhan_rui_ro"] = str(form.get("xac_nhan_rui_ro") or "").strip() not in ("", "0", "false")
    if "muc_quyen" in form:
        chan = _chan_nang_quyen(form.get("muc_quyen"), form["xac_nhan_rui_ro"])
        if chan is not None:
            return chan
    if "ngoai_le" in form:
        form["xac_nhan_ngoai_le"] = str(form.get("xac_nhan_ngoai_le") or "").strip() not in ("", "0", "false")
        chan = _chan_ngoai_le(form.get("ngoai_le"), (chatbot_store.get_bot(bot_id) or {}).get("ngoai_le"),
                              form["xac_nhan_ngoai_le"])
        if chan is not None:
            return chan
    ok, err = chatbot_store.update_bot(bot_id, form)
    if not ok:
        # 404 CHỈ khi thật sự không có bot nào id đó; mọi lý do còn lại (xác nhận rủi ro, slug
        # Agent hỏng) là 400 - bot có thật, chỉ yêu cầu sai. Bản trước liệt kê ngược lại: mặc
        # định 404 rồi trừ ra một trường hợp, nên mỗi lý do từ chối mới thêm vào kho lại đi ra
        # ngoài dưới dạng "không tìm thấy bot", đọc xong không lần được ra lỗi thật.
        return JSONResponse({"ok": False, "error": err},
                            status_code=404 if err == chatbot_store.LOI_KHONG_CO_BOT else 400)
    # Đang chạy mà đổi token/agent/brain thì phải khởi động lại mới ăn. Khởi động lại luôn cho
    # chắc thay vì đoán trường nào cần: sai ở đây là bot chạy bằng cấu hình cũ mà không ai biết.
    if bot_id in chatbot_runtime._RUNNING:
        chatbot_runtime.start_bot(bot_id)
    if "reply_policy" in form:
        _rp_sau_khi_luu(bot_id)
    return {"ok": True}


@app.post("/chatbots/{bot_id}/enable")
async def chatbots_enable(bot_id: str, on: str = Form("1")):
    bat = str(on).strip() not in ("0", "false", "")
    ok, err = chatbot_store.set_enabled(bot_id, bat)
    if not ok:
        return JSONResponse({"ok": False, "error": err}, status_code=400)
    if bat:
        thanh, loi = chatbot_runtime.start_bot(bot_id)
        if not thanh:
            chatbot_store.set_enabled(bot_id, False)   # bật hụt thì đừng để cấu hình nói dối
            return JSONResponse({"ok": False, "error": loi}, status_code=400)
    else:
        chatbot_runtime.stop_bot(bot_id)
    return {"ok": True, "status": chatbot_runtime.status(bot_id)}


@app.post("/chatbots/{bot_id}/groups")
async def chatbots_groups(bot_id: str, chat_id: str = Form(...), on: str = Form("1")):
    """Cho phép (hoặc gỡ) MỘT nhóm cho bot, bằng đúng một cú bấm trên thẻ.

    Đường này tồn tại vì đường cũ dài tới mức không ai đi hết: thả bot vào nhóm, gõ /id, chép
    id, mở dashboard, bấm Sửa, kéo xuống cuối form, dán vào ô textarea, Lưu. Bỏ sót một bước
    là bot im, và không có gì nói cho biết đã sót ở đâu.

    Không khởi động lại poller: `_answer` đọc lại bản ghi bot MỖI LƯỢT, nên nhóm vừa cho phép
    ăn ngay từ câu tiếp theo.
    """
    bot = chatbot_store.get_bot(bot_id)
    if not bot:
        return JSONResponse({"ok": False, "error": localefmt.chu("Không có bot nào id đó", "No bot with that id")},
                            status_code=404)
    cid = str(chat_id or "").strip()
    if not cid:
        return JSONResponse({"ok": False, "error": localefmt.chu("Thiếu id nhóm", "Missing group id")}, status_code=400)
    bat = str(on).strip() not in ("0", "false", "")
    ds = [str(x) for x in (bot.get("groups") or [])]
    if bat:
        if cid not in ds:
            ds.append(cid)
    else:
        ds = [x for x in ds if x != cid]
    ok, err = chatbot_store.update_bot(bot_id, {"groups": ds})
    if not ok:
        return JSONResponse({"ok": False, "error": err}, status_code=400)
    # Ra khỏi hàng đợi dù chủ chọn gì: cho phép rồi thì hết chờ, mà bấm bỏ qua cũng là đã
    # quyết. Nhóm nào bị gỡ mà sau này lại có người gọi bot thì nó tự quay lại hàng đợi.
    chatbot_runtime.bo_nhom_cho(bot_id, cid)
    return {"ok": True, "groups": (chatbot_store.get_bot(bot_id) or {}).get("groups") or []}


@app.get("/chatbots/{bot_id}/log")
async def chatbots_log(bot_id: str, limit: int = 50):
    """Nhật ký hội thoại khách + danh sách CÂU BOT TRẢ LỜI KHÔNG NỔI.

    Trả cả hai trong một lời gọi: chúng luôn được xem cùng nhau, và mỗi cái đọc lại chính file
    đó nên tách ra chỉ tốn hai lượt đọc đĩa cho cùng một dữ liệu.
    """
    if not chatbot_store.get_bot(bot_id):
        return JSONResponse({"ok": False, "error": localefmt.chu("Không có bot nào id đó", "No bot with that id")},
                            status_code=404)
    return {"ok": True, "turns": chatbot_log.doc(bot_id, limit),
            "gaps": chatbot_log.lo_hong(bot_id), "tom_tat": chatbot_log.tom_tat(bot_id)}


@app.post("/chatbots/{bot_id}/delete")
async def chatbots_delete(bot_id: str):
    """Xoá bản ghi bot. KHÔNG đụng brain và Agent của nó - xem chatbot_store.delete_bot."""
    chatbot_runtime.quen_bot(bot_id)   # tắt + dọn hết vết trong RAM (hàng đợi nhóm, bộ đếm)
    ok, err = chatbot_store.delete_bot(bot_id)
    if not ok:
        return JSONResponse({"ok": False, "error": err}, status_code=404)
    chatbot_log.xoa(bot_id)   # nhật ký của một bot không còn tồn tại thì không ai đọc được nữa
    return {"ok": True}


